window.__D("text/tikkunei-zohar/c002",{"p":[[9500011091,"<p>דְשַׁבָּת דְּאִתּוֹסַף לְעָנִי דְאִיהוּ צַדִּיק, יוֹם הַשַּׁבָּת וַדַּאי, דְּלֵית לֵיהּ מִדִּילֵיהּ אֶלָּא נִשְׁמָתָא יְתֵירָה דְאִתּוֹסַף לְגַבֵּיהּ בְּגִין שְׁכִינְתָּא, אִתְקְרֵי אִיהוּ מוּסַף שַׁבָּת.</p>\n<p>וּבְהַהוּא זִמְנָא אִתְקְרִיאַת אִיהִי תּוֹסֶפְתָּא, מִסִּטְרָא דְיוֹם שַׁבָּת כַּמָּה תּוֹסָפוֹת נָחֲתִין עִמָּה לְתַלְמִידֵי חֲכָמִים, דְּאִתְקְרִיאוּ נְשָׁמוֹת יְתֵירוֹת, הֲדָא הוּא דִכְתִיב נִשְׁמַת כָּל חַי תְּבָרֵךְ אֶת שִׁמְךָ יהו\"ה אלהינ\"ו וכו',</p>\n<p>וְאִלֵּין (אינון) דְּמִתּוֹסְפָאן לְעַמָּא קַדִּישָׁא בְּעִִרֶב שַׁבָּת יָרְתִין לוֹן תַּלְמִידֵי חֲכָמִים בְּיוֹמִין דְּחוֹל, וּבְהוֹן אִתְעֲבִיד חוֹל קֹדֶשׁ, וְאִלֵּין אִינוּן תּוֹסָפוֹת דְּקָא נָחֲתִין מִתּוֹסֶפְתָּא. דְוַדַּאי שְׁכִינְתָּא אִיהִי תִקּוּנָא דְגוּפָא דְקוּדְשָׁא בְּרִיךְ הוּא,</p>\n<p>אִיהִי בְרַיְתָא כַּד אִתְּמַר בָּהּ (רות ג ז) וַתְּגַל מַרְגְּלוֹתָיו,</p>\n<p>וְאִיהִי תּוֹסֶפְתָּא מִסִּטְרָא דְחַ\"י עָלְמִין, דְּאִיהוּ מוּסַף שַׁבָּת,</p>\n<p>וְאִיהִי מִשְׁנָה מִסִּטְרָא דְגוּפָא, מִשְׁנֶה תּוֹרָה וַדַּאי,</p>\n<p>וְאִיהִי הַתְּקָפָא מִסִּטְרָא דִדְרוֹעָא יְמִינָא דְמַלְכָּא, הֲדָא הוּא דִכְתִיב (שמות טו ו) יְמִינְךָ יהו\"ה נֶאְדָּרִי בַּכֹּחַ, בַּכֹּחַ תַּרְגּוּם בְּתוּקְפָא,</p>\n<p>הַצְרָכָה אִיהִי מִסִּטְרָא דִשְׂמָאלָא, וּבִדְרוֹעָא שְׂמָאלָא אֲחִיד בָּהּ, וּבִדְרוֹעָא יְמִינָא אַתְקַן בָּהּ, וְיֵימָא קוּמִי שְׁבִי יְרוּשָׁלָםִ.</p>\n<p>וְעוֹד מִסִּטְרָא דִימִינָא אִיהִי תוּקְפָא לְבַר נַשׁ, וּמִסִּטְרָא דִשְׂמָאלָא יְהִיב לוֹן צָרְכֵיהוֹן בַּאֲרַע מַדְבְּרָא,</p>\n<p>שְׁאֵלָה אִיהִי בְּפִימָא דְמַלְכָּא, הֲדָא הוּא דִכְתִיב (דברים לב ז) שְׁאַל אָבִיךָ, וּתְיוּבְתָּא לְגַבֵּיהּ הֲדָא הוּא דִכְתִיב וְיַגֶּדְךָ,</p>\n<p>וּבָהּ בַּר נַשׁ שׁוֹאֵל כְּעִנְיַן וּמֵשִׁיב כַּהֲלָכָה.</p>\n<p>שְׁמַעִִתְּתָא אִיהִי בְלִבָּא דְתַמָּן מַחֲשָׁבָה,</p>\n<p>תֵּיקוּ אִיהִי כַד אִסְתַּלַּק מַלְכָּא מִינָהּ, הֲדָא הוּא דִכְתִיב (תהלים לט ג) נֶאֱלַמְתִּי דוּמִיָּה הֶחשֵׁתִי מִטּוֹב, וּבָהּ צְלוֹתָא בַחֲשָׁאי, וְכַד אִיהוּ תֵּיקוּ אִתְּמַר בָּהּ (משלי א כח) אָז יִקְרָאוּנְנִי וְלֹא אֶעֱנֶה.</p>\n<p>כַּד שַׁרְיָא בָּהּ יהו\"ה אִתְקְרִיאַת הַגָּדָה, בְּהַהוּא זִמְנָא אָז תִּקְרָא וַיהו\"ה יַעֲנֶה,</p>\n<p>שִׁטָּה אִתְקְרִיאַת כַּד לָא יְהֵא קוּשְׁיָא וּמַחֲלֹקֶת, הֲדָא הוּא דִכְתִיב (ישעיה מ ד) כָּל גֵּיא יִנָּשֵׂא וְכָל הַר וְגִבְעָה יִשְׁפָּלוּ, וְהָיָה הֶעָקֹב לְמִישׁוֹר,</p>\n<p>פְּסַק אִתְקְרִיאַת מִכַּמָּה גַוָּונִין, אִית בְּנֵי נָשָׁא דְמִשְׁתַּדְלִין בְּאוֹרַיְיתָא דִבְעַל פֶּה לִשְׁמָהּ, וְאִינוּן בַּעֲלֵי אוּמָנוּת לְגַבָּהּ, אִית דְּפָסְקִין בָּהּ אֲבָנִין כְּטוּרִין וּסְלָעִין תַּקִּיפִין, וּלְבָתַר דְּפָסְקִין לוֹן מְתַקְּנִין לוֹן בְּכַמָּה פִרוּקִין, וַעֲלַיְיהוּ אִתְּמַר (דברים כז ו) אֲבָנִים שְׁלֵמוֹת תִּבְנֶה, וְעָבְדִין בְּהוֹן כַּמָּה בִנְיָנִין לְמַלְכָּא וּלְמַטְרוֹנִיתָא לְדַיְירָא בֵּינַיְיהוּ.</p>\n<p>וְאִית פְּסָקוֹת דְּאִינוּן לְבוּשִׁין דְּמַטְרוֹנִיתָא, וְחָתְּכִין לוֹן לְכַמָּה סִטְרִין, וּלְבָתַר מְתַקְּנִין לוֹן בְּכַמָּה פִרוּקִין, לְאִתְחַזָּאָה בְּהוֹן מַטְרוֹנִיתָא קֳדָם מַלְכָּא, בְּהַהוּא זִמְנָא וּרְאִיתִיהָ לִזְכּוֹר בְּרִית עוֹלָם (בראשית ט טז), וְאִלֵּין אִינוּן לְבוּשִׁין דְּכַהֲנָא, דְאִינוּן אַרְבַּע בִּגְדֵי לָבָן וְאַרְבַּע בִּגְדֵי זָהָב,</p>\n<p>וְאִית פְּסָקוֹת מֵאִלֵּין מָארֵי תְרִיסִין דְּקָא אַתְיָין לְבֵי מֶדְרָשָׁא, דְפָסְקִין וְחָתְּכִין בְּהוֹן בְּלִישָׁנְהוֹן, דְּאִינוּן כְּרוּמְחִין וְסַיְיפִין, וְאִלֵּין אִינוּן פָּרְשָׁיָּין וְתַקִּיפִין, כְּמַגִּיחִין קְרָבָא בְיַמָּא וּבְיַבֶּשְׁתָּא, דְאִינוּן אוֹרַיְיתָא דְבִכְתָב וְאוֹרַיְיתָא דִבְעַל פֶּה.</p>\n<p>זַכָּאִין אִינוּן אִם מַלְכָּא בֵינַיְיהוּ דְאִיהוּ עַמּוּדָא דְאֶמְצָעִיתָא, כְּלִיל תְּרֵין תּוֹרוֹת דְּאִנּוּן תּוֹרָה שֶׁבִּכְתָב וְתוֹרָה שֶׁבְּעַל פֶּה, דְאִתְיְיהִיבוּ מִימִינָא וּמִשְּׂמָאלָא, דְבֵיהּ נָצְחִין קְרָבָא,</p>\n<p>וַוי לוֹן לְאִלֵּין דְּיַעֲלוּן לְאַגָּחָא קְרָבָא בִתְרֵין תּוֹרוֹת בְּלָא מַלְכָּא, דַעֲלַיְיהוּ אִתְּמַר (תהלים יט ד) אֵין אֹמֶר וְאֵין דְּבָרִים בְּלִי נִשְׁמָע קוֹלָם,</p>\n<p>כָּל בַּעֲלֵי אוּמָנִיּוֹת מִשְׁתַּכְּחִין בְּתוֹרָה שֶׁבְּעַל פֶּה, וְאִיהִי מִלְּגָאו, הֲדָא הוּא דִכְתִיב (שם מה יד) כָּל כְּבוּדָּה בַת מֶלֶךְ פְּנִימָה.</p>\n<p>אִיהִי הֲלָכָה דְמַלְכָּא, כַּד אִיהִי אָזְלַת גַּבֵּיהּ בִּתְרֵין שׁוֹקִין דְּאִינוּן תְּרֵי סַמְכֵי קְשׁוֹט, וְכַד סְלִיקַת בְּגוּפָא בִּתְרֵין דְּרוֹעוֹי דְּמַלְכָּא אִתְקְרִיאַת קַבָּלָה,</p>\n<p>וְכַד נְשִׁיקַת לֵיהּ בְּפִימֵיהּ אִתְקְרִיאַת אוֹרַיְיתָא דִבְעַל פֶּה, בְּהַהוּא זִמְנָא דְסָלְקָא לְפִימָא דְמַלְכָּא, מִיָּד יִתְקַיֵּים בְּרַעִִיָא מְהֵימְנָא (במדבר יב ח) פֶּה אֶל פֶּה אֲדַבֶּר בּוֹ,</p>\n<p>כַּד קָמַת עַל רַגְלָהָא בְגָלוּתָא בַתְרָאָה, אִתְקְרִיאַת הֲלָכָה לְמֹשֶׁה מִסִּינַי, וְכַד שַׁרְיָיא בִדְרוֹעוֹי</p>"],[9500011092,"<p>דְּמַלְכָּא, אִתְקְרִיאַת קַבָּלָה לְמֹשֶׁה מִסִּינַי,</p>\n<p>וְכַד שַׁרְיָיא בְּפִימָא דְמַלְכָּא מִיָּד פֶּה אֶל פֶּה אֲדַבֶּר בּוֹ,</p>\n<p>וְכַד אִיהִי מְרַחֲקָא הֲלָכָה מִמֹּשֶׁה, שְׁכִינְתָּא אִיהִי רִיב לַיהו\"ה לְתַתָּא, וְכַד לַאו אִיהִי בִדְרוֹעוֹי קַבָּלָה,</p>\n<p>אִיהִי רִיב לְעִילָא. וּבְגִין דָּא שִׁמְעוּ הָרִים אֶת רִיב יהו\"ה, אִלֵּין תְּלַת אֲבָהָן, מַאי רִיב דִּלְהוֹן, דָּא שְׁכִינְתָּא,</p>\n<p>וּבְהִפּוּךְ אַתְוָון רִי\"ב אִיהוּ רַבִּ\"י, דְּאִיהוּ רַבִּי מֵאֶרֶץ יִשְׂרָאֵל, וְעִמֵּיהּ אִיהִי שְׁכִינְתָּא רִיב,</p>\n<p>וְהָאֵיתָנִים אִלֵּין תְּרֵי תַּנָּאֵי, אֵיתָנִי\"ם בְּהִפּוּךְ אַתְוָון תַּנָּאִי\"ם, מוֹסְדֵי אָרֶץ אִלֵּין צַדִּיק וָצֶדֶק.</p>\n<p>דָּבָר אַחֵר שִׁמְעוּ הָרִים, מָאן הָרִים אִלֵּין תְּלַת נְקוּדִין דְּאִינוּן סֶגוֹ\"ל, וְהָאֵיתָנִים אִלֵּין תְּרֵין נְקוּדִין דְּאִינוּן צֵרִ\"י,</p>\n<p>וְעוֹד שִׁמְעוּ הָרִים מָאן הָרִים אִלֵּין תְּלַת נְקוּדִין תִּנְיָינִין דְּאִינוּן שׁוּרֵ\"ק, וְאֵיתָנִים אִינוּן תְּרֵין נְקוּדִין תִּנְיָינִין דְּאִינוּן שְׁבָ\"א.</p>\n<p>מַאי רִיב יהו\"ה דָּא חִירֵ\"ק, רִיב יהו\"ה לְעִילָא חוֹלֵ\"ם, רִיב יהו\"ה לְתַתָּא חִירֵ\"ק, תְּרֵי רִיבוֹת אִינוּן עַל שׁוּרֵ\"ק, דְּאִיהוּ (חד) צַדִּיק קִשּׁוּרָא דְתַרְוַיְיהוּ,</p>\n<p>(עמודא דאמצעיתא) כַּד אִיהוּ מִתְרַחֵק מִנַּיְיהוּ אִיהוּ רִיב, וְכַד מִתְקַשֵּׁר בֵּין תַּרְוַיְיהוּ אִיהוּ רַבִּי, וְאִיהוּ שָׁלוֹם, וְאִיהוּ קֶשֶׁר, הֲדָא הוּא דִכְתִיב (בראשית מד ל) וְנַפְשׁוֹ קְשׁוּרָה בְנַפְשׁוֹ.</p>\n<p>וְעוֹד תְּרֵי רִיבוֹת אִינוּן, חַד צַדִּיק, וְחַד עַמּוּדָא דְאֶמְצָעִיתָא, חַד אִיהוּ רִיב בֵּין אַבָּא וְאִמָּא, דְאִנּוּן קָמֵ\"ץ וּפַתַ\"ח, דָּא עַמּוּדָא דְאֶמְצָעִיתָא אִיהוּ רִיב בֵּינַיְיהוּ, (נ\"א דאינון ריב בין אבא ואימא דאנון, קמ\"ץ ופת\"ח, ואמאי אינון ריב בינייהו), בְּגִין שְׁכִינְתָּא דְלֵית לָהּ מְזוֹנָא בְגָלוּתָא,</p>\n<p>בְגִין דְּתַרְעָא אִיהוּ פַתַ\"ח, דְּאִתְּמַר בֵּיהּ (תהלים קמה טז) פּוֹתֵחַ אֶת יָדֶיךָ, דְאִיהוּ י' חָכְמָה, קָמֵ\"ץ סָתוּם, עֲלֵיהּ אִתְּמַר פּוֹתֵחַ אֶת יָדֶיךָ וּמַשְׂבִּיעַ לְכָל חַ\"י,</p>\n<p>וְדָא חַ\"י עָלְמִין, דְּאִיהוּ כְּלִיל חַ\"י בִּרְכָאָן, אִיהוּ חָרֵב וְיָבֵשׁ בִּצְלוֹתָא דְאִיהוּ שְׁכִינְתָּא, וּבְגִין דָּא אִיהוּ צְלוֹתָא יְבֵשָׁה, בְּגִינַיְהוּ אִיהוּ רִיב בֵּין אַבָּא וְאִימָּא.</p>\n<p>וְכַד אִתְפַּתַּח קָמֵ\"ץ בְּפַתָ\"ח דְּאִיהוּ תַרְעָא דִילֵיהּ, עַמּוּדָא דְאֶמְצָעִיתָא נָחִית מָלֵא,</p>\n<p>וּמְהַלֵּךְ חָמֵשׁ מְאָה שְׁנִין, עַד דְּמָטוּ לְחַ\"י עָלְמִין (דאיהו כליל ח\"י ברכאן), וְאִתְמַלָּא מִנַּיְיהוּ, וּמִנֵּיהּ אִתְשַׁקְיָיא לִשְׁכִינְתָּא דְאִיהִי צְלוֹתָא, וּמַאי דַּהֲוָה יַבָּשָׁה קָרָא לֵיה אֶרֶץ,</p>\n<p>הֲדָא הוּא דִכְתִיב (בראשית א ו) וַיִּקְרָא אלהי\"ם לַיַּבָּשָׁה אֶרֶץ, לְמֶעִִבַּד פֵּרִין וְאִיבִּין, דְּאִינוּן אַרְעָא קַדִּישָׁא דְיִשְׂרָאֵל לְתַתָּא, הֲדָא הוּא דִכְתִיב (שם יא) וַיֹּאמֶר אלהי\"ם תַּדְשֵׁא הָאָרֶץ דֶּשֶׁא.</p>\n<p>וְעַמּוּדָא דְאֶמְצָעִיתָא כַּד סָלִיק לְאַבָּא וְאִימָּא לְנַחֲתָא מְזוֹנָא מִתַּמָּן, קָלֵיהּ סָלְקָא עַל כָּל אִינוּן נְחָלִין וּמַבּוּעִין, וְכַד נָחְתָא קָלֵיהּ נָחְתָא עַל כָּל אִינוּן נְחָלִין וּמַבּוּעִין דְּאוֹרַיְיתָא, הֲדָא הוּא דִכְתִיב (תהלים צג ג) נָשְׂאוּ נְהָרוֹת יהו\"ה, נָשְׂאוּ נְהָרוֹת קוֹלָם,</p>\n<p>נָשְׂאוּ נְהָרוֹת אִלֵּין אִינוּן תְּרֵין נְקוּדִין דְּאִינוּן צֵרִ\"י, מָאן אִיהוּ דְסָלִיק עַל גַּבַּיְיהוּ בִתְרֵין דְּרוֹעִין, דָּא חוֹלֵ\"ם, וּבֵיהּ אִתְעֲבִידוּ סֶגוֹלְתָּ\"א, וּמָאן אִיהוּ דְנָחִית תְּחוֹתַיְיהוּ בִּתְרֵין שׁוֹקִין, דָּא חִירֵ\"ק, וּבֵיהּ אִתְעֲבִידוּ סֶגוֹ\"ל.</p>\n<p>בְּהַהוּא זִמְנָא נָשְׂאוּ נְהָרוֹת קוֹלָם, דְּאִיהוּ קוֹל יַעֲקֹב, קוֹל הַשּׁוֹפָר, וּלְאָן סָלְקִין לֵיהּ לְגַבֵּי אַבָּא וְאִימָּא, וְכַד נָחִית נָחִית בִּתְרֵין נְקוּדִין דְּאִינוּן שְׁבָ\"א תְּרֵי יַרְכֵי קְשׁוֹט, הֲדָא הוּא דִכְתִיב (שם) יִשְׂאוּ נְהָרוֹת דָּכְיָם, כְּגוֹן עַל כָּתֵף יִשָּׂאוּ</p>\n<p>(במדבר ז ט). (ואבא נחית) בַּצַּדִּיק, דְּאִיהוּ שׁוּרֵ\"ק בִּנְקוּדַת (חיר\"ק) חֲדָא, כִּי שָׁם חֶלְקַת מְחוֹקֵק סָפוּן (דברים לג כא), קִשּׁוּרָא דִתְרֵין יַרְכִין דִּקְשׁוֹט, דְּאִיהוּ דָּכְיָם, דָּךְ יָם, דָּ\"ךְ דִּכְלִיל כ\"ד אַתְוָון דְּיִחוּדָא תִּנְיָינָא, עֲלֵיהּ אִתְּמַר (תהלים עד כד) אַל יָשׁוֹב דַּךְ נִכְלָם,</p>\n<p>דָּ\"ךְ אִיהוּ בְּכ\"ד סְפָרִים דְּאוֹרַיְיתָא, וּשְׁכִינְתָּא (בראשית כד טו) וְכַדָּ\"הּ עַל שִׁכְמָהּ, וְכַד צַדִּיק אִיהוּ מָלֵא מֵעַמּוּדָא דְאֶמְצָעִיתָא, דְאִתְּמַר בֵּיהּ (שם טז) וַתְּמַלֵּא כַדָּהּ וַתָּעַל. סְלִיקַת הַאי נְקוּדָה דְאִיהוּ חַד שׁוּרֵ\"ק עַל תְּרֵין דְּאִינוּן שְׁבָ\"א, וְאִתְעֲבִידוּ שׁוּרֵ\"ק,</p>\n<p>בָּתַר דְּאִיהוּ מַלְיָא מִסִּטְרָא דִילֵיהּ וּמִסִּטְרָא דְעַמּוּדָא דְאֶמְצָעִיתָא, אִתְּמַר בִּשְׁכִינְתָּא וַתְּמַלֵּא כַדָּהּ וַתָּעַל,</p>\n<p>וַתּוֹרֶד כַּדָּהּ מֵעַל שִׁכְמָהּ, כָּל הַכּוֹרֵעַ כּוֹרֵעַ בְּבָרוּךְ, וַתְּמַלֵּא כַדָּהּ וַתָּעַל, כָּל הַזּוֹקֵף זוֹקֵף בְּשֵׁם,</p>\n<p>סְלִיקַת וַדַּאי מִגָּלוּתָא לְגַבֵּי בַּעִִלָהּ,</p>\n<p>בְּהַאי שַׁעִִתָּא</p>"],[9500011093,"<p>אִיהִי אָמְרַת לְגַבֵּי צַדִּיק (בראשית כד יח) וַתֹּאמֶר שְׁתֵה אֲדוֹנִי, וְגַם גְּמַלֶּיךָ אַשְׁקֶה, דְאִינוּן גְּמוּלֵי מֵחָלָב.</p>\n<p>וְעוֹד חוֹלֵ\"ם אִתְקְרֵי עַמּוּדָא דְאֶמְצָעִיתָא לְגַבֵּי מוֹחָא, וְחִירֵ\"ק לְגַבֵּי לִבָּא, שׁוּרֵ\"ק אִתְקְרֵי בְקִשּׁוּרָא דְתַרְוַיְיהוּ,</p>\n<p>וְעוֹד חוֹלֵ\"ם אִתְקְרֵי בְכָל סִטְרָא דִימִינָא, הֲדָא הוּא דִכְתִיב (ויקרא ב יג) עַל כָּל קָרְבָּנְךָ תַּקְרִיב מֶלַח, וְחִירֵ\"ק אִתְקְרֵי בְּכָל סִטְרָא דִשְׂמָאלָא, וְאִיהוּ שׁוּרֵ\"ק קִשּׁוּרָא דְתַרְוַיְיהוּ,</p>\n<p>וְעוֹד חֹלֵ\"ם אִתְקְרֵי בְאִימָּא עִלָּאָה, יוֹם הַכִּפּוּרִים דְּאִיהוּ עָשׂוֹר, וּבֵיהּ יְהֵא מוֹחֵ\"ל וְסוֹלֵחַ חוֹבִין דְּעַמֵּיהּ, וְחִירֵ\"ק אִתְּמַר בְּאִימָּא תַּתָּאָה, וּבֵיהּ חוֹרֵ\"ק עָלָיו שִׁנָּיו עַל סמא\"ל, דְּאִשְׁתַּעֲבִיד בִּבְנוֹי דִּשְׁכִינְתָּא בְגָלוּתָא.</p>\n<p>דָּבָר אַחֵר נָשְׂאוּ נְהָרוֹת קוֹלָם, דָּא תְּרֵין זִמְנִין דִּמְיַחֲדִין יִשְׂרָאֵל לְקוּדְשָׁא בְּרִיךְ הוּא, וְסָלְקִין לֵיהּ בֵּיהּ קָלָא עִִרֶב וָבֹקֶר וְצָהֳרָיִם, דְּאִינוּן יְמִינָא וּשְׂמָאלָא, בְּתַרְוַיְיהוּ סָלְקִין קָלָא דְאִיהוּ עַמּוּדָא דְאֶמְצָעִיתָא,</p>\n<p>לְגַבֵּי מָאן סָלְקָאן לֵיהּ לְגַבֵּי אִימָּא עִלָּאָה, דְאִיהוּ כ\"ה בִּימִינָא וְכ\"ה בִּשְׂמָאלָא עִִרֶב וָבֹקֶר, וְאִינוּן חַמְשִׁין תַּרְעִין דְּבִינָה,</p>\n<p>קָרָאן לֵיהּ בְּהוֹן, דְּנָחִית לְגַבֵּי צַדִּיק וָצֶדֶק. דְּאִיהוּ דָ\"ךְ בְּשׁוֹקָא יְמִינָא, וְאִיהִי כַּדָּהּ עַל שִׁכְמָהּ בְּשׁוֹקָא שְׂמָאלָא, דְּאִינוּן תְּרֵי סַמְכֵי קְשׁוֹט,</p>\n<p>וּבְגִין דָּא יִשְׂאוּ נְהָרוֹת דָּכְיָם, דָּ\"ךְ יָ\"ם, וְאִיהוּ דָּ\"ךְ בְּכ\"ד אַתְוָון דְּבָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעִִד דְּעַרְבִית, וְאִיהוּ דָּ\"ךְ בְּכ\"ד אַתְוָון דְּשַׁחֲרִית,</p>\n<p>וְרָזָא דְמִלָּה וְשַׂמְתִּי כַּ\"דְכֹ\"ד שִׁמְשׁוֹתַיִךְ (ישעיה נד יב), וְאִיהִי כַּדָּ\"הּ בְּתַרְוַיְיהוּ, וְאַל יָשׁוֹב דָּ\"ךְ נִכְלָם. וְצָרִיךְ דְּלָא אִשְׁתַּמַע קָלָא בְהַהוּא דָךְ, אֶלָּא יִשְׂאוּ נְהָרוֹת, נָשְׂאוּ לָא כְּתִיב אֶלָּא יִשְׂאוּ, בְּגִין עַל כָּתֵף יִשָּׂאוּ,</p>\n<p>בְּהַהִיא זִמְנָא (בראשית כד טז) וַתְּמַלֵּא כַדָּה וַתָּעַל, וַתֹּאמֶר שְׁתֵה אֲדוֹנִי וְגַם לִגְמַלֶּיךָ אַשְׁקֶה,</p>\n<p>אִלֵּין אִינוּן רְמַ\"ח תֵּיבִין דְּאַרְבַּע פָּרָשִׁיָּין דְּיִחוּדָא דִקְרִיאַת שְׁמַע, דִּבְכֻלְּהוּ אִינוּן רְמַ\"ח אֵבָרִים דִּכְלִילָן בַּבְּרִית דְּאִיהוּ צַדִּיק, כֻּלְּהוּ אִתְשַׁקְיָין עַל יְדֵי שְׁכִינְתָּא, דְּאִיהוּ כ\"ד י\"ם.</p>\n<p>כ\"ד סִפְרִין דְּאוֹרַיְיתָא, וַדַּאי אִינוּן כ\"ד דְּאִתְמַלִּי מִן יַמָּא עִלָּאָה דְאוֹרַיְיתָא, דְאִיהִי כְלִילָא דְחַמְשִׁין אַתְוָון דְּיִחוּדָא, דְאִינוּן כ\"ה וְכ\"ה, דִּמְיַחֲדִין בְּהוֹן לְקוּדְשָׁא בְּרִיךְ הוּא תְּרֵין זִמְנִין,</p>\n<p>וְכַד סָלִיק י\"ם חַמְשִׁין, דָּא אִיהוּ יִשְׂאוּ נְהָרוֹת דָּכְיָם, בְּהִפּוּךְ אַתְוָון דָּךְ וְאִיהוּ כ\"ד,</p>\n<p>וְדָךְ אִיהוּ צַדִּיק בְּהַאי כַּד, בְּגִין דְּאִיהוּ תְּבִירָא בְגָלוּתָא, שְׁכִינְתָּא דְאִיהִי כַּד עֲלֵיהּ אִתְּמַר (תהלים נא יט) לֵב נִשְׁבָּר וְנִדְכֶּה אלהי\"ם לֹא תִבְזֶה,</p>\n<p>צַדִּיק אִיהוּ דָּךְ בְּמַיָּא דְאוֹרַיְיתָא. וְאִיהוּ כָּתִית בְּמִשְׁחָא דְאוֹרַיְיתָא, הֲדָא הוּא דִכְתִיב (במדבר כח ה) שֶׁמֶן כָּתִית, אֵימָתַי, בְּזִמְנָא דְאִסְתַּלַּק ו' מִן ה', וְאִשְׁתְּאָרַת ד', דַּלַּת וַדַּאי, וּבְגִין דָּא שֶׁמֶן כָּתִית רְבִיעִית הַהִין, רְבִיעִית הֵ\"א וַדַּאי, דְּאִתְחַזְרַת דָּלֵ\"ת, וְהַהוּא כָּתִית אִיהוּ ו' זְעִירָא, שְׁלִימוּ דְה',</p>\n<p>וַעֲלֵיהּ אִתְּמַר (שמות לא יז) בֵּינִי וּבֵין בְּנֵי יִשְׂרָאֵל אוֹת הִיא לְעוֹלָם, אוֹת ה' וַדַּאי, וּבְגִין דָּא אִתְקְרִיאַת ה' עַל שְׁמֵיהּ, יוֹם הַשִּׁשִּׁי, הֵ\"א דְּשִׁשִּׁי.</p>\n<p>מִקּוֹלוֹת מַיִם רַבִּים (תהלים צג ד), אִלֵּין שֶׁבַע (קלין) שְׁמָהָן, דְּמִתְפַּלְגִין לְשִׁבְעָה נְהָרוֹת, וְכֻלְּהוֹן מִתְפַּלְגִין בְּהַהוּא נָהָר דְּנָפִיק מֵעִדֶן,</p>\n<p>וְאִינוּן בְּהָבוּ לַיהו\"ה, שֶׁבַע אִינוּן דְּאָזְלִין עַל שֶׁבַע שְׁמָהָן, דְּאִינוּן אבגית\"ץ וכו', וְאִינוּן שֶׁבַע סְפִירָן, (שם כט ג)</p>\n<p>קוֹל יהו\"ה עַל הַמָּיִם דָּא חֶסֶ\"ד וְאִיהוּ אבגית\"ץ, דְּמִתַּמָּן מַיָּא דְאוֹרַיְיתָא, קוֹל יהו\"ה בַּכֹּחַ דָּא קר\"ע שט\"ן וְדָא גְבוּרָ\"ה, קוֹל יהו\"ה בֶּהָדָר דָּא נג\"ד יכ\"ש וְדָא תִפְאֶרֶ\"ת, כִּסְאוֹ כַּשֶּׁמֶ\"שׁ נֶגְדִּ\"י (שם פט לז),</p>\n<p>וּבֵיהּ אִתְּמַר לְמֹשֶׁה (שמות לד י) נֶגֶד כָּל עַמְּךָ אֶעֱשֶׂה נִפְלָאוֹת,</p>\n<p>קוֹל יהו\"ה שׁוֹבֵר אֲרָזִים (תהלים כט ז) דָּא בט\"ר צת\"ג וְדָא נֶצַ\"ח, קוֹל יהו\"ה חוֹצֵב לַהֲבוֹת אֵשׁ דָּא חק\"ב טנ\"ע וְדָא הוֹ\"ד, קוֹל יהו\"ה יָחִיל מִדְבָּר דָּא יג\"ל פז\"ק דְּאִיהוּ יְסוֹ\"ד, הַר סִינַי, קוֹל יהו\"ה יְחוֹלֵל אַיָּלוֹת דָּא שק\"ו צי\"ת וְדָא מַלְכוּ\"ת, דַּעֲלָהּ אִתְּמַר (שם כב א) לַמְנַצֵּחַ עַל אַיֶּלֶת הַשַּׁחַר,</p>\n<p>וְדָא אִיהוּ מִקּוֹלוֹת מַיִם רַבִּים. אַדִּירִים מִשְׁבְּרֵי יָם (שם צג ד), אִלֵּין טַעֲמֵי דְאוֹרַיְיתָא, דְאִתְּמַר בְּהוּ (שם מב ח) כָּל מִשְׁבָּרֶיךָ וְגַלֶּיךָ עָלַי עָבָרוּ, וְאִלֵּין אִינוּן זַרְקָ\"א מַקַּ\"ף שׁוֹפָ\"ר הוֹלֵ\"ךְ סֶגּוֹלְתָּ\"א.</p>"],[9500011094,"<p>זַרְקָ\"א, קַו דִּיּוֹקְנָא דְאָת ו', רֵישָׁא דִילֵיהּ י', תְּלַת גַּלְגַּלִּים (נ\"א אית) סָלְקִין בֵּיהּ בְּיַמָּא דְאוֹרַיְיתָא, וְאִינוּן סֶגוֹ\"ל (נ\"א סגולתא), וְכָל גַּלְגַּל סָלִיק לְי' גַּלְגַּלִּים לְעִילָא, וְהָאוֹפַנִּים יִנָּשְׂאוּ לְעְִמָּתָם (יחזקאל א כ), וּלְזִמְנָא דְיִנָּשְׂאוּ הָאוֹפַנִּים לְעוּמָתָם, מִיָּד נָשְׂאוּ נְהָרוֹת יהו\"ה,</p>\n<p>תְּרֵין נְקוּדִין דְּאִינוּן סֶגוֹלְתָּ\"א סָלְקִין לְהַהִיא נְקוּדָה חֲדָא עַל גַּדְפוֹי, וְאִתְעֲבִידוּ י\"ה, וְדָא אִיהוּ נָשְׂאוּ נְהָרוֹת יהו\"ה, אִינוּן ב' נְקוּדִין דְּא', י' לְעִילָא וְי' לְתַתָּא, סָלְקִין ו' עַל (גדפוי) גַּדְפִין,</p>\n<p>וּלְאָן סָלְקִין, אֶלָּא חוּשְׁבָּנָא דִלְהוֹן לְחוּשְׁבַּן שְׁמָא דְיהו\"ה, וְכַד סָלְקִין לָהּ עַל גַּדְפַיְיהוּ, לְקַבְּלָא עֲלַיְיהוּ עִלַּת הָעִילּוֹת, דְּנָחִית עַל גַּבַּיְיהוּ.</p>\n<p>וְעוֹד זַרְקָ\"א אִיהוּ יְפֵה נוֹף מְשׂוֹשׂ כָּל הָאָרֶץ (תהלים מח ג), אִיהוּ ז', יוֹם הַשְּׁבִיעִי, וְדָא צַדִּיק, וְאִיהוּ עַנְפָא מִגּוּפָא דְאִילָנָא, דְאִיהוּ עַמּוּדָא דְאֶמְצָעִיתָא, הַר צִיּוֹן יַרְכְּתֵי צָפוֹן דָּא נְקוּדָה חֲדָא י' (נ\"א א) זְעִירָא אוֹת הַבְּרִית,</p>\n<p>וַעֲלָהּ אִתְּמַר (שם צג ג) נָשְׂאוּ נְהָרוֹת יהו\"ה, וּמַאי נִיהוּ יַרְכְּתֵי צָפוֹן (שם מח ג), דְּסָלְקִין לָהּ לְגַבֵּיהּ דְיהו\"ה דְּאִיהוּ בַּעִִלָהּ, וְכַד סָלְקִין לָהּ לְגַבֵּיהּ אִתְקְרִיאַת הַהִיא נְקוּדָה קִרְיַת מֶלֶךְ רָב.</p>\n<p>בְּהַהִיא זִמְנָא דְסָלְקַת הַהִיא נְקוּדָה בִּתְרֵין יַרְכֵי, מְקַבְּלִין לָהּ תְּרֵין דְּרוֹעִין, דְּאִינוּן ב' נְהָרוֹת עִלָּאִין, וְסָלְקִין לָהּ בְּעַמּוּדָא דְאֶמְצָעִיתָא,</p>\n<p>וְדָא אִיהוּ נָשְׂאוּ נְהָרוֹת קוֹלָם (שם צג ג), תְּרֵין יַרְכִין אָזְלִין לָהּ לְגַבֵּי בַּעִִלָהּ, וּתְרֵין דְּרוֹעִין אִינוּן מְקַבְּלִין לָהּ לְגַבֵּי בַּעִִלָהּ, וּבְגִין דָּא תְּרֵין נְהָרוֹת אִתְּמַר בְּהוֹן נָשְׂאוּ נְהָרוֹת יהו\"ה, וּתְרֵין תִּנְיָינִין יִשְׂאוּ נְהָרוֹת (שם).</p>\n<p>וְעוֹד אִתְּמַר בָּהּ סְלִיקוּ וּנְחִיתוּ, כְּגַוְונָא דָא, כַּד סָלְקִין לָהּ לְגַבֵּי עַמּוּדָא דְאֶמְצָעִיתָא אִתְּמַר בֵּיהּ נָשְׂאוּ נְהָרוֹת קוֹלָם, אֲבָל כַּד נָחֲתִין לָהּ לְגַבֵּי צַדִּיק אִתְּמַר בֵּיהּ יִשְׂאוּ נְהָרוֹת דָּכְיָם,</p>\n<p>וּמַה דַּהֲוָה סֶגוּלָה לְעִילָא כְּגַוְונָא דָא כַּד נָחְתָא לְגַבֵּי צַדִּיק אִתְעֲבִידַת סֶגוֹ\"ל כְּגַוְונָא דָא</p>\n<p>וּבְגִין דָּא מַה דַּהֲוַת לְעִילָא אִתְנַטְּלַת (נ\"א אתחזרת) לְתַתָּא, וּבְגִין דָּא אִתְקְרִיאַת בְּצַדִּיק דָּכְיָם.</p>\n<p>וּבָהּ מַיִם הַתַּחְתּוֹנִם בָּכָאן, בְּגִין דְּאִינוּן תַּרְעִין דְּדִמְעָה, וַעֲלַיְיהוּ אִתְּמַר שַׁעֲרֵי דִּמְעָה לֹא נִנְעָלוּ, וּבְגִין דְּאִיהִי דִמְעָה דִלְהוֹן, דָּכְיָם וַדַּאי,</p>\n<p>וְצַדִּיק בָּהּ דָּ\"ךְ יָ\"ם, וְהָא אוּקְמוּהוּ (שם עד כא) אַל יָשׁוֹב דַּךְ נִכְלָם,</p>\n<p>וּבֵיהּ אֶל דִּמְעָתִי אַל תֶּחרַשׁ (שם לט יג), וַעֲלָהּ אִתְּמַר (שמות ג ט) צַעֲקַת בְּנֵי יִשְׂרָאֵל בָּאָה אֵלָי.</p>\n<p>תְּנוּעָה דְסָלִיק לָהּ לְגַבֵּי בַעִִלָהּ דָּא רָבִי\"עַ,</p>\n<p>וּבְהַהוּא זִמְנָא אִתְקְרֵי זָקֵ\"ף גָּדוֹ\"ל, וְאִיהִי אִתְקְרִיאַת קִרְיַת מֶלֶךְ רָב,</p>\n<p>וּבְאָן אִיהוּ זַקְפָא לְגַבֵּיהּ, בִּתְרֵין נְהָרוֹת, דְּאִתְּמַר בְּהוֹן (שם טו ו) יְמִינְךָ יהו\"ה נֶאְדָּרִי בַּכֹּחַ יְמִינְךָ יהו\"ה תִּרְעַץ אוֹיֵב,</p>\n<p>וַעֲלַיְיהוּ אִתְּמַר (תהלים טז יא) נְעִימוֹת בִּימִינְךָ נֶצַח, מַאי בִּימִינְךָ דָא גְדוּלָה,</p>\n<p>בְּהַהוּא זִמְנָא אִתְקְרֵי זָקֵ\"ף גָּדוֹ\"ל, וְכַד נָחֲתַת בְּצַדִּיק אִתְקְרִיאַת זָקֵף קָטָ\"ן, וּמַאי אִיהִי תְּנוּעָה דְקָא נָחִית לָהּ, דָּא תְּבִי\"ר,</p>\n<p>רָבִי\"עַ לִימִינָא, אֶרֶךְ אַפַּיִם עַל בֵּינוּנִים, וּבֵיהּ אִיהוּ מַאֲרִי\"ךְ, תְּבִי\"ר לִשְׂמָאלָא, תְּבִירוּ דְחַיָּיבַיָּא,</p>\n<p>חַד סָלִיק בִּתְקִיעָ\"ה וּמַאֲרִיךְ בָּהּ, וְחַד נָחִית לָהּ בִּשְׁבָרִי\"ם, שַׁלְשֶׁלֶ\"ת דָּא תְרוּעָ\"ה קִשּׁוּרָא דְתַרְוַיְיהוּ,</p>\n<p>דִיּוֹקְנָא דְשׁוּרֵ\"ק דִּלְתַתָּא, בְּשַׁלְשֶׁלֶ\"ת סָלְקָא, בְּשֻׁרֵ\"ק נָחְתָא, הַאי אִיהוּ סֻלָּם (נ\"א חל\"ם) דְּסָלְקָא לְעִילָא, וְהַאי אִיהוּ סֻלָּם (נ\"א חירק) דְּנָחְתָא לְתַתָּא, וְהַיְינוּ דַרְגָּ\"א תְרֵ\"י טַעֲמֵ\"י.</p>\n<p>וְעִנּוּיָא דִשְׁכִינְתָּא אַף עַל גַּב דְּאִיהִי בִּתְלַת סִטְרִין, בִּתְקִיעָ\"ה דְאִיהִי דִינָא רַפְיָא רָפֵ\"ה, וּבִשְׁבָרִי\"ם דְּאִיהוּ דִינָא קַשְׁיָא דָגֵ\"שׁ גְּבוּרָה, לֵית לָהּ עִנּוּיָא כְּעִנּוּיָא דְבַעִִלָהּ דְּאִיהוּ תְרוּעָ\"ה, שַׁלְשֶׁלֶ\"ת,</p>\n<p>וְרָזָא דְמִלָּה אֵין קוֹל עַנוֹת גְּבוּרָה (שמות לב יח) דָא שְׁבָרִי\"ם, וְאֵין קוֹל עַנוֹת חֲלוּשָׁה דָא תְּקִיעָ\"ה, אֶלָּא קוֹל עַנּוֹת אָנֹכִי שׁוֹמֵעַ דָּא תְרוּעָ\"ה, דְּסָלְקָא בְּעִנּוּיָיא דָא בָתַר דָּא כִּתְרוּעָה,</p>\n<p>וּבְגִין דָּא אַשְׁרֵי הָעָם יוֹדְעִי תְרוּעָה (תהלים פט טז), אַף עַל גַּב דִּשְׁכִינְתָּא אִיהִי בְּעִנּוּיָיא מִימִינָא וּמִשְּׂמָאלָא, לֵית עִנּוּיָיא כְּעִנּוּיָא דְבַעִִלָהּ,</p>\n<p>תְּרוּעָ\"ה דְאִיהִי תוֹרָ\"ה עַיִ\"ן אַנְפִּין, וְאִיהִי תְרוּעָה דִילֵיהּ, וּבְגִין דָּא</p>"],[9500011095,"<p>אַשְׁרֵי הָעָם יוֹדְעִי תְרוּעָה.</p>\n<p>דָּבָר אַחֵר קוֹל עַנוֹת אָנֹכִי שׁוֹמֵעַ (שמות לב יח), דָּא אִיהוּ עִנּוּיָא דְאָנֹכִי שׁוֹמֵעַ, דְּאִיהִי צָוְוחַת בְּכָל יוֹמָא לְמַעִִלָה, הִיא וּבְנָהָא, וְקָרָאן לֵיהּ תְּרֵין זִמְנִין עִִרֶב וָבֹקֶר שְׁמַע יִשְׂרָאֵל,</p>\n<p>וְכָל בַּר נַשׁ דְּאִית לֵיהּ עִנּוּי מִשְּׁכִינְתָּא, דְאִיהִי עַנְיָא בְגָלוּתָא, רְחִיקָא מִן בַּעִִלָהּ, וְקָרָא לֵיהּ בְּכָל יוֹמָא שְׁמַע יִשְׂרָאֵל, דִּיְהֵא נָחִית לְגַבָּהּ, וַדַּאי עֲלֵיהּ אִתְּמַר קוֹל עַנּוֹת אָנֹכִי שֹׁמֵעַ, קוֹל דְּעִנּוּיָא דְהַאי עַנְיָא אָנֹכִי שֹׁמֵעַ.</p>\n<p>קָם אֶחָד בְּקִירְטָא וְדָא שְׁכִינְתָּא תַּתָּאָה, וְחַד בְּקַשְׁתָּא דָא בְרִית צַדִּיק, עֲלֵיהּ אִתְּמַר שׁוֹפָ\"ר הוֹלֵ\"ךְ פָּזֵ\"ר גָּדוֹ\"ל, גִּירִין דִּילָהּ אִינוּן צַדִּיקִים דְּיִשְׂרָאֵל דְּקַבִּילוּ בְרִית, דְּבִזְכוּתֵיהּ נָפְקִין מִגָּלוּתָא,</p>\n<p>וְרָזָא דְמִלָּה (בראשית מז כג) הֵא לָהֶם זֶרַע, דְּאִינוּן טִיפִּין וְדָּא</p>\n<p>וְדָּא זַרְקָ\"א.</p>\n<p>קָמוּ תַּנָּאִין וַאֲמוֹרָאִין דִּלְעִילָא וּבָרִיכוּ לֵיהּ, וְאָמְרוּ מַטָּרָה (נ\"א עטרה) תְּהֵא אֲגִינַת עֲלָךְ מֵחִצִּים בְּגָלוּתָא, עֲלָךְ אִתְּמַר (תהלים צא ה) לֹא תִירָא מִפַּחַד לָיְלָה מֵחֵץ יָעוּף יוֹמָם, וְקַשְׁתָּא וְחִצָּא דְסִטְרָא דִקְדוּשָׁה יָגֵן עֲלָךְ, וְתַחַת כְּנָפָיו תֶּחְסֶּה צִנָּה וְסֹחֵרָה אֲמִתּוֹ,</p>\n<p>צִנָּה דָא שְׁכִינְתָּא תַּתָּאָה, וְסֹחֵרָה דָא שְׁכִינְתָּא עִלָּאָה, אֲמִתּוֹ דָא עַמּוּדָא דְאֶמְצָעִיתָא.</p>\n<p>קָם אִיהוּ וְאָמַר תַּנָּאִין תַּנָּאִין מִשְׁנֶה תְּהֵא בְּעִִזְרַיְיכוּ, וְלָא תִּשְׁתַּנִּיאוּ מֵרַחֲמֵי לְדִינָא,</p>\n<p>הֲלָכָה אָזְלַת לִימִינָא דִלְכוֹן, לְאִתְגַבְּרָא בָּהּ עַל שַׂנְאֵכוֹן, קַבָּלָה תִּתְקַבֵּל צְלוֹתְכוֹן, בְּרַיְיתָא אֲפִיקַת לְכוֹן וְלִבְנַיְיכוּ מִגָּלוּתָא, וּמִשִּׁעִִבּוּדָא וְדִינָא דְהַהוּא דִמְמַנָּא עַל גָּלוּתָא עַל בְּנַיְיכוּ,</p>\n<p>מִיָּד דְּבָרִיךְ לוֹן סָלִיק לְאַתְרֵיהּ.</p>\n<p>קָם רַבִּי שִׁמְעוֹן בְּקַדְמֵיתָא פָּתַח וְאָמַר, תַּנָּא תַּנָּא אִסְתַּמַּר לָךְ, דְּהָא קִירְטָא לְגַבָּךְ, וְדָא שְׁכִינְתָּא, וּבָהּ אִזְדְּרִיקוּ תְלַת אַבְנִין, דְּאִינוּן תְּלַת טִפִּין דְּמוֹחָא עִלָּאִין, דְּאִינוּן י'י'י', וְאִתְכְּלִילוּ בְּחָכְמָה בִּתְבוּנָה וּבְדַעַת.</p>\n<p>אָמַר לֵיהּ רַבִּי שִׂים בַּסֶּלַע קִנֶּךָ, דְּהָא קַשְׁתָּא לְגַבָּךְ דְּאִיהוּ אוֹת הַבְּרִית, אִסְתַּמַּר מִגִּירִין דִּילֵיהּ, דְּאִינוּן תְּלַת ו'ו'ו', דְּסָלְקִין חַ\"י בְּחוּשְׁבַּן, וְדָא חַ\"י עָלְמִין.</p>\n<p>קָם תַּנָּא תִּנְיָינָא וְאָמַר לֵיהּ, הָא תַּנְיָא דִמְסַיֵּיעַ לָךְ, בְּרוּמְחָא דְאִיהוּ כְּלִילָא מֵאַרְבַּע פַּרָשִׁיָּין, וְדָא ו' דְּאִיהוּ עַמּוּדָא דְאֶמְצָעִיתָא, כְלִיל שִׁית תֵּיבִין דְּיִחוּדָא, וְרַמַ\"ח תֵּיבִין דְּאִתְּמַר בֵּיהּ (במדבר כד כא) וְשִׂים בַּסֶּלַע קִנֶּךָ.</p>\n<p>דְּהָא קַרְנֵי פָרָה [ציור] לְגַבָּךְ, דְּאִנּוּן תְּרֵין נְבִיאֵי קְשׁוֹט,</p>\n<p>עֲלַיְהוּ אִתְּמַר (תהלים קלב יז) אַצְמִיחַ קֶרֶן לְדָוִד, וּמַצְמִיחַ קֶרֶן יְשׁוּעָה</p>\n<p>מִסִּטְרָא דִשְׁכִינְתָּא אִתְקְרֵי קַרְנֵי פָרָה, מִסִּטְרָא דְשׁוֹר (דברים לג יז) וְקַרְנֵי רְאֵם קַרְנָיו, וְאִינוּן מָשִׁיחַ רִאשׁוֹן וְשֵׁנִי י' ו', בַּיִת רִאשׁוֹן וְשֵׁנִי ה\"ה.</p>\n<p>וּשְׁכִינְתָּא נַטְלָא פּוּרְפִּירָא מֵאֶשָּׁא סוּמְקָא וְאִצְטַבְּעַת בָּהּ, וְאִתְקְרִיאַת סוּמְקָא</p>\n<p>פָרָה אֲדֻמָּה תְּמִימָה (במדבר יט ב), אֲדוּמָה וַדַּאי מִסִּטְרָא דִגְבוּרָה, תְּמִימָה מִסִּטְרָא דְהַהוּא דְאִתְּמַר בֵּיהּ (בראשית יז א) הִתְהַלֵּךְ לְפָנַי וְהְיֵה תָמִים,</p>\n<p>אֲשֶׁר אֵין בָּהּ מוּם מִסִּטְרָא דְיַעֲקֹב דְּלֵית בֵּיהּ פְּסוֹלֶת, דְּאִתְּמַר בֵּיהּ (שם כה כז) וְיַעֲקֹב אִישׁ תָּם, יַעֲקֹב דִּלְעִילָא, וּבְדִיּוֹקְנֵיהּ יַעֲקֹב דִּלְתַתָּא, אֲשֶׁר לֹא עָלָה עָלֶיהָ עוֹל (במדבר יט ב), מִשִּׁעִִבּוּדָא דְגָלוּתָא, בְּגִין דְּאִיהִי שְׁכִינְתָּא עִלָּאָה אִתְקְרִיאַת,</p>\n<p>וְלָא עוֹד אֶלָּא דְאִיהִי אִתְקְרִיאַת שַׁבָּת, דְּאִיהִי אָסוּר בִּמְלָאכָה, בְּגִין דְּאִתְקְרִיאַת חֵרוּת.</p>\n<p>וּשְׁלֹמֹה בְגִינָהּ אָמַר (קהלת ז כג) אָמַרְתִּי אֶחְכָּמָה וְהִיא רְחוֹקָה מִמֶּנִּי, בְּגִין פָּרָה אֲדוּמָה דְאִיהִי מְטַהֶרֶת אֶת הַטָּמֵא וּמְטַמְּאָה אֶת הַטָּהוֹר דְּאִתְעַסַּק בָּהּ,</p>\n<p>וְרָזָא דְמִלָּה מִי יִתֵּן טָהוֹר מִטָּמֵא לֹא אֶחָד (איוב יד ד), מְטַהֶרֶת אֶת הַטָּמֵא מִסִּטְרָא דִימִינָא, דְּכַהֲנָא מִסִּטְרָא דִימִינָא אִתְקְרֵי אִישׁ טָהוֹר, בְּגִין דִּלְסִטְרָא (נ\"א דסטרא) דִימִינָא אִיהִי מַיָּא דְאוֹרַיְיתָא, אַף עַל גַּב דִּיְהֵא טָמֵא אִתְדַּכִּי בָּהּ, וּמְטַמֶּאֶת אֶת הַטָּהוֹר דָּא גְבוּרָה, דִלְסִטְרָא סמא\"ל דְּנָפַל מִקְּדוּשָׁתֵיהּ, וּמַה דַּהֲוָה טָהוֹר סָאִיב לֵיהּ, בְּגִין דְּשַׁלִּיט</p>"],[9500011096,"<p>עַל חֲיָילִין דִּמְסָאֲבוּ,</p>\n<p>וְכַהֲנָא דְאִיהוּ טָהוֹר כַּד הֲוָה מִשְׁתַּדֵּל לְקָרְבָא לֵיהּ לַעֲזָאזֵל, הֲוָה מְטַהֵר לְיִשְׂרָאֵל מִכָּל חוֹבִין דִּלְהוֹן, כְּמָה דְאַתְּ אָמַר (ויקרא טז ל) כִי בַּיּוֹם הַזֶּה יְכַפֵּר עֲלֵיכֶם לְטַהֵר אֶתְכֶם וכו',</p>\n<p>וְאִיהוּ דַהֲוָה טָהוֹר הֲוָה מִתְטַמֵּא בְהַהוּא עֲזָאזֵל,</p>\n<p>וְהָכִי לְמֵי נִדָּה הֲוָה כַהֲנָא מְטַהֵר לָהּ, וְאִיהוּ הֲוָה מִסְתָּאֵב עַד עִדָּן רַמְשָׁא דַהֲוָה מִתְדַכֵּי.</p>\n<p>וְעוֹד מְטַהֶרֶת אֶת הַטָּמֵא, כַּד נוֹלַד מֹשֶׁה אִתְּמַר בֵּיהּ (לגבי בת פרעה) (שמות ב ב) וַתֵּרֶא אוֹתוֹ כִּי טוֹב הוּא, דְחָמַאת עִמֵּיהּ שְׁכִינְתָּה, וּמִיָּד דְּנָגְעָה (איהי) בֵּיהּ בַּת פַּרְעֹה אִתְדַּכִּיאַת וְאִתְּסִיאַת מִצָּרַעִִתָּא דִילָהּ, וּמֹשֶׁה אִתְדַּבְּקַת בֵּיהּ צָרַעַת, כְּמָה דְאַתְּ אָמַר (שם ד ו) וְהִנֵּה יָדוֹ מְצוֹרַעַת כַּשָּׁלֶג,</p>\n<p>דִּבְהַהוּא זִמְנָא דְנָגְעָה בֵיהּ בַּת פַּרְעֹה, פָרְחַת שְׁכִינְתָּא מִנֵּיהּ, וּבְגִין דָּא כַד בָּעָא לְאִתְקָרְבָא לְגַבָּהּ בַּסְּנֶה, אָמְרָה לֵיהּ אַל תִּקְרַב הֲלוֹם שַׁל נְעָלֶיךָ מֵעַל רַגְלֶיךָ (שם ג ה) עַד דְּיִתְפַּשַּׁט מֵהַהוּא גוּפָא דְנָגְעַת בֵּיהּ בַּת פַּרְעֹה,</p>\n<p>תַּמָּן אַחֲזֵי לֵיהּ, דְּגוּפָא דְבַר נַשׁ בְּהַאי עָלְמָא, אִיהוּ צָרַעַת מִמַּשְׁכָא דְחִוְיָא.</p>\n<p>לְבָתַר דְּאִתְפַּשַּׁט מִנֵּיהּ, וְהָדַר לְגִנְּתָא דְעִדֶן, אִתְלַבַּשׁ בְּגוּפָא קַדִּישָׁא דִילֵיהּ, וְדָא אִיהוּ וְהִנֵּה שָׁבָה כִּבְשָׂרוֹ (שם ד ה),</p>\n<p>וְהָכִי אִתְלַבַּשׁ מֹשֶׁה בָּהּ, וְדָא אִיהוּ וְהִנֵּה שָׁבָה כִּבְשָׂרוֹ, כְּקַדְמֵיתָא דְאִתְּמַר בֵּיהּ (בראשית ב כג) עִִצֶם מֵעֲצָמַי וּבָשָׂר מִבְּשָׂרִי,</p>\n<p>וּבְגִין דָּא אָמַר לֵיהּ שַׁל נְעָלֶיךָ מֵעַל רַגְלֶיךָ (שמות ג ה), דָּא גוּפָא דַהֲוָה לֵיהּ כְּנַעַל, הַהוּא דְנָגְעָה בֵיהּ בַּת פַּרְעֹה, וְאִתְלַבַּשׁ בְּאָחֳרָא, וּבְהַהוּא זִמְנָא אַהֲדַרַת עֲלֵיהּ שְׁכִינְתָּא.</p>\n<p>וּבְגִין דָּא אִתְחֲזֵי (נ\"א אחזי) לֵיהּ בְּאָתִין דְּעָבַד בְּאָת קַדְמָאָה, וְאָמַר לֵיהּ הָבֵא נָא יָדְךָ בְּחֵיקֶךָ וכו' (שם ד ו), וְאַמַּאי בְּחֵיקֶךָ, הָכָא רָמִיז מִשּׁוֹכֶבֶת חֵיקֶךָ שְׁמוֹר פִּתְחֵי פִיךָ (מיכה ז ו), וְהִנֵּה מְצוֹרַעַת כַּשָּׁלֶג (שמות ד ו),</p>\n<p>וּלְבָתַר אַחֲזֵי לֵיהּ דְּאִתְדַּכְיָא בְאוֹרַיְיתָא, הֲדָא הוּא דִכְתִיב בָּהּ (שם) וְהִנֵּה שָׁבָה כִּבְשָׂרוֹ.</p>\n<p>וְעוֹד שְׁכִינְתָּא תַּתָּאָה אִיהִי עִִגְלָה עֲרוּפָה, וּמִסִּטְרָא דְפָרָה שׁוֹר, וְדָא אִיהוּ וּפְנֵי שׁוֹר מֵהַשְּׂמֹאל (יחזקאל א י), וּמִסִּטְרָא דְעִִגְלָה, עִגֶל בֶּן בָּקָר לְחַטָּאת (ויקרא ט ב), וּפָרָה וַדַּאי אִתְקְרִיאַת שְׁכִינְתָּא עִלָּאָה כַּד נָטְלַת מִן גְּבוּרָה, וּשְׁכִינְתָּא תַּתָּאָה עִִגְלָה כַּד נְטִילַת מִנֵּיהּ.</p>\n<p>וְעוֹד קַרְנֵי פָרָה נֶצַח וָהוֹד, בָּהֶם עַמִּים יְנַגַּח יַחְדָּיו (דברים לג יז), קַרְנֵי רְאֵם חֶסֶד גְּבוּרָה, דְיַעֲבִיד בְּהוֹן קְרָבָא בַעֲמָלֵק, וְיִמְחֵי לֵיהּ וּלְזַרְעִיהּ מִן עָלְמָא.</p>\n<p>וְעוֹד קַרְנֵי פָרָה אִלֵּין תַּלְמִידֵי חֲכָמִים דְּמִתְוַוכְּחִין דָּא עִם דָּא בְאוֹרַיְיתָא, וּמִתְנַגְּחִין כַּשְּׁוָורִים דָּא עִם דָּא, בְּגִין דְּאוֹרַיְיתָא דְעַל פֶּה אִיהִי מִסִּטְרָא דִגְבוּרָה דְאִתְקְרֵי אלהי\"ם, וּבֵיהּ פָּתְחַת אוֹרַיְיתָא בְּרֵאשִׁית בָּרָא אלהי\"ם,</p>\n<p>בְּגִין דָּא תַּלְמִידֵי חֲכָמִים אִינוּן מִתְנַגְּחִין בְּאוֹרַיְיתָא כַּשְּׁוָורִים דָּא עִם דָּא, וּבְגִין דָּא יהו\"ה כַּגִּבּוֹר יֵצֵא (ישעיה מב יג) מִסִּטְרָא דִגְבוּרָה, יָרִיעַ בִּתְרוּעָה, יַצְרִיחַ בַּשְּׁבָרִים, עַל אוֹיְבָיו יִתְגַּבָּר בִּתְקִיעָה</p>\n<p>בְּהַהוּא זִמְנָא כָל סְפִירָן נָטְלִין מִגְּבוּרָה, וּשְׁמָא דְיו\"ד ה\"א וא\"ו ה\"א, וַאֲפִילוּ מַלְאָכִים דִּלְעִילָא, וְיִשְׂרָאֵל דִּלְתַתָּא.</p>\n<p>וּלְבָתַר דְּנָטִיל נוּקְמָא מִנַּיְיהוּ, יִתְמַלֵּא רַחֲמִין עַל יִשְׂרָאֵל, וְקֳדָם דִּיְהֵא נָטִיל נוּקְמָא מֵעֲמָלֵק, לָא יְתִיב בְּכָרְסַיָּא,</p>\n<p>וּבְהַהוּא זִמְנָא דְנָטִיל נוּקְמָא מִבְּנֵי עִשָׂו, יֵיתֵי לְפַיְיסָא לְאַיָּלָתָא, וְאִיהִי גַעִִיָ\"א וּבוֹכָה, הֲדָא הוּא דִכְתִיב (ירמיה לא יד) רָחֵל מְבַכָּה עַל בָּנֶיהָ, עַד דְּאוֹמֵי לָהּ קוּדְשָׁא בְּרִיךְ הוּא לְאַעֲבָרָא לוֹן מֵעָלְמָא, וְיִקְטוֹל בְּהוֹן, עַד דְּיִצְטַבַּע יַמָּא מִן דִּמְהוֹן, וְיִקְטוֹל בְּהוֹן עַד דְּיִתְפַּרְנְסוּן מִנְּהוֹן חֵיוָון בָּרָא תְּרֵי עֲשַׂר שְׁנִין, וְעוֹפִין דִּשְׁמַיָּא שֶׁבַע שְׁנִין.</p>\n<p>וְעוֹד גַּעִִיָ\"א, תַּלְשָׁ\"א, אַזְלָ\"א גְרִי\"שׁ,</p>\n<p>גַּעִִיָ\"א בִתְרוּעָה, וְיָהִיב בְּהוֹן סְקִילָה, הֲדָא הוּא דִכְתִיב (ישעיה לד יא) וְנָטָה עָלֶיהָ קַו תֹהוּ וְאַבְנֵי בֹהוּ,</p>\n<p>תַּלְשָׁ\"א בַּשְּׁבָרִים תֵּ\"ל אֵ\"שׁ (ודא שריפה), תֵּ\"ל דָּא חָנֵק, כְּגַוְונָא דָא אֵ\"שׁ שְׂרֵיפָה,</p>\n<p>אַזְלָ\"א גְרִי\"שׁ בִּתְקִיעָה, דְאִיהוּ כְּרוּמְחָא לְקַטְלָא לוֹן בַּהֶרֶג.</p>\n<p>שַׁלְשֶׁלֶ\"ת תְּרוּעָה לְמִתְפַּשׂ לוֹן אֲסוּרִין בְּבֵית אֲסוּרִין דְּמַלְכָּא, כְּמָה דְאַתְּ אָמַר (תהלים קמט ה) לֶאְסוֹר מַלְכֵיהֶם בְּזִיקִים וכו',</p>\n<p>שׁוֹפָ\"ר הוֹלֵ\"ךְ, פָּסֵ\"ק, מַקַּ\"ף, קָלָא דְשׁוֹפָרָא סָלְקָא בִתְרוּעָה</p>"],[9500011097,"<p>כְרוּמְחָא, לְעוֹרֵר עֲלַיְיהוּ קוֹל תְּרוּעַת מִלְחָמָה, וְדָא שׁוֹפָ\"ר הוֹלֵ\"ךְ,</p>\n<p>פָּסֵק דָּא שְׁבָרִים דְּעָבִיד לוֹן פְּסָקוֹת וְקָטְרִין (נ\"א וקרטין או וקרעין), וְדָא מַכַּת חֶרֶב וְהֶרֶג וְאַבְּדָן,</p>\n<p>מַקַּף תְּרוּעָה דָּא חָנֵק, וְדָא אִיהוּ הוֹלֵךְ וְחָזֵק מְאֹד (שמות יט ט), מְאֹד דָּא מָוְת דְּאִתְתַּקַּף עֲלַיְיהוּ, כְּגַוְונָא דְמַתַּן תּוֹרָה.</p>\n<p>וְעוֹד אַזְלָ\"א גְרִי\"שׁ, שְׁכִינְתָּא אָמְרַת לְקוּדְשָׁא בְּרִיךְ הוּא, גָּרֵשׁ הָאָמָה הַזֹּאת וְאֶת בְּנָהּ (בראשית כא י) אִלֵּין עִרֶב רַב, (ש\"א כו יט) דְּגֵרְשׁוּנִי מֵהִסְתַּפֵּחַ בְּנַחֲלַת יהו\"ה, גַּרֵישׁ לוֹן מִן עָלְמָא דֵין וּמֵעָלְמָא דְאָתֵי, דְלָא יְהֵא לוֹן חוּלָקָא עִם יִשְׂרָאֵל,</p>\n<p>שׁוֹפָ\"ר הוֹלֵ\"ךְ, רָבִי\"עַ, שְׁנֵ\"י גְרִישִׁי\"ן, שַׁלְשֶׁלֶ\"ת,</p>\n<p>בְּהַהוּא זִמְנָא נָטִיל קוּדְשָׁא בְּרִיךְ הוּא רוֹמַ\"ח, דְּאִיהִי רְמַ\"ח תֵּיבִין דְּאִית בִּקְרִיאַת שְׁמַע וְשִׁית תֵּיבִין דְּיִחוּדָא, וּבָהּ (במדבר כה ח) וַיִּדְקֹר אֶת שְׁנֵיהֶם, דְּכַר וְנוּקְבָא, דָא סמא\"ל וְנָחָשׁ, וְרָבִי\"עַ דִּיּוֹקְנָא דוּמְיָא דְרוֹמַ\"ח.</p>\n<p>שְׁנֵ\"י גְרִישִׁי\"ן, תָּרֵיךְ לוֹן קוּדְשָׁא בְּרִיךְ הוּא מִן שְׁמַיָּא וְאַרְעָא, בְּהַהוּא זִמְנָא שֶׁקֶר הַסּוּס לִתְשׁוּעָה וכו' (תהלים לג יז), דְּקוּדְשָׁא בְּרִיךְ הוּא רָדִיף אַבַּתְרַיְיהוּ, וְנָטִיל לוֹן בְּשַׁלְשֶׁלֶ\"ת עַל צַוָּארֵיהוֹן, וּלְבָתַר קָטִיל לוֹן בְּרוּמְחָא דְאִיהוּ רָבִי\"עַ,</p>\n<p>בְּקַדְמֵיתָא תָרֵיךְ לוֹן, וּלְבָתַר רָדִיף אַבַּתְרַיְיהוּ וְתָּפִיס לוֹן, וּלְבָתַר קָטִיל לוֹן.</p>\n<p>וְרָבִי\"עַ, וּשְׁנֵ\"י גְרִישִׁי\"ן, וְשַׁלְשֶׁלֶ\"ת, אִינוּן תְּקִיעָ\"ה שְׁבָרִי\"ם תְּרוּעָ\"ה,</p>\n<p>שְׁבָרִי\"ם שַׁבֵּר (שמות כג כד) תְּשַׁבֵּר מַצֵּבוֹתֵיהֶם, אִלֵּין דְּאִתְּמַר בְּהוֹן (איוב א ו) וַיָּבֹאוּ בְּנֵי הָאלהי\"ם לְהִתְיַצֵּב עַל יהו\"ה, בְּדִינָא עַל שְׁכִינְתָּא וְיִשְׂרָאֵל, דְאִתְּמַר בֵּיהּ וַיָּבֹא גַם הַשָּׂטָן בְּתוֹכָם, דָּא סמא\"ל דְּאָתָא לְקַטְרֵג עַל בְּנוֹי דְּיִשְׂרָאֵל, וְלָדוּן לִשְׁכִינְתָּא, וְכֵיוָן דְּהוּא בָעִי דִינָא עַל שְׁכִינְתָּא וּבְנוֹי, כְּאִלּוּ קַיְימִין עֲלֵיהּ,</p>\n<p>תְּרוּעָ\"ה בָהּ (תהלים ב ט) תְּרוֹעִם בְּשֵׁבֶט בַּרְזֶל,</p>\n<p>תְּקִיעָ\"ה וְהוֹקַע אוֹתָם לַיהו\"ה נֶגֶד הַשָּׁמֶשׁ (במדבר כה ד), וְשׁוֹפָר אִיהוּ קָלָא, מִנֵּיהּ נָפִיק קָלָא בִתְקִיעָה שְׁבָרִים תְּרוּעָה,</p>\n<p>תְּקִיעָה מִן מוֹחָא, שְׁבָרִים מִלִּבָּא, כְּמָה דְאַתְּ אָמַר (תהלים נא יט) לֵב נִשְׁבָּר וְנִדְכֶּה וְגוֹמֵר, דָּא אִיהוּ זִבְחֵי אלהי\"ם רוּחַ נִשְׁבָּרָה, קָלָא בִתְרוּעָה מִכַּנְפֵי רֵיאָה, וְכֻלְּהוּ אִתְכְּלִילוּ בְקָנֶה וְרֵיאָה, וְאִתְעֲבִידוּ קוֹל, וּבְפוּמָא דִבּוּר.</p>\n<p>וְעוֹד נִשְׁמָתָא וְרוּחָא וְנַפְשָׁא דְבַר נַשׁ, אִינוּן תְּקִיעָה תְּרוּעָה שְׁבָרִים,</p>\n<p>נַפְשָׁא בְּלִבָּא וְדָא שְׁבָרִים, כְּמָה דְאַתְּ אָמַר לֵב נִשְׁבָּר וְנִדְכֶּה,</p>\n<p>נִשְׁמָתָא בְמוֹחָא וְדָא תְקִיעָה,</p>\n<p>רוּחָא בְּכַנְפֵי רֵיאָה, דְנָשִׁיב עַל לִבָּא דְאִיהוּ נוּר דָּלֵיק, וְאִם לַאו הֲוָה דָלֵיק כָּל גּוּפָא, וְרָזָא דְמִלָּה כַּנְפֵי יוֹנָה נֶחְפָּה בַכֶּסֶף וְגוֹמֵר (שם סח יד), וְרוּחָא כְּלִיל מֵאֶשָּׁא וּמַיָּא, וּבְגִין דָּא אִיהוּ תְרוּעָה,</p>\n<p>וַעֲלֵיהּ אִתְּמַר (שם פט טז) אַשְׁרֵי הָעָם יוֹדְעִי תְרוּעָה, בְּגִין דְּנִשְׁמָתָא אִיהִי נִשְׁמַת חַיִּים, בִּינָה דְנָטְלָה מֵחָכְמָה, נֶפֶשׁ מַלְכוּת תְּבוּנָה, רוּחַ תִּפְאֶרֶת, וְאִיהוּ דַעַת כְּלִיל תַּרְוַיְיהוּ, עֲלֵיהּ אִתְּמַר (משלי כד ד) וּבְדַעַת חֲדָרִים יִמָּלְאוּ.</p>\n<p>וּמִבִּינָה נְבִיאִים, וְאִינוּן נֶצַח וָהוֹד, וּמִמַּלְכוּת כְּתוּבִים וְאִינוּן חֶסֶד וּגְבוּרָה, תִּפְאֶרֶת תּוֹרָה כְּלִיל כֻּלְּהוּ,</p>\n<p>וְכֹלָּא עַל עַמּוּדָא חַד קַיְימָא וְדָא (משלי י כה) צַדִּיק יְסוֹד עוֹלָם.</p>\n<p>כָּבֵד וּטְחוֹל דָּא סמא\"ל וְנָחָ\"שׁ, כָּבֵד אֶשָּׁא סוּמְקָא, מָרָה אֶשָּׁא יְרוֹקָא, טְחוֹל אֶשָּׁא אוּכְמָא, יוֹתֶרֶת כְּלִילָא דְכֻלְּהוּ, כָּבֵד וּטְחוֹל סמא\"ל וְנָחָ\"שׁ, כָּבֵד אֵל אַחֵר, מָרָה סַם מָוְת דִּילֵיהּ, טְחוֹל נָחָשׁ נוּקְבָא דִילֵיהּ, חֵלֶב טָמֵא, וּמָרָה אִיהוּ חַרְבָּא דְמַלְאַךְ הַמָּוְת, כְּמָה דְאַתְּ אָמַר (שם ה ד) וְאַחֲרִיתָהּ מָרָה כַלַּעֲנָה חַדָּה כְּחֶרֶב פִּיּוֹת,</p>\n<p>וּבְאוֹרַיְיתָא דְאִיהִי סַם חַיִּים אִי נִשְׁמָתָא טָמֵא אִתְעַבְּרָא מִן עָלְמָא, (כבד וטחול דא סמא\"ל ונח\"ש, דאינהו אל אחר),</p>\n<p>וְכָבֵד דְּהוּא אֵל אַחֵר בִּתְרוּעָה דְאִיהוּ רוּחָא מִתְעַבְּרָא מִן עָלְמָא,</p>\n<p>טְחוֹל דְּהוּא נָחָשׁ בַּשְּׁבָרִים דְּאִיהוּ נֶפֶשׁ מִתְעַבְּרָא מִן עָלְמָא,</p>\n<p>מָרָה דְהוּא סַם הַמָּוְת בִּתְקִיעָה מִתְעַבְּרָא מִן עָלְמָא.</p>\n<p>זַכָּאָה אִיהוּ דְכָלֵיל נִשְׁמָתָא וְרוּחָא עִם נַפְשָׁא בְקָלָא דְאוֹרַיְיתָא, דִבְאוֹרַיְיתָא אִתְתַּקְּפוּן, דְּכָל מָאן דְּלָא אִתְעַסַּק בְּאוֹרַיְיתָא חַלִּישׁ נִשְׁמָתֵיהּ רוּחֵיהּ וְנַפְשֵׁיהּ עִילָא וְתַתָּא,</p>\n<p>וְיוֹתֶרֶת הַכָּבֵד אִיהוּ זוֹנָה, שִׁיּוּרִין אִיהוּ לְכָל אֱלֹהִים אֲחֵרִים מִתְתַּקְפָא, וְאַמַּאי אִתְקְרִיאַת יוֹתֶרֶת הַכָּבֵד, אֶלָּא בָּתַר דְּעָבִיד נִאוּפָא עִם כֻּלְּהוּ, יְהִיבַת שִׁיּוּרִין לְבַעִִלָהּ, וַעֲלָהּ אִתְּמַר (שם ד כו) כִּי בְעַד אִשָּׁה זוֹנָה עַד כִּכַּר לָחֶם, דְּאִיהִי אִתְחַמְמַת מִכָּבֵד,</p>\n<p>וּטְחוֹל</p>"],[9500011098,"<p>אִיהוּ שְׂחוֹק הַכְּסִיל, וַעֲלֵיהּ אִתְּמַר אִם רָאִיתָ רָשָׁע שֶׁהַשָּׁעָה מְשַׂחֶקֶת לוֹ אַל תִּתְגָּרֶה בּוֹ, בְּגִין דְּאִיהוּ שְׁאוֹל תַּחְתִּית, דְּאִתְּמַר בֵּיהּ צַדִּיק מִמֶּנּוּ בּוֹלֵעַ, אֲבָל צַדִּיק גָּמוּר אֵינוֹ בּוֹלֵעַ, כָּבֵד כּוֹעִס וְקָטִיל.</p>\n<p>לֵב מֵבִין, לֵב יוֹדֵעַ, לֵב רוֹאֶה, לֵב אִיהוּ שְׁכִינְתָּא, דְלָא נַטְלָא אֶלָּא דְמָא צַח, דְּאִיהִי קָרְבָּנָא דִצְלוֹתָא נְקִיָּה בְּלָא חוֹבִין וּבְלָא פְּסוֹלֶת, וּקְרִיבַת לְגַבֵּי בַּעִִלָהּ שׁוּפְרָא דְכֹלָּא.</p>\n<p>אֲבָל יוֹתֶרֶת הַכָּבֵד לָא יְהִיבַת לְבַעִִלָהּ אֶלָּא שִׁיּוּרִין וּפְסוֹלֶת, וּמַאי נִיהוּ בַּעִִלָהּ (טחול) (ס\"א כבד) אֵל אַחֵר, וּמֵאִלֵּין שִׁיּוּרִין דְּנָטִיל מִנָּהּ אִתְעֲבִיד דָּם טְחוֹל חָשׁוּךְ וְאוּכְמָא, הוּא נָחָשׁ רַמַּאי דְּפַתִּי לְחַוָּה דְּאִיהִי לִבָּא, וְגָרַם לָהּ מוֹתָא.</p>\n<p>וְהָא תְּרֵי בָּתֵּי לִבָּא אִינוּן לְמָאן פַּתִּי מִנַּיְיהוּ, אֶלָּא הַהוּא דִשְׂמָאלָא דְאִתְּמַר בָּהּ (קהלת י ב) לֵב כְּסִיל לִשְׂמֹאלוֹ,</p>\n<p>וַעֲלֵיהּ אִתְּמַר (שם ז כו) וּמוֹצֵא אֲנִי מַר מִמָּוְת אֶת הָאִשָּׁה, לֵב חָכָם לִימִינוֹ דָא אֵשֶׁת חַיִל עֲטֶרֶת בַּעִִלָהּ, עֲלָהּ אִתְּמַר (משלי יח כב) מָצָא אִשָּׁה מָצָא טוֹב, דְּאִיהִי יֵצֶר הַטּוֹב מַזָּלֵיהּ דְּבַר נַשׁ, עֲלָהּ אִתְּמַר (יחזקאל מד ל) לְהָנִיחַ בְּרָכָה אֶל בֵּיתֶיךָ, בִּרְכַּת יהו\"ה הִיא תַּעֲשִׁיר, וַעֲלָהּ אִתְּמַר (קהלת ט ט) רְאֵה חַיִּים עִם הָאִשָּׁה אֲשֶׁר אָהַבְתָּ.</p>\n<p>אִיהִי בְדִיּוֹקְנָא דִשְׁכִינְתָּא תַּתָּאָה כְּלִילָא מֵעִִשֶׂר, וְאִיהִי נֵר מִצְוָה, וְרוּחָא דְנָשִׁיב בָּהּ תִּפְאֶרֶת יִשְׂרָאֵל אִיהִי בְּכַנְפֵי רֵיאָה, וְדָא אִיהוּ וְתוֹרָה אוֹר, דְּנָהִיר בָּהּ דָּא שְׁכִינְתָּא עִלָּאָה נִשְׁמַת חַיִּים, דְּנָחֲתָא מִן מוֹחָא לְאַנְהָרָא לוֹן בְּלִבָּא.</p>\n<p>מַאי נֵ\"ר נַפְשָׁא רוּחָא,</p>\n<p>דְּנַפְשָׁא אִיהִי פְּתִילָה (נ\"א על שם דאיהי שותפא דגופא), רוּחָא דָא זֵיתָא, נִשְׁמָתָא נֵר יהו\"ה נִשְׁמַת אָדָם (משלי ב כז),</p>\n<p>(אדם דאיהי אור נר, נהיר ביה אורייתא דבכתב, ונשמתא דאיהי נר נהיר בה מצוה, ובזמנא דלא נהירין בה אור ונר אתמר בנשמתא אל תראוני שאני שחרחרת (שיר א ו), ואתמר באדם (ישעיה נ ג) אלביש שמים קדרות),</p>\n<p>וּמַאי נֵ\"ר נַפְשָׁא רוּחָא, נ' נַפְשָׁא ר' רוּחָא,</p>\n<p>לָקֳבֵל תְּלַת קִטְרִין אִלֵּין, אִינוּן תְּלַת גַּוָּונִין, אֶשָּׁא אוּכְמָא חִוְורָא וּתְכֵלְתָּא, מָאן דְּנָטִיר נֵר יהו\"ה נִשְׁמַת אָדָם בְּאוֹרַיְיתָא, בְּפִקּוּדִין דַּעֲשֵׂה וְלֹא תַעֲשֶׂה, לָא שַׁלִּיט עֲלֵיהּ נוּרָא דְגֵיהִנָּם,</p>\n<p>וְדָא אִיהוּ כָּבֵד וּמָרָה וּטְחוֹל, כָּבֵד אֶשָּׁא סוּמְקָא, מָרָה אֶשָּׁא יְרוֹקָא, טְחוֹל אֶשָּׁא אוּכְמָא, יוֹתֶרֶת הַכָּבֵד כְּלָלָא דְכֻלְּהוּ, תְּכֵלֶת חָשׁוּךְ. וּתְכֵלֶת דְּצִיצִית מִצְוָה, וּתְכֵלֶת לֵית בְּסִטְרָא אָחֳרָא, בְּגִין דְּאִיהוּ דוֹמֶה לְכָרְסַיָּא יַקִּירָא,</p>\n<p>גַּוָּונִין דִּשְׁרַגָּא אִינוּן לְבוּשִׁין לְנֵר יהו\"ה נִשְׁמַת אָדָם,</p>\n<p>גַּוָּון אוּכַם דְּאִיהוּ טְחוֹל, כַּד מִתְלַבְּשַׁת תַּמָּן נַפְשָׁא בְּחוֹבִין, אִיהִי אָמְרַת (שיר א ו) אַל תִּרְאוּנִי שֶׁאֲנִי שְׁחַרְחֹרֶת, שְׁחַרְחֹרֶת בְּקַדְרוּתָא דְבָנַי, בְּדוֹחֲקָא דִלְהוֹן בַּעֲנִיּוּתָא דִלְהוֹן,</p>\n<p>קַדְרוּתָא וְלַיְצָנוּתָא וַעֲנִיּוּתָא מִטְּחוֹל נַפְקָא, כַּד נִשְׁמָתָא אֲסִירָא בָּהּ בְּגָלוּתָא, וְדָא אִיהוּ (משלי ל כג) וְשִׁפְחָה כִּי תִירַשׁ גְּבִירְתָּהּ, וּבְהַהוּא זִמְנָא טְחוֹל שׂוֹחֵק,</p>\n<p>וּלְזִמְנָא דְיֵיתֵי מַלְכָּא מְשִׁיחָא לְנַטְלָא נוּקְמָא מִטְּחוֹל דְּאִיהִי שִׁפְחָה, (תהלים ב ד) יוֹשֵׁב בַּשָּׁמַיִם יִשְׂחָק, יִשְׂחָק אִיהוּ בְאִבּוּדָא דִלְהוֹן, כְּמָה דְאַתְּ אָמַר (משלי יא ו) וּבַאֲבֹד רְשָׁעִים רִנָּה.</p>\n<p>רִנָּ\"ה אִיהוּ הַנֵּ\"ר, אִיהוּ נָהָ\"ר יוֹצֵא מֵעִדֶן, וּמַאי נִיהוּ מִצְוֹת עֲשֵׂה וּמִצְוֹת לֹא תַעֲשֶׂה כְּחוּשְׁבַּן נָהָ\"ר, נוּ\"ן הֵ\"א רֵי\"שׁ, וְאִיהִי הַנֵּר הַמֵּאִיר לְאָדָם, וְעַל דָּא בַּאֲבֹד רְשָׁעִים רִנָּ\"ה,</p>\n<p>וּבְהַהוּא זִמְנָא הַטְּחוֹל דְּשׂוֹחֵק אִתְאֲבִיד, וְאָז יִתְקַיַּים (תהלים קכו ב) אָז יִמָּלֵא שְׂחוֹק פִּינוּ וּלְשׁוֹנֵנוּ רִנָּה וַדַּאי, וְאָז (משלי לא יח) לֹא יִכְבֶּה בַּלַּיְלָה נֵרָהּ, בְּגִין (שם) דְּטָעֲמָה כִּי טוֹב סַחְרָהּ,</p>\n<p>וּבְהַהִיא זִמְנָא מִתְתַּקְנָא יְרוּשָׁלַםִ דְּאִיהִי לִבָּא, לִבָּא אִיהוּ לַהַ\"ב הַמִּזְבֵּחַ, יִכְבֶּ\"ה בְּחוּשְׁבַּן הַלֵּ\"ב, לַהַ\"ב הֶבֶ\"ל, לֹא יִכְבֶּה בְגָלוּתָא דְאִיהִי לַיְלָה,</p>\n<p>וְאִתְבְּנִיאַת עַל יְדָא דְקוּדְשָׁא בְּרִיךְ הוּא, כְּמָה דְאַתְּ אָמַר (תהלים קמז ב) בּוֹנֵה יְרוּשָׁלַם יהו\"ה,</p>\n<p>(מאן דנטיר נר יהו\"ה נשמת אדם בפקודין דעשה ולא תעשה, לא שליט עליה נורא דגיהנם, דאיהי כבד מרה טחול).</p>\n<p>וְעוֹד מָרָה טְחוֹל כָּבֵד, אִינוּן גָּלוּתָא לְנִשְׁמָתָא וְרוּחָא וְנַפְשָׁא, דְאִיהִי שְׁכִינְתָּא כַּד גָּלַת בְּכָבֵד, אִתְּמַר בְּאֵבָרִים דְּאִינוּן עַמָּא קַדִּישָׁא חֵילָהָא דִילָהּ, תִּכְבַּד הָעֲבוֹדָה עַל הָאֲנָשִׁים (שמות ה ט), כַּד גָּלַת בְּמָרָה אִתְּמַר בָּהּ (שם א יד) וַיְמָרְרוּ אֶת חַיֵּיהֶם, כַּד גָּלַת בַּטְּחוֹל אִתְּמַר בָּהּ (שם ו ט) וְלֹא שָׁמְעוּ אֶל מֹשֶׁה מִקֹּצֶר רוּחַ (דהוה בבטנה, ומעבודה קשה דהוה בטחול), וַהֲווֹ צָוְוחִין לְקוּדְשָׁא בְּרִיךְ הוּא מִנָּהּ, הֲדָא הוּא דִכְתִיב (יונה ב ג) מִבֶּטֶן שְׁאוֹל שִׁוַּעִִתִּי שָׁמַעִִתָּ קוֹלִי, וְאִתְּמַר בְּהוֹן (שמות ב כג) וַתַּעַל שַׁוְעָתָם אֶל הָאלהי\"ם מִן הָעֲבוֹדָה,</p>\n<p>וְנִשְׁמָתָא בְגָלוּתָא בַתְרָאָה</p>"],[9500011099,"<p>אִתְּמַר בָּהּ (רות ג ז) וַתְּגַל מַרְגְּלוֹתָיו וַתִּשְׁכָּב, שְׁכִיבַת לְעַפְרָא,</p>\n<p>וַוי לֵיהּ לְבַר נַשׁ דְּנִשְׁמָתֵיהּ נְחִיתַת תְּחוֹת רַגְלוֹי, דִּבְהַהוּא זִמְנָא אִתְּמַר בְּמַזָּלֵיהּ (עמוס ה ב) נָפְלָה לֹא תוֹסִיף קוּם, וְלֵית לֵיהּ עִלּוּי וְסִלּוּק אֶלָּא בִידָא דְקוּדְשָׁא בְּרִיךְ הוּא, דְאָזִיל שְׁמָא קַדִּישָׁא לִימִינָא וְאוֹקִים לָהּ.</p>\n<p>וְרָזָא דְמִלָּה לִינִי הַלַּיְלָה וְהָיָה בַבֹּקֶר אִם יִגְאָלֵךְ טוֹב יִגְאָל (רות ג יג), טוֹב דְּאִיהוּ בְּרִית יִגְאָל, וְאִם לֹא יַחְפּוֹץ לְגָאֳלֵךְ וּגְאַלְתִּיךְ אָנֹכִי, חַי יהו\"ה שִׁכְבִי עַד הַבֹּקֶר, אָנֹכִי דְאִיהִי אִימָּא עִלָּאָה, אָנֹכִי דִיצִיאַת מִצְרַיִם,</p>\n<p>חַי יהו\"ה שִׁכְבִי עַד הַבֹּקֶר דְּאִיהִי יְמִינָא, דְבֵיהּ תּוּקְפָא דְאוֹרַיְיתָא דְבִכְתָב דְּאִיהִי עַמּוּדָא דְאֶמְצָעִיתָא, דְמִימִינָא אִתְיְיהִיבַת אוֹרַיְיתָא דְבִכְתָב, וּמִשְּׂמָאלָא אִתְיְיהִיבַת אוֹרַיְיתָא דְעַל פֶּה דְאִיהִי נוּקְבָא.</p>\n<p>וּבְגִין דָּא טוֹב צַדִּיק חַ\"י עָלְמִין אִיהוּ מִסִּטְרָא דִשְׂמָאלָא, דְאִיהוּ גִבּוֹר הַכּוֹבֵשׁ אֶת יִצְרוֹ, דְאִיהוּ סמא\"ל,</p>\n<p>וּבְגִין דָּא שְׂמֹאל דּוֹחֶה, וּבִימִינָא יֵקוּם, דְּמָאן דְּנָפִיל לָא צָרִיךְ לְאַקָּמָא אֶלָּא בִידָא יְמִינָא, וּבְגִין דָּא חַי יהו\"ה שִׁכְבִי עַד הַבֹּקֶר.</p>\n<p>וּשְׂמָאלָא אִיהִי רֹאשׁ הַשָּׁנָה, וִימִינָא פֶּסַח, וּבֵיהּ הֲוָה אוֹמָאָה בְּי\"ד יוֹמִין, וְדָא אִיהוּ כִּי יָד עַל כֵּס י\"הּ (שמות יז טז),</p>\n<p>וְעַל הַהוּא זִמְנָא אִיהִי אָמְרַת (שיר א ו) אַל תִּרְאוּנִי שֶׁאֲנִי שְׁחַרְחֹרֶת, אַל תִּרְאוּנִי מִסִּטְרָא דִשְׂמָאלָא דְיִצְחָק, דַּאֲנָא בְקַדְרוּתָא בֵיהּ,</p>\n<p>הֲדָא הוּא דִכְתִיב (בראשית כז א) וַתִּכְהֶיןָ עִינָיו מֵרְאוֹת, מֵרְאוֹת וַדַּאי בְּפוּרְקָנָא, דְּאִיהִי אוֹר מַרְאוֹת דִּנְבוּאָה, דְּאִתְּמַר בְּהוֹן (יחזקאל א א) נִפְתְּחוּ הַשָּׁמַיִם וָאֶרְאֶה מַרְאוֹת אלהי\"ם, וְדָא אִיהוּ וַתִּכְהֶיןָ עִינָיו מֵרְאוֹת מִסִּטְרָא דִשְׂמָאלָא, וְאִתְּמַר בְּהַהוּא זִמְנָא בְּקוּדְשָׁא בְּרִיךְ הוּא אַלְבִּישׁ שָׁמַיִם קַדְרוּת (ישעיהו נ ג).</p>\n<p>נֵר אִיהִי ה', חָמֵשׁ גַּוָּונִין נְהִירִין בָּהּ, וְאִינוּן חִוָּור סוּמַק יָרוֹק וְאוּכַם וּתְכֵלֶת, ו' אוֹר הַנֵּר מִלְּגָאו,</p>\n<p>סמא\"ל חֹשֶׁךְ, נָחָשׁ קַדְרוּת, וַעֲלָהּ אִתְּמַר אַלְבִּישׁ שָׁמַיִם קַדְרוּת נוּקְבָא דִילֵיהּ, וְשַׂק אָשִׂים כְּסוּתָם,</p>\n<p>וַוי לְנִשְׁמָתָא כַּד אִתְלַבְּשַׁת בְּקַדְרוּתָא דִלְהוֹן, וַעֲלֵיהּ אִתְּמַר וַתִּכְהֶיןָ עִינָיו מֵרְאוֹת,</p>\n<p>וְאִינוּן חֲשׁוֹכִין דִּמְכַסְּיָין עַל עַיְינִין, דְּלֵית לוֹן רְשׁוּ לְאִסְתַּכְּלָא בְּקוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ.</p>\n<p>וְאוֹר וְנֵר דְּנַהֲרִין (נ\"א דחשכו) בְּהוֹן, אִתְּמַר בְּהוֹן (קהלת יב ג) וְחָשְׁכוּ הָרוֹאוֹת בָּאֲרֻבּוֹת, כְּמָה דְּאָמַר קֹהֶלֶת (שם ב) עַד אֲשֶׁר לֹא תֶחְשַׁךְ הַשֶּׁמֶשׁ וְהָאוֹר וְגוֹמֵר,</p>\n<p>וְאוֹר וְנֵר עֲלַיְיהוּ אִתְּמַר (משלי ו כג) כִּי נֵר מִצְוָה וְתוֹרָה אוֹר, וְאַמַּאי אִתְחַשְׁכָן בְּהוֹן, בְּגִין דְּלָא הֲווֹ מִשְׁתַּדְלִין בְּאוֹרַיְיתָא וּמִצְוָה, בִּדְחִילוּ וּבִרְחִימוּ דְאִינוּן י\"ה,</p>\n<p>וּמִיָּד דְּמִשְׁתַּדְלִין בְּהוֹן בִּדְחִילוּ וּרְחִימוּ, אוֹמָאָה אִיהוּ לְקוּדְשָׁא בְּרִיךְ הוּא בְּי\"ה דְּאִינוּן דְּחִילוּ וּרְחִימוּ, לְאַעִִבָּרָא לוֹן מֵעָלְמָא דְנִשְׁמָתָא, בְגִין דְּאִינוּן חֲשׁוֹכִין אַפְרִישִׁין בֵּין י\"ה וּבֵין ו\"ה, כְּמָה דְאוּקְמוּהוּ דִכְתִיב (שמות יז טז) כִּי יָד עַל כֵּס י\"ה,</p>\n<p>וּבְהַהוּא זִמְנָא אִתְּמַר בְּאָדָם לָבְשׁוּ שָׁמַיִם קַדְרוּת וְגוֹמֵר, וּבְהַהוּא זִמְנָא דְמִתְעַבְרִין קַדְרוּתָא וַחֲשׁוֹכָא מִנִּשְׁמָתָא, מִיָּד כֹּל הַנְּשָׁמָה תְּהַלֵּל י\"הּ (תהלים קנ ו).</p>\n<p>וּמָאן אִינוּן אִלֵּין חֲשׁוֹכִין אִלֵּין סמא\"ל וְנָחָשׁ, וּמָאן גְּרִים לוֹן לְשַׁלְטָאָה עֲלַיְיהוּ, אֶלָּא רָזָא דִקְרָא אוֹלִיף כִּי אִם עֲוֹנוֹתֵיכֶם הָיוּ מַבְדִּילִים בֵּינֵיכֶם לְבֵין אלהיכ\"ם (ישעיה נט ב), וְדָוִד בְּגִינַיְהוּ אָמַר (תהלים קיט יח) גַּל עִינַי וְאַבִּיטָה נִפְלָאוֹת מִתּוֹרָתֶךָ,</p>\n<p>וּבְהַהוּא זִמְנָא מַה דַּהֲווֹ שָׁלְטִין חֲשׁוֹכִין עַל נְהוֹרִין דְּעַיְינִין, מִתְהַפְּכִין נְהוֹרִין וְשָׁלְטִין עַל חֲשׁוֹכִין,</p>\n<p>וְרָזָא דְמִלָּה שׁוֹפָ\"ר מְהוּפָּ\"ךְ קַדְמָ\"א זָקֵ\"ף קָטָ\"ן, הַהוּא דְאִתְּמַר בֵּיהּ (בראשית לב יא) קָטֹנְתִּי מִכֹּל הַחֲסָדִים וּמִכָּל הָאֱמֶת, אִזְדַקַּף וְאִקְרֵי זָקֵף גָּדוֹל, וְאֵין אֱמֶת אֶלָּא תוֹרָה, הֲדָא הוּא דִכְתִיב (מלאכי ב ו) תּוֹרַת אֱמֶת הָיְתָה בְּפִיהוּ,</p>\n<p>וּבְהַהוּא זִמְנָא מִתְהַפְּכָא כָּרְסַיָּא מִדִּינָא לְרַחֲמֵי, וְדָא הִיא רָזָא דְאוּקְמוּהָ מָארֵי מַתְנִיתִין צַדִּיקִיּם מְהַפְּכִין מִדַּת הַדִּין לְמִדַּת רַחֲמִים.</p>\n<p>וּבְהַהוּא זִמְנָא אִתְחֲשִׁיב כְּאִלּוּ אִתְבְּרִי עָלְמָא, וִיסַדֵּר נְהוֹרִין כִּדְקָא יָאוּת, הֲדָא הוּא דִכְתִיב (בראשית א ג) וַיִּקְרָא אלהי\"ם לָאוֹר יוֹם וְלַחֹשֶׁךְ קָרָא לָיְלָה,</p>\n<p>וַיִּקְרָא אלהי\"ם לָאוֹר יוֹם דָּא יִשְׂרָאֵל, דְּשָׁלְטָנוּתְהוֹן יְהֵא לְזִמְנָא דְפוּרְקָנָא, וְרַשִּׁיעַיָּא יִשְׁתָּאֲרוּן (נ\"א אזלי) בַּחֲשׁוֹכָא, הֲדָא הוּא דִכְתִיב וְלַחֹשֶׁךְ קָרָא לָיְלָה, וְאִתְּמַר בִּימִינָא</p>"],[9500011100,"<p>וּשְׂמָאלָא וַיְהִי עִִרֶב וַיְהִי בֹקֶר יוֹם אֶחָד (שם א ה), דְּאִיהוּ עִִרֶב דְּיִצְחָק, וּבֹקֶר דְּאַבְרָהָם.</p>\n<p>בְּהַהוּא זִמְנָא מַה דַּהֲוַת נִשְׁמָתָא מְהַדְּקָא בֵּין רַגְלִין, הֲדָא הוּא דִכְתִיב (רות ג ז) וַתְּגַל מַרְגְּלוֹתָיו וַתִּשְׁכָּב, דְּאִתְחַזְרַת לְלִבָּא, דְאִיהִי כְּגַוְונָא דִיְרוּשְׁלֵם,</p>\n<p>בְּהַהוּא זִמְנָא הַלֵּב רוֹאֶה, הֲדָא הוּא דִכְתִיב (ישעיה ל כ) וְלֹא יִכָּנֵף עוֹד מוֹרֶיךָ וְהָיוּ עִינֶיךָ רוֹאוֹת אֶת מוֹרֶיךָ, הַלֵּב שׁוֹמֵעַ דְּאִתְחַזַּר עֲבוֹדָה וּכְרוּבִים לְבֵי מַקְדְּשָׁא, דְאִתְּמַר בְּהוֹן (במדבר ז פט) וַיִּשְׁמַע אֶת הַקּוֹל מִדַּבֵּר אֵלָיו מֵעַל הַכַּפֹּרֶת מִבֵּין שְׁנֵי הַכְּרוּבִים,</p>\n<p>וְכָל עֲנָנִין (דאינון רומי רבתא ורומי זעירא) דְּאִינוּן מְכַסְּיָין עַל צְלוֹתִין, הֲדָא הוּא דִכְתִיב (איכה ג מד) סַכּוֹתָ בֶעָנָן לָךְ מֵעֲבוֹר תְּפִלָּה מִתְעַבְּרִין, וְנָהֲרִין עַיְינִין דְּאִינוּן בַּיִת רִאשׁוֹן וּבַיִת שֵׁנִי, דִבְהוֹן סָלְקִין צְלוֹתִין.</p>\n<p>דִּבְזִמְנָא דְאִינוּן יִשְׂרָאֵל מְלוּכְלָכִין בְּטִנּוּפִין דִּשְׁאָר עַמִּין, נִשְׁמָתָא דְאִיהִי שְׁכִינְתָּא אָמְרַת, (שיר א ו) אַל תִּרְאוּנִי שֶׁאֲנִי שְׁחַרְחֹרֶת, וּצְלוֹתָא נָפְלַת, הֲדָא הוּא דִכְתִיב (עמוס ה ב) נָפְלָה לֹא תוֹסִיף קוּם בְּתוּלַת יִשְׂרָאֵל,</p>\n<p>וְכַד נָפְלַת שְׁכִיבַת לְעַפְרָא בֵּין רַגְלִין, וְהָא אוּקְמוּהוּ (רות ג ז) וַתְּגַל מַרְגְּלוֹתָיו וַתִּשְׁכָּב, וְאִיהִי מְצַלֵּי לְקוּדְשָׁא בְּרִיךְ הוּא דְיוֹקִים לָהּ מֵעַפְרָא, הֲדָא הוּא דִכְתִיב (שם ט) וּפָרַשְׂתָּ כְנָפֶךָ עַל אֲמָתְךָ כִּי גוֹאֵל אָתָּה.</p>\n<p>בְּהַהוּא זִמְנָא (שם ח) וַיֶּחֱרַד הָאִישׁ וַיִּלָּפֵת, הַהוּא דְאִתְּמַר בֵּיהּ (שמות טו ג) יהו\"ה אִישׁ מִלְחָמָה, מַאי וַיִּלָּפֵת כְּמָה דְאַתְּ אָמַר (איוב ו יח) יִלָּפְתוּ אָרְחוֹת דַּרְכָּם,</p>\n<p>בְּהַהוּא זִמְנָא יֵיתֵי קוּדְשָׁא בְּרִיךְ הוּא וְיֵימָא לָהּ, לִינִי הַלַּיְלָה וְהָיָה בַבֹּקֶר (רות ג יג), לִינִי הַלַּיְלָה דְאִיהִי שְׂמָאלָא, וְהָיָה בַבֹּקֶר דְּאִיהִי רַחֲמֵי יְמִינָא, דְּמִתַּמָּן נְהִיר אוֹר, הֲדָא הוּא דִכְתִיב (בראשית מד ג) הַבֹּקֶר אוֹר,</p>\n<p>אִם יִגְאָלֵךְ טוֹב יִגְאָל, אִם יַעֲבִיד בָּךְ יִשְׂרָאֵל עוֹבְדִין טָבִין לְסָלְקָא לָךְ מִבֵּין רַגְלִין שַׁפִּיר, תִּגְאָל עַל יְדֵי דְיִשְׂרָאֵל עִלָּאָה דְּאִיהוּ בַעִִלָךְ, טוֹב וַדַּאי, וְאִם לָא יַעַבְדוּן בָּךְ עוֹבְדִין טָבִין, וּגְאַלְתִּיךְ אָנֹכִי.</p>\n<p>וְהָא אוּקְמוּהוּ (רות ג יג) חַי יהו\"ה שִׁכְבִי עַד הַבֹּקֶר, אוֹמָאָה בְּחַ\"י, דְאִיהוּ כְלִיל חַ\"י בִּרְכָאָן דִּצְלוֹתָא, שִׁכְבִי עַד הַבֹּקֶר, עַד הַהוּא נַהֲרָא,</p>\n<p>דִבְהַהוּא זִמְנָא צְלוֹתָא תְהֵא נַהֲרָא בְלִבָּא וּבְעַיְינִין, וּבְגִין דִּבְחַ\"י בִּרְכָאָן דִּצְלוֹתָא תַלְיָא פּוּרְקָנָא, וּבֵיהּ אִתְגַּלְיָא, דְאִיהוּ יְסוֹד חַ\"י עָלְמִין, אִתְּמַר בֵּיהּ (ד\"ה ב ז טז) וְהָיוּ עִינַי וְלִבִּי שָׁם כָּל הַיָּמִים.</p>\n<p>וְהָיוּ עִינַי וְלִבִּי אַדְכִּיר עַיְינִין וְלִבָּא, בְּגִין דְּצָרִיךְ בַּר נַשׁ בִּצְלוֹתֵיהּ לְמֶהֱוִי עִינוֹי לְתַתָּא לְגַבֵּי נִשְׁמָתָא, דְאִיהִי שְׁכִינְתָּא דְאִיהִי אֲסִירָא בְגָלוּתָא, וְלִבֵּיהּ לְעִילָא בְּקוּדְשָׁא בְּרִיךְ הוּא,</p>\n<p>וְרָזָא דְמִלָּה עִינַי תָּמִיד אֶל יהו\"ה כִּי הוּא יוֹצִיא מֵרֶשֶׁת רַגְלָי (תהלים כה טו), וְלִבֵּיהּ לְעִילָא לְנָטְלָא נוּקְמָא מֵעֲמָלֵק, הֲדָא הוּא דִכְתִיב (ישעיה סג ד) כִּי יוֹם נָקָם בְּלִבִּי, בְלִבִּי וַדַּאי, בֵּיהּ עָתִיד לְנָטְלָא נוּקְמָא, כְּמָה דְנָטִיל בֵּיהּ נוּקְמָא מִמִּצְרָאֵי.</p>\n<p>דְּאִיהִי לִבִּ\"י שֵׁם בֶּן אַרְבָּעִים וּתְרֵין, אבגית\"ץ בֵּיהּ אַפִּיק לְיִשְׂרָאֵל מִגָּלוּתָא, קְרַ\"ע שָׂטָ\"ן דְּאִיהוּ שְׁמָא תִנְיָינָא דְיוֹמָא תִנְיָינָא, בֵּיהּ קָרַע יַמָּא, וּבְהַאי שְׁמָא אִתְּמַר (בראשית א ו) יְהִי רָקִיעַ בְּתוֹךְ הַמָּיִם וְגוֹמֵר, נג\"ד יכ\"ש נֶגֶד כָּל עַמְּךָ אֶעֱשֶׂה נִפְלָאוֹת (שמות לד י), בְּכָל שְׁמָא נָטַל נוּקְמָא בְּמִצְרַיִם.</p>\n<p>וּפוּרְקָנָא בְלִבָּא תַלְיָא, דְאִתְּמַר בֵּיהּ הַלֵּב רוֹאֶה, וּבְגִין דָּא כִּי יוֹם נָקָם בְּלִבִּי (ישעיה סג ד), נְקָמָה בְּמַאי בְּלִבִּי בְּי\"ה, דְּאִתְּמַר בֵּיהּ (תהלם קן ו) כֹּל הַנְּשָׁמָה תְּהַלֵּל י\"הּ, וַעֲלֵיהּ אִתְּמַר (שמות יז טז) כִּי יָד עַל כֵּס י\"הּ,</p>\n<p>וּפוּרְקָנָא בְלִבָּא תַלְיָא, דְבֵיהּ אִתְּמַר הַלֵּב רוֹאֶה, וּבְגִין דָּא אוּקְמוּהוּ מָארֵי מַתְנִיתִין לְלִבִּ\"י גִלִּיתִי וּלְאֵבָרַי לֹא גִלִּיתִי, מַאי לְלִבִּי,</p>\n<p>אֶלָּא אוֹרַיְיתָא דְבִכְתָב אִתְקְרִיאַת לִבִּי, וְאוֹרַיְיתָא דְעַל פֶּה אִתְקְרִיאַת פּוּמָא וְאוּקְמוּהוּ מָארֵי מַתְנִיתִין מִלִּבָּא לְפוּמָא לָא גַלִּי, לְלִבִּ\"י גִלִּיתִי דָא שְׁמָא דְע\"ב שְׁמָהָן, וְאִינוּן שַׁבְעִין אַנְפִּין לְאוֹרַיְתָא, דְתַלְיָין מִן ב'.</p>\n<p>וְאוֹרַיְיתָא אִית לָהּ רֵישָׁא וְגוּפָא וְלִבָּא וּפִימָא וְאֵבָרִין, כְּגַוְונָא דְאִית בְּיִשְׂרָאֵל, דְּאִינוּן רֵישִׁין רֵישֵׁי עַמָּא, וּמִנְּהוֹן עַיְינִין</p>\n<p>הֲדָא הוּא דִכְתִיב (במדבר טו כד) וְהָיָה אִם מֵעִינֵי הָעִדָה, וְאִית מִנְּהוֹן לִבָּא, דְאִינוּן לָקֳבֵל שַׁבְעִין סַנְהֶדְרִין וּמֹשֶׁה וְאַהֲרֹן עַל גַּבַּיְיהוּ, דְּלָא חָסְרִין מֵעָלְמָא כְּוָתַיְיהוּ, וְדָא אִיהוּ לְלִבִּי גִלִּיתִי, אֲבָל אָחֳרָנִין דְּאִינוּן כִּשְׁאָר אֵבָרִין אִתְּמַר בְּהוֹן וּלְאֵבָרַי לֹא גִלִּיתִי,</p>\n<p>וְכֵן בְּאוֹרַיְיתָא שַׁבְעִין אַנְפִּין תַּלְיָין מִתְּרֵין תּוֹרוֹת, אוֹרַיְיתָא דְבִכְתָב וְאוֹרַיְיתָא דִבְעַל פֶּה.</p>\n<p>וּבְגָלוּתָא חָלַק לִבָּ\"ם (הושע י ב), דְּאִינוּן ע\"ב צַדִּיקִים דְּאִינוּן כְּגַוְונָא דְסַנְהֶדְרִין, וְרָזָא דְמִלָּה (ישעיה ל יח) אַשְׁרֵי כָּל חוֹכֵי לוֹ, לֹ\"ו בְּחוּשְׁבָּנָא סְלִיק תְּלָתִין וְשִׁית, וְאִינוּן ל\"ו בְּאַרְעָא דְיִשְׂרָאֵל, וְל\"ו לְבָר מֵאַרְעָא דְיִשְׂרָאֵל, וְדָא אִיהוּ חָלַק לִבָּ\"ם,</p>\n<p>וּמָאן חָלַק לִבָּם.</p>"],[9500011101,"<p>שְׂאוֹר וְחָמֵץ דְּאִינוּן עִרֶב רַב,</p>\n<p>וְרָזָא דְמִלְתָא וִיהִי מַבְדִּיל בֵּין מַיִם לָמָיִם (בראשית א ו), דַּעֲלַיְיהוּ אִתְּמַר (שמות יב טו) אַךְ בַּיּוֹם הָרִאשׁוֹן תַּשְׁבִּיתוּ שְׂאֹר מִבָּתֵּיכֶם, אַךְ חָלַק,</p>\n<p>וְאוֹמָאָה דְיִתְמַחוּן בְּי\"ד, דְּאִינוּן אַרְבַּע סְרֵי יוֹמֵי דְפִסְחָא, לְקַיְימָא כִּימֵי צֵאתְךָ מֵאֶרֶץ מִצְרַיִם אַרְאֶנּוּ נִפְלָאוֹת (מיכה ז טו), (ודא שבעה יומי דפסחא דגלותא קדמאה, ושבעה יומי דפסחא דגלותא בתראה), הֲדָא הוּא דִכְתִיב (יחזקאל מה כא) חָג שְׁבֻעוֹת יָמִים מַצּוֹת יֵאָכֵל.</p>\n<p>וּבְגִין דָּא אוֹר לְאַרְבָּעָה עָשָׂר בּוֹדְקִין אֶת הֶחָמֵץ לְאוֹר הַנֵּר, וְדָא אוֹר הַנֵּר דְּאִיהִי אוֹרַיְיתָא וּפִקּוּדַיָּא, דְאִתְּמַר בְּהוֹן (משלי ו כג) כִּי נֵר מִצְוָה וְתוֹרָה אוֹר,</p>\n<p>נֵר בְּלִבָּא, אוֹר בְּעַיְינִין, דְּאִיהוּ אוֹר הַנֵּר, בִּדְחִילוּ וּרְחִימוּ בְּי\"ה, מִתְעַבְּרִין חֲשׁוֹכָא וְקַדְרוּתָא מִנַּיְיהוּ, וּבְגִין דָּא כִּי יוֹם נָקָם בְּלִבִּי (ישעיה סג ד).</p>\n<p>וְעוֹד בְּלִבִּי דָא ל\"ב אלהי\"ם דְּעוֹבְדָא דִבְּרֵאשִׁית, וַעֲשַׂר אֲמִירָן דְּאִינוּן י' מִן לִבִּי,</p>\n<p>וְלֵב הַאי אִיהוּ לֵב, דְּבֵיהּ נָהִיר הַהוּא דְאִתְּמַר בֵּיהּ (שמות ב ב) וַתֵּרֶא אוֹתוֹ כִּי טוֹב הוּא, וּבֵיהּ עָתִיד לְאִתְגַּלְיָיא קוּדְשָׁא בְּרִיךְ הוּא לְמֹשֶׁה בְאוֹרַיְיתָא בְגָלוּתָא בַתְרָאָה, כְּגַוְונָא דְפוּרְקָנָא קַדְמָאָה, דְאִתְּמַר בֵּיהּ (שם ג ב) וַיֵּרָא מַלְאַךְ יהו\"ה אֵלָיו בְּלַבַּת אֵשׁ,</p>\n<p>בְּקַדְמֵיתָא בְּלַבַּת אֵשׁ דִּנְבוּאָה, וּבְגָלוּתָא בַתְרָאָה בְּלַבַּת אֵשׁ דְּאוֹרַיְיתָא.</p>\n<p>וְדָא בַ\"ת מִן בְּרֵאשִׁית, דְּאִיהִי כְלִילָא מֵעֲשַׂר אֲמִירָן וְל\"ב אלהי\"ם דְּעוֹבְדָא דִבְּרֵאשִׁית,</p>\n<p>בַּת כְּלִילָא מֵעֲשַׂר אֲמִירָן אִיהִי בַת עַיִן אוּכְמָא, דְאִתְּמַר בָּהּ שְׁחוֹרָה אֲנִי וְנָאוָה, וּבֵיהּ נָהִיר אוֹר,</p>\n<p>הֲדָא הוּא דִכְתִיב (משלי ו כג) וְתוֹרָה אוֹר,</p>\n<p>ל\"ב אלהי\"ם בֵּיהּ נָהִיר מִצְוָה, דְּאִתְּמַר בֵּיהּ (שם כ כז) נֵר יהו\"ה נִשְׁמַת הָאָדָם וכו':</p>\n<p>(כאן חסר והוא בתיקונים זוהר חדש)</p>\n<p>וְגַדְפוֹי דִּשְׁכִינְתָּא אִינוּן כִּסּוּי דַּם חַיָּה וְעוֹף, דִּמְכַסֵּי עֲלַיְיהוּ בִרְחִימוּ, וְכַד מְכַסֵּי עֲלַיְיהוּ בִרְחִימוּ דְאַהֲבָה, מֵי טוֹפָנָא לָא שָׁלְטָא עֲלַיְיהוּ, מַיִם רַבִּים דְּמֵי טוֹפָנָא לֹא יוּכְלוּ לְכַבּוֹת אֶת הָאַהֲבָה דְיִשְׂרָאֵל בַּאֲבוּהוֹן דְּבִשְׁמַיָּא,</p>\n<p>בְּהַהוּא זִמְנָא כָּרְסַיָּא יְהֵא עַל אַרְבַּע חֵיוָון, וְדָא אִיהוּ שׁוֹפָר הוֹלֵ\"ךְ רָבִי\"עַ מְרוּבַּע, דַּרְגָּ\"א בְּשִׁית דַּרְגִּין, דְּאִינוּן שֵׁשׁ מַעֲלוֹת לַכִּסֵּא (מלכים א י יט), הָא אִיהוּ מַלְכָּא עַל כָּרְסַיָּא.</p>\n<p>בְּהַהִיא זִמְנָא וַעֲשֵׂה לִי מַטְעַמִּים כַּאֲשֶׁר אָהַבְתִּי (בראשית כז ד) מִפִּקּוּדִין דַּעֲשֵׂה דְאִתְיְיהִיבוּ מֵאַהֲבָה, וְלָא מִפִּקּוּדִין דְּלֹא תַעֲשֶׂה, דְהוּא אַקְרִיב לֵיהּ מְמַנָּא דְעִשָׂו, לְקַטְרְגָא בְהוֹן לְיִשְׂרָאֵל, דִּבְגִינַיְיהוּ אִתְּמַר (מלאכי א ג) וְאֶת עִשָׂו שָׂנֵאתִי.</p>\n<p>וְדָא אִיהוּ דַרְגָּ\"א תְרֵי טַעֲמֵ\"י, דְמִסִּטְרָא דְפִקּוּדִין דְּלֹא תַעֲשֶׂה מְמַנָּא דְעִשָׂו אִיהוּ רָבִי\"עַ עַל יִשְׂרָאֵל, וְאִיהִי דַרְגָּ\"א עֲלַיְיהוּ,</p>\n<p>וְאִי תֵימָא דְשָׁלְטָא עַל שְׁכִינְתָּא דְאִיהִי עִמְּהוֹן בְּגָלוּתָא, הָא אָמַר קְרָא (ישעיה מב ח) אֲנִי יהו\"ה הוּא שְׁמִי וּכְבוֹדִי לְאַחֵר לֹא אֶתֵּן וּתְהִלָּתִי לַפְּסִילִים,</p>\n<p>וּכְבוֹדִי שְׁכִינְתָּא עִלָּאָה, לְאַחֵר לֹא אֶתֵּן אֵל אַחֵר, וּתְהִלָּתִי לַפְּסִילִים דָּא שְׁכִינְתָּא תַּתָּאָה,</p>\n<p>וּבְגִין דָּא בְשִׁית יוֹמִין דְּשָׁלְטָא סַם הַמָּוְת, אֵל אַחֵר, אִתְּמַר בִּשְׁכִינְתָּא (יחזקאל מו א) יִהְיֶה סָגוּר שֵׁשֶׁת יְמֵי הַמַּעֲשֶׂה, בְּשַׁבָּת וּבְרָאשֵׁי חֳדָשִׁים דְּלָא שָׁלְטִין מְמַנָּן בִּישִׁין, אִתְּמַר בְּהוֹן (נ\"א בה) וּבְיוֹם הַשַּׁבָּת יִפָּתֵחַ וּבְיוֹם הַחֹדֶשׁ יִפָּתֵחַ.</p>\n<p>וְעוֹד רָבִי\"עַ אִיהוּ כְּגַוְונָא דָא כּ, וּלְזִמְנִין כְּגַוְונָא דָא [ציור] בַּת מֶלֶךְ פְּנִימָה סְגִירָא בְּבֵיתָא, וְאִיהִי סִיהֲרָא קַדִּישָׁא לְעוֹלָם לָא אִסְתַּכְּלַת בָּהּ חַמָּה בִישָׁא, גֵיהִנָּם סַם הַמָּוְת נוּקְבָא בִישָׁא, כָּל שֶׁכֵּין אֵל אַחֵר,</p>\n<p>דְּהָכִי אוּקְמוּהוּ קַדְמָאִין, לְעוֹלָם לָא חָזָא חַמָּה פְּגִימוּתָא דְסִיהֲרָא, דִּבְזִמְנָא דְחַמָּה נָפְקָא (נפקא) מִמִּזְרָח, סִיהֲרָא חָזְרַת אַנְפָּהָא מִינֵיהּ כְּגַוְונָא דָא [ציור]</p>\n<p>וּבְגִין דָּא אָמַר בִּלְעָם הָרָשָׁע לֹא הִבִּיט אָוְן בְּיַעֲקֹב וְלֹא רָאָה עָמָל בְּיִשְׂרָאֵל (במדבר כג כא), עָמָל וָאָוְן סמא\"ל וְנָחָשׁ.</p>\n<p>וּבְזִמְנָא דְּדָחֲקִין לָהּ לְאִסְתַּכָּלָא בָהּ, אִתְכַּסְיָא מִכָּל וָכֹל, וְאֵימָתַי בְּיַרְחָא שְׁבִיעָאָה, הֲדָא הוּא דִכְתִיב (תהלים פא ג) תִּקְעוּ בַחֹדֶשׁ שׁוֹפָר בַּכֶּסֶה לְיוֹם חַגֵּנוּ, מַאי בַּכֶּסֶה בְּיַרְחָא דְאִתְכַּסְיָיא בֵּיהּ סִיהֲרָא,</p>\n<p>בְּהַהוּא זִמְנָא דְאִתְכְּסִיאַת מִנֵּיהּ, אִיהִי אָמְרַת לְיִשְׂרָאֵל דִּיְתַקְנוּן צְלוֹתִין בְּמַאֲכָלִין טָבִין, מִפִּקּוּדִין דַּעֲשֵׂה, דִּצְלוֹתָא שְׁקִילָא כְּכָל פִּקּוּדִין,</p>"],[9500011102,"<p>בְּהַהוּא זִמְנָא יֵימָא קוּדְשָׁא בְּרִיךְ הוּא לְיִשְׂרָאֵל, וַעֲשֵׂה לִי מַטְעַמִּים (בראשית כז ד) בִּרְעוּתָא דִשְׁכִינְתָּא, כַּאֲשֶׁר אָהַבְתִּי מִפִּקּוּדִין דַּעֲשֵׂה, וְתַקִּנַּת שְׁכִינְתָּא עִם יִשְׂרָאֵל מַאֲכָלִין דִּצְלוֹתִין דְּאִינוּן קָרְבָּנִין,</p>\n<p>וּבְזִמְנָא דְאִיהִי תַקִּינַת מְזוֹנָא לְמַלְכָּא, יְהִיבַת לוֹן עִיטָא לְאַתְעָרָא בַשּׁוֹפָר, דְּבֵיהּ עָתִיד קוּדְשָׁא בְּרִיךְ הוּא לְאַכְנָשָׁא בֵיהּ לְיִשְׂרָאֵל מִן גָּלוּתָא מֵאַרְבַּע סִטְרִין, הֲדָא הוּא דִכְתִיב תְּקַע בְּשׁוֹפָר גָּדוֹל לְחֵירוּתֵינוּ וְשָׂא נֵס לְקַבֵּץ גָּלֻיּוֹתֵינוּ, וְאִיהוּ חָשִׁיב דְּאִיהוּ יוֹמָא דְּדִינָא דִילֵיהּ וּבָרַח (ס\"א ובר\"ה).</p>\n<p>עַד הַהוּא זִמְנָא קוּדְשָׁא בְּרִיךְ הוּא מַאֲרִיךְ עֲלַיְיהוּ דְחַיָּיבַיָּא, וּלְבַסּוֹף אַפְסִיק לוֹן וְחָרִיב לוֹן מֵעָלְמָא, וְדָא אִיהוּ מַאֲרִי\"ךְ טַרְחָ\"א סוֹף פָּסוּ\"ק.</p>\n<p>וְעוֹד שׁוֹפָ\"ר הוֹלֵךְ רָבִי\"עַ דַּרְגָּ\"א תְרֵי טַעֲמֵ\"י, בְהַהוּא זִמְנָא דְיִתְמַחוּן חַיָּיבַיָּא מֵעָלְמָא, סָלְקָא צְלוֹתָא בְנִגּוּנָא בְּאַרְבַּע מִינִין, דְּאִינוּן שִׁיר פָּשׁוּט וְדָא י', שִׁיר כָּפוּל וְדָא י\"ה, שִׁיר מְשׁוּלָשׁ וְדָא יה\"ו, שִׁיר מְרוּבַּע וְדָא יהו\"ה,</p>\n<p>בִּשְׁמָא דְיהו\"ה סָלְקָא צְלוֹתָא דְאִיהִי שְׁכִינְתָּא,</p>\n<p>אוֹרַיְתָא בְנִגּוּנָא, שְׁכִינְתָּא בְנִגּוּנָא, יִשְׂרָאֵל סָלְקִין מִגּוֹ גָלוּתָא בְנִגּוּנָא, הֲדָא הוּא דִכְתִיב (שמות טו א) אָז יָשִׁיר מֹשֶׁה וּבְנֵי יִשְׂרָאֵל אֶת הַשִּׁירָה הַזֹּאת לַיהו\"ה.</p>\n<p>צְלוֹתָא דְאִיהִי שְׁכִינְתָּא, סָלְקָא לְגַבֵּיהּ דְּמַלְכָּא בַעֲשָׂרָה זִכְרוֹנוֹת וּבַעֲשָׂרָה מַלְכִיּוֹת וּבַעֲשָׂרָה שׁוֹפָרוֹת, דְּאִינוּן י י י', וַעֲשָׂרָה כִּתּוֹת דְּמַלְאָכִים יִתְעָרוּן לְגַבַּיְיהוּ, וְסָלְקָא לוֹן לְגַבֵּי עֲשַׂר סְפִירָן,</p>\n<p>וְנִגּוּנִין סָלְקִין מִנַּיְיהוּ מְרוּבָּעִים מִסִּטְרָא דְרָבִי\"עַ בְּאַרְבַּע חֵיוָון, וְאִינוּן חַיּוֹת קְטַנּוֹת עִם גְּדוֹלוֹת אִינוּן תְּמַנְיָא, וְאִינוּן יאהדונה\"י, וַעֲלַיְיהוּ אִתְּמַר (שם) אָז יָשִׁיר מֹשֶׁה,</p>\n<p>כַד יְהֵא קוּדְשָׁא בְּרִיךְ הוּא בִּשְׁכִינְתֵּיהּ בְּחֵיוָן תְּמַנְיָא, דְאִינוּן חֵיוָן דְּאֶשָּׁא עִתִּים חָשׁוֹת עִתִּים מְמַלְּלוֹת, וְכֻלְּהוּ מְחָאָן בְּגַדְפַיְיהוּ בְּנִגּוּנָא, וְנִגּוּנָא בְהוֹן (סלקא) בְּאַרְבַּע אַנְפִּין, לְכָל סִטְרָא מְרוּבָּעִין, הֲדָא הוּא דִכְתִיב (יחזקאל א ו) וְאַרְבָּעָה פָנִים לְאֶחָת וְאַרְבַּע כְּנָפַיִם לְאַחַת מֵהֶם, לְכָל חַיָּה תְמַנְיָא אִינוּן בֵּין אַנְפִּין וְגַדְפִין, לָקֳבֵל תְּמַנְיָא דִי בְּהוֹן שַׁבַּח מֹשֶׁה אָ\"ז.</p>\n<p>וְדָוִד בְּגִין דָּא תַקִּין מָנָא בִתְמַנְיָא נִימִין, וְשַׁבַּח לְקוּדְשָׁא בְּרִיךְ הוּא בִתְּמַנְיָא, הֲדָא הוּא דִכְתִיב (תהלים יב א) לַמְנַצֵּחַ עַל הַשְּׁמִינִית, וּתְמַנְיָא אַתְוָון, לְכָל חַד תְּמַנְיָא, סָלְקִין כֻּלְּהוּ ע\"ב, יאהדונה\"י תְּמַנְיָא, וְתַלְיָין מִנַּיְיהוּ ס\"ד תְּמַנְיָא לְכָל חַד, סָלְקִין כֻּלְּהוּ ע\"ב, דָּא אִיהוּ רָזָא דְחַשְׁמַל.</p>\n<p>וְאִית נִגּוּנָא דְסָלְקָא בְעִִשֶׂר, וְדָא אִיהוּ יו\"ד ה\"א וא\"ו ה\"א, וַעֲלַיְיהוּ אִתְּמַר (שיר ה יד) יָדָיו גְּלִילֵי זָהָב, וְאִית נִגּוּנָא דְסָלִיק בְּשִׁית, הֲדָא הוּא דִכְתִיב שׁוֹקָיו עַמּוּדֵי שֵׁשׁ,</p>\n<p>י\"ה יהו\"ה צוּר עוֹלָמִים, י\"ה י\"ה י\"ה אָדָ\"ם.</p>\n<p>אַרְבַּע כְּנָפַיִם אַרְיֵה שׁוֹר נֶשֶׁר, מֶרְכָּבָה, תִּנְיָינָא י\"ה יהו\"ה י\"ה יהו\"ה י\"ה יהו\"ה,</p>\n<p>לְעִילָא מִכֻּלְּהוּ י\"ה יהו\"ה חָכְמָ\"ה בִּינָ\"ה, כֶּתֶר אהי\"ה אֲשֶׁר אהי\"ה, וַעֲלַיְיהוּ אִתְּמַר (ישעיה ו ב) שְׂרָפִים עוֹמְדִים מִמַּעַל לוֹ שֵׁשׁ כְּנָפַיִם שֵׁשׁ כְּנָפַיִם לְאֶחָד, וְדָא אבגית\"ץ, בִּשְׁתַּיִם יְכַסֶּה פָנָיו לְיִשְׂרָאֵל דְּלָא יִסְתַּכְּלוּן בְּהוֹן שָׂנְאֵיהוֹן, וּבִשְׁתַּיִם יְכַסֶּה רַגְלָיו דְּלָא אַדְכִּיר לוֹן עוֹבְדָא דְעִִגְלָא, וּבִשְׁתַּיִם יְעוֹפֵף מִן גָּלוּתָא, הֲדָא הוּא דִכְתִיב (שמות יט ד) וָאֶשָּׂא אֶתְכֶם עַל כַּנְפֵי נְשָׁרִים וָאָבִיא אֶתְכֶם אֵלָי.</p>\n<p>וְאִית נִגּוּנָא דְסָלְקָא בִתְרֵין כְּגוֹן הַלְלוּיָהּ, וְאִית נִגּוּנָא דְסָלִיק בְּאָת חַד כְּגוֹן הַלְלִי בְּי', וְאִית נִגּוּנָא דְסָלִיק בְּחָמֵשׁ כְּגוֹן ה', וְהָא אִתְּמַר בְּכִנּוֹר דְּחָמֵשׁ נִימִין, אֲבָל נִגּוּנָא דְסָלִיק בְּשִׁית דְּאִינוּן אבגית\"ץ מִן ו' אִיהִי, וְאִית דְּסָלִיק לֵיהּ בִּתְלַת וְדָא יה\"ו, דְאִיהוּ אהי\"ה, וְסָלִיק נִגּוּנָא בֵיהּ בַּתְּקִיעָה שְׁבָרִים תְּרוּעָה.</p>\n<p>בַּתְּקִיעָה הוּא קָלָא אָרוּךְ בְּנִגּוּנָא, עַד דַּהֲוָה סָלִיק לֵיהּ לְגַבֵּי יְמִינָא דְאִיהוּ חֶסֶד,</p>\n<p>בַּשְּׁבָרִים הֲוָה סָלִיק קָלָא דְנִגּוּנָא לְגַבֵּי גְבוּרָה, דְתַמָּן י\"ה בִּימִינָא וּשְׂמָאלָא, וַהֲוָה נָחִית מִנֵּיהּ בְּחֶדְוָה חָכְמָתָא וְעוּתְרָא, כְּמָה דְאוּקְמוּהוּ הָרוֹצֶה לְהַחְכִּים יַדְרִים, לְהַעֲשִׁיר יַצְפִּין,</p>\n<p>בִּתְרוּעָה הֲוָה סָלִיק קָלָא דְנִגּוּנָא לְגַבֵּי עַמּוּדָא דְאֶמְצָעִיתָא, וַהֲוָה נָחִית מִנֵּיהּ מַלְכָּא לְגַבֵּי</p>"],[9500011103,"<p>כַּלָּה דְאִיהִי קוֹל דְּמָמָה דַקָּה,</p>\n<p>בְּהַהוּא זִמְנָא יִתְעָרוּן כָּל מִינֵי נִגּוּנָא, הֲדָא הוּא דִכְתִיב (תהלים קנ ג) הַלְלוּהוּ בְּתֵקַע שׁוֹפָר, הַלְלוּהוּ בְּנֵבֶל וְכִנּוֹר, הַלְלוּהוּ בְּתוֹף וּמָחוֹל, הַלְלוּהוּ בְּמִינִים וְעוּגָב, הַלְלוּהוּ בְּצִלְצְלֵי שָׁמַע, הַלְלוּהוּ בְּצִלְצְלֵי תְרוּעָה.</p>\n<p>שׁוֹפָר אִיהִי שְׁכִינְתָּא עִלָּאָה, תְּקַע דִּילָהּ שְׁכִינְתָּא תַּתָּאָה, דְּאִתְּמַר בָּהּ (בראשית לב כו) וַתֵּקַע כַּף יֶרֶךְ יַעֲקֹב בְּגָלוּתָא,</p>\n<p>בְּהַהוּא זִמְנָא סָלְקָא מִן גָּלוּתָא בַשּׁוֹפָר גָּדוֹל, וְאִתְקְרִיאַת תְּקַע בְּשׁוֹפָר גָּדוֹל לְחֵרוּתֵנוּ.</p>\n<p>בְּנֵבֶ\"ל, בֶּ\"ן לֵ\"ב,</p>\n<p>בְּהַהוּא זִמְנָא בֶּ\"ן יֵעוּל לְהֵיכָלֵיהּ דְּאִיהוּ לֵ\"ב, וְאִתְּמַר בֵּיהּ (משלי טו טו) וְטוֹב לֵב מִשְׁתֶּה תָמִיד,</p>\n<p>וּמַה דְּאִתְּמַר בְּקַדְמֵיתָא (בראשית ו ו) וַיִּתְעַצֵּב אֶל לִבּוֹ בְּגִין חַיָּיבַיָּא, מִיָּד דְּאִתְאֲבִידוּ אִתְקַיַּים בֵּיהּ וּבַאֲבֹד רְשָׁעִים רִנָּה (משלי יא י),</p>\n<p>כִּנּוֹר, כ\"ו נ\"ר, קוּדְשָׁא בְּרִיךְ הוּא דְאִיהוּ יהו\"ה, דְּאִתְּמַר בֵּיהּ (תהלים כז א) יהו\"ה אוֹרִי וְיִשְׁעִי, נָהִיר בְּנֵ\"ר דְּאִיהִי שְׁכִינְתָּא, מִצְוָה דִילֵיהּ, וְחָדֵי בָהּ.</p>\n<p>צִלְצְלֵי שָׁמַע חֶסֶד גְּבוּרָה, צִלְצְלֵי תְרוּעָה נֶצַח וָהוֹד, וּבְכֻלְּהוּ כֹּל הַנְּשָׁמָה תְּהַלֵּל י\"הּ, דְּאִיהוּ חָכְמָה וּבִינָה, דִּי בְהוֹן יְהֵא פוֹרְקָנָא ל\"וֹ וְלָ\"הּ דְּאִינוּן בֵּן וּבַת,</p>\n<p>וּבְהוֹן יִתְמַחוּן עֲמָלֵקִים מֵעָלְמָא, וְדָא אִיהוּ סוֹף פָּסוּק.</p>\n<p>דָּבָר אַחֵר וַעֲשֵׂה לִי מַטְעַמִּים כַּאֲשֶׁר אָהַבְתִּי (בראשית כז ד) מִפִּקּוּדִין דַּעֲשֵׂה, וְלָא כַאֲשֶׁר שָׂנֵאתִי מִפִּקּוּדִין דְּלֹא תַעֲשֶׂה,</p>\n<p>פִּקּוּדִין דְּלֹא תַעֲשֶׂה תַּלְיָין מִדְּחִילוּ דְיִרְאָה, וְאִינוּן לְרַחֲקָא הַשָּׂטָן מִנַּיְיהוּ, דְּלָא יִתְקַרִיב לְגַבֵּי כָּרְסַיָּא דְאִיהוּ לִבָּא, לְתַבְעָא דִינִין עַל אֵבָרִין קַדִּישִׁין דְּאִינוּן יִשְׂרָאֵל, וְלִבָּא שְׁכִינְתָּא בֵינַיְיהוּ.</p>\n<p>הַשָּׂטָן אִיהוּ סמא\"ל, שָׁלְטָנוּתָא דִילֵיהּ בְּכָבֵד, דַּעֲלֵיהּ אִתְּמַר (בראשית לו א) עִשָׂו הוּא אֱדוֹם, עַרְקִין דְּכַבְדָּא חֲיָילִין וּמַשִּׁרְיָין דִּילֵיהּ, וְכָבֵד נָטִיל כָּל לִכְלוּכִין וְחוֹבִין דְּעַרְקִין, הֲדָא הוּא דִכְתִיב (ויקרא טז כב) וְנָשָׂא הַשָּׂעִיר עָלָיו אֶת כָּל עֲוֹנוֹתָם אֶל אֶרֶץ גְּזֵרָה, עֲוֹנוֹת תָּם, דְּהַהוּא אִישׁ תָּם, אֶל אֶרֶץ גְּזֵרָה, אֲתַר דִּגְזֵרַת עִירִין.</p>\n<p>מָרָה חַרְבָּא דִילֵיהּ, עֲלָהּ אִתְּמַר (בראשית כז מ) וְעַל חַרְבְּךָ תִּחְיֶה, וּמְנָא לָן דְּמָרָה אִיהִי חַרְבָּא דְמַלְאַךְ הַמָּוְת, דִּכְתִיב (משלי ה ד) וְאַחֲרִיתָהּ מָרָה כַלַּעֲנָה חַדָּה כְּחֶרֶב פִּיּוֹת, אִיהִי חַיִּים לְכָבֵד, וְסַם הַמָּוְת לְלִבָּא,</p>\n<p>מָרָה אִיהִי גֵיהִנָּם, וְאִית לָהּ תְּרֵי פִיּוֹת דְּאָמְרִין הַב הַב, הֲדָא הוּא דִכְתִיב (שם ל טו) לַעֲלוּקָה שְׁתֵּי בָנוֹת הַב הַב, שְׁתֵּי בָנוֹת דְּאָמְרִין הַב חַיָּיבִין לְגֵיהִנָּם.</p>\n<p>שַׁבְעִין עַרְקִין אִינוּן בְּכַבְדָּא, לָקֳבֵל שַׁבְעִין מְמַנָּן, כָּבֵד וְיוֹתֶרֶת ע\"ב, יוֹתֶרֶת דִּילֵיהּ אִיהִי נָחָשׁ אֵשֶׁת זְנוּנִים, בְּגִין דְּשִׁיּוּרִין דִּילֵיהּ (נ\"א דילה) נַטְלָא טְחוֹל דְּאִיהוּ חֹשֶׁךְ, וַעֲלָהּ אִתְּמַר (בראשית א ד) וְלַחֹשֶׁךְ קָרָא לָיְלָה, דְּשָׁלְטָנוּתָהּ בְּגָלוּתָא דְאִיהוּ לַיְלָה,</p>\n<p>וּבְגָלוּתָא שַׁעִִתָּא קַיְימָא לֵיהּ, דְּאִיהִי לִילִי\"ת אִימָּא דְעִרֶב רַב, וְאִיהִי שְׂחוֹק הַכְּסִיל (ס\"א הטחול), וּבְגִינָהּ אִתְּמַר (איוב ז ט) כָּלָה עָנָן וַיֵּלַךְ כֵּן יוֹרֵד שְׁאוֹל לֹא יַעֲלֶה. וְדָא אִיהוּ צַדִּיק מִמֶּנּוּ בּוֹלֵעַ,</p>\n<p>דְּרָשָׁע וַדַּאי דְּאִיהוּ כְּסִיל, עֲלֵיהּ אִתְּמַר (חבקוק א יג) לָמָּה תַבִּיט בּוֹגְדִים תַּחֲרִישׁ בְּבַלַּע רָשָׁע צַדִּיק מִמֶּנּוּ, וְאוּקְמוּהוּ מָארֵי מַתְנִיתִין, צַדִּיק מִמֶּנּוּ בּוֹלֵעַ אֲבָל צַדִּיק גָּמוּר אֵינוֹ בּוֹלֵעַ, וּבְגִינֵיהּ אִתְּמַר (ש\"א ב ו) מוֹרִיד שְׁאוֹל וַיָּעַל,</p>\n<p>וַוי לְנִשְׁמָתָא כַד בָּלַע לָהּ טְחוֹל, וַוי לְיִשְׂרָאֵל כַּד אִתְבַּלְעוּ בְּעִרֶב רַב, דַּעֲלַיְיהוּ אִתְּמַר (בראשית מא כא) וְלֹא נוֹדַע כִּי בָאוּ אֶל קִרְבֶּנָה, וּמַרְאֵיהֶן רַע כַּאֲשֶׁר בַּתְּחִלָּה.</p>\n<p>בְּזִמְנָא דְגָלוּתָא כָּל מְמַנָּן דְּאוּמִין דְּעָלְמָא וְעִרֶב רַב, אִתְּמַר בְּהוֹן (איכה א ה) הָיוּ צָרֶיהָ לְרֹאשׁ אוֹיְבֶיהָ שָׁלוּ, צָרֶיהָ וַדַּאי אִינוּן עִרֶב רַב, עֲלַיְיהוּ אִתְּמַר (ישעיה א כג) שָׂרַיִךְ סוֹרְרִים וְחַבְרֵי גַנָּבִים כֻּלּוֹ, אוֹהֵב שֹׁחַד וְגוֹמֵר, אוֹיְבֶיהָ שָׁלוּ אִלֵּין עִשָׂו וְיִשְׁמָעִאל וְשַׁבְעִין מְמַנָּן, דְּאִינוּן כֻּלְּהוּ בְּשַׁלְוָה בְעוּתְרָא, וְיִשְׂרָאֵל בְּדוֹחֲקָא בַעֲנִיּוּתָא,</p>\n<p>וּבְגִין דָּא וַוי לְעָלְמָא כַּד אִתְבַּלְעוּ בְּעִרְבוּבְיָא בִישָׁא, וּמָאן גָּרַם דְּאִתְבַּלְעוּ בְּמֵעַיְיהוּ וְלֹא נוֹדַע כִּי בָאוּ אֶל קִרְבֶּנָה, בְּגִין דְּעוֹבְדֵיהוֹן בִּישִׁין בִּידֵיהוֹן, הֲדָא הוּא דִכְתִיב (תהלים קו לה) וַיִּתְעָרְבוּ בַגּוֹיִם וַיִּלְמְדוּ מַעֲשֵׂיהֶם,</p>\n<p>כְּגַוְונָא דָא נִשְׁמָתָא אִיהִי כְּנֶסֶת יִשְׂרָאֵל, כַּד</p>"],[9500011104,"<p>אִיהִי שְׁלֵימָא בְּפִקּוּדִין דַּעֲשֵׂה, אִתְּמַר בָּהּ (שיר ד ז) כֻּלָּךְ יָפָה רַעִִיָתִי וּמוּם אֵין בָּךְ,</p>\n<p>בְּהַהוּא זִמְנָא שַׁרְיָא שֵׁם יהו\"ה עֲלָהּ, וְאִתְּמַר בָּהּ (דברים כח י) וְרָאוּ כָּל עַמֵּי הָאָרֶץ כִּי שֵׁם יהו\"ה נִקְרָא עָלֶיךָ וְיָרְאוּ מִמֶּךָּ,</p>\n<p>וּמְמַנָּן דְּכָבֵד וְעַרְקִין דִּילֵיהּ וּמְמַנָּן דִּטְחוֹל וְעִרְבוּבְיָא בִישָׁא דִילֵיהּ, מִתְכַּפְיָין תְּחוֹת לִבָּא דְתַמָּן נִשְׁמָתָא.</p>\n<p>וְאִם נִשְׁמָתָא אִיהִי מִתְטַנְפָא (ס\"א פגימא) בְחוֹבִין, אוֹ גָּרַע מִינָהּ אֲפִילוּ פִקּוּדָא חֲדָא מֵאִינוּן פִּקּוּדִין, כְּמָה דְאוּקְמוּהָ מָארֵי מַתְנִיתִין עֲבֵירָה מְכַבָּה מִצְוָה, בְּהַהוּא אֲתַר (נ\"א אבר) דְּשַׁרְיָא עֲבֵירָה וְאִסְתַּלַּק מִצְוָה מִנֵּיהּ, הַהוּא אֵבֶר אִיהוּ פָּגוּם, וְאִיהוּ מוּם דְּנִשְׁמָתָא, בְּגִינֵיהּ לָא שַׁרְיָא קוּדְשָׁא בְּרִיךְ הוּא עַל נִשְׁמָתָא, הֲדָא הוּא דִכְתִיב (ויקרא כא יח) כָל אֲשֶׁר בּוֹ מוּם לֹא יִקְרָב, נִשְׁמָתָא דְאִית בָּהּ מוּם בְּחַד מֵרַמַ\"ח פִּקּוּדִין דִּילָהּ לָא אִתְקְרִיבַת בְּגִינֵיהּ לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>אֲבָל נִשְׁמָתָא מִסִּטְרָא דִשְׁכִינְתָּא לֵית בָּהּ מוּם, הֲדָא הוּא דִכְתִיב (שיר ד ז) כֻּלָּךְ יָפָה רַעִִיָתִי וּמוּם אֵין בָּךְ, אִם יֵצֶר הָרָע בָּעִי לְקָרְבָא לְהַהוּא אֲתַר, כֵּיוָן דִּשְׁכִינְתָּא שַׁרְיָא תַמָּן דְּאִיהִי נִשְׁמָתָא, אִתְּמַר בָּהּ (במדבר א נא) וְהַזָּר הַקָּרֵב יוּמָת,</p>\n<p>בְּגִין דַּעֲלָהּ אִתְּמַר (ישעיה מב ח) אֲנִי יהו\"ה הוּא שְׁמִי וּכְבוֹדִי לְאַחֵר לֹא אֶתֵּן, דְּהַיְינוּ אֵל אַחֵר אֵל זָר,</p>\n<p>דְּנִשְׁמָתָא אִיהִי יְקָרֵיהּ, וְאִיהִי תּוּשְׁבַּחְתֵּיהּ, דְּבָהּ מְשַׁבַּח בַּר נַשׁ לְקוּדְשָׁא בְּרִיךְ הוּא בִּצְלוֹתָא בְּכָל יוֹמָא בְּכַמָּה תּוּשְׁבְּחָן וְהוֹדָאָן,</p>\n<p>וּבְגִין דָּא אֲנִי יהו\"ה הוּא שְׁמִי וּכְבוֹדִי לְאַחֵר לֹא אֶתֵּן וּתְהִלָּתִי לַפְּסִילִים, אִלֵּין שַׁבְעִין מְמַנָּן, דְּלָא יְהִיב לוֹן קוּדְשָׁא בְּרִיךְ הוּא רְשׁוּ לְשַׁלְטָאָה עֲלָהּ, דְּאִינוּן עַרְקִין דְּכָבֵד דְּאִיהוּ אֵל אַחֵר,</p>\n<p>טְחוֹל נָחָשׁ יוֹתֶרֶת הַכָּבֵד אֵשֶׁת זְנוּנִים, בָּתַר דַּעֲבִידַת זִיּוּפָא (נ\"א נאופא) עִם אֱלֹהִים אֲחֵרִים, וּפַלִּיגַת דְּמָא דִילָהּ דְּאִיהִי תַּמְצִית דִּילָהּ לְכָל עַרְקִין, שִׁיּוּרָא קְרֵיבַת לְגַבֵּי טְחוֹל דְּאִיהוּ בַּעִִלָהּ כְּסִיל, דְּלָא נָטִיל טְחוֹל אֶלָּא תַּמְצִית (נ\"א שמרים) דִּדְמָא, וְלָא יְהִיב לֵיהּ מִדְּמָא אָחֳרָא, וּבְגִין דָּא אִתְקְרִיאַת יוֹתֶרֶת הַכָּבֵד, בְּגִין דְּלָא יְהִיב לֵיהּ אֶלָּא שִׁיּוּרִין,</p>\n<p>וְכָבֵד אִיהוּ קִטְרוּגָא דְרֵיאָה, דְּסָלִיק לְגַבֵּי לִבָּא נוּרָא מִנֵּיהּ, וְאִי לַאו דְּנָשִׁיב בֵּיהּ כַּנְפֵי רֵיאָה, הֲוָה אוֹקִיד לְלִבָּא (והוה אוקיד כל גופא נורא דלבא),</p>\n<p>הַדְרָא דְכִנְתָא לִוְיָתָן, לָקֳבֵל חֵלֶב טָמֵא, וַעֲלֵיהּ אִתְּמַר אֲפִילוּ נָחָשׁ כָּרוּךְ עַל עֲקֵבוֹ לֹא יַפְסִיק, אֲבָל עַקְרָב פּוֹסֵק,</p>\n<p>שָׂרָף אִיהוּ מָרָה קִטְרוּגָא דְרֵיאָה, בְּגִין דְּמָרָה אִיהִי שְׂרֵיפַת כָּל גּוּפָא.</p>\n<p>בְּגִין דָּא תְּקִיעָה שְׁבָרִים וּתְרוּעָה אִינוּן תְּבִירוּ דִלְהוֹן, וַעֲלַיְיהוּ אִתְּמַר (תהלים פט טז) אַשְׁרֵי הָעָם יוֹדְעִי תְרוּעָה יהו\"ה בְּאוֹר פָּנֶיךָ יְהַלֵּכוּן, מַאי פָּנֶיךָ אִלֵּין תְּקִיעָה שְׁבָרִים וּתְרוּעָה, דְּאִינוּן תְּקִיעָה חִוְורוּ דְאַנְפִּין, שְׁבָרִים סוּמְקוּ דְאַנְפִּין, תְּרוּעָה יְרוֹקָא דְאַנְפִּין, וּבָהּ נָפְקִין יִשְׂרָאֵל מִן גָּלוּתָא, בְזִמְנָא דְמִתְהַפְּכִין אַנְפִּין דְּיִשְׂרָאֵל לִירוֹקָא כְּאִתְּתָא עוּבָּרָא.</p>\n<p>וּבְאִלֵּין תְּלַת גַּוָּונִין נַהֲרָא שְׁרַגָּא דְאִיהִי נֵר יהו\"ה נִשְׁמַת אָדָם (משלי כ כז), מַאי אָדָם יו\"ד ה\"א וא\"ו ה\"א,</p>\n<p>תְּלַת גַּוָּונִין דִּשְׁרַגָּא, וּתְלַת גַּוָּונִין אִלֵּין אִינוּן לְבוּשִׁין לִתְלַת אֲבָהָן, דְּאִינוּן חִוָּור סוּמָק יָרוֹק, גַּוָּון אוּכְמָא אִיהִי קַדְרוּתָא דִלְהוֹן, וַעֲלָהּ אִתְּמַר (ישעיה נ ג) אַלְבִּישׁ שָׁמַיִם קַדְרוּת, וּבְהוֹן מִתְלַבְּשִׁין הו\"ה, תְּכֵלֶת לְבוּשָׁא דְאָת י' דְּאִיהוּ תַּכְלִית דְּכֹלָּא,</p>\n<p>נֵר אִיהוּ י', שַׁלְהוֹבָא דְסָלִיק מִנֵּיהּ ו', וְנִעִִנוּעָא דִילֵיהּ הָכָא וְהָכָא דָא ה\"ה.</p>\n<p>וּלְסִטְרָא אָחֳרָא אִית נֵר חֲשׁוֹכָא דְגֵיהִנָּם, וְאִית לֵיהּ תְּלַת גַּוָּונִין, גַּוָּון סוּמָק דָּא כָּבֵד, עִשָׂו הוּא אֱדוֹם (בראשית לו א), מָרָה גַוָּון יָרוֹק, טְחוֹל גַּוָּון שָׁחוֹר, וַעֲלֵיהּ אִתְּמַר (שם כז א) וַתִּכְהֶיןָ עִינָיו מֵרְאוֹת,</p>\n<p>וְסִימָנִיךְ בְּאִלֵּין גַּוָּונִין שְׁקַעֲרוּרוֹת (ויקרא יד לז) יְרַקְרַקּוֹת אוֹ אֲדַמְדַּמּוֹת וּמַרְאֵיהֶן שָׁפָל מִן הַקִּיר, שָׁפָל הוּא גַוָּון אוּכָם, דְּאִתְּמַר</p>"],[9500011105,"<p>בֵּיהּ (שם יג כא), וּשְׁפָלָה אֵינֶנָּה מִן הָעוֹר וְהִיא כֵהָה, וְאִיהִי שִׁפְלוּת דְּנִשְׁמָתָא בְּגוּפָא</p>\n<p>נֵ\"ר (נ\"א כד) נִשְׁמָתָא וְרוּחָא וְנַפְשָׁא אִתְגַּלְיָין בְּכָבֵד מָרָה וּטְחוֹל, כָּל אִינוּן אֵבָרֵי דְגוּפָא דְאִינוּן עַמָּא קַדִּישָׁא, כֻּלְּהוּ דַחֲקָן בִּמְרִירוּ, בְגִין דְּנִשְׁמָתָא אַתְרָא דִילָהּ מוֹחָא, יוֹנָה קַדִּישָׁא,</p>\n<p>נִשְׁמָתָא נִשְׁרָא, דִּבְהַאי יוֹנָה אִתְפַּרְנְסַת, בְּכַמָּה צְלוֹתִין וּפוּלְחָנִין,</p>\n<p>סְפִינָה דְיוֹנָה קַרְקַפְתָּא, וְכַמָּה מְמַנָּן אִית בְּהַאי סְפִינָה דְמַנְהִיגִין לָהּ, וְאִינוּן אוּדְנִין עַיְינִין חוֹטָמָא פוּמָא, שֶׁבַע מְמַנָּן אִינוּן, וְסָלְקִין לְשִׁבְעִים לָשׁוֹן דַּהֲווֹ בִּסְפִינָה דְיוֹנָה.</p>\n<p>וְיוֹנָה אִיהִי צְלוֹתָא שְׁכִינְתָּא תַּתָּאָה, נִשְׁרָא דְאִתְפַּרְנְסַת בָּהּ דָּא שְׁכִינְתָּא עִלָּאָה,</p>\n<p>אִם יִשְׂרָאֵל לָא מִשְׁתַּדְּלִין בִּצְלוֹתִין וּבָעוּתִין וּפוּלְחָנִין דְּנִשְׁרָא דְּאִיהִי רֵיאָה, מִיָּד וַיהו\"ה הֵטִיל רוּחַ גְּדוֹלָה אֶל הַיָּם (יונה א ד), דְּאִיהִי רוּחַ סְעָרָה, רוּחַ יהו\"ה תְּנִיחֵהוּ בְּקַדְמֵיתָא, רוּחַ דְּנָשִׁיב בְּכַנְפֵי נִשְׁרָ\"א דְאִיהוּ עַמּוּדָא דְאֶמְצָעִיתָא, דְבֵיהּ פָּרַח נִשְׁרָא בְאִינוּן תְּרֵין שִׂפְוָון, רוּחַ דְּנָשִׁיב בְּכֻלְּהוּ דָא רוּחַ דְּחוֹטָמָא.</p>\n<p>הַאי רוּחַ בְּכָל אֲתַר דְּאִיהוּ שְׁכִינְתָּא עִלָּאָה וְתַתָּאָה תַמָּן אִשְׁתַּכְּחוּ, אִיהוּ ו' דְּנָשִׁיב בְּכַנְפֵי רֵיאָה, וְעַל לִבָּא דְּתַמָּן נֵר יהו\"ה, דָּא נִשְׁמָתָא בְּמוֹחָא, רוּחַ בְּכַנְפֵי רֵיאָה, נֶפֶשׁ בְּלִבָּא,</p>\n<p>וּלְזִמְנִין תְּלַת בִּתְלַת מוֹחִין, וּמַחֲשָׁבָה רָכִיב עֲלַיְיהוּ דְאִיהוּ אָדָם, וְהָכִי תְּלַת בְּלֵב,</p>\n<p>נֵ\"ר נְ\"שָׁמָה ר\"וּחַ. רוּחָא דְנָשִׁיב בְּהוֹן נֵ\"ר בִּתְרֵי בָּתֵּי לִבָּא, וְאִינוּן נֶפֶ\"שׁ וְרוּ\"חַ, סִימָן נֵ\"ר,</p>\n<p>וְהַאי ו' אִיהוּ דְנָשִׁיב בִּדְרוֹעִין בְּשִׁית פִּרְקִין דִּלְהוֹן, וְאִיהוּ נַשִּׁיב בִּתְרֵין שׁוֹקִין בְּשִׁית פִּרְקִין, דְּאִתְּמַר בְּהוֹן (שיר ה טו) שׁוֹקָיו עַמּוּדֵי שֵׁשׁ, וַעֲלֵיהּ אִתְּמַר (ישעיה יא ב) וְנָחָה עָלָיו רוּחַ יהו\"ה.</p>\n<p>כַּד אֵבָרִין דְּגוּפָא מִתְנַהֲגִין בְּהַאי רוּחָא בְּאוֹרַיְיתָא קַדִּישָׁא בְּפִקּוּדִין דְּאוֹרַיְיתָא, סְפִינָה מִתְנַהֲגָא לְכָל סִטְרָא דְבָעִי בַּר נַשׁ, כְּמָה דְאַתְּ אָמַר (יחזקאל א יב) אֶל אֲשֶׁר יִהְיֶה שָׁמָּה הָרוּחַ לָלֶכֶת יֵלֵכוּ, דִּסְפִינָה אִיהִי רֵישָׁא וְאִיהִי לִבָּא וְאִיהִי גוּפָא.</p>\n<p>וְאִם אֵבָרִין דְּגוּפָא דְאִינוּן מָארֵי סְפִינָה דְאִינוּן עַמָּא קַדִּישָׁא, לָא מִתְנַהֲגִין בְּאוֹרַיְיתָא דְאִיהִי נִשְׁמָתָא וּבְמִצְוָה דְאִיהִי נַפְשָׁא, פָּרַח רוּחָא מִבֵּינַיְיהוּ,</p>\n<p>בְּהַהוּא זִמְנָא (יונה א ד) וַיהו\"ה הֵטִיל רוּחַ גְּדוֹלָה אֶל הַיָּם, דְּאִיהִי רוּחַ סְעָרָה, דְאִיהִי גְזֵרַת דִּינָא קַשְׁיָא, דִסְעָרָה גוּפֵיהּ דְּבַר נַשׁ דְּאִינוּן יִשְׂרָאֵל, וְיִשְׂרָאֵל אִינוּן בִּסְעָרָה, וְהָאֳנִיָּה דְאִיהִי גוּפָא חִשְּׁבָה לְהִשָּׁבֵר.</p>\n<p>בֵּיהּ זִמְנָא וְיוֹנָה יָרַד אֶל יַרְכְּתֵי הַסְּפִינָה (שם ה) דָא שְׁכִינְתָּא תַּתָּאָה, דְּאִתְּמַר בָּהּ (רות ג ז) וַתְּגַל מַרְגְּלוֹתָיו וַתִּשְׁכָּב, שְׁכִיבַת לְעַפְרָא, וְדָא אִיהוּ (יונה א ה) וַיִּשְׁכַּב וַיֵּרָדַּם, וְאַמַּאי נָפְלַת, בְּגִין דְּפָרַח מִינָהּ רוּחָא דְאִיהוּ עַמּוּדָא דְאֶמְצָעִיתָא דְסָמִיךְ לָהּ, וְאִיהִי נָפְלַת,</p>\n<p>וּבְהַהוּא זִמְנָא אִתְּמַר בָּהּ (איכה א א) אֵיכָה יָשְׁבָה בָדָד, וּמָאן גָּרִים נְחִיתוּ דִילָהּ, בְּגִין דִּבְטִילוּ יִשְׂרָאֵל אוֹרַיְיתָא וּמִצְוָה,</p>\n<p>בְּהַהוּא זִמְנָא דְאִיהִי נָחֲתַת בֵּין רַגְלִין, יִשְׂרָאֵל בְּנָהָא אִינוּן מְהוּדָקִין בֵּין רַגְלִין, וְאִינוּן בְּמַרְעִין בְּמַכְתָּשִׁין,</p>\n<p>בְּהַהוּא זִמְנָא דְגוּפָא בְּבֵי מַרְעִין דְּאִינוּן יִשְׂרָאֵל, וּשְׁכִינְתָּא עִמְּהוֹן דְּאִיהִי יוֹנָה, מַה כְּתִיב בֵּיהּ (יונה א ו) וַיִּקְרַב אֵלָיו רַב הַחוֹבֵל, הַהוּא דְחָבִיל בִּשְׂרָא בְּבֵי מַרְעָא.</p>\n<p>וְעוֹד מָאן רַב הַחוֹבֵל הַהוּא דְאִתְּמַר בֵּיהּ (שמות כב כה) אִם חָבוֹל תַּחְבּוֹל שַׂלְמַת רֵעִִךָ, חָבוֹל בְּבַיִת רִאשׁוֹן, תַּחְבּוֹל בְּבַיִת שֵׁנִי, וְאִיהוּ רַב דְּכָל מַנְהִיגֵי סְפִינָה,</p>\n<p>וּמָה אָמַר לֵיהּ (יונה א ו) קוּם קְרָא אֶל אלהי\"ך, דְּהָא דִינִין קָא אַתְיָין עֲלָךְ וְעַל בְּנָיִךְ, הָא מָארֵי דְחוֹבִין מִתְכַּנְשִׁין, דְּאִינוּן סַחֲרִין לִסְפִינָה דִילָךְ דְּאִינוּן רוּחִין בִּישִׁין, אִסְתַּכַּל בְּזַכְוָון דִּילָךְ, בְּאִלֵּין אֵבָרִים דְּמִשְׁתַּדְלִין בְּאוֹרַיְיתָא וּבְפִקּוּדִין טָבִין, וְיַחֲזִירוּן שְׁכִינְתָּא עִלָּאָה דְאִיהִי תְּיוּבְתָּא עֲלָךְ, וְאִיהִי אֲגִינַת עֲלָךְ,</p>\n<p>דַּעֲלָהּ אִתְּמַר (דברים לב יא) כְּנֶשֶׁר יָעִיר קִנּוֹ דָּא יְרוּשָׁלֵם, עַל גּוֹזָלָיו יְרַחֵף (שם) דְּאִינוּן יִשְׂרָאֵל, יִפְרוֹשׂ כְּנָפָיו עֲלַיְיהוּ בְּשַׁבַּתָּא וְיֹמִין טָבִין, וּבְגִינָהּ מְבָרְכִין בְּהוֹן</p>"],[9500011106,"<p>בָּרוּךְ אַתָּה יהו\"ה הַפּוֹרֵס סֻכַּת שָׁלוֹם,</p>\n<p>וּבְזִמְנָא דִפְּרִישַׁת גַּדְפָהָא עַל יִשְׂרָאֵל אִתְּמַר (דברים לב יא) יִקָּחֵהוּ יִשָּׂאֵהוּ עַל אֶבְרָתוֹ, כְּמָה דְאוּקְמוּהוּ (שמות יט ד) וָאֶשָּׂא אֶתְכֶם עַל כַּנְפֵי נְשָׁרִים וכו',</p>\n<p>וּבְגִין דָּא קוּם קְרָא אֶל אלהי\"ך דְאִיהִי שְׁכִינְתָּא עִלָּאָה, דְאִיהִי תְיוּבְתָּא דִילָךְ, וְתוּב בָּהּ לְמָארָךְ דְּאִיהוּ קוּדְשָׁא בְּרִיךְ הוּא,</p>\n<p>אִסְתַּכַּל דְּשִׁפְחָה בִּישָׁא שָׁלְטָא עֲלָךְ דְּאִיהִי טִפָּה סְרוּחָה, וַעֲלָהּ אִתְּמַר (איוב א ז) וַיֹּאמֶר יהו\"ה אֶל הַשָּׂטָן מֵאַיִן תָּבֹא, דְּכָל חוֹבִין אִינוּן מֵאֵבָרִין דְּטִפָּה סְרוּחָה, דִּבְגִינָהּ אִתְּמַר לְגַבֵּי חַיָּיבַיָּא מֵאַיִן בָּאתָ מִטִּפָּה סְרוּחָה,</p>\n<p>וַיַּחְתְּרוּ הָאֲנָשִׁים לְהָשִׁיב אֶל הַיַּבָּשָׁה (יונה א יג) בְּתִיּוּבְתָּא, וְלֹא יָכוֹלוּ כִּי הַיָּם, דְּאִיהוּ גְזֵרַת דִּינָא, הוֹלֵךְ וְסוֹעִר עֲלֵיהֶם.</p>\n<p>בְּהַהוּא זִמְנָא וַיְמַן יהו\"ה דָּג גָּדוֹל לִבְלוֹעַ אֶת יוֹנָה (שם ב א), דָא גָלוּתָא קַדְמָאָה, דְּאִתְּמַר בֵּיהּ וְיוֹנָה יָרַד אֶל יַרְכְּתֵי הַסְּפִינָה, וְדָא הוּא (בראשית מו ד) אָנֹכִי אֵרֵד עִמְּךָ מִצְרַיְמָה, כְּמָה דְאוּקְמוּהוּ בְּכָל אֲתַר דְּגָלוּ יִשְׂרָאֵל שְׁכִינְתָּא עִמְּהוֹן,</p>\n<p>קִלְקְלוּ יִשְׂרָאֵל עוֹבְדֵיהוֹן, בֵּיהּ זִמְנָא אִתְּמַר בְּהוֹן (שמות א ח) וַיָּקָם מֶלֶךְ חָדָשׁ עַל מִצְרָיִם, וְדָא פַּרְעֹה, עֲלֵיהּ אִתְּמַר וַיְמַן יהו\"ה דָּג גָּדוֹל לִבְלוֹעַ אֶת יוֹנָה, דְּבָעָא לְבַטְלָא יִשְׂרָאֵל מֵעָלְמָא, הֲדָא הוּא דִכְתִיב (שם כב) כָּל הַבֵּן הַיִּלּוֹד הַיְאוֹרָה תַּשְׁלִיכוּהוּ,</p>\n<p>לְקִבְּלֵיהּ וַיְמַן יהו\"ה דָּג גָּדוֹל לִבְלוֹעַ אֶת יוֹנָה, לְקַטְלֵיהּ, לִבְלוֹעַ יוֹנָה לָא כְּתִיב, אֶלָּא לִבְלוֹעַ אֶת יוֹנָה, אֶת אָתָא לְרַבּוֹת רַעִִיָא מְהֵימְנָא דְעָתִיד לְאִתְיַיהֲבָא אוֹרַיְיתָא עַל יְדֵיהּ, דְּאִיהִי מֵאַלֶּ\"ף וְעַד תָּי\"ו,</p>\n<p>כָּל אִלֵּין גִּלְגּוּלִין עַל יְדֵיהּ הֲווֹ, וְדָא אִיהוּ דָּג גָּדוֹל, דְּאִתְּמַר בֵּיהּ (יחזקאל כט ג) הַתַּנִּין הַגָּדוֹל, אִיהוּ דָּג מִצְרָיִם, וּבַת זוּגֵיהּ דָּגָה (יונה ב ב) וַיִּתְפַּלֵּל יוֹנָה אֶל יהו\"ה אֱלֹהָי\"ו מִמְּעִי הַדָּגָה, מָאן מְעִי הַדָּגָה אִלֵּין מִצְרָאֵי.</p>\n<p>וְעוֹד וַיְמַן יהו\"ה דָּג גָּדוֹל, דָּא טְחוֹל לִילִית דְּאִיהִי עִרֶב רַב מֵהַהוּא רַב הַחוֹבֵל (נ\"א דא סמא\"ל, דגה דא נח\"ש לילי\"ת בת זוגיה מההוא רב החובל טחול דאיהו ערב רב) דְּאִתְּמַר בֵּיהּ (שמות יב לח) וְגַם עִרֶב רַב וכו', וּטְחוֹל אִיהוּ שְׂחוֹק הַכְּסִיל, עֲלֵיהּ אִתְּמַר (קהלת ז ט) כִּי הַכַּעַס בְּחֵיק כְּסִילִים יָנוּחַ,</p>\n<p>לִבְלוֹעַ אֶת יוֹנָה דָא נַפְשָׁא, מִסִּטְרָא דִילֵיהּ (שמות ו ט) וְלֹא שָׁמְעוּ אֶל מֹשֶׁה מִקֹּצֶר רוּחַ, וּמֵעֲבוֹדָה קָשָׁה מִסִּטְרָא דְכָבֵד, דְּאִתְּמַר בֵּיהּ (שם ז יד) כָּבֵד לֵב פַּרְעֹה, תִּכְבַּד הָעֲבוֹדָה, (שם ה ט) מִסִּטְרָא דְמָרָה (שם א יד) וַיְמָרַרוּ אֶת חַיֵּיהֶם.</p>\n<p>דָּג גָּדוֹל אִיהוּ עִרֶב רַב, דְּאִינוּן (נ\"א דאיהו) רַב הַחוֹבֵל, מָאן חוֹבֵל אֶלָּא רַב מִכָּל מַלְאֲכֵי חַבָּלָה, אִיהוּ חוֹבֵל, וְאִיהִי חַבָּלָה, עִרֶב רַב בְּנִין דְּלִילִית חַיָּיבָא, דִבְהוֹן חָאבוּ יִשְׂרָאֵל וַחֲבִילוּ יָת בִּשְׂרַיְיהוּ בְּאָת בְּרִית, אִינוּן רַב עֲלַיְיהוּ בְגָלוּתָא, וְאִינוּן דָּגָה לְיִשְׂרָאֵל, וּבְגִין דָּא אָמְרוּ (במדבר יא ה) זָכַרְנוּ אֶת הַדָּגָה וכו'.</p>\n<p>וּבְזִמְנָא דְנָפְקוּ יִשְׂרָאֵל מִמִּצְרַיִם קְטִיל מִנַּיְיהוּ סַגִּיאִין, וּבְגָלוּתָא בַתְרָאָה עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְקָטְלָא לוֹן, וְדָא אִיהוּ (שמות ז יח) וְהַדָּגָה אֲשֶׁר בַּיְאוֹר מֵתָה, וַיִּבְאַשׁ הַיְאוֹר דָּא אוֹרַיְיתָא, דְאִתְּמַר בָּהּ (משלי ו כג) וְתוֹרָה אוֹר, סָרְחַת לְגַבַּיְיהוּ,</p>\n<p>וְאִתְּמַר בְּיִשְׂרָאֵל (שמות א כב) כָּל הַבֵּן הַיִּלּוֹד הַיְאוֹרָה תַּשְׁלִיכוּהוּ, אוֹר אִיהוּ רָ\"ז, הַיְאוֹרָה בַּת זוּגֵיהּ דְּהַהוּא אוֹר, דְּאִתְּמַר בָּהּ (שם י כג) וּלְכָל בְּנֵי יִשְׂרָאֵל הָיָה אוֹר בְּמוֹשְׁבוֹתָם,</p>\n<p>כְּגַוְונָא דָא בְגָלוּתָא בַתְרָאָה (היאורה) הַזּוֹהַר בֵּיהּ הָוָה רָ\"ז, דְּאִיהוּ אוֹר דְּפוּרְקָנָא בַתְרַיְיתָא, לְקַיֵּים (מיכה ז טו) כִּימֵי צֵאתְךָ מֵאֶרֶץ מִצְרָיִם אַרְאֶנּוּ נִפְלָאוֹת, וְדָא אִיהוּ כָּל הַבֵּן הַיִּלּוֹד הַיְאוֹרָה תַּשְׁלִיכוּהוּ, וְכָל הַבַּת תְּחַיּוּן, אִלֵּין דְּמִשְׁתַּדְלִין בְּאוֹרַיְיתָא דִבְעַל פֶּה.</p>\n<p>דָּבָר אַחֵר וַיְמַן יהו\"ה דָּג גָּדוֹל לִבְלוֹעַ אֶת יוֹנָה (יונה ב א), דָּא עֲנִיּוּתָא, דְּאִיהוּ עִִצֶב, וְנוּקְבָא דִילֵיהּ עִצָּבוֹן, דְּכוּרָא דָג נוּקְבָא דָגָה, דָּא הוּא (שם ב) וַיִּתְפַּלֵּל יוֹנָה אֶל יהו\"ה אֱלֹהָי\"ו מִמְּעִי הַדָּגָה, מִכַּפְנָא דַעֲנִיּוּתָא דְמָטֵי לִמְעוֹי דְּיִשְׂרָאֵל,</p>\n<p>בְּהַהוּא זִמְנָא וַיֹּאמֶר יהו\"ה לַדָּג וַיָּקֵא אֶת יוֹנָה וְגוֹמֵר (שם יא), בְּדוֹחֲקָא דִדְאָגָה דִלְהוֹן דְּדוֹאֲגִין מִן עֲנִיּוּתָא, מִדּוֹחֲקָא יִפְקוּן מִן גָּלוּתָא, הֲדָא הוּא דִכְתִיב (שמואל ב, כב כח) וְאֶת עַם עָנִי תּוֹשִׁיעַ, דָּא נְבוּאָה דְיוֹנָה דְנִתְנַבָּא דְיִפְקוּן יִשְׂרָאֵל מִן גָּלוּתָא בִדְאָגָה (ס\"א בדוחקא) דַעֲנִיּוּתָא,</p>\n<p>וּבִימִינָא יִפְקוּן,</p>"],[9500011107,"<p>בְּגִין דְּצַדִּיק חַ\"י עָלְמִין אִיהוּ עָנִי דְאִתְקַשַּׁר בִּימִינָא, דְאִיהוּ פֶּסַח, כְּגַוְונָא דְיִשְׂרָאֵל דְּאִתְּמַר בְּהוֹן (יחזקאל טז ז) וְאַתְּ עִרוֹם וְעִִרְיָה,</p>\n<p>וְהַאי יוֹנָה אִיהִי יוֹנָה דְתֵיבַת נֹחַ.</p>\n<p>דָּבָר אַחֵר (יונה ב יא) וַיֹּאמֶר יהו\"ה לַדָּג וַיָּקֵא אֶת הַיוֹנָה אֶל הַיַּבָּשָׁה,</p>\n<p>קָם סָבָא מִבָּתַר טוּלָא פָּתַח וְאָמַר, וְהַמָּן כִּזְרַע גַּד הוּא (במדבר יא ז), מַאי כִּזְרַע גַּד, אֶלָּא גַד אִיהוּ יְמִינָא וּשְׂמָאלָא, גְמוֹ\"ל דַּלִּי\"ם, כִּזְרַע גַּד דָּא יוֹנָה י' וַדַּאי, טִפָּה חִוַּורְתָּא, דְּבֵיהּ אִשְׁתַּלִּים גַּד וְאִתְעֲבִיד גִּיד,</p>\n<p>וְעַל דָּא הַאי זַרְעָא דְאִיהִי יוּ\"ד דְּאִיהִי טִפָּה קַדִּישָׁא, אִתְּמַר (יונה ב יא) וַיָּקֵא אֶת יוֹנָה אֶל הַיַּבָּשָׁה דְאִיהִי נוּקְבָא, וּמִמַּה דַּהֲוַת יַבָּשָׁה ה' אִתְקְרִיאַת אֶרֶץ, לְאַפָּקָא זַרְעִין וְאִיבִין, הֲדָא הוּא דִכְתִיב (בראשית א י) וַיִּקְרָא אלהי\"ם לַיַּבָּשָׁה אֶרֶץ,</p>\n<p>וּלְמִקְוִה הַמַּיִם קָרָא יַמִּים, דָּא מִקְוִה יִשְׂרָאֵל מוֹשִׁיעוֹ בְּעִת צָרָה (ירמיה יד ח).</p>\n<p>מְקוֹרָא דִנְבִיעוּ מֵהַהוּא זֶרַע דְּאִתְמַשַּׁךְ מִמּוֹחָא עִלָּאָה, וְהַאי (נ\"א וההיא) טִפָּה אִיהִי י' זְעִירָא, כַּד נָפְקַת א מִן מוֹחָא דְאִיהִי חָכְמָה, כָּל סְפִירָה נָטְלַת חֶלְקָהָא, עַד דְּאִתְפַּלִּיגַת לְתֵשַׁע נְקוּדִין,</p>\n<p>וְכַד נָטִיל כָּל חַד חוּלָקֵיהּ אִשְׁתָּאַרַת עִשּׂוּרָא מִכֻּלְּהוּ טִפִּין, דְּנַטִּילַת הַהִיא יַבָּשָׁה דְּאִיהִי עֲשִׂירִית הָאֵיפָה סֹלֶת, וּבְגִינָהּ מְעַשְּׂרִין.</p>\n<p>וְהַהִיא טִפָּה בְּעַמּוּדָא דְאֶמְצָעִיתָא אִתְאָרְכַת, וְאִתְעֲבִידַת זֶרַע ו', דְּכָלִיל שִׁית סִטְרִין, וּכְמָה דְכָל סְפִירָן נָטְלִין חוּלָקֵיהוֹן מֵהַהוּא טִפָּה, הָכִי נָטְלִין מִזֶּרַע (נ\"א מההוא זרע) דְּאִיהוּ ו', כַּד אִיהוּ זְעִיר אִתְעֲבִיד שִׁית, כַּד נָטִיל בְּיוּ\"ד סָלִיק לְשִׁתִּין, שִׁית זִמְנִין עִִשֶׂר, אֲבָל כָּל סְפִירָן כָּל חַד אִיהוּ תֵשַׁע, וּמַלְכוּת בָּהּ אִשְׁתַּלִּים כָּל חַד לְעִִשֶׂר,</p>\n<p>וְכֹלָּא אִתְמַשַּׁךְ לְגַבֵּיהּ דְּגִיד דְּאִיהוּ צַדִּיק, וּמִנֵּיהּ לְהַהוּא יַבָּשָׁה, וּבְהַהוּא זִמְנָא דְאָרִיק בָּהּ כֹּלָּא אִתְקְרִיאַת תֵּיבַת נֹחַ,</p>\n<p>וְרָזָא דְמִלָּה וַתָּנַח הַתֵּיבָה בַּחֹדֶשׁ הַשְּׁבִיעִי (בראשית ח יג), מַה דַּהֲוַת ה' יַבָּשָׁה, אִתְעֲבִידַת הֵ\"א הַשְּׁבִיעִי,</p>\n<p>וְדָא אִיהוּ וַתָּנַח הַתֵּיבָה בַּחֹדֶשׁ הַשְּׁבִיעִי, וַתָּנַח וַדַּאי בַּחֹדֶשׁ הַשְּׁבִיעִי, וְדָא אִיהוּ גִיד צַדִּיק חַ\"י עָלְמִין, בְּגִין דְּמִנֵּיהּ נָפִיק זֶרַע לְהַאי יַבָּשָׁה.</p>\n<p>וְכָל מָאן דְּאַפֵּיק הַאי זֶרַע דְּאִיהוּ נְבִיעוּ מִלְּעִילָא דְלָא בְהַאי יַבָּשָׁה, גָרִים פִּרוּדָא בְהַהוּא נְבִיעוּ, כַּבְיָכוֹל כְּאִלּוּ אִתְפַּסַּק נְבִיעוּ דִשְׁכִינְתָּא, וְיִתְרַבָּהּ נְבִיעוּ דְסִטְרָא אָחֳרָא, דְאִינוּן מֵי טוֹפָנָא, הֲדָא הוּא דִכְתִיב (בראשית ז יט) וְהַמַּיִם גָּבְרוּ מְאֹד מְאֹד עַל הָאָרֶץ,</p>\n<p>בְּהַהוּא זִמְנָא דְלֵית נְבִיעוּ בְּהַהִיא יַבָּשָׁה דְהִיא כְּבֵדָה, אִתְעֲבִידַת קַלָּה, לְאִסְתַּלְקָא מֵעַל יִשְׂרָאֵל, וְאִתְּמַר בָּהּ (שם יז) וַתָּרָם מֵעַל הָאָרֶץ, וְלָא נָחֲתַת עַד יַרְחָא שְׁבִיעָאָה, דְאִתְמְלִיאַת בְּזַכְוָון דִּילָהּ וְאִיהִי כְּבֵדָה נָחֲתַת, הֲדָא הוּא דִכְתִיב (שם ח ד) וַתָּנַח הַתֵּיבָה בַּחֹדֶשׁ הַשְּׁבִיעִי, דְאִיהוּ תִּשְׁרִי דְרוֹעָא שְׂמָאלָא,</p>\n<p>דְּאִי הֲווֹ נָפְקִין בֵּיהּ יִפְקוּן בְּמִיתָה, וְלָא יִשְׁתָּאֲרוּן אֶלָּא חַד מֵעִיר וּשְׁנַיִם מִמִּשְׁפָּחָה, חַד מֵעִיר כְּגוֹן נֹחַ, וּשְׁנַיִם מִמִּשְׁפָּחָה כְּגוֹן שֵׁם וְיֶפֶת, וּמֵאָחֳרָנִין שְׁנַיִם שְׁנַיִם שִׁבְעָה שִׁבְעָה, מֵאִינוּן עַמֵּי הָאָרֶץ דְּדַמְיָין לִבְעִירָן וְעוֹפִין וְחֵיוָון,</p>\n<p>וְאִלֵּין אִינוּן דְּאוֹקְרִין יָמִים טוֹבִים וְחַגִּין, דְּאִינוּן שְׁנַיִם שְׁנַיִם תְּרֵין יוֹמִין חַד דְּרֹאשׁ הַשָּׁנָה וְחַד דְּשָׁבוּעוֹת, תְּרֵין יוֹמִין דְּפוּרִים, שִׁבְעָה שִׁבְעָה אִלֵּין שִׁבְעָה יוֹמִין דְּפִסְחָא, וְשִׁבְעָה יוֹמִין דְּסֻכּוֹת,</p>\n<p>אוֹ דְמִתְפַּלְּלִין חַ\"י בִּרְכָאָן דִּצְלוֹתָא בְּכָל יוֹמָא.</p>"],[9500011108,"<p>דְסָלְקִין לְחוּשְׁבַּן שְׁנַיִם שְׁנַיִם שִׁבְעָה שִׁבְעָה חַ\"י.</p>\n<p>אוֹ אִלֵּין דַּהֲווֹ נָטְרִין י' דְּאִיהוּ אוֹת בְּרִית מִילָה דְאִיהוּ לִשְׁמֹנָה דְכֹלָּא חַ\"י,</p>\n<p>אוֹ אִלֵּין דְּמַנְחָן תְּפִלֵּי בְּכָל יוֹמָא דְאִינוּן אוֹת י', כְּמָה דְאַתְּ אָמַר (שמות יג טז) וְהָיָה לְאוֹת כו', וַהֲווֹ קָשְׁרִין לֵיהּ בְּח' בָּתֵּי דִתְּפִלֵּי, דְאִינוּן ד' בָּתֵּי דִתְּפִלִּין דְּרֵישָׁא, וְאַרְבַּע פַּרְשִׁיָּין דִּתְּפִלִּין דְּיָד,</p>\n<p>אוֹ אִינוּן דְּנָטְרִין אוֹת י' שַׁבָּת בִּתְּחוּמָא דִילֵיהּ דְּאִיהוּ ח', תְּרֵי אַלְפֵי אַמִּין לְכָל סִטְרָא, וְכֹלָּא חַ\"י,</p>\n<p>לְאִלֵּין אִינוּן מְקַבְּלִין בִּתְשׁוּבָה, דְאִיהִי תֵּיבַת נֹחַ יוֹם הַכִּפּוּרִים. אֲבָל לְאָחֳרָנִין לָא יְקַבֵּל לוֹן בִּתְיוּבְתָּא, וְאִם יִפְקוּן בְּיוֹמָא דְּדִינָא, אִלֵּין דְּלָא הֲווֹ נָטְרִין, אִתְּמַר בְּהוֹן (בראשית ז כא) וַיִּגְוַע כָּל בָּשָׂר הָרֹמֵשׂ עַל הָאָרֶץ, וְאִלֵּין אִתְקְרִיאוּ רְשָׁעִים גְּמוּרִים דְּנִדּוֹנִין לְאַלְתַּר לְמִיתָה, דִּבְהוֹן בְּשִׁית יוֹמִין הֲוַת שְׁכִינְתָּא מִתְתַּרְכָא</p>\n<p>הֲדָא הוּא דִכְתִיב (שם ח ט) וְלֹא מָצְאָה הַיּוֹנָה מָנוֹחַ לְכַף רַגְלָהּ, וְאִלֵּין אִינוּן יוֹמִין דְּחוֹל.</p>\n<p>צַדִּיקִים גְּמוּרִים אִלֵּין אִינוּן דְּנָטְרִין חַ\"י וְשַׁבָּתוֹת וְיֹמִין טָבִין, עֲלַיְיהוּ אִתְּמַר וַתָּשָׁב אֵלָיו הַיּוֹנָה לְעִת עִִרֶב וְדָא עַרְבֵי שַׁבָּתוֹת וְיוֹמִין טָבִין, דִּשְׁכִינְתָּא קָא אַתְיָא לְשַׁרְיָא עֲלַיְיהוּ בְּגִין דְּאִינוּן קֹדֶשׁ, כְּמָה דְאַתְּ אָמַר (ירמיה ב ג) קֹדֶשׁ יִשְׂרָאֵל לַיהו\"ה,</p>\n<p>וְאַתֶּם הַדְּבֵקִים בַּיהו\"ה אלהיכ\"ם חַיִּים כֻּלְּכֶם הַיּוֹם (דברים ד ד). וְאִינוּן צַדִּיקִים גְּמוּרִים דְּנִכְתָּבִין וְנֶחתָמִין לְאַלְתַּר לְחַיִּים, וּכְתִיבִין בְּסִפְרָא דְחַיֵּי, כְּמָה דְאַתְּ אָמַר וּבְסֵפֶר חַיִּים בְּרָכָה וכו',</p>\n<p>בֵּינוּנִיִּים דִּכְּלִילָן מֵחוֹל וְקֹדֶשׁ תַּלְיָין עַד יוֹם הַכִּפּוּרִים דְּאִיהוּ כְּגַוְונָא דְתֵּיבַת נֹחַ, אִם תַּיְיבִין בִּתְיוּבְתָּא יְקַבֵּל לוֹן וְיִכָּתְבוּן לְחַיֵּי, וְאִם לַאו יִכָּתְבוּן לְמִיתָה עִם אָחֳרָנִין, דְּאִתְּמַר בְּהוֹן (בראשית ז כא) וַיִּגְוַע כָּל בָּשָׂר וכו',</p>\n<p>וּבֵינוּנִיִּים בְּגִין דְּאִית בְּהוֹן פִּקּוּדִין וְחוֹבִין, אִתְּמַר בְּהוֹן (שם ו יט) וּמִכָּל הָחַי מִכָּל בָּשָׂר וכו', מִכָּל הָחַי מִסִּטְרָא דְזַכְוָון, מִכָּל בָּשָׂר מִסִּטְרָא דְחוֹבִין.</p>\n<p>(ועוד דבזמנא דייתי משיחא כל אינון דנטרו אות ברית ישזיב יתהון ממותנא, דבההוא זמנא יתבטל מותנא, דהוו מתנבאין אינון נביאיא דאספקלריא דלא נהרא דלא ישתארון אלא חד מעיר ושנים ממשפחה, כגון ההוא דכתיב (שם ז ט) שנים שנים באו אל נח,</p>\n<p>ואית מאן דאמר שבעה שבעה מסטרא דבת שבע, ואלין אינון חד מעיר, נח דא שבת, דביה נייחא דירית לה צדיק, שנים שנים תרין יומין חד דראש השנה וחד דיום הדין, דתניינא איהו מספק ויומא חדא דיום הכפורים, ויומא חדא דשבועות, ושבעה שבעה אינון שבעה יומי דסכות ושבעה יומי דפסחא, דמאן דנטיר אינון יומין עתיד לאשתזבא בגלותא).</p>\n<p>וּבְגִין דְּגַלֵּי כָּל דָּא קוּדְשָׁא בְּרִיךְ הוּא לְמֹשֶׁה, שְׁאִיל רַחֲמֵי עֲלַיְיהוּ, וּמָסַר גַּרְמֵיהּ לְמִיתָה, הֲדָא הוּא דִכְתִיב (שמות לב לב) וְאִם אַיִן מְחֵנִי נָא מִסִּפְרְךָ, וּבְפִיּוּסָא דִילֵיהּ אִדַּבַּק בְּמַלְכָּא, וַאֲחִיד בִּדְרוֹעָא דִיְמִינָא וְאָמַר (שם יג) זְכוֹר לְאַבְרָהָם, וּלְבָתַר אֲחִיד בִּשְׂמָאלָא וְאָמַר זְכוֹר לְיִצְחָק, וּלְבָתַר אֲחִיד בְּגוּפָא וְאָמַר (שם) וּלְיִשְׂרָאֵל,</p>\n<p>וְאָמַר קוּדְשָׁא בְּרִיךְ הוּא לְאִלֵּין בֵּינוּנִים לְגַבַּיְיהוּ תַּמָּה זְכוּת אָבוֹת, כֵּיוָן דְּלָא תָאבוּ בִתְיוּבְתָּא הָא אִינוּן כִּרְשָׁעִים גְּמוּרִים וְאִם תָּאבִין בִּתְיוּבְתָּא אִתְּמַר לְגַבַּיְיהוּ חָלָה זְכוּת אָבוֹת,</p>\n<p>וּבְגִין דְּלָא יִתְאֲבִידוּ אִלֵּין בֵּינוּנִיִּים אָמַר מֹשֶׁה וְכִי יֵמְרוּן בְּנֵי עָלְמָא דַאֲנָא כְּנֹחַ דְּלָא בָּעָא רַחֲמֵי עַל דָּרֵיהּ, בְּהַהוּא זִמְנָא מָסַר גַּרְמֵיהּ עֲלַיְיהוּ, הֲדָא הוּא דִכְתִיב וְאִם אַיִן מְחֵנִי נָא.</p>\n<p>וּבְגִין דָּא עָתִיד רַעִִיָא מְהֵימְנָא לְמֶהֱוִי בְגָלוּתָא בַתְרָאָה, וּבֵיהּ יִתְקַיֵּים (ישעיה נג ה) וְהוּא מְחוֹלָל מִפְּשָׁעִינוּ, אִתְעֲבִיד חוֹל בְּגִינַיְיהוּ, מְדוּכָּא בַּעֲוֹנוֹתֵינוּ בְּמַכְתְּשִׁין דְּיִסּוּרִין דַּעֲנִיּוּתָא, בְּכַמָּה דוֹחֲקִין דְּסָבִיל עֲלַיְיהוּ, וּבְגִינֵיהּ (שמות לב ד) וַיִּנָּחֶם יהו\"ה עַל הָרָעָה וְגוֹמֵר, וְהֲדָא הוּא דִכְתִיב (ישעיה נג ה) וּבַחֲבוּרָתוֹ נִרְפָּא לָנוּ,</p>\n<p>וּבְגִינֵיהּ שְׂמֹאל דּוֹחֶה לְבֵינוּנִיִּים דְּאִיהִי רֹאשׁ הַשָּׁנָה, וְיָמִין מְקָרֵב לוֹן בִּתְיוּבְתָּא דְאִיהוּ פֶּסַח,</p>"],[9500011109,"<p>דְּרוֹעָא יְמִינָא לְקַבֵּל שָׁבִים, וְיוֹקִים לוֹן מִנְּפִילוּ דִלְהוֹן וַאֲחִיד בִּידֵיהוֹן, וְיֵימִי לוֹן קוּמִי שְׁבִי יְרוּשָׁלָם,</p>\n<p>וּבְשָׁבוּעוֹת יִפְקוּן בִּזְכוּתָא דְמֹשֶׁה דְאִיהוּ מַתַּן תּוֹרָה רַחֲמֵי, וְגַלִּי לוֹן סֵפֶר תּוֹרָה, וְיִתְכַּנְשׁוּן לִירוּשְׁלֵם, וְתֵרָאֶה הַיַּבָּשָׁה מַלְכוּת הָרִשְׁעָה, וְרַחֲמֵי עַל בְּנוֹי, וּבֵיהּ (דברים לב יא) כְּנֶשֶׁר יָעִיר קִנּוֹ, מָאן קִנּוֹ יְרוּשְׁלֵם קִנּוֹ (לשכינתא).</p>\n<p>בְּהַהוּא זִמְנָא שׁוֹפָ\"ר מְהוּפָּ\"ךְ קַדְמָ\"א זָקֵף קָטָ\"ן, אִתְהַפַּךְ מֶמְשָׁלָה דְאוּמִין דְּעָלְמָא, וְיִשְׂרָאֵל דְּאִינוּן מִזַּרְעָא דְהַהוּא דְאִתְּמַר בֵּיהּ (בראשית לב יא) קָטֹנְתִּי מִכֹּל הַחֲסָדִים אִסְתַּלַּק וְאִזְדַּקַּף,</p>\n<p>וְאִתְּמַר בֵּיהּ זָקֵ\"ף גָּדוֹ\"ל, בִּימִינָא אִסְתַּלְקוּ מִן גָּלוּתָא, בְּגִין דְּמוֹלִיךְ לִימִין מֹשֶׁה דְּדַרְגֵּיהּ עַמּוּדָא דְאֶמְצָעִיתָא דְאִיהוּ שָׁבוּעוֹת.</p>\n<p>וּבֵיהּ מַאֲרִי\"ךְ טַרְחָ\"א, בֵיהּ מַאֲרִיךְ קוּדְשָׁא בְּרִיךְ הוּא דְאִיהוּ אֶרֶךְ אַפַּיִם עַל בֵּינוּנִיִּים, וְטָרַח בְּגִינַיְיהוּ, לְקַיָּימָא וּבְרַחֲמִים גְּדוֹלִים אֲקַבְּצֵךְ (ישעיה נד ז),</p>\n<p>וּבֵיהּ יִפְקוֹן עַל יְדָא דְהַהוּא דְאִתְיַיהִיב אוֹרַיְתָא עַל יְדֵיהּ בְּשָׁבוּעוֹת, דְּאָזִיל לִימִינָא דְהַיְינוּ פֶסַח, בְּהַהִיא זִמְנָא אָז יָשִׁיר מֹשֶׁה (שמות טו א),</p>\n<p>וּבַסֻּכּוֹת וַיָּבֹא יַעֲקֹב שָׁלֵם (בראשית לג יח), שָׁלֵם בְּגוּפֵיהּ, שָׁלֵם בְּמָמוֹנֵיהּ, וְאִסְתַּחַר בְּשִׁבְעָה עֲנָנֵי יְקָר כְּגַוְונָא דְקַדְמֵיתָא כַּד נָפְקוּ יִשְׂרָאֵל מִמִּצְרַיִם, לְקַיֵּים כִּימֵי צֵאתְךָ מֵאֶרֶץ מִצְרָיִם וְגוֹמֵר (מיכה ז טו).</p>\n<p>וְרַשִּׁיעַיָּא דְאִינוּן עִרֶב רַב אִתְּמַר בְּהוֹן סוֹ\"ף פָּסוּ\"ק, דְּאִינוּן מִזַּרְעָא דַעֲמָלֵק דְּאִתְּמַר בֵּיהּ (שמות יז טו) וַיֹּאמֶר כִּי יָד עַל כֵּס י\"הּ,</p>\n<p>וְאִינוּן חָמֵשׁ מִינִים עֲמָלֵקִים גִּבּוֹרִים נְפִילִים עֲנָקִים רְפָאִים, דְּכֻלְּהוּ מִסְתַּלְּקִין וּמִתְגַּבְּרִין עַל יִשְׂרָאֵל בְּגָלוּתָא, הֲדָא הוּא דִכְתִיב (בראשית ז יח) וַיִּגְבְּרוּ הַמַּיִם וַיִּרְבּוּ מְאֹד עַל הָאָרֶץ, אַרְבַּע זִמְנִין כְּתִיב וַיִּגְבְּרוּ וְגָבְרוּ, לָקֳבֵל אַרְבַּע גַּלְוָון, וַעֲלַיְיהוּ אִתְּמַר סוֹ\"ף פָּסוּ\"ק, דְּפָסִיק לוֹן קוּדְשָׁא בְּרִיךְ הוּא לְסוֹף יוֹמַיָּא מֵעָלְמָא.</p>\n<p>וּבְהַהוּא זִמְנָא הַקָּטֹן יִהְיֶה לָאֶלֶף (ישעיה ס כב) מִסִּטְרָא דִשְׂמָאלָא, וְהַצָּעִיר לְגוֹי עָצוּם (שם) מִסִּטְרָא דִימִינָא, אֲנִי יהו\"ה בְּעִתָּהּ אֲחִישֶׁנָּה (שם) מִסִּטְרָא דְעַמּוּדָא דְאֶמְצָעִיתָא,</p>\n<p>וּמִיָּד יִתְפַּסְקוּן עֲמָלֵקִים מִן עָלְמָא, וְקוּדְשָׁא בְּרִיךְ הוּא יְתִיב עַל כָּרְסְיֵיהּ, וְדָא אִיהוּ שׁוֹפָ\"ר הוֹלֵ\"ךְ אַתְנָ\"ח יְתִי\"ב,</p>\n<p>בְּהַהוּא זִמְנָא דְיִתְמַחוּן עֲמָלֵקִים מֵעָלְמָא, יְהֵא קוּדְשָׁא בְּרִיךְ הוּא נָח נְיָיחָא לְיִשְׂרָאֵל, וְיָתִיב עַל כָּרְסְיֵיהּ, כְּמָה דְאִתְּמַר בֵּיהּ (דניאל ז ט) וְעַתִּיק יוֹמִין יְתִיב, לְבוּשֵׁהּ כִּתְלָג חִוָּר, לְקַיְימָא אִם יִהְיוּ חֲטָאֵיכֶם כַּשָּׁנִים כַּשֶּׁלֶג יַלְבִּינוּ (ישעיה א יח).</p>\n<p>וּלְגַבֵּי עִשָׂו וְיִשְׂמָעִאל כְּתִיב (דניאל ז ט) כָּרְסְיֵיהּ שְׁבִיבִין דִּי נוּר, (ס\"א רומי) וּמֵאִינוּן שְׁבִיבִין דְּכָרְסְיֵיהּ אוֹקְדוּן כָּל טַעֲוָון דִּילְהוֹן, גַּלְגִּלּוֹהִי נוּר דָּלִיק, דְּנָחֲתִין מִנֵּיהּ עִִשֶׂר גַּלְגַּלִּין מִסִּטְרָא דְאָת י', וּשְׁבִיבִין מִסִּטְרָא דְאָת ה', תְּרֵין אַתְוָון יִתְעָרוּן בְּנוּרָא לְאוֹקָדָא טַעֲוָון דִּלְהוֹן, בְּהַהוּא זִמְנָא (ישעיה א לא) וְהָיָה הֶחָסֹן לִנְעוֹרֶת וכו'.</p>\n<p>בְּהַהוּא זִמְנָא סָלִיק ו' עַל דַּרְגָּא דִילֵיהּ דְּאִיהוּ שֵׁשׁ מַעֲלוֹת לַכִּסֵּא, וְדָא אִיהוּ דַרְגָּ\"א, תְרֵ\"י טַעֲמֵ\"י, מַאי תְּרֵ\"י טַעֲמֵ\"י,</p>\n<p>אֶלָּא בָּתַר דְּסָלִיק לְדַרְגֵּיהּ יֵימַר לְיִשְׂרָאֵל וַעֲשֵׂה לִי מַטְעַמִּים כַּאֲשֶׁר אָהַבְתִּי (בראשית כז ד), מִפִּקּוּדִין דַּעֲשֵׂה דִכְלִילָן בְּה' דְּאַבְרָהָם, דִּכְלִיל רְמַ\"ח פִּקּוּדִין, דִּבְהוֹן אִתְקְרִיב ה' לְגַבֵּי ו', וְקָרְבָּנָא דָא אִיהוּ קְרִיבוּ דְקוּדְשָׁא בְּרִיךְ הוּא עִם שְׁכִינְתֵּיהּ. בְּכָל אֲתַר וַאֲתַר (נ\"א אבר ואבר) קְרִיבוּ י\"ה,</p>\n<p>ה' חֲמֵשֶׁת אֲלָפִים לִבְרִיאַת עוֹלָם, ו' אֶלֶף הַשִּׁשִּׁי בְּרַמַ\"ח, וּבִשְׂמָאלָא דְתַמָּן לִבָּא יִטּוֹל נוּקְמִין מֵאוּמִין דְּעָלְמָא,</p>\n<p>וְרָזָא דְמִלָּה (ישעיהו ס״ג:ד׳) כִּי יוֹם נָקָם בְּלִבִּי, וַדַּאי אִתְכְּלִילָן בְּעַמּוּדָא דְאֶמְצָעִיתָא, דְפִקּוּדִין דַּעֲשֵׂה אִתְיְיהִיבוּ מִימִינָא, וּפִקּוּדִין דְּלֹא תַעֲשֶׂה מִשְּׂמָאלָא, וְאִלֵּין אִינוּן תְּרֵ\"י טַעֲמֵ\"י, וּפִקּוּדִין דַּעֲשֵׂה אִינוּן מַאֲכָלִין דְּקוּדְשָׁא בְּרִיךְ הוּא, וּפִקּוּדִין דְלֹא תַעֲשֶׂה פַרְנָסָה לְסמא\"ל לְמָאן דְּעָבַר עֲלַיְיהוּ.</p>\n<p>(ואלין הוה קריב) (נ\"א אקדים) (נ\"א ובאלין מתקרב) עִשָׂו לְיִצְחָק וְאָמַר לֵיהּ יָקֻם אָבִי וְיֹאכַל מִצֵּיד בְּנוֹ (בראשית כז לא), וְסמא\"ל בְּגִינַיְיהוּ הֲוָה אַקְדִּים (נ\"א קריב) לִשְׂמָאלָא, לְאַטְעָמָא לְקוּדְשָׁא בְּרִיךְ הוּא מֵחוֹבִין דִּבְנוֹי דְּאִינוּן מַאֲכָלִין מְרִירָן, דִּבְגִינַיְהוּ אִתְּמַר (מלאכי א ג) וְאֶת עִשָׂו שָׂנֵאתִי,</p>\n<p>עַמּוּדָא דְאֶמְצָעִיתָא מִתַּמָּן אִתְיְיהִיבַת אוֹרַיְתָא, דְאִיהִי כְּלִילָא</p>"],[9500011110,"<p>דִימִינָא וּשְׂמָאלָא,</p>\n<p>בְּהַהוּא זִמְנָא עָשָׁן יִתְעַר לְגַבֵּי שְׂמָאלָא לְאַעֲבָרָא מִתַּמָּן סמא\"ל, וּמִיָּד סָלִיק עָשָׁן אָחֳרָא דְאִיהוּ עֲשַׁן הַקְּטֹרֶת, (איהו כללא דאורייתא קשורא דיליה פקודין דעשה) לְקָשְׁרָא וּלְקָרְבָא יְמִינָא בִּשְׂמָאלָא, דְּעַמּוּדָא דְעָשָׁן אִיהוּ עַמּוּדָא דְאֶמְצָעִיתָא (ברחימו, ופקודין דלא תעשה בדחילו) עַמּוּד הַקְּטֹרֶת.</p>\n<p>מַאי קְטֹרֶת דִּילֵיהּ שְׁכִינְתָּא תַּתָּאָה, דְּאִיהִי סָלְקָא בְּכַמָּה רֵיחִין וּבוּסְמִין טָבִין, וְכַד סָלְקָא לְגַבֵּיהּ אִתְּמַר בָּהּ (שיר ג ו) מִי זֹאת עוֹלָה מִן הַמִּדְבָּר וכו' דְּסָלְקָא בְּהוֹן, דָּא ה' תַּתָּאָה, זֹאת סָלְקָא בְמִ\"י,</p>\n<p>מְקֻטֶּרֶת מֹר וּלְבֹנָה (שם) תְּרֵי יַרְכֵי קְשׁוֹט, מִכֹּל אַבְקַת רוֹכֵל (שם) דָּא צַדִּיק, דְּאִיהוּ כְּלִיל כֹּלָּא, אִיהוּ רוֹכֵל, וְאִיהִי אַבְקַת דִּילֵיהּ, הֲדָא הוּא דִכְתִיב (בראשית ב כד) וְדָבַק בְּאִשְׁתּוֹ, וּבֵיהּ סְלִיקַת לְגַבֵּי בַּעִִלָהּ.</p>\n<p>שְׁכִינְתָּא תַּתָּאָה אִיהִי קְטֹרֶת דְּקוּדְשָׁא בְּרִיךְ הוּא, וְאִיהִי קָרְבָּן דִּילֵיהּ, מִזְבֵּחַ דִּילֵיהּ, דְּבָהּ מְתַקְּנִין יִשְׂרָאֵל מַאֲכָלִים דְּקָרְבָּנִין דִּצְלוֹתִין לְקוּדְשָׁא בְּרִיךְ הוּא, דְּאִינוּן לָקֳבֵל קָרְבַּן הַשַּׁחַר, וְקָרְבַּן דְּבֵין הָעַרְבַּיִם, וְקָרְבָּנָא דְאֵמוּרִים וּפְדָרִים דְּמִתְאַכְלִין כָּל לֵילְיָא,</p>\n<p>וְאִיהוּ קָרְבַּן מוּסַף דְּאִיהוּ צַדִּיק, וְאִיהוּ קָרְבָּנָא דְשַׁבָּתוֹת וְיָמִים טוֹבִים דְּלֵית קָרְבָּנָא (קריבו לעמא קדישא לקודשא בריך הוא בשבת ויום טוב) אֶלָּא בָּהּ, הֲדָא הוּא דִכְתִיב (ויקרא טז ג) בְּזֹאת יָבֹא אַהֲרֹן אֶל הַקֹּדֶשׁ, וְאַל יִתְהַלֵּל הַמִּתְהַלֵּל כִּי אִם בְּזֹאת (ירמיהו ט כג). אִיהִי מַשְׁכּוֹנָא דִילֵיהּ, דִּבְגִינָהּ אִיהוּ שָׁארֵי בְגַוַּויְיהוּ, הֲדָא הוּא דִכְתִיב (שמות כה ח) וְעָשׂוּ לִי מִקְדָּשׁ וְשָׁכַנְתִּי בְּתוֹכָם וְגוֹמֵר,</p>\n<p>אִיהִי אָרוֹן דִּילֵיהּ, וְאִיהוּ סֵפֶר תּוֹרָה גָנִיז בְּגַוָּוהּ,</p>\n<p>אִיהִי מְנַרְתָּא דִילֵיהּ, וּמְנוֹרַת הַמָּאוֹר מֵהַהוּא דְאִתְּמַר בֵּיהּ (משלי ו כג) וְתוֹרָה אוֹר,</p>\n<p>וְאִיהִי נֵר דְּדָלִיק קֳדָמֵיהּ, כְּמָה דְאַתְּ אָמַר (ויקרא כד ב) לְהַעֲלוֹת נֵר תָּמִיד, וְאִיהִי בַּת שֶׁבַע מְנַרְתָּא כְלִילָא מִשִּׁבְעָה בוֹצִינִין, אִיהִי נֵר לְגַבֵּיהּ מִסִּטְרָא דִשְׂמָאלָא, וְאִיהוּ אוֹר לְגַבָּהּ מִסִּטְרָא דִימִינָא, וְעַל תַּרְוַיְיהוּ אִתְּמַר (משלי ו כג) כִּי נֵר מִצְוָה וְתוֹרָה אוֹר.</p>\n<p>אִיהִי קִדּוּשִׁין דִּילֵיהּ מִסִּטְרָא דִשְׂמָאלָא, בְגִין דִּקְדוּשָׁה מִסִּטְרָא דִלְוִיִּם, כְּמָה דְאַתְּ אָמַר וְקִדַּשְׁתָּ אֶת הַלְוִיִּם, וַעֲלָהּ אִתְּמַר תְּהֵא לִי מְקוּדֶשֶׁת בְּטַבַּעַת זֹאת,</p>\n<p>וְאִיהִי בְּרָכָה דִילֵיהּ מִסִּטְרָא דִימִינָא, דְאִיהִי כְּהוּנָה, הֲדָא הוּא דִכְתִיב (במדבר ו כג) כֹּה תְבָרַכוּ אֶת בְּנֵי יִשְׂרָאֵל.</p>\n<p>וְאִתְקְרִיאַת כַּלָּה דִילֵיהּ מִסִּטְרָא דְצַדִּיק דְּאִיהוּ כָּ\"ל, וְדָא אִיהוּ כַלָּ\"ה, כָּ\"ל ה', בְּגִין דְּאִיהוּ בְּרִית דַּאֲחִיד בְּתַרְוַיְיהוּ, וּמִסִּטְרָא דְצַדִּיק אִיהוּ יִחוּד דִילָהּ, דְּאִיהוּ קוֹצָא דְאָת ד' מִן אֶחָד, דְּקָשִׁיר בֵּין א\"ח וּבֵין ד',</p>\n<p>וְאִיהִי צְלוֹתָא דִילֵיהּ מִסִּטְרָא דְחַי עָלְמִין, דְּאִיהוּ חַ\"י בִּרְכָאָן דִּצְלוֹתָא.</p>\n<p>אִיהִי אוֹת דְּשַׁבָּתוֹת וְיֹמִין טָבִין, שַׁבָּת אִיהִי כְּלָל דִּתְלַת אֲבָהָן, בְּגִין דְּאִיהִי בַת כְּלִילָא בִתְלַת עַנְפֵי אֲבָהָן דְּאִינוּן ש,</p>\n<p>אִיהִי תְּחוּם דִּילֵיהּ וְאִיהִי רְשׁוּת דִּילֵיהּ, רְשׁוּת הַיָּחִיד דְּגָבְהוֹ עֲשָׂרָה, וְדָא יו\"ד ה\"א וא\"ו ה\"א, וְרָחְבּוֹ אַרְבָּעָה דְאִינוּן יהו\"ה,</p>\n<p>אִיהוּ עִירוּב דִּילָהּ מִסִּטְרָא דִימִינָא וּשְׁמָאלָא, דְאִינוּן ע\"ב רי\"ו דְהַיְינוּ חֶסֶד וּגְבוּרָה, וְאִיהִי עַרְבִית דִּילֵיהּ עִיבוּר דִּילֵיהּ.</p>\n<p>אִיהִי טַלִּית דְּקוּדְשָׁא בְּרִיךְ הוּא, וּבָהּ אִתְעַטֵּף קוּדְשָׁא בְּרִיךְ הוּא, כְּמָה דְאַתְּ אָמַר (תהלים קד ב) עוֹטֶה אוֹר כַּשַּׂלְמָה, וְאִיהִי צִיצִית דְּצַדִּיק דְּאִיהוּ עָנִי בְּגָלוּתָא, הֲדָא הוּא דִכְתִיב (שם קב א) תְּפִלָּה לְעָנִי כִי יַעֲטֹף,</p>\n<p>עָנִי וַדַּאי, דְּבֵיהּ אִתְעַטֵּף, בְּגִין דְּאִיהִי כְסוּתֹה לְבַדָּהּ הִיא שִׂמְלָתוֹ לְעוֹרוֹ (שמות כב כו), דָא מִשְׁכָא דִתְּפִלֵּי, דְאִתְּמַר בְּהוֹן (בראשית ג כא) וַיַּעַשׂ יהו\"ה אֱלֹהִים לְאָדָם וּלְאִשְׁתּוֹ כָּתְנוֹת עוֹר וַיַּלְבִּישֵׁם.</p>\n<p>אַרְבַּע בָּתֵּי דְרֵישָׁא אִינוּן אהי\"ה, אַרְבַּע פָּרָשִׁיָּין דְּאִינוּן קַדֶּשׁ לִי (שמות יג ב), וְהָיָה כִּי יְבִיאֲךָ (שם יא), שְׁמַע יִשְׂרָאֵל (דברים ו ד), וְהָיָה אִם שָׁמֹעַ (שם יא יג), דָא יהו\"ה,</p>\n<p>אַרְבָּעָה בָּתֵּי דְיָד דָּא אדנ\"י, אַרְבָּעָה פָּרְשִׁיָּין דָּא יהו\"ה, וּבְהוֹן מ\"ב אַזְכָּרוֹת בִּתְמַנְיָא פָּרְשִׁיָּין, דְּאִתְּמַר בְּהוֹן (תהלים סה יח) אדנ\"י בָם, דָּא אִיהוּ כִּי הִיא שִׂמְלָתוֹ לְעוֹרוֹ (שמות כב כו), וְאִיהִי תְּכֵלֶת שֶׁבַּצִּיצִית,</p>\n<p>אִיהִי סוֹד הַיִּבּוּם, יְבָמָה דִילֵיהּ בְּגָלוּתָא, י\"ב מ\"ה ב\"י מ\"ה.</p>"],[9500011111,"<p>תְּלַת גִּלְגּוּלִין דִּילָהּ אִינוּן תְּלַת אֲבָהָן, דַּעֲלַיְיהוּ אִתְּמַר (איוב לג כט) הֶן כָּל אֵלֶּה יִפְעַל אֵ\"ל פַּעֲמַיִם שָׁלֹשׁ עִם גָּבֶר,</p>\n<p>אִיהִי יְשׁוּעָה דִילֵיהּ, גְּאוּלָה דִילֵיהּ, בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא לֵית לֵיהּ רְשׁוּתָא לְאַפָּקָא מִן גָּלוּתָא, עַד דְּאִיהִי נָפְקַת עִמֵּיהּ,</p>\n<p>הִיא נְבוּאָה דִילֵיהּ, נְבוּאָה כְלִילָא שִׁית דַּרְגִין מִסִּטְרָא דְאָת ו' דְּאִיהִי עַמּוּדָא דְאֶמְצָעִיתָא,</p>\n<p>וְאִיהִי חֲלוֹם אֶחָד מִשִּׁתִּין בִּנְבוּאָה, וּמַאי שִׁתִּין אֶלָּא לֵית שֵׂיבָ\"ה (נ\"א שינה) פְּחוּתָה מִשִּׁתִּין, וְדָא יִשְׂרָאֵל סָבָא, דְסָלִיק בְּאָת ו' שִׁית זִמְנִין עִִשֶׂר דְּאִיהוּ שִׁתִּין.</p>\n<p>וְאִיהִי יִרְאָה מִסִּטְרָא דִשְׂמָאלָא, אַהֲבָה מִסִּטְרָא דִימִינָא,</p>\n<p>וְאִיהִי תוֹרָה מִסִּטְרָא דְעַמּוּדָא דְאֶמְצָעִיתָא,</p>\n<p>וְאִיהִי אָנֹכִי מִסִּטְרָא דְאִימָּא עִלָּאָה דַאֲחִידָא בִימִינָא, בְּגִין דְאָנֹכִ\"י אִיהוּ כִסֵּ\"א בְחוּשְׁבָּן, וְאִתְּמַר בֵּיהּ (ישעיה טז ה) וְהוּכַן בַּחֶסֶד כִּסֵּא,</p>\n<p>וַעֲלָהּ אִתְּמַר (שמות כ ג) לֹא יִהְיֶה לְךָ אֱלֹהִים אֲחֵרִים עַל פָּנָי, מִסִּטְרָא דְסמא\"ל וְנָחָשׁ דְּאִינוּן אֱלֹהִים אֲחֵרִים.</p>\n<p>וְאִיהִי פֶּסַח מִסִּטְרָא דִימִינָא, וְאִיהִי רֹאשׁ הַשָּׁנָה מִסִּטְרָא דִשְׂמָאלָא, וְאִיהִי מַצָּה פְּרוּסָה מִסִּטְרָא דִשְׂמָאלָא, וְאִיהִי מַצָּה שְׁלֵמָה מִסִּטְרָא דִימִינָא, בְּגִין דְּסִטְרָא דְצָפוֹן לַאו אִיהוּ שְׁלִים, וּבְגִין דָּא מִצָּפוֹן תִּפָּתַח הָרָעָה (ירמיה א יד),</p>\n<p>וְהִיא (מצה) מִצְוָה בְּאָת ו' מִסִּטְרָא דְעַמּוּדָא דְאֶמְצָעִיתָא. וְאִיהִי שָׁבוּעוֹת מִסִּטְרָא דְעַמּוּדָא דְאֶמְצָעִיתָא, שִׁבְעָה שָׁבוּעוֹת וַדַּאי אִית בְּהוֹן שֶׁבַע שַׁבָּתוֹת, וּבְהוֹן מ\"ט יוֹמִין, כְּחוּשְׁבַּן מ\"ט אַתְוָון דִּקְרִיאַת שְׁמַע, דְּאִינוּן שְׁמַע יִשְׂרָאֵל וכו', בָּרוּךְ שֵׁם וכו',</p>\n<p>בְּיוֹמָא דְחַמְשִׁין שַׁרְיָא שְׁכִינְתָּא עִלָּאָה בָּהּ, וְאִתְקְרִיאַת מַתַּן תּוֹרָה,</p>\n<p>וְעַמּוּדָא דְאֶמְצָעִיתָא אִיהוּ תוֹרָה דְאִתְיְיהִיבַת בְּחַמְשִׁין יוֹמִין דְּשָׁבוּעוֹת, וַעֲלֵיהּ אִתְּמַר בֶּן חֲמִשִּׁים לְזִקְנָה (נ\"א לבינה), בְּהַהִיא דְאִתְּמַר בָּהּ כִּי זָקְנָה אִמֶּךָ,</p>\n<p>וַעֲלָהּ אִתְּמַר (משלי ב ג) כִּי אִם לַבִּינָה תִקְרָא, בְּגִין דְּאִיהִי ה' וְסָלְקָא בְּאָת י' לְחַמְשִׁין חָמֵשׁ זִמְנִין עִִשֶׂר, וַעֲלָהּ אִתְּמַר בֶּן חֲמִשִּׁים לְזִקְנָה, בְּהַהִיא דְאִתְּמַר (שם כג כב) אַל תָּבוּז כִּי זָקְנָה אִמֶּךָ, (ו' בן י\"ה).</p>\n<p>וְזִמְנִין אִתְקְרִיאַת ם' סְתִימָא, וְאִתְּמַר בָּהּ בֶּן אַרְבָּעִים לַבִּינָה, (כד לא איהי) בְּשׁוּתָּפָא דְאָת י' אִתְקְרִיאַת אַרְבָּעִים, וְאִיהִי עָלְמָא דְאָתֵי דְלֵית בֵּיהּ אֲכִילָה וּשְׁתִיָּה,</p>\n<p>וְכַד סָלִיק מֹשֶׁה לְגַבָּהּ אִתְּמַר בֵּיהּ (שמות כד יח) וַיְהִי מֹשֶׁה בָּהָר אַרְבָּעִים יוֹם וְאַרְבָּעִים לָיְלָה וְגוֹמֵר.</p>\n<p>מַתַּן תּוֹרָה דָא שְׁכִינְתָּא תַּתָּאָה, וַעֲלָהּ אִתְּמַר יִשְׂמַח מֹשֶׂה בְּמַתְּנַת חֶלְקוֹ, בְּגִין דְּאִיהִי דוּגְמָא דְעַמּוּדָא דְאֶמְצָעִיתָא,</p>\n<p>וְעוֹד שָׁבוּעוֹת עַל שֵׁם מַלֵּא שְׁבֻעַ זֹאת וְנִתְּנָה לְךָ גַם אֶת זֹאת (בראשית כט כז),</p>\n<p>מַלֵּא שְׁבוּעַ זֹאת דָּא שְׁכִינְתָּא עִלָּאָה, (מלא שבוע ה' מלא י\"ה), דְּאִתְּמַר בֵּיהּ (שמות יז טז) כִּי יָד עַל כֵּ\"ס י\"הּ, וְנִתְּנָה לְךָ גַם אֶת זֹאת דָּא שְׁכִינְתָּא תַּתָּאָה ה' זְעִירָא,</p>\n<p>מַלֵּא דְכֹלָּא עִלָּאָה וְתַתָּאָה דָא ו', אִיהוּ מַלֵּא י\"ה לְעִילָא, דְּאִיהִי מְלֵיאָ\"ה אלהי\"ם, וַעֲלָהּ אִתְּמַר (רות א כא) אֲנִי מְלֵאָה הָלַכְתִּי, מְלֵאָה הָלַכְתִּי לְטוּרָא דְסִינַי, וּבְגָלוּתָא רֵיקָם הֱשִׁיבַנִי יהו\"ה (שם) וְאִיהוּ מָלֵא ה', וּבָהּ (נ\"א וביה) (תהלים קד כד) מָלְאָה הָאָרֶץ קִנְיָנֶךָ.</p>\n<p>וּשְׁכִינְתָּא תַּתָּאָה אִיהִי סוּכָּ\"ה, כ\"ו ה\"ס, דְּאִיהִי יהו\"ה אדנ\"י, כְּלִילָא מִתְּרֵין שְׁמָהָן, סוּכָּה חִבּוּרָא דְתַרְוַיְהוּ כְּגַוְונָא דָא יאהדונה\"י, בְּגִין דְּאִיהִי כַּלָּה דִילֵיהּ, וְאִיהִי בַּת שֶׁבַע כְּלָלָא דְשֶׁבַע יְמֵי סוּכָּה,</p>\n<p>וְכַד נָטְלָא מֵאִימָּא עִלָּאָה דְאִיהִי שִׂמְחַת תּוֹרָה שִׂמְחַת בֵּית הַשּׁוֹאֵבָה, וְאִיהִי חוּפָּה דִילֵיהּ, אִתְקְרִיאַת שְׁמִינִי חַג עֲצֶרֶת.</p>\n<p>בְּהַהוּא זִמְנָא דְשִׂמְחַת תּוֹרָה שַׁוְיָין (נ\"א שריא) עֲטָרָה בְרֵישׁ כָּל צַדִּיק לְעִילָא, כְּמָה דְאַתְּ אָמַר (שיר ג יא) בַּעֲטָרָה שֶׁעִטְּרָה לוֹ אִמּוֹ, בְּיוֹם חֲתוּנָתוֹ וּבְיוֹם שִׂמְחַת לִבּוֹ, בְּיוֹם חֲתוּנָתוֹ דָּא שְׁכִינְתָּא תַּתָּאָה, וּבְיוֹם שִׂמְחַת לִבּוֹ דָא שְׁכִינְתָּא עִלָּאָה,</p>\n<p>וְהָכִי צְרִיכִין יִשְׂרָאֵל לְאִתְעַטְרָא בְּכֹלָּא (נ\"א כלהו) בַעֲטָרָא עַל רֵישַׁיְיהוּ</p>"],[9500011112,"<p>בְּיוֹמָא דְשִׂמְחַת תּוֹרָה.</p>\n<p>וּלְקַחְתֶּם לָכֶם בַּיּוֹם הָרִאשׁוֹן פְּרִי עִץ הָדָר כַּפּוֹת תְּמָרִים וכו' (ויקרא כג מ), אֶתְרוֹג אִיהִי שְׁכִינְתָּא תַּתָּאָה, וְדַמְיָא לְלִבָּא דְאִיהוּ לִשְׂמָאלָא דְאִיהוּ גְבוּרָה,</p>\n<p>וּבְגִין כַּךְ צָרִיךְ בַּר נַשׁ לְנָטְלָא אֶתְרוֹג בִּידָא שְׂמָאלָא וּצְרִיכָא לְמֶהֱוִי אֶתְרוֹג דְּדַמְיָא לְלִבָּא שְׁלֵימָא בִתְיוֹמֶת דִּילָהּ, בְּגִין הַהוּא דְאִתְּמַר בֵּיהּ (בראשית כה כז) וְיַעֲקֹב אִישׁ תָּם, לְמֶהֱוִי שְׁלֵימָא עִמֵּיהּ, וּכְמָה דְלֵית פְּסוּל בְּיַעֲקֹב דִּלְעִילָא, כֵּן צָרִיךְ דְּלָא יְהֵא פְסוּל בְּאֶתְרוֹג, לְקַיְימָא קְרָא (שיר ד ז) כֻּלָּךְ יָפָה רַעִִיָתִי וּמוּם אֵין בָּךְ,</p>\n<p>וְאִם הִיא יְרוֹקָא הִיא מְשׁוּבַּחַת יַתִּיר, כְּדִיּוֹקְנָא דַהֲוַת אֶסְתֵּר יְרַקְרֹקֶת, דְּאִתְּמַר בָּהּ (אסתר ה א) וַתִּלְבַּשׁ אֶסְתֵּר מַלְכוּת. וְאִתְקְרִיאַת הֲדַסָּה עַל שֵׁם הֲדַס, וַהֲדַס אִית לֵיהּ תְּלַת הֲדַסִּין, לְאִשְׁתַּכְלָלָא בִּתְלַת אֲבָהָן, וְאִתְקְרִיאַת עֲרָבָה מִסִּטְרָא דִתְרֵין שִׂפְוָון דְּאִינוּן לִמּוּדֵי יהו\"ה,</p>\n<p>וְאִתְקְרִיאַת לוּלָב מִסִּטְרָא דְחַ\"י עָלְמִין, דְּאִיהוּ כְלִיל חַ\"י בִּרְכָאָן דִּצְלוֹתָא, וּלְקִבְלַיְיהוּ עָבְדִין חַ\"י נִעִִנוּעִין בְּלוּלָב בְּשִׁית סִטְרִין, תְּלַת לְכָל סִטְרָא וְסִטְרָא, שִׁית סִטְרִין דִּכְלִילָן בְּגוּפָא דְאִיהוּ עַמּוּדָא דְאֶמְצָעִיתָא, דְלוּלָב עַל שְׁמֵיהּ אִתְקְרֵי ל\"ו ל\"ב.</p>\n<p>וְאִינוּן נִעִִנוּעִין חַ\"י ד' זִמְנִין, דְּסָלְקִין ע\"ב, וְאִינוּן חַ\"י נִעִִנוּעִין בְּהוֹדוּ לַיהו\"ה תְּחִלָּה וָסוֹף, חַ\"י בְּאָנָא יהו\"ה הוֹשִׁיעָה נָא, הָא ע\"ב,</p>\n<p>וְאִינוּן תַּלְיָין מִן ד' דְּאִיהִי שְׁכִינְתָּא, וְצַדִּיק בָּהּ אִתְקְרֵי ד' זִמְנִין חַ\"י חַ\"י חַ\"י חַ\"י דְּסָלִיק ע\"ב, מִסִּטְרָא דִתְלַת אֲבָהָן, וּשְׁכִינְתָּא דְאִשְׁתַּתְּפַת עִמְּהוֹן, דְּאִינוּן חַ\"י (פרקין) בִּדְרוֹעָא יְמִינָא, וְחַ\"י בִּשְׂמָאלָא, וְחַ\"י בְּגוּפָא לְגַבֵּי שִׁדְרָה, וְחַ\"י בִּבְרִית מִילָה,</p>\n<p>וְאִינוּן ו' סִטְרִין תְּרֵין דְּרוֹעִין דְּמַלְכָּא, וּתְרֵין שׁוֹקִין דְּמַלְכָּא, דְאִינוּן תְּרֵי נְבִיאֵי קְשׁוֹט, וְגוּפָא וּבְרִית הָא שִׁית, חַ\"י</p>\n<p>חַ\"י נִעִִנוּעִין לָקֳבֵל חַ\"י חוּלְיָין דְּשִׁדְרָה מִסִּטְרָא דְגוּפָא, וְכָל דָּא מִסִּטְרָא דְאִילָנָא דְחַיֵּי, וּמִסִּטְרָא דְאִילָנָא דְטוֹב וָרָע. אֶתְרוֹג דָּמֵי לְצַדִּיקַיָּיא, וַהֲדַס לְבֵינוּנִיִּים, וַעֲרָבָה לָרְשָׁעִים,</p>\n<p>וּשְׁכִינְתָּא אִתְּמַר בָּהּ (תהלים קג יט) וּמַלְכוּתוֹ בַּכֹּל מָשָׁלָה, אַף עַל גַּב דְּאִתְּמַר בָּהּ (משלי ג יח) עִץ חַיִּים הִיא לַמַּחֲזִיקִים בָּהּ, אִיהִי שָׁלְטָא עַל עִץ הַדַּעַת טוֹב וָרָע, מִסִּטְרָא דִילֵיהּ הִיא קְרִיבָא לְמַלְכָּא, (נ\"א ומסטרין אלין לזמנין איהי נוקבא קריבא למלכא),</p>\n<p>הֲדָא הוּא דִכְתִיב (ויקרא טז ג) בְּזֹאת יָבֹא אַהֲרֹן אֶל הַקֹּדֶשׁ מִסִּטְרָא דִימִינָא, לְזִמְנִין אִיהִי רְחִיקָא מִנֵּיהּ מִסִּטְרָא דִשְׂמָאלָא, וְאַל יָבֹא בְכָל עִת אֶל הַקֹּדֶשׁ,</p>\n<p>מִסִּטְרָא דִימִינָא אִיהִי לָא מְקַבְּלָא טוּמְאָה, טוֹב הוּא יְמִינָא, אֲבָל אַתְרָהָא טוֹב מְקַבְּלָא טוּמְאָה מֵרַע וּמָוְת, הוּא אֲתַר לֵית לֵיהּ קְרִיבוּ, (נ\"א אל הקדש איהי לא מקבלא טומאה, אבל אתרהא טוב מקבלא טומאה מרע ומההוא אתר דלית ליה קריבו),</p>\n<p>וְתַמָּן צָרִיךְ קוּרְבָּנָא לְקָרְבָא, וּקְטֹרֶת לְרַחֲקָא רוּחַ הַטּוּמְאָה מֵהַהוּא אֲתַר, וּלְקָרְבָא זְכוּתָא לִשְׂמָאלָא גְבִירְתָּא, וּלְרַחֲקָא שִׁפְחָה מִתַּמָּן, וּבְגִין דָּא כָּל שְׁמָהָן אִית בָּהּ.</p>\n<p>וְאִתְקְרֵי שִׁדְרָה אָחוֹר מִסִּטְרָא דְסִיהֲרָא, וּמִסִּטְרָא דְעַמּוּדָא דְאֶמְצָעִיתָא אִתְקְרֵי קֶדֶם, וְרָזָא דְמִלָּה אָחוֹר וָקֶדֶם צַרְתָּנִי (תהלים קלט ה),</p>\n<p>וּבְגָלוּתָא הֵשִׁיב אָחוֹר יְמִינוֹ מִפְּנֵי אוֹיֵב (איכה ב ג),</p>\n<p>מַאי אוֹיֵב דָּא סמא\"ל, דְּכָל אֱלֹהִים אֲחֵרִים אִינוּן לְאָחוֹר, וּבְגִין דְּלָא יִסְתַּכְּלוּן בִּשְׁכִינְתָּא דְאִיהִי לְמַעֲרָב דְּאִיהוּ אָחוֹר, שַׁוִּי לָהּ בִּימִינָא,</p>\n<p>וּבְגִין דָּא אָסוּר לְצַלָּאָה לְמַעֲרָב דְּאִיהוּ אָחוֹר, בְּגִין דְּתַמָּן אֱלֹהִים אֲחֵרִים, וְתַמָּן סַם הַמָּוְת שַׁבְּתַא\"י,</p>\n<p>וּבְגִין דַּהֲוַת בְּקַדְמֵיתָא לְמַעֲרָב וְחָזְרַת לִימִינָא, שָׁאֲלִין עֲלָהּ אֱלֹהִים אֲחֵרִים שַׁבְּתַא\"י אֵ\"י שַׁבָּ\"ת, שַׁבְּתַא\"י אַתְוָון דִּילֵיהּ אֵי שַׁבָּת.</p>\n<p>וּצְרִיכִין יִשְׂרָאֵל לְשַׁנִּי לָהּ אֲתַר וּשְׁמָא וְעוֹבָדָא, וְדָא אִיהוּ שִׁנּוּי מָקוֹם וְשִׁנּוּי הַשֵּׁם וְשִׁנּוּי מַעֲשֶׂה, בְּגִין דְּלָא אִשְׁתְּמוֹדָע בֵּיהּ אוֹיֵב דְּאִיהוּ סמא\"ל, וְדָא אִיהוּ הֵשִׁיב אָחוֹר יְמִינוֹ וכו',</p>\n<p>אִם זַכָּאָן</p>"],[9500011113,"<p>לְנָטְרָא שַׁבָּת, צָרִיךְ לְשַׁנּוּיֵי לֵיהּ מִיּוֹמִין דְּחוֹלָא בִּלְבוּשִׁין וּמֵיכְלִין דְּאִינוּן עֹנֶג שַׁבָּת, דְּאִם הֲוָה רָגִיל לְמֵיכַל תְּרֵי סְעוּדוֹת בְּיוֹמָא דְחוֹלָא, בְּשַׁבָּת אָכִיל תְּלַת, דִּכְתִיב (שמות טז כה) וַיֹּאמֶר מֹשֶׁה אִכְלוּהוּ הַיּוֹם, כִּי שַׁבָּת הַיּוֹם לַיהו\"ה הַיּוֹם לֹא תִמְצָאוּהוּ בַּשָּׁדֶה,</p>\n<p>וּבְכֹלָּא צָרִיךְ לְמֶעֱבַד בְּשַׁבָּת תּוֹסֶפֶת, דְּאִם הֲוָה רָגִיל לְמֵיכַל בְּיוֹמָא דְחוֹלָא נַהֲמָא וְחַמְרָא, יוֹסִיף בְּשַׁבָּת בִּשְׂרָא, דָא תוֹסֶפֶת שַׁבָּת.</p>\n<p>שִׁנּוּי מַעֲשֶׂה, דְאִם הֲוָה רָגִיל לְמֶעֱבַד עוֹבָדָא בְּחוֹל, לָא יַעֲבֵיד בְּשַׁבָּת, הֲדָא הוּא דִכְתִיב (שם כ ט) שֵׁשֶׁת יָמִים תַּעֲבוֹד וכו',</p>\n<p>שִׁנּוּי הַשֵּׁם לְכָל יוֹמָא קָארֵי לֵיהּ מַעֲשֶׂה, כְּמָה דְאַתְּ אָמַר (יחזקאל מו א) שֵׁשֶׁת יְמֵי הַמַּעֲשֶׂה, וּלְיוֹם הַשְּׁבִיעִי קָארֵי לֵיהּ שַׁבָּת, דְּאִיהוּ הַשְׁבָּתַת מַעֲשֶׂה, בִּיטוּלָא דְעוֹבָדָא,</p>\n<p>שִׁנּוּי מָקוֹם, אִם הוּא רָגִיל לְאוֹקָדָא נוּרָא בְחוֹלָא, דְּיִשְׁנֵי וְלָא יוֹקִיד לֵיהּ בְּשַׁבַּתָּא, הֲדָא הוּא דִכְתִיב (שם לה ג) לֹא תְבַעֲרוּ אֵשׁ בְּכֹל מוֹשְׁבוֹתֵיכֶם בְּיוֹם הַשַּׁבָּת.</p>\n<p>וְעוֹד אִית שִׁינּוּי, דְּצָרִיךְ לְשַׁנּוֹת מֵעַבְדָּא לְמַטְרוֹנִיתָא, דְלָא יְהוֹן שָׁוִין, דְּמַטְרוֹנִיתָא אִיהִי מְקוֹמוֹ דְקוּדְשָׁא בְּרִיךְ הוּא, צָרִיךְ לְשַׁנּוֹת לְמַלְכָּא, הֲדָא הוּא דִכְתִיב (אסתר ב ט) וַיְשַׁנֶּהָ וְאֶת נַעֲרוֹתֶיהָ, בְּיוֹם הַשַּׁבָּת, דְּאִשְׁתַּנֵי יוֹמָא דְשַׁבַּתָּא מִיּוֹמָא דְחוֹל דְּשָׁלְטָא בֵּיהּ עַבְדָּא דְמַלְכָּא.</p>\n<p>וְעוֹד מוֹשְׁבוֹתֵיכֶם מוֹשַׁב דְּבַר נַשׁ אִיהוּ מָקוֹם דִּילֵיהּ, וְעוֹד שִׁנּוּי מָקוֹם, לְתַקְנָא בֵיתָא בְּשַׁבַּתָּא תוֹסֶפֶת מִבַּחוֹל,</p>\n<p>וְעוֹד שִׁנּוּי מַעֲשֶׂה אִם הוּא עָצִיב בְּחוֹלָא, דִּיְהֵא חָדֵי בְּשַׁבַּתָּא, וְאִם אִית לֵיהּ קְטָטָה בְחוֹלָא עִם בַּר נַשׁ אוֹ עִם אִתְּתֵיהּ, דִּיְהֵא לֵיהּ שְׁלָמָא עִמָּהּ בְּשַׁבַּתָּא,</p>\n<p>וּבְדָא לֵית רְשׁוּ לְקָרְבָא לְסַם הַמָּוְת חֲלָלָה, וּלְבַעִִלָהּ דְּאִיהוּ אֵל אַחֵר חִלּוּל שַׁבָּת, (לית לון רשו לקרבא), וּבְגִין דָּא אָמְרוּ קַדְמָאֵי, אִם יִשְׂרָאֵל הֲווֹ מְקַיְּימִין שַׁבָּת אַחַת כְּהִלְכָתָהּ (נ\"א שתי שבתות כהלכתן), מִיָּד הֲווֹ נִגְאָלִין.</p>\n<p>וְכַךְ צָרִיךְ לְשַׁנּוּיֵי בְּנֵר דָּלוּק, וּבְמִטָּה מוּצַעַת, וּבְפָתוֹרָא, כְּגַוְונָא דָא אִם הֲוָה רָגִיל בְּיוֹמֵי דְחוֹל לְאַדְלָקָא שְׁרַגָּא בִּפְתִילָה חַד יוֹסִיף בְּשַׁבָּת תִּנְיָינָא, וּבְפָתוֹרָא אִם רָגִיל לְבָרְכָא הַמּוֹצִיא עַל נַהֲמָא חֲדָא, בְּשַׁבָּת יוֹסִיף תִּנְיָינָא, דְּאִינוּן כְּגַוְונָא דְלֶחֶם מִשְׁנֶה, מִטָּה הָא אִתְּמַר דְּאִם הֲוָה רָגִיל לְשַׁמֵּשׁ בְּיוֹמָא דְחוֹלָא בִקְטָטָה עִם אִתְּתֵיהּ וּבְפִרוּדָא, לָא יִזְדַוִּוג לְאִתְּתֵיהּ בְּשַׁבַּתָּא אֶלָּא בִּשְׁלָמָא, וּבְגִין דָּא תַּלְמִידֵי חֲכָמִים עוֹנָתָן מִלֵּיל שַׁבָּת לְלֵיל שַׁבָּת,</p>\n<p>וְצָרִיךְ לְשַׁנּוּיֵי שַׁבָּת מִיּוֹמָא דְחוֹלָא בְּכֹלָּא, וְאִם אִית לוֹן שְׁלָמָא בְּכָל שִׁית יוֹמִין דְּחוֹלָא, יַעַבְדוּן תּוֹסֶפֶת בְּשַׁבַּתָּא בְּפִיּוּסָא דָא לְדָא בִּרְחִימוּ סַגִּי, כְּגַוְונָא דִלְעִילָא, דְאִתְּמַר לְגַבֵּי שְׁכִינְתָּא (שיר ה ב) פִּתְחִי לִי אֲחוֹתִי רַעִִיָתִי יוֹנָתִי תַמָּתִי, בְּתוֹסֶפֶת מִלִּין דְּפִיּוּסָא, כְּגַוְונָא דָא צָרִיךְ בַּר נַשׁ לְפַיְיסָא לְאִתְּתֵיהּ בְּשַׁבָּת בְּתוֹסֶפֶת מִלִּין דְּפִיּוּסָא.</p>\n<p>וּבְזִמְנָא דְאֱלֹהִים אֲחֵרִים חַזְיָין בְּשַׁבָּת שִׁנּוּיָיא בְּכֹלָּא, לֵית לוֹן רְשׁוּ לְקָרְבָא, הֲדָא הוּא דִכְתִיב (במדבר א נא) וְהַזָּר הַקָּרֵב יוּמָת, בְּגִין דְּקֹדֶשׁ הִיא לָכֶם מְחַלֲלֶיהָ מוֹת יוּמָת, וּבְגִין דָּא אִתְּמַר בִּקְרָא (ויקרא יט ג) אֶת שַׁבְּתוֹתַי תִּשְׁמוֹרוּ וְגוֹמֵר,</p>\n<p>וּבְאִלֵּין תּוֹסֶפֶת אִתְקְרִיאַת שְׁכִינְתָּא מוּסַף שַׁבָּת, וְכַד מִתְרַחֲקִין מִינָהּ כָּל דַּרְגִּין דְּחוֹל, וְלָא אִית רְשׁוּ נוּכְרָאָה בְּשַׁבָּת, לְאַעָלָא בֵין קוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ, אִיהִי אִתְקְרִיאַת קְדוּשָׁה דִילֵיהּ, וְכַד מְבָרְכִין לָהּ בְּבִרְכַת מְזוֹנָא אִתְקְרִיאַת בְּרָכָה דִילֵיהּ, וּבְתַרְוַיְהוּ אִיהִי יִחוּד דִּילֵיהּ, כַּלָּה דִילֵיהּ, בְּהַהוּא זִמְנָא אִיהִי שַׁבָּת שְׁקוּלָה כְּכָל אוֹרַיְיתָא.</p>\n<p>וּשְׁרַגָּא אִיהִי דִיּוֹקְנָא דִמְנַרְתָּא, וְצָרִיךְ לְמֶהֱוִי לִימִינָא, וַעֲלָהּ אִתְּמַר הָרוֹצֶה לְהַחְכִּים יַדְרִים,</p>\n<p>וּפָתוֹרָא דְשַׁבָּת צָרִיךְ לְמֶהֱוֵי לִשְׂמָאלָא, וַעֲלָהּ אִתְּמַר הָרוֹצֶה לְהַעֲשִׁיר יַצְפִּין,</p>\n<p>מִטָּה בֵּין צָפוֹן לַדָּרוֹם,</p>\n<p>וְשַׁבָּת אִיהוּ אוֹת בְּרִית מִילָה, אוֹת דִּתְּפִלִּין, מָאן דִּמְחַלֵּל דָּא כְּאִלוּ מְחַלֵּל דָּא,</p>\n<p>תְּפִלִּין דְּרֵישָׁא לָקֳבֵל זָכוֹר, תְּפִלִּין דְּיָד לָקֳבֵל שָׁמוֹר,</p>\n<p>מָה רְשׁוּת הָרַבִּים אִיהוּ חִלּוּל שַׁבָּת, אוּף הָכִי אוֹת בְּרִית אִיהִי חִלּוּל דִּילֵיהּ זוֹנָה, וְדָא רְשׁוּ נוּכְרָאָה,</p>\n<p>לֵית פִּקּוּדָא דַעֲשֵׂה וְלֹא תַעֲשֶׂה דְלָא</p>"],[9500011114,"<p>אִשְׁתַּכַּח בְּשַׁבָּת, וּבְגִין דָּא שַׁבָּת הִיא שְׁקוּלָה כְּכָל אוֹרַיְיתָא כֻּלָּהּ.</p>\n<p>וְכֵן שְׁכִינְתָּא תַּתָּאָה אִתְקְרִיאַת שׁוֹפָר, מִסִּטְרָא דִשְׁכִינְתָּא עִלָּאָה דְאִיהִי שׁוֹפָר גָּדוֹל, תְּקַע בְּשׁוֹפָר גָּדוֹל לְחֵירוּתֵנוּ,</p>\n<p>תְּקַע שׁוֹפָר אִיהוּ לָשׁוֹן תְּקִיעָה דְּוַדַּאי שְׁכִינְתָּא תַּתָּאָה אִיהִי תְּקִיעָה דְקוּדְשָׁא בְּרִיךְ הוּא מִסִּטְרָא דִימִינָא, וְאִתְקְרִיאַת שְׁבָרִים דִּילֵיהּ מִסִּטְרָא דִשְׂמָאלָא, וְאִתְקְרִיאַת תְּרוּעָה דִילֵיהּ מִסִּטְרָא דְעַמּוּדָא דְאֶמְצָעִיתָא, דְאִיהוּ דַעַת,</p>\n<p>וּבְגִין דָּא אִתְּמַר (תהלים פט טז) אַשְׁרֵי הָעָם יוֹדְעִי תְרוּעָה, יוֹדְעִי בְדַעַת, דְאִתְּמַר בֵּיהּ (משלי ג כ) בְּדַעִִתּוֹ תְּהוֹמוֹת נִבְקָעוּ, וּבְדַעַת חֲדָרִים יִמָּלְאוּ (שם כד ד),</p>\n<p>אִיהִי שׁוֹפָר, וְקוּדְשָׁא בְּרִיךְ הוּא קוֹל הַשּׁוֹפָר, וּבְזִמְנָא דְהִיא סָלְקָא לְגַבֵּיהּ בִּתְלַת קִטְרִין אִלֵּין, אִתְּמַר בֵּיהּ (שמות יט יט) וַיְהִי קוֹל הַשּׁוֹפָר הוֹלֵךְ וְחָזֵק מְאֹד, הוֹלֵךְ בַּתְּקִיעָה, וְחָזֵק בַּשְּׁבָרִים, מְאֹד בַּתְּרוּעָה.</p>\n<p>וְאִיהִי יוֹם הַכִּפּוּרִים, וְכַד אִתְקַשְּׁטַת קֳדָמֵיהּ בִּלְבוּשִׁין שַׁפִּירִין דְּאִינוּן לְבוּשֵׁי כַפָּרָה, אִתְקְרִיאַת צִיץ דִּילֵיהּ, מִצְנֶפֶת דִּילֵיהּ, אַבְנֵט דִּילֵיהּ,</p>\n<p>אִיהִי כְלִילָא מֵאַרְבַּע בִּגְדֵי לָבָן מִסִּטְרָא דִימִינָא, וּמֵאַרְבַּע בִּגְדֵי זָהָב מִסִּטְרָא דִשְׂמָאלָא,</p>\n<p>בְּהַהוּא זִמְנָא דְאִתְקַשְּׁטַת בְּאִלֵּין לְבוּשִׁין דְּכַפָּרָה אִתְּמַר בָּהּ (אסתר ה א) וַתִּלְבַּשׁ אֶסְתֵּר מַלְכוּת, וּבְהוֹן עָאלַת לִפְנַי וְלִפְנִים, הֲדָא הוּא דִכְתִיב (שם) וַתַּעֲמוֹד בַּחֲצַר בֵּית הַמֶּלֶךְ הַפְּנִימִית, וּבְהוֹן נָשְׂאָה חֵן בְּעִינָיו,</p>\n<p>וְרָזָא דְמִלָּה וּרְאִיתִיהָ לִזְכּוֹר בְּרִית עוֹלָם (בראשית ט טז), וּמִיָּד אדנ\"י שְׁמָעָה אדנ\"י סְלָחָה אדנ\"י הַקְשִׁיבָה וַעֲשֵׂה אַל תְּאַחַר (דניאל ט יט).</p>\n<p>פּוּרִים אִתְקְרִיאַת עַל שֵׁם יוֹם הַכִּפּוּרִים, דַּעֲתִידִין לְאִתְעַנְגָא בֵּיהּ, וּלְשַׁנּוּיֵי לֵיהּ מֵעִנּוּי לְעֹנֶג, וּמַה דְּאִיהִי שְׁכִינְתָּא אָסוּר בֵּיהּ נְעִילַת הַסַּנְדָל,</p>\n<p>בְּהַהוּא זִמְנָא אִתְּמַר בָּהּ (שיר ז ב) מַה יָּפוּ פְעָמַיִךְ בַּנְּעָלִים בַּת נָדִיב, וְעִנּוּגָא וְחֶדְוָה וְכַמָּה טָבִין מְזוּמָנִין לְגַבָּהּ, וְדָא יְהֵא בְזִמְנָא דְפוּרְקָנָא בַעֲגָלָא.</p>\n<p>וּמָאן גָּרַם עִנּוּי לִשְׁכִינְתָּא בְגָלוּתָא, אֶלָּא רָזָא דְמִלָּה וּבְכֵן אָבֹא אֶל הַמֶּלֶךְ אֲשֶׁר לֹא כַדָּת (אסתר ד טז), בְּגִין דְּעָאלַת בְּלָא בַּעִִלָהּ, דְּאִתְּמַר בֵּיהּ (דברים לג) מִימִינוֹ אֵשׁ דָּת לָמוֹ, דְּבַטִּילוּ בָּהּ אוֹרַיְיתָא, וְדָא גָרַם אִבּוּדָא דְבַיִת רִאשׁוֹן וְשֵׁנִי, הֲדָא הוּא דִכְתִיב (אסתר ד טז) וְכַאֲשֶׁר אָבַדְתִּי אָבָדְתִּי,</p>\n<p>וְעִם כָּל דָּא אַף עַל גַּב דְּעָאלַת בְּלָא בַּעִִלָהּ דְאִיהוּ דִבְרֵי תוֹרָה, עִם כָּל דָּא עָאלַת בַּאֲבָהָן, דְּאִינוּן שְׁלֹשֶׁת יָמִים לַיְלָה וָיוֹם דְּאִתְעַנַּת בְּהוֹן, וְאִינוּן סַהֲדִין דְעוּלֵימְתָא עָאלַת בֵּיהּ לְמַלְכָּא, הֲדָא הוּא דִכְתִיב (שם ב יג) וּבָזֶה הַנַּעֲרָה בָּאָה אֶל הַמֶּלֶךְ, נַעֲרָה וַדַּאי בָּאָה אֶל הַמֶּלֶךְ דְּאִישׁ לֹא יְדָעָהּ אֶלָּא בַעִִלָהּ, וּכְמָה דְבָעִִרֶב הִיא בָאָה נַעֲרָה בְּתוּלָה וַדַּאי, הָכִי נַמִּי בַּבֹּקֶר הִיא שָׁבָה נַעֲרָה בְּתוּלָה וַדַּאי,</p>\n<p>וּבָהּ עִִרֶב וָבֹקֶר פַּעֲמַיִם קוֹרִין לְיִשְׂרָאֵל בַּעִִלָהּ, וְסַהֲדִין עֲלָהּ דְּלָא חֲלִיפַת לֵיהּ הִיא וּבְנָהָא בְאָחֳרָא,</p>\n<p>וּבְגִין דָּא יִשְׂרָאֵל אָמְרִין בְּכָל יוֹמָא שְׁמַע יִשְׂרָאֵל יהו\"ה אלהינ\"ו יהו\"ה אֶחָד, שְׁמַ\"ע אֶחָ\"ד, שֵׁ\"ם אָ\"ח עִ\"ד, אָ\"ח נָטִיר לָהּ, בְּגִין דְּאָח לְצָרָה יִוָּלֵד (משלי יז יז), וַעֲלֵיהּ אִתְּמַר (תהלים לב ז) אַתָּה סֵתֶר לִי, בָּרוּךְ אַתָּה בְּבוֹאֶךָ (דברים כח ו), יְהוּדָה אַתָּה יוֹדוּךָ אַחֶיךָ (בראשית מט כח), בְּגִין דְּבֵיהּ יהו\"ה וּבֵיהּ ד', בֵּיהּ אִיהִי נְטִירָא.</p>\n<p>וַעֲלֵיהּ אִתְּמַר (אסתר ב ז) וַיְהִי אֹמֵן אֶת הֲדַסָּה, הוּא אוּמָן דִּילָהּ וְאִיהִי אֱמוּנָה דִילֵיהּ, וְדָא אִיהוּ דְאִתְּמַר (שם כ) כַּאֲשֶׁר הָיְתָה בְאָמְנָה אִתּוֹ, וְלָא נָגַע בָּהּ נוּכְרָאָה דְאִיהוּ אֲחַשְׁוִרוֹ\"שׁ, בְּגִין דְּאָח עִמָּהּ וַדַּאי, וְאִיהוּ סָתִיר לָהּ מִנֵּיהּ,</p>\n<p>בְּמַאי סָתִיר לָהּ מִנֵּיהּ בַּנְּקוּדָה דְאִיהִי קוֹצָא דְאָת ד' מִן אֶחָד, א\"ח נְטִיר ד', דְּלָא יִתְקַרִיב לְגַבָּהּ אַחֵר, הֲדָא הוּא דִכְתִיב (ישעיה מב ח) אֲנִי יהו\"ה הוּא שְׁמִי וּכְבוֹדִי לְאַחֵר לֹא אֶתֵּן, וְהַאי נְקוּדָה אִיהִי אוֹת בְּרִית, דְּבָהּ אִשְׁתַּלִּים א\"ח לְעִִשֶׂר, וּבָהּ אִתְעֲבִיד י',</p>\n<p>וּמָאן דִּמְשַׁקֵּר בִּבְרִית מִילָה גָּרִים לְאִסְתַּלְקָא מִינֵיהּ</p>"],[9500011115,"<p>שְׁכִינְתָּא, דְאִיהִי יִחוּדָא דְקוּדְשָׁא בְּרִיךְ הוּא, וְשַׁלִּיט עֲלֵיהּ ש\"ד דְּאִיהוּ אַחֵר.</p>\n<p>וַדַּאי י' דְּשַׁדַּי, אִיהִי קוֹצָא מִן ד' דְאֶחָד, וְאִם מְשַׁקֵּר אַעֲבַר קוֹצָא מִן ד' מִן אֶחָד וְאִשְׁתָּאַר אַחֵר,</p>\n<p>וּבְגִין דָּא אָמַר קְרָא (שמות לד יד) לֹא תִשְׁתַּחֲוְה לְאֵל אַחֵר וְגוֹמֵר, וּבְהַהוּא זִמְנָא דְשָׁלְטָא עַל בַּר נַשׁ שֵׁד דְּאִיהוּ אֵל אַחֵר, אִיהוּ מִשְׁתַּעִִבֵּד בֵּיהּ בְּכָל מִינֵי עִנּוּיִין, וְחוֹבָא דָא גָרָם לְיִשְׂרָאֵל לְאִשְׁתַּעִִבְּדָא בְּהוֹן אוּמִין דְּעָלְמָא.</p>\n<p>וּמָאן דְּנָטִיר אוֹת בְּרִית בְּכָל אֲתַר דְּאִיהִי, בֵּין בִּבְרִית מִילָה, בֵּין בְּשַׁבָּת וְיֹמִין טָבִין, קוּדְשָׁא בְּרִיךְ הוּא נָטִיר לֵיהּ בְּגִינָהּ בְּכָל אֲתַר, וּמְכַסֵּי עֲלוֹי מִשָּׂנְאוֹי, כְּגַוְונָא דְמֹשֶׁה דְאִתְּמַר בֵּיהּ (תהלים צא א) בְּצֵל שַדָ\"י יִתְלוֹנָן,</p>\n<p>וּכְגַוְונָא דְאֶסְתֵּר דְּסָתִיר לָהּ מֵאֲחַשְׁוִרוֹשׁ דְּאִיהוּ עָרֵלוְטָ מֵא, וְ שַׁוִּיבְּ אַתְרֵיהּשֵׁנִית (נ\"אשדית) בּדִיּוֹקְנָ אדִילָהּ, הֲדָא הוּא דִכְתִיב (אסתר ב יג) כָּל אֲשֶׁר תֹּאמַר וְגוֹמֵר, בָּעִִרֶב הִיא בָאָה וּבַבֹּקֶר הִיא שָׁבָה אֶל בֵּית הַנָּשִׁים שֵׁנִי,</p>\n<p>וְאִיהוּ נָטִיר לָהּ מֵהָמָן הָרָשָׁע, הֲדָא הוּא דִכְתִיב (תהלים לב ז) מִצַּר תִּצְּרֵנִי, דְאִיהוּ צַר וְאוֹיֵב. וּבְגִין הַאי קִנְאָה דְכַסִּי קוּדְשָׁא בְּרִיךְ הוּא בְאוֹת דִּילֵיהּ עַל אֶסְתֵּר, דְּאִיהִי קְדוּשָׁה דִילֵיהּ, דְּלָא אִיהִי קְדוּשָׁה פָּחוּת מֵעֲשָׂרָה, אִתְלַבְּשׁוּ עֲשָׂרָה כִּתְרִין תַּתָּאִין בַּעֲשָׂרָה בְּנִין דְּהָמָן, דְּתַמָּן אֵל אַחֵר, דְּהָמָן אָמַר וַעֲשֶׂרֶת אֲלָפִים כִּכַּר כֶּסֶף אֶשְׁקוֹל וְגוֹמֵר (אסתר ג ט), וְכֹלָּא לְנָטְלָא נוּקְמָא מֵאֶסְתֵּר וְאוּמָתָהּ, דְּאִתְּמַר בָּהּ (שם ה א) וַתִּלְבַּשׁ אֶסְתֵּר מַלְכוּת,</p>\n<p>וְקוּדְשָׁא בְּרִיךְ הוּא מָסַר לוֹן בִּידָהָא וּבִידָא דְאוּמָתָהּ, וְתָלוּ אוֹתוֹ וְאֶת בָּנָיו עַל הָעִץ (שם ט כה), וְאִיהוּ עָבַד עִץ גָּבוֹהַּ חֲמִשִּׁים אַמָּה, וְקוּדְשָׁא בְּרִיךְ הוּא נָטִיל נוּקְמָא מִנֵּיהּ וּמִבְּנוֹי בִּשְׁכִינְתָּא עִלָּאָה, דְמָחַאת לְמִצְרָאֵי חֲמִשִּׁים מַכּוֹת.</p>\n<p>וְעוֹד שְׁכִינְתָּא אִתְקְרִיאַת צְדָקָה, וְקוּדְשָׁא בְּרִיךְ הוּא בַּעַל צְדָקָה, וּבְגָלוּתָא אִיהִי עֲנִיָּה, וּבְנָהָא עֲנִיִּים,</p>\n<p>וְקוּדְשָׁא בְּרִיךְ הוּא כַּבְיָכוֹל אִיהוּ עָנִי כַּד אִיהוּ בַּר מֵאַתְרֵיהּ, וּבְגִינָהּ אִתְּמַר (ישעיה לג ז) הֵן אֶרְאֶלָּם צָעֲקוּ חוּצָה וכו',</p>\n<p>וּבְאָן אֲתַר אִיהוּ עָנִי וְאִיהִי עֲנִיָּה בְּצַדִּיק דְּאִיהוּ בְּרִית, וּבְגִין דְּחָאבוּ בֵּיהּ יִשְׂרָאֵל לְתַתָּא אִיהוּ נָהָר יֶחרַב וְיָבֵשׁ (איוב יד יא) בְּבַיִת רִאשׁוֹן וְשֵׁנִי, וּשְׁכִינְתָּא אִיהִי בֵּיהּ חֲרֵבָה וִיבֵשָׁה, בְּגִין דְּאִינוּן גְּרָמֵי דְיִתְכַּנְשׁוּן מִנֵּיהּ מַיִּין עִלָּאִין, וּשְׁכִינְתָּא אִשְׁתְּאָרַת יְבֵשָׁה, הֲדָא הוּא דִכְתִיב (בראשית א ט) יִקָּווּ הַמַּיִם מִתַּחַת הַשָּׁמַיִם אֶל מָקוֹם אֶחָד וְתֵרָאֶה הַיַּבָּשָׁה.</p>\n<p>וְכָל מָאן דְּעָבִיד צְדָקָה בְּמִסְכֵּנָא גָּרִים הַהוּא נָהָר דְּיִתְמַשֵּׁךְ מֵעִדֶן דְּאִיהִי אִימָּא עִלָּאָה, לְהַשְׁקוֹת אֶת הַגָּן דְּאִיהִי ד' דַּלָּה מִסְכֵּנָא,</p>\n<p>וְעָנִי אִיהוּ יוֹם שַׁבָּת, וּמָאן דִּמְקַיֵּים בָּהּ עֹנֶג שַׁבָּת גָּרִים לְאַשְׁקָאָה הַהִיא ד', וְהַהוּא עָנִי אִתְמַלֵּי וְאִתְקְרֵי נָהָר, וּמָאן דְּאִית לֵיהּ רְשׁוּ לְמֶעֱבַד עֹנֶג שַׁבָּת וְלָא עָבִיד, אִתְהַפֵּךְ לֵיהּ עֹנֶג לְנֶגַע צָרַעַת, וְחָרִיב בֵּיתֵיהּ וּמָמוֹנֵיהּ,</p>\n<p>וְכֵן עֲנִיָּה אִיהִי אוֹרַיְיתָא דְעַל פֶּה וַדַּאי, וְאִיהִי קַבָּלָה כַּד מְקַבְּלָא מִבַּעַל צְדָקָה, דְאִיהוּ אוֹרַיְיתָא דְבִכְתָב, כַּד אָזְלַת לְגַבֵּיהּ לְקַבָּלָה אִתְקְרִיאַת הֲלָכָה, כַּד מְקַבְּלָא מִנֵּיהּ אִתְקְרִיאַת קַבָּלָה,</p>\n<p>וּבְהַהוּא זִמְנָא אִיהִי פְלִיגַת מַה דְּיַהֲבִין לָהּ לְעַבְדִין דִּילָהּ וְלִבְנִין וּלְעוּלֵמִין דִּילָהּ, כְּמָה דְאַתְּ אָמַר (משלי לא טו) וַתִּתֵּן טֶרֶף לְבֵיתָהּ וְחֹק לְנַעֲרוֹתֶיהָ, וּמְקַבְּלִין דֵּין מִן דֵּין, מֵהַהוּא דִמְקַבְּלִין מִינָהּ.</p>\n<p>בַּעַל קַבָּלָה אִיהוּ עַמּוּדָא דְאֶמְצָעִיתָא, וְאִיהִי קַבִּילַת מִינֵיהּ, וּבְאָן אֲתַר קַבִּילַת מִנֵּיהּ בִּימִינָא, בְּגִין דַּעֲלֵיהּ אִתְּמַר כִּי יְמִינְךָ פְּשׁוּטָה לְקַבֵּל שָׁבִים,</p>\n<p>הֲלָכָה אִיהִי מִסִּטְרָא דִשְׂמָאלָא, קַבָּלָה</p>"],[9500011116,"<p>הִיא מִסִּטְרָא דִימִינָא, הֲלָכָה בִשְׂמָאלָא לְגַבֵּי בַּעִִלָהּ, וְקַבִּילַת מִנֵּיהּ בִּימִינָא וְנָחֲתָא מַלְיָא לְגַבֵּי צַדִּיק, וּבְגִין דָּא (תהלים לז כה) לֹא רָאִיתִי צַדִּיק נֶעֱזָב וכו',</p>\n<p>וכו', (ובמאי) וְכַד נָחֲתָא מַלְיָא לְגַבֵּי בַעִִלָהּ דְּאִיהוּ ו', נָהָר דְּאִתְמַשַּׁךְ מֵעִדֶן, ו' עָאל בְּד' וְאִתְעֲבִידַת ה', וּמַה דַּהֲוָה צֶדֶק אִתְעֲבִידַת צְדָקָה לְגַבֵּי עָנִי דְאִיהוּ צַדִּיק.</p>\n<p>וְהַהוּא נָהָר עֲלֵיהּ אִתְּמַר שֶׁמֶשׁ בְּשַׁבָּת צְדָקָה לַעֲנִיִּים, וַעֲלֵיהּ אִתְּמַר (משלי יד לד) צְדָקָה תְּרוֹמֵם גּוֹי, וּמַה דַּהֲוַת צֶדֶק דִּינָא, אִתְעֲבִידַת רַחֲמֵי,</p>\n<p>וְכָל סְפִירָן עַל שְׁמָהּ אִתְקְרִיאוּ, מֹאזְנֵי צֶדֶק אַבְנֵי צֶדֶק אֵיפַת צֶדֶק וְהִין צֶדֶק (ויקרא יט לו), כַּד אִתְרַחַק מִינָהּ בַּעִִלָהּ דְּאִיהוּ רַחֲמֵי, מֹאזְנֵי צֶדֶק תְּרֵין דְּרוֹעִין, אַבְנֵי צֶדֶק תְּרֵין סַמְכֵי קְשׁוֹט, הִין צֶדֶק צַדִּיק,</p>\n<p>וְכַד עַמּוּדָא דְאֶמְצָעִיתָא מְרַחֵק מִינָהּ אִיהוּ מִשְׁפָּט, וּבֵיהּ כְּתִיב (תהלים עה ח) כִּי אלהי\"ם שׁוֹפֵט זֶה יַשְׁפִּיל וְזֶה יָרִים, זֶה יַשְׁפִּיל מָאן דְּגָרִים לְאַשְׁפָּלָא לִשְׁכִינְתָּא מֵאַתְרָהָא, וְזֶה יָרִים מָאן דְּגָרִים לְסָלְקָא לָהּ מֵאַתְרָהָא,</p>\n<p>דְּחוֹבִין דְּיִשְׂרָאֵל אִינוּן אַשְׁפִּילָן לָהּ לְתַתָּא, וְזַכְוָון דִּלְהוֹן סָלְקִין לָהּ לְאַתְרָהָא, הָא זַכָּאָה אִיהוּ מָאן דְּעָבִיד זַכְוָון לְסָלְקָא לָהּ לְאַתְרָהָא.</p>\n<p>וְעוֹד שְׁכִינְתָּא אִיהִי שִׁלּוּחַ הַקֵּן, מָאן קֵן דִילָהּ דָּא יְרוּשָׁלַםִ, וּלְעִילָא קֵן דִּילָהּ הַהוּא דְאִתְּמַר בֵּיהּ (שמות לד ז) וְנַקֵּה לֹא יְנַקֶּה, וְדָא מטטרו\"ן, עֲלֵיהּ אִתְּמַר אַל תִּסְתַּכֵּל בְּקַנְקַן אֶלָּא בַּמֶּה דְאִית בֵּיהּ,</p>\n<p>וְדָא אִיהוּ כִּי יִקָּרֵא קַן צִפּוֹר לְפָנֶיךָ בַּדֶּרֶךְ בְּכָל עִץ אוֹ עַל הָאָרֶץ (דברים כב ו), בְּכָל עִץ דָּא גוּף וּבְרִית, צַדִּיק אִיהוּ בְרִית וְאִיהוּ כָּ\"ל, עִץ דָּא עַמּוּדָא דְאֶמְצָעִיתָא, אוֹ עַל הָאָרֶץ דָּא אִימָּא תַּתָּאָה, אֶפְרֹחִים תְּרֵין דְּרוֹעִין, אוֹ בֵּיצִים תְּרֵין שׁוֹקִין, וְהָאֵם רֹבֶצֶת דָּא אִימָּא עִלָּאָה, שַׁלֵּחַ תְּשַׁלַּח אֶת הָאֵם דָּא אִימָּא תַּתָּאָה אֶת וַדַּאי.</p>\n<p>שַׁלֵּחַ תְּשַׁלַּח, הֲדָא הוּא דִכְתִיב (בראשית ח ח) וַיְשַׁלַּח אֶת הַיּוֹנָה מֵאִתּוֹ, וְאִתְּמַר בְּיַעֲקֹב (שם כז ל) וַיְהִי אַךְ יָצֹא יָצָא, לָקֳבֵל שַׁלֵּחַ תְּשַׁלַּח, וְאִינוּן תְּרֵין דְרוֹעִין שְׁנֵי גְרִישִׁי\"ן וְאִינוּן תְּרֵין תְּרוּכִין, וְדָא אִיהוּ שַׁלֵּחַ תְּשַׁלַּח אֶת הָאֵם, וְאֶת הַבָּנִים תִּקַּח לָךְ, אִלֵּין שִׁית פִּרְקִין דְּאִינוּן בִּתְרֵי דְרוֹעִין, אִשְׁתְּאָרַת ה' ד' בְּלָא ו',</p>\n<p>מָאן גָּרִים לָהּ תְּרֵי תְּרוּכִין, אֶלָּא בְּגִין דְעָבְרִין בְּנָהָא עַל פִּקּוּדֵי אוֹרַיְיתָא עֲשֵׂה וְלֹא תַעֲשֶׂה, הֲדָא הוּא דִכְתִיב (ישעיה נ יח) וּבְפִשְׁעִיכֶם שֻׁלְּחָה אִמְּכֶם.</p>\n<p>וַיּוֹסֶף שַׁלַּח אֶת הַיּוֹנָה מֵאִתּוֹ (בראשית ח י) דָא עַמּוּדָא דְאֶמְצָעִיתָא, מָאן גָּרִים דָּא דְאִתְתָּרְכַת מִינֵיהּ, בְּגִין דְּיִשְׂרָאֵל עָבְרוּ עַל אוֹרַיְיתָא,</p>\n<p>וַיָּחֶל עוֹד שִׁבְעַת יָמִים אֲחֵרִים (שם) (נ\"א וישלח את היונה ולא יספה שוב), דָּא ז', יוֹמָא שְׁבִיעָאָה דִכְלִיל שֶׁבַע שַׁבָּתוֹת, וּמָאן גָּרַם דְּאִתְתָּרְכַת מִנֵּיהּ, בְּגִין דְּעָבְרוּ יִשְׂרָאֵל עַל אוֹת שַׁבָּת וְיוֹמִין טָבִין וְאוֹת בְּרִית.</p>\n<p>מִסִּטְרָא דְיִצְחָק דְּאִיהוּ רֹאשׁ הַשָּׁנָה, אִתְּמַר בֵּיהּ (שם) וַתָּבֹא אֵלָיו הַיּוֹנָה לְעִת עִִרֶב, וְדָא עִִרֶב דְּיִצְחָק, וּמִסִּטְרָא דְצַדִּיק אִתְּמַר בָּהּ (שם) וְהִנֵּה עֲלֵה זַיִת טָרָף בְּפִיהָ, וַיֵּדַע נֹחַ כִּי קַלּוּ הַמַּיִם מֵעַל הָאָרֶץ,</p>\n<p>וּבְכָל אֲתַר דְּלָא אַשְׁכַּחַת לְתַתָּא דִיּוֹקְנָא דְבַעִִלָהּ בְּאוֹרַיְיתָא, לָא הֲוַת שַׁרְיָא עֲלָהּ, הֲדָא הוּא דִכְתִיב (שם ט) וְלֹא מָצְאָה הַיּוֹנָה מָנוֹחַ לְכַף רַגְלָהּ בְּגָלוּתָא, מִיָּד דְּאַשְׁכְּחַת בַּעִִלָהּ לְרַעִִיָא מְהֵימְנָא, שַׁרְיָא עֲלֵיהּ וְלָא חָזְרַת לְתֵיבָה,</p>\n<p>הֲדָא הוּא דִכְתִיב (שם יב) וְלֹא יָסְפָה שׁוּב אֵלָיו עוֹד, וְעַל דָּא אִתְּמַר (שם ב כד) עַל כֵּן יַעֲזָב אִישׁ אֶת אָבִיו וְאֶת אִמּוֹ וְגוֹמֵר, אִיהִי אִתְדַּבְּקַת בֵּיהּ וְאִיהוּ בָהּ.</p>\n<p>בְּהַהוּא זִמְנָא וַיִּפְתַּח נֹחַ אֶת חַלּוֹן הַתֵּיבָה אֲשֶׁר עָשָׂה (שם ח ו), וְנָפְקוּ כֻלְּהוּ וְאָזְלוּ לְגַבֵּי יוֹנָה וּבַעִִלָהּ,</p>\n<p>וְאִתְּמַר לְגַבֵּי נֹחַ וַיִּפְתַּח נֹחַ, מַאי וַיִּפְתַּח נֹחַ, אֶלָּא רָמִיז וַתִּפְתַּח וַתִּרְאֵהוּ אֶת הַיֶּלֶד (שמות ב כד), אדנ\"י שְׂפָתַי תִּפְתָּח, וְדָא יִשְׂרָאֵל דְּפָתְחִין בִּתְיוּבְתָּא בַּבִּכְיָה, וּמִיָּד וַתַּחְמוֹל עָלָיו.</p>\n<p>וְעוֹד שְׁכִינְתָּא אִתְקְרִיאַת חַג, בְּכָל זִמְנִין וְיוֹמִין טָבִין, חָג דִּתְלַת רְגָלִין, דְּאִתְּמַר בְהוֹן (שמות כג יד) שָׁלֹשׁ</p>"],[9500011117,"<p>רְגָלִים תָּחוֹג לִי בַּשָּׁנָה, וּבְגִינָהּ יֵרָאֶה כָּל זְכוּרְךָ, לְקַיְימָא זָכוֹר וְשָׁמוֹר זָכוֹר לַזָּכָר וְשָׁמוֹר לַנְּקֵבָה, כֻּלְּהוּ אִלֵּין דְּאָזְלִין לְאִסְתַּכְּלָא (נ\"א לאתכללא) בִשְׁכִינְתָּא, צְרִיכִין לְמֵיהַב לָהּ דּוֹרוֹנָא, הֲדָא הוּא דִכְתִיב (דברים טז טז) וְלֹא יֵרָאֶה אֶת פְּנֵי יהו\"ה רֵיקָם,</p>\n<p>וְצָרִיךְ לְמֶחדֵי בָּהּ, הֲדָא הוּא דִכְתִיב (שם) וְשָׂמַחְתָּ בְּחַגֶּךָ, דְּאִיהִי חֶדְוָא דְקוּדְשָׁא בְּרִיךְ הוּא אִתְקְרִיאַת, וּמָאן דְּאָזִיל לְמֶחמֵי לָהּ צָרִיךְ לְנָטְרָא גַרְמֵיהּ מֵעֲצִיבוּ, דְאִיהִי לִילִי\"ת חֲשׁוֹכָא עִצָּבוֹן שְׁאוֹל טְחוֹל, דְּאִיהִי מוּם, וַעֲלֵיהּ אִתְּמַר (ויקרא כא יח) כָל אֲשֶׁר בּוֹ מוּם לֹא יִקְרָב.</p>\n<p>אִישׁ כְּמַתְּנַת יָדוֹ דָא שְׁכִינְתָּא עִלָּאָה, דַעֲלָהּ אִתְּמַר (משלי כא יד) מַתָּן בַּסֵּתֶר יִכְפֶּה אָף, בְּגִין דְּאִיהִי סְתִימָא, עוֹלָם הַבָּא קָרִינָן לָהּ מַתָּנָה, וַעֲלָהּ אִתְּמַר יִשְׂמַח מֹשֶׁה בְּמַתְּנַת חֶלְקוֹ, בְּגִין דְּמַתַּת אלהי\"ם הִיא,</p>\n<p>כְּבִרְכַּת יהו\"ה אלהי\"ך אֲשֶׁר נָתַן לָךְ דָּא שְׁכִינְתָּא תַּתָּאָה, חַד מִסִּטְרָא דִיְמִינָא בְרָכָה, וְחַד מִסִּטְרָא דִשְׂמָאלָא מַתָּנָה.</p>\n<p>וְעוֹד שְׁכִינְתָּא אִיהִי חֶשְׁבּוֹן תְּקוּפוֹת וּמַזָּלוֹת וּמוֹלָדוֹת וְעִבּוּרִין,</p>\n<p>אַרְבַּע תְּקוּפָן דְּאִתְקְרִיאוּ אַרְבַּע תְּקוּפוֹת, וּלְכָל תְּקוּפָה תְּלַת יַרְחִין, וּבְהוֹן תְּרֵין עֲשַׂר מַזָּלוֹת, וְאִינוּן לָקֳבֵל תְּרֵין עֲשַׂר שִׁבְטִין דְּיִשְׂרָאֵל, וְכֹלָּא אִתְקַשֵּׁר בְּהַאי שְׁמָא אדנ\"י, אִיהִי שְׁכִינְתָּא תַּתָּאָה, תַּקִּיפָא בְּאַרְבַּע תְּקוּפִין, דְּאִינוּן מִסִּטְרָא דִשְׂמָאלָא חָזָק תַּקִּיף, וְאִינוּן אל\"ף דל\"ת נו\"ן יו\"ד,</p>\n<p>וְכֻלְּהוּ תְּרֵין עֲשַׂר מַזָּלוֹת קָשִׁין מִסִּטְרָא דְּדִין, וּבְגִין דִּמְזוֹנָא קָא אַתְיָא מִנַּיְיהוּ, אָמְרוּ מָארֵי מַתְנִיתִין קָשִׁין מְזוֹנוֹתָיו שֶׁל אָדָם כִּקְרִיעַת יַם סוּף, דְּאִתְקַרַע בְּהוֹן לִתְרֵין עֲשַׂר קְרָעִין.</p>\n<p>וְאִינוּן אַרְבַּע תְּקוּפוֹת תְּרֵין דְּרוֹעִין וּתְרֵין שׁוֹקִין, תְּרֵין עֲשַׂר מַזָּלוֹת תְּרֵין עֲשַׂר פִּרְקִין דְּאִית בְּהוֹן, וּלְקִבְלַיְיהוּ תְּרֵין עֲשַׂר יַרְחֵי שַׁתָּא, וְאִינוּן ו' ו' רָזָא דְעִבּוּרָא וְדָא יַרְחָא תְּלַת עֲשַׂר, דָּא א, וְדָא וָא\"ו, שַׁתָּא מִתְּלַת עֲשַׂר יַרְחִין,</p>\n<p>וּבֵיהּ צָרִיךְ לְהַשְׁווֹת שְׁנַת הַחַמָּה עִם שְׁנַת הַלְּבָנָה, וּלְיַחֲדָא לוֹן בְּמַהֲלַךְ הָאֶמְצָעִי דְאִיהוּ עַמּוּדָא דְאֶמְצָעִיתָא,</p>\n<p>וְאִם בַּר נַשׁ יָדַע לְמִמְנֵי וּלְהַשְׁווֹת שְׁנַת הַחַמָּה עִם שְׁנַת הַלְּבָנָה וּלְיַיחֵד לוֹן, אִיהוּ יָדַע מָתַי יְהֵא פֶּסַח בַּחֹדֶשׁ הָאָבִיב, וּבְדָא יִשְׁווּן אַבָּא וְאִמָּא בְּרָא וּבְרַתָּא, הֲדָא הוּא דִכְתִיב (דברים ד ו) וּשְׁמַרְתֶּם וַעֲשִׂיתֶם כִּי הִיא חָכְמַתְכֶם וּבִינַתְכֶם, וּשְׁמַרְתֶּם וַעֲשִׂיתֶם דָּא ו\"ה, כִּי הִיא חָכְמַתְכֶם וּבִינַתְכֶם דָּא י\"ה</p>\n<p>וּבַמֶּה יְהוֹן שָׁוִין אַבָּא וְאִמָּא בְּרָא וּבְרַתָּא, בְּא' דְהוּא כִּתְרָא עִלָּאָה, דְּאָמְרָה סִיהֲרָא עֲלָהּ, אִי אֶפְשַׁר לִשְׁנֵי מְלָכִים שֶׁיִּשְׁתַּמְּשׁוּ בְּכֶתֶר אֶחָד,</p>\n<p>וּבְגִינֵיהּ אָמְרִין בְּשַׁבָּת וְיוֹמִין טָבִין וּבְרֵישֵׁי יַרְחִין, כֶּתֶר יִתְּנוּ לְךָ יהו\"ה אלהינ\"ו מַלְאָכִים הֲמוֹנֵי מַעִִלָה, מֶלֶךְ וּמַלְכוּת.</p>\n<p>וְעוֹד אִיהִי מִצְוַת שְׁחִיטָה כְּשֵׁרָה בַּזָּרִים (נ\"א בנשים), דְּאִינוּן בְּנֵי נָשָׁא דְּדַמְיָין לִבְעִירָן, דְּאִלֵּין דְּלָא מִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא צָרִיךְ לְמֶעֱבַד בְּהוֹן קָרְבָּנִין דִּצְלוֹתִין, דְּיִתְקַרִיבוּ לְקוּדְשָׁא בְּרִיךְ הוּא,</p>\n<p>וְאִם מִתְקָרְבִין בִּצְלוֹתִין לְקוּדְשָׁא בְּרִיךְ הוּא, וְסָבְלִין כַּמָּה מַכְתָּשִׁין, הֲדָא הוּא דִכְתִיב (תהלים מד כג) כִּי עָלֶיךָ הוֹרַגְנוּ כָל הַיּוֹם נֶחְשַׁבְנוּ כְּצֹאן טִבְחָה, אִתְחֲזֵי כְּאִלּוּ וְזָבַחְתָּ עָלָיו אֶת עוֹלוֹתֶיךָ וְאֶת שְׁלָמֶיךָ וְגוֹמֵר (שמות כ כד), דְּדָא שֵׁזִיב לוֹן מִמִּיתָה דְמַלְאַךְ הַמָּוְת, הֲדָא הוּא דִכְתִיב (תהלים לו ז) אָדָם וּבְהֵמָה תּוֹשִׁיעַ יהו\"ה.</p>\n<p>וְאִלֵּין דְּעוֹבְדַיְיהוּ כִּבְעִירָן דְּחַקְלָא דְאָכְלִין בְּלָא צְלוֹתִין, מִיתַתְהוֹן יְהֵא כִּבְעִירָן דְּחַקְלָא, וְשָׁחִיט לוֹן מַלְאַךְ הַמָּוְת מִדָּה כְּנֶגֶד מִדָּה,</p>\n<p>וְלָא עוֹד אֶלָּא בְּסַכִּין פָּגוּם קָא שָׁחִיט לוֹן, וְאִתְקְרִיאוּ נְבֵלָה, וַעֲלַיְיהוּ אִתְּמַר (ישעיה כו יט) נְבֵלָתִי יְקוּמוּן,</p>\n<p>מַאי סַכִּין פָּגוּם דָּא סמא\"ל אֵל אַחֵר, סַכִּין פָּגוּם וַדַּאי אִתְקְרֵי, וְאִיהִי פְּגִימָה סַם הַמָּוְת, טְרֵיפָה וּנְבֵלָה.</p>"],[9500011118,"<p>וְכֵיוָן דְּאִתְיְיהִיבוּ בִידֵיהוֹן כְּבָר קַבִּילוּ עָנְשַׁיְהוּ, וּבְגִין דָּא נְבֵלָתִי יְקוּמוּן,</p>\n<p>וְכָל סִירְכָאן דְּסַם הַמָּוְת אִינוּן רַגְלִין דִּילָהּ, וַעֲלַיְיהוּ אִתְּמַר (משלי ה ה) רַגְלֶיהָ יוֹרְדוֹת מָוְת וְגוֹמֵר, וְאִינוּן חַ\"י סִרְכוֹת, עֲלַיְיהוּ כְּתִיב (בראשית ח כא) וְלֹא אוֹסִיף עוֹד לְהַכּוֹת אֶת כָּל חַ\"י כַּאֲשֶׁר עָשִׂיתִי, לְאִינוּן דִּמְצַלִּין חַ\"י בִּרְכָאָן דִּצְלוֹתִין,</p>\n<p>(ומאן גרים דמי טופנא מתגברין, מאן דאריק מיא דזרע ברית מילה בנדה שפחה גויה זונה)</p>\n<p>וּלְעוֹלָם וַורְדָּא בְכָל אֲתַר דְּתִתְסָרֵךְ טְרֵפָה וְאֵינָה חַיָּה, דִבְכָל אֲתַר דְּתִתְסָרֵךְ בְּבַר נַשׁ בְּחוֹבִין דִּילָהּ קְטִילַת.</p>\n<p>וְעוֹד שְׁכִינְתָּא אִיהִי מִצְוַת אֲסִיפַת נוּנִי יַמָּא דְאוֹרַיְיתָא, דְאִתְּמַר בְּהוֹן דָּגִים וַחֲגָבִים אֵינָן טְעוּנִין שְׁחִיטָה, וְאִינוּן תַּלְמִידֵי דְבֵי רַב דְּמִתְרַבִּין בְּיַמָּא דְאוֹרַיְיתָא, דַּעֲלַיְיהוּ אִתְּמַר אֲסִיפָתָן הִיא הַמַּתֶּרֶת אוֹתָן, הֲדָא הוּא דִכְתִיב (במדבר יא כב) יֵאָסֵף לָהֶם וּמָצָא לָהֶם, הִיא הַמַּתֶּרֶת אוֹתָם מִשְּׁחִיטָה וַדַּאי.</p>\n<p>וְגַדְפוֹי דִשְׁכִינְתָּא אִינוּן כִּסּוּי דַם חַיָּה אוֹ עוֹף, דְּאִינוּן כַּנְפֵי יוֹנָה, וְאִלֵּין אִינוּן כַּנְפֵי מִצְוָה, דִמְכַסְּיָן עַל דְּמֵיהוֹן, דְּלָא שָׁלְטִין עֲלַיְהוּ כַּלְבִּין דְּאִנּוּן חֲצִיפִין, דְּאִינוּן מַלְאֲכֵי חַבָּלָה (וכלהו), וּדְלָא אִשְׁתְּמוֹדְעוּן בְּהוֹן מָארֵי חוֹבִין, (הרי) הָכִי הַדָּם הוּא הַנֶּפֶשׁ, וְעַפְרָא דִמְכַסְּיָא עָלָיו רָמִיז (דברים לב מג) וְכִפֶּר אַדְמָתוֹ עַמּוֹ.</p>\n<p>וְעוֹד שְׁכִינְתָּא אִיהִי בְּדִיקַת סִימָנֵי חַיָּה אוֹ עוֹף, מִבְּנֵי נָשָׁא דְּדַמְיָין לְחֵיוָן וּבְעִירָן וְעוֹפִין, דַּעֲלַיְיהוּ אִתְּמַר (שמואל א יד לד) וּשְׁחַטְתֶּם בָּזֶה, בְּדוֹק כְּמוֹ זֶה, דְּאִינוּן סָבְלִין מַכְתָּשִׁין, כְּמָה דְאוּקְמוּהוּ כִּי עָלֶיךָ הוֹרַגְנוּ כָל הַיּוֹם (תהלים מד כג), וּבְכָל יוֹמָא לָא מַנִּיחִין צְלוֹתִין, וּבָדִיק לוֹן קוּדְשָׁא בְּרִיךְ הוּא בְּכַמָּה מַכְתְּשִׁין,</p>\n<p>וְאָמְרִין זֶה לָזֶה בִּצְלוֹתִין, קוּדְשָׁא בְּרִיךְ הוּא פָּרִיק לָן מִדִּינָא דִבְעִירָן וְחֵיוָן דְּאַרְעָא, וְאַעִיל לָן לְמֶהֱוֵי לָן חוּלָקָא בְּמַלְאָכַיָּא, דְאִינוּן חַיּוֹת הַקֹּדֶשׁ, דְּקָרָאן זֶה לָזֶה וְאָמְרִין קָדוֹשׁ קָדוֹשׁ קָדוֹשׁ, דָּא אִיהוּ (קדוש) דְּאִתְקַדַּשׁ שְׁמֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא עַל יְדֵיהּ, וִיהֵא לֵיהּ חוּלָקָא בֵּיהּ.</p>\n<p>וְעוֹד וּשְׁחַטְתֶּם בָּזֶה דָּא אל\"ף דל\"ת נו\"ן יו\"ד, דְּבֵיהּ דָּן קוּדְשָׁא בְּרִיךְ הוּא כָּל נְזִיקִין, וְעַל כָּל אִלֵּין דְּקָטְלִין חַד לְחַבְרֵיהּ, וְעַל כָּל אִלֵּין דְּגָזְלִין</p>\n<p>יהו\"ה אִיהוּ דָן, דְּאִתְלַבַּשׁ בְּתֹהוּ וָבֹהוּ וְחֹשֶׁךְ וּתְהוֹם, וְדָן בְּהוֹן אַרְבַּע מִיתוֹת בֵּית דִּין, וְהָא אוּקְמוּהוּ כֻּלְּהוּ בְּאַתְוָון, י' גַּחֶלֶת, ו' שַׁלְהוֹבָא, ה\"ה גַּוָּונִין וּנְהוֹרִין דְּנוּרָא דָּא אִיהוּ שְׂרֵפָה, (דברים ד כד) כִּי יהו\"ה אלהי\"ך אֵשׁ אוֹכְלָה הוּא,</p>\n<p>סְקִילָה בִּתְלַת אַבְנִין י' י' י', וְאִינוּן יהו\"ה כ\"ו, וְד' אַתְוָון י' י' י',</p>\n<p>הֶרֶג בְּחַרְבָּא, י' רֵישָׁא דְחַרְבָּא, ו' גּוּפָא דְחַרְבָּא, ה\"ה תְּרֵין פִּפִיּוֹת דִּילָהּ,</p>\n<p>חֶנֶק ו' (ס\"א ג') אִתְעֲבִיד חוּט כְּגַוְונָא דָא זַרְקָא [ציור] וַעֲלָהּ י' דְּעִזְקָא בְחוּטָא לְמֶהֱוֵי כְּרִיךְ לָהּ עַל צַוָּאר,</p>\n<p>וְרָזָא דְמִלָּה (במדבר כז ג) אָבִינוּ מֵת בַּמִּדְבָּר, מַקַּ\"ף וְהוֹלֵ\"ךְ אִינוּן ה\"ה, חַד מַקַּף לֵיהּ וְחַד הוֹלֵךְ, עַד דְּחָנְקִין לֵיהּ, וּבְגִין דָּא אָמַר קוּדְשָׁא בְּרִיךְ הוּא, רְאוּ עַתָּה כִּי אֲנִי אֲנִי הוּא, אֲנִי אָמִית וַאֲחַיֶּה, מָחַצְתִּי וַאֲנִי אֶרְפָּא וְאֵין מִיָּדִי מַצִּיל (דברים לב לט).</p>\n<p>ו' עִץ, גָּבוֹהַּ חֲמִשִּׁים אַמָּה דָּא ה' דִּסְלִיקַת בְּי' לְחַמְשִׁין, זַרְקָא קַו דַּחֲנִיקַת בִּתְלַת אַתְוָון, דִּשְׁכִינְתָּא תַּתָּאָה אִיהִי דָן אַרְבַּע מִיתוֹת בֵּית דִּין, אִיהִי חֲנִיקַת לְחַיָּיבַיָּא, וְהָרַג לוֹן, בִּשְׂרֵפָה וּסְקִילָה, וּבְגִין דָּא רְאוּ עַתָּה כִּי אֲנִי אֲנִי הוּא, הֲדָא הוּא דִכְתִיב (ויקרא כו כח) וְיִסַּרְתִּי אֶתְכֶם אַף אָנִי וְגוֹמֵר,</p>\n<p>וּכְמָה דְבִשְׁמֵיהּ קָטִיל לְמָאן דְּאַעֲבַר עַל כְּרִיתוֹת וּמִיתוֹת בֵּית דִּין דְּאוֹרַיְיתָא, הָכִי מַסֵּי וּמְחַיֶה בִּשְׁמֵיהּ לְמָאן דִּמְקַיֵּים לוֹן.</p>\n<p>וְעוֹד מִצְוַת גְּזֵלַת הֶעָנִי בְּבָתֵּיכֶם דָּא שְׁכִינְתָּא, דְּמָאן דְּגָזִיל צְלוֹתָא דְאִיהִי צְדָקָה לְצַדִּיק חַ\"י עָלְמִין, כְּלִיל חַ\"י בִּרְכָאָן, כְּאִלּוּ גָזִיל לֵיהּ חַיִּים דִּילֵיהּ דְּאִיהוּ שְׁכִינְתָּא, דְאִתְּמַר בָּהּ (קהלת ט ט) רְאֵה חַיִּים עִם אִשָּׁה אֲשֶׁר אָהַבְתָּ,</p>\n<p>וְכֵן מָאן דְּגָרַע מֵעֹנֶג שַׁבָּת, כְּאִלּוּ גָזִיל לֵיהּ שְׁכִינְתֵּיהּ דְּאִיהִי שַׁבָּת בַּת יְחִידָה, וְדָא גָרַם דְּאִתְגְזִילַת מִנֵּיהּ בְּגָלוּתָא, הֲדָא הוּא דִכְתִיב (ישעיה נ א) וּבְפִשְׁעִיכֶם שֻׁלְּחָה אִמְּכֶם,</p>\n<p>וּתְיוּבְתָּא מַאי נִיהוּ וְהֵשִׁיב</p>"],[9500011119,"<p>אֶת הַגְּזֵלָה אֲשֶׁר גָּזָל (ויקרא ה כג), דְּיַחֲזִיר שְׁכִינְתָּא לְאַתְרָהּ, אוֹ אֶת הָעֹשֶׁק אֲשֶׁר עָשָׁק (שם) דָּא קוּדְשָׁא בְּרִיךְ הוּא דְאִתְפָּרַשׁ מִינָהּ,</p>\n<p>דִּשְׁכִינְתָּא אִתְקְרִיאַת מִצְוַת עֲשֵׂה מִסִּטְרָא דִימִינָא, וּמִצְוַת לֹא תַעֲשֶׂה מִסִּטְרָא דִשְׂמָאלָא, וְתוֹרָה אִתְקְרִיאַת מִסִּטְרָא דְעַמּוּדָא דְאֶמְצָעִיתָא, וְכָל מָאן דְּגָזִיל אוֹ עָשַׁק בְּאוֹרַיְיתָא, וּבְמִצְוַת עֲשֵׂה וְלֹא תַעֲשֶׂה, כְּאִלּוּ גָזַל שְׁכִינְתָּא מִדְּרוֹעוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>וְכֵן מִסִּטְרָא דִיְסוֹד חַ\"י עָלְמִין, אִתְקְרִיאַת מִצְוַת בְּרִית מִילָה, מָאן דְּגָזַל בִּבְרִית וְאַפִּיק זַרְעָא מִינֵיהּ לִרְשׁוּ נוּכְרָאָה, כְּאִלּוּ אַפִּיק מֵרְשׁוּת הַיָּחִיד לִרְשׁוּת הָרַבִּים, וְגָרַם לְמֶהֱוִי שְׁכִינְתָּא נָפְקָא מֵאַתְרָהּ דְאִיהִי אֶרֶץ יִשְׂרָאֵל רְשׁוּת הַיָּחִיד, וְגָלָה אוֹתָהּ בֵּין אוּמִין דְּעָלְמָא דְאִינוּן רְשׁוּת הָרַבִּים,</p>\n<p>הֲדָא הוּא דִכְתִיב (ישעיה נ יא) וּבְפִשְׁעִיכֶם שֻׁלְּחָה אִמְּכֶם, וּבְגִין דָּא לֹא תִשָּׂא אֶת שֵׁם יהו\"ה אלהי\"ך לַשָּׁוְא (שמות כ ז), מָאן שֵׁם יהו\"ה דָּא שְׁכִינְתָּא, לַשָּׁוְא דָּא עֲבוֹדָה זָרָה דְּגָלַת תַּמָּן.</p>\n<p>וְעוֹד אִיהִי תְּשׁוּבָה יוֹם הַכִּפּוּרִים, כְּלִילָא מֵעֲשֶׂרֶת יְמֵי תְּשׁוּבָה דְאִינוּן י\"ה, יוֹם הַכִּפּוּרִים דָּא ה' כְּלִילָא מֵחָמֵשׁ צְלוֹתִין, עֲשֶׂרֶת יְמֵי תְּשׁוּבָה דָא י', לְקַבֵּל שָׁבִים דָּא ו\"ה, כָּל מָאן דְּחָזַר בִּתְיוּבְתָּא כְּאִלּוּ חָזַר ו\"ה עִם י\"ה,</p>\n<p>וְעִקָּרָא לְסָלְקָא כֹלָּא בְּמַחֲשָׁבָה דְאִיהִי יו\"ד ה\"א וא\"ו ה\"א.</p>\n<p>וּגְבוּרָה תַמָּן סמא\"ל דְּאִיהוּ יֵצֶר הָרָע, וְכָל מָאן דְּיִתְגַבֵּר עַל יִצְרֵיהּ כְּאִלּוּ הֲוָה מִתְגַבֵּר גְּבוּרָה עַל סמא\"ל בְּדִינָא לְגַבֵּי בְּנוֹי, וּבְגִין דָּא אָמְרוּ מָארֵי מַתְנִיתִין, אֵיזֶהוּ גִבּוֹר הַכּוֹבֵשׁ אֶת יִצְרוֹ,</p>\n<p>מַאי הַכּוֹבֵשׁ, כְּמָה דְאַתְּ אָמַר (בראשית א כח) וְכִבְשׁוּהָ, דִּיְהֵא כְּבוּשָׁה תְּחוֹת יְדֵיהּ, כְּכַלְבָּא דְאִיהוּ כָּבוּשׁ וְקָשׁוּר תְּחוֹת יְדֵי דְבַר נַשׁ.</p>\n<p>וְצָרִיךְ בַּר נַשׁ לְקַבְּלָא עֲלֵיהּ חָמֵשׁ עִנּוּיִין, בְּגִין עִנּוּי דְּגָרִים לְה' זְעִירָא דְגָלַת בְּגָלוּתָא, וְאִתְקְרִיאַת עֲנִיָּה סוֹעֲרָה לֹא נוּחָמָה, וְאַבָּא וְאִמָּא אִינוּן נָחְתֵי בִימִינָא וּשְׂמָאלָא, לְקַבְּלָא בְּהוֹן ו\"ה, דְּאִינוּן תּוֹרָה וּמִצְוָה,</p>\n<p>וְרָזָא דְמִלָּה וָשָׁב וְרָפָא לוֹ (ישעיה ו י), וְדָא אִיהוּ שׁוּבָה יִשְׂרָאֵל עַד יהו\"ה אלהי\"ך (הושע יד ב).</p>\n<p>וְעוֹד מִצְוַת פִּרְיָה וְרִבְיָה דָא שְׁכִינְתָּא, לֹא תֹהוּ בְרָאָהּ לָשֶׁבֶת יְצָרָהּ (ישעיה מה יח), כָּל תַּלְמִיד חָכָם דְּמָנַע מִינָהּ עוֹנַת קְרִיאַת שְׁמַע כְּאִלּוּ מָנַע מִינָהּ בִּרְכָאָן מִלְּעִילָא.</p>\n<p>שִׁית סִטְרִין אִינוּן דִּכְלִילָן בְּאָת ו', דְּאִיהוּ (בראשית א יא) עִץ פְּרִי עוֹשֶׂה פְּרִי, מָאן פְּרִי דִילֵיהּ י', דְּאָת ו' אִיהוּ עַנְפָא דְאִילָנָא, דְאִתְפָּרַשׁ לְשִׁית עַנְפִין, וּמִשִּׁית לְעַנְפִין דְּלֵית לוֹן חוּשְׁבַּן, י' אִיהִי אִיבָּא עַל כָּל עַנְפָא וְעַנְפָא דְאִיהוּ ו'.</p>\n<p>קָם סָבָא וְאָמַר רַבִּי רַבִּי חֲזוֹר בָּךְ, אִילָנָא הוּא ו', אִיבָּא דִילֵיהּ י' הָכִי הוּא וַדַּאי, אֲבָל עַנְפוֹי לְעִילָא אִיהוּ ה' עִלָּאָה וְשָׁרְשׁוֹי ה' תַּתָּאָה, וּמָאן דְּאַפְרִישׁ עַנְפָא מִינֵיהּ דָּא אִיהוּ מְקַצֵּץ בִּנְטִיעוֹת, וְהָכִי אִתְקַצַּץ אִיהוּ מֵעָלְמָא דֵין וּמֵעָלְמָא דְאָתֵי.</p>\n<p>וְעוֹד מִצְוָה לְאִתְעַסְקָא בְּאוֹרַיְיתָא יוֹמָם וָלַיְלָה, הֲדָא הוּא דִכְתִיב (יהושע א ח) וְהָגִיתָ בּוֹ יוֹמָם וָלַיְלָה, וְכִי יָכִיל בַּר נַשׁ לְאִתְעַסְקָא בְּאוֹרַיְיתָא בְּכָל יוֹמֵי וְלֵילֵי כָּל יוֹמוֹי, וְהָא קוּדְשָׁא בְּרִיךְ הוּא לֵית בָּא בִּטְרוּנְיָא עִם בִּרְיוֹתָיו, אֶלָּא כָּל מָאן דְּקָרָא קְרִיאַת שְׁמַע בְּכָל יוֹם עִִרֶב וָבֹקֶר, כְּאִלּוּ מְקַיֵּים בּוֹ וְהָגִיתָ בּוֹ יוֹמָם וָלַיְלָה,</p>\n<p>כָּל פִּקּוּדִין אִית מִנַּיְיהוּ דְתַלְיָין בִּפְרִי אִילָנָא, מִנַּיְיהוּ בְעַנְפִין, מִנְּהוֹן בְּשָׁרְשִׁין, מִנְּהוֹן בְּאִילָנָא, וּבְגִין דָּא אִתְקְרִיאַת אוֹרַיְיתָא עִץ חַיִּים, וְכָל מָאן דְּאָכַל מִנֵּיהּ וְאָכַל וָחַי לְעוֹלָם.</p>\n<p>וְאִית אִילָנָא לְתַתָּא, דְעַנְפּוֹי וְשָׁרְשׁוֹי וְגוּפָא וְאִיבָּא דִילֵיהּ, כֻּלְּהוּ סַם הַמָּוְת וְדָא סמא\"ל, מָאן דְּאַעֲבַר עַל אוֹרַיְיתָא, אִתְשַׁקְיָיא מֵהַהוּא אִילָנָא וְאִתְפַּרְנֵס מִינֵיהּ, וַעֲלֵיהּ אִתְּמַר (בראשית ב יז) כִּי בְּיוֹם אֲכָלְךָ מִמֶּנּוּ מוֹת תָּמוּת, וּמִסִּטְרָא דִילֵיהּ חַיֵּי צַעַר.</p>\n<p>וְעוֹד שְׁכִינְתָּא אִיהִי מִצְוַת הַעֲמָדַת מַלְכָּא, הֲדָא הוּא דִכְתִיב (דברים יז טו) שׂוֹם תָּשִׂים עָלֶיךָ מֶלֶךְ, וְכַבְיָכוֹל כָּל זִמְנָא דְלֵית שְׁכִינְתָּא בְּאַתְרָהָא לֵית מַלְכָּא, וּבְגִין דִּשְׁכִינְתָּא אִיהִי מַלְכוּת עַל בַּר נַשׁ, אִתְּמַר בֵּיהּ שׂוֹם תָּשִׂים עָלֶיךָ מֶלֶךְ, לְמֶהֱוִי יִשְׂרָאֵל בָּהּ כֻּלְּהוּ בְּנֵי מְלָכִים.</p>"],[9500011120,"<p>דְּלֵית מֶלֶךְ בְּלָא מַלְכוּת, דִּבְגָלוּתָא שִׁפְחָה תִּירַשׁ גְּבִירְתָּהּ,</p>\n<p>וּבְזִמְנָא דְיֵיתֵי מְשִׁיחָא אִתְּמַר (אסתר א יט) וּמַלְכוּתָהּ יִתֵּן הַמֶּלֶךְ לִרְעוּתָהּ הַטּוֹבָה מִמֶּנָּה, אִיהִי מַלְכוּתֵיהּ, אִיהִי כָרְסְיֵיהּ, אִיהִי עֲטֶרֶת דִילֵיהּ,</p>\n<p>לְמַלְכָּא דְּאִית לֵיהּ מָאנָא דִיקָר וְאִיהִי מְחַבְּבָא לְגַבֵּיהּ, לְזִמְנִין שַׁוִּי לֵיהּ עֲטָרָה עַל רֵישֵׁיהּ דָּא תְּפִלִּין דְּרֵישָׁא, לְזִמְנִין קָשִׁיר לֵיהּ בְּאֶצְבְּעָא וְדָא תְּפִלִּין דְּיָד, לְזִמְנִין שַׁוִּי לֵיהּ תְּחוֹתֵיהּ וְאִתְקְרֵי כָּרְסַיָּא דִילֵיהּ, לְזִמְנִין עָבִיד מִינָהּ לְבוּשָׁא.</p>\n<p>וּכְעַן דְּאִיהִי מְרַחֲקָא מִן מַלְכָּא, אִתְּמַר בְּמַלְכָּא (ישעיה נ ג) אַלְבִּישׁ שָׁמַיִם קַדְרוּת, וּשְׁכִינְתָּא אָמְרַת אַל תִּרְאוּנִי שֶׁאֲנִי שְׁחַרְחֹרֶת (שיר א ו),</p>\n<p>וּבְנֵי נָשָׁא דְאִינוּן שַׁטְיָין מִסְתַּכְּלִין בִּלְבוּשָׁא, וְאָחֳרָנִין הָכִי מִסְתַּכְּלִין בְּגוּפָא, וּבְגָלוּתָא כֻלְּהוֹן שַׁטְיָין, אֲבָל פִּקְחָא חַכִּימָא אִסְתַּכַּל מִלְּגָאו,</p>\n<p>וְכַד יֵתֵי פּוּרְקָנָא אִתְפַּשַּׁט מִלְבוּשִׁין דְּקַדְרוּתָא, וְזָרִיק לוֹן עַל אוּמִין דְּעָלְמָא, הֲדָא הוּא דִכְתִיב (שמות י כב) וַיְהִי חֹשֶׁךְ אֲפֵלָה וְגוֹמֵר, וּלְכָל בְּנֵי יִשְׂרָאֵל הָיָה אוֹר בְּמוֹשְׁבוֹתָם.</p>\n<p>דִּבְהַהוּא זִמְנָא דְאִתְלַבַּשׁ בְּאִלֵּין לְבוּשִׁין, אִתְּמַר בֵּיהּ (דברים לב כ) וַיֹּאמֶר אַסְתִּירָה פָנַי מֵהֶם,</p>\n<p>לְבָתַר דְּאִתְפַּשַּׁט מִנַּיְיהוּ וַיִּירְאוּ הָעָם אֶת יהו\"ה (שמות יד לא), וְכָל יְנוּקִין אַחְזִין לֵיהּ בְּאֶצְבַּע, הֲדָא הוּא דִכְתִיב (שם טו ב) זֶה אֵלִי וְאַנְוִהוּ, וּבְגָלוּתָא יָשֶׁת חֹשֶׁךְ סִתְרוֹ (תהלים יח יב), וּבְגִין דָּא אָמַר דָּנִיֵּאל (דניאל ב כב), יָדַע מָה בַחֲשׁוֹכָא וּנְהוֹרָא עִמֵּיהּ שְׁרֵיהּ,</p>\n<p>וּבְהַהוּא זִמְנָא דְאִיהוּ בַּחֲשׁוֹכָא מִתְלַבֵּשׁ בְּתֹהוּ וָבֹהוּ וּבְחֹשֶׁךְ וּתְהוֹם, כַּבְיָכוֹל אַתְוָון אִינוּן בְּפִרוּדָא וְלָא מִתְיַחֲדִין תַּמָּן,</p>\n<p>וּלְבָתַר דְּנָפִיק מִנַּיְיהוּ, וְהָיָה יהו\"ה לְמֶלֶךְ עַל כָּל הָאָרֶץ בַּיּוֹם הַהוּא יִהְיֶה יהו\"ה אֶחָד וּשְׁמוֹ אֶחָד (זכריה יד ט).</p>\n<p>בְּהַהוּא זִמְנָא כָּל חֵיוָן יִתְעָרוּן בְּנִגּוּנָא, וְכַנְפֵיהֶם פְּרוּדוֹת מִלְּמָעִִלָה לְקַבְּלָא לֵיהּ בְּחֶדְוָה, וְכֻלְּהוֹן יְהוֹן רָצִין וְשָׁבִין בְּנִגּוּנָא, וּשְׁלִיחוּתָא לְגַבֵּיהּ, הֲדָא הוּא דִכְתִיב (יחזקאל א יד) וְהַחַיּוֹת רָצוֹא וָשׁוֹב כְּמַרְאֵה הַבָּזָק, לְבַשְּׂרָא לְיִשְׂרָאֵל,</p>\n<p>וּבְהַהוּא זִמְנָא הַלֲלוּ אֶת יהו\"ה מִן הָאָרֶץ תַּנִּינִים וְכָל תְּהוֹמוֹת וְגוֹמֵר (תהלים קמח ז), כֻּלְּהוּ לְעִילָא וּלְתַתָּא מַה דְּאִתְבְּרִי עַד יִתּוּשׁ זְעִירָא, כֻּלְּהוּ מְשַׁבְּחִין לֵיהּ, כִי מָלְאָה הָאָרֶץ דֵּעָה אֶת יהו\"ה כַּמַּיִם לַיָּם מְכַסִּים (ישעיה יא ט),</p>\n<p>בְּהַהוּא זִמְנָא יִתְקַיַּים קְרָא, (צפניה ג ט) כִּי אָז אֶהְפּוֹךְ אֶל עַמִּים שָׂפָה בְרוּרָה לִקְרֹא כֻלָּם בְּשֵׁם יהו\"ה וְגוֹמֵר.</p>\n<p>בְּהַהוּא זִמְנָא אִתְבְּנִי בֵּיתָא דִשְׁכִינְתָּא דְאִיהִי בֵּית הַבְּחִירָה עַל יְדָא דְקוּדְשָׁא בְּרִיךְ הוּא, דְאִתְּמַר בָּהּ (זכריה ב ט) וַאֲנִי אֶהְיֶה לָּהּ נְאֻם יהו\"ה חוֹמַת אֵשׁ סָבִיב,</p>\n<p>וַאֲנִי אֶבְנֶה אִינוּן אֲבָנִין טָבִין דְּאִתְבְּנִי מִינָהּ, הֲדָא הוּא דִכְתִיב (בראשית ל ג) וְאִבָּנֶה גַם אָנֹכִי מִמֶּנָּה, נְטִיעִין קַדִּישִׁין, הֲדָא הוּא דִכְתִיב (ישעיה ס כא) נֵצֶר מַטָּעַי מַעֲשֵׂה יָדַי לְהִתְפָּאֵר,</p>\n<p>וּבִנְיָינָא דְבֵי מַקְדְּשָׁא תְהֵא בְּנוּיָה מִכַּסְפָּא וְדַהֲבָא וְאַבְנִין יַקִּירִין, וּתְהֵא מְרַקְּמָא מִכָּל צִיּוּרָא דְּעוֹבָדָא דִבְּרֵאשִׁית, וַעֲלָהּ נַהֲרָא יְרוּשָׁלֵם דִּלְעִילָא, לְעִילָא מְרַקְּמָא מִכָּל מִינֵי גַוָּונִין דִּנְהוֹרָא,</p>\n<p>וְרָזָא דְמִלָּה יְרוּשָׁלַםִ הַבְּנוּיָה כְּעִיר שְׁחֻבְּרָה לָּהּ יַחְדָּיו (תהלים קכב ג), דְּאַנְהָרָא עַל גַּבּוֹי.</p>\n<p>בְּהַהוּא זִמְנָא אִתְקַיַּים בְּיִשְׂרָאֵל (ישעיה ס כ) לֹא יָבֹא עוֹד שִׁמְשֵׁךְ, וִירֵחֵךְ לֹא יֵאָסֵף וְגוֹמֵר, וְאִתְעַר שִׁיר הַשִּׁירִים בְּעָלְמָא, וְאַדְלִיק נְהוֹרָא עַל זֵיתָא וּשְׁרַגָּא, דְיִשְׂרָאֵל אִינוּן פְּתִילָה, אוֹרַיְיתָא מִשְׁחָא, שְׁכִינְתָּא שְׁרַגָּא, הֲדָא הוּא דִכְתִיב (איוב כט ג) בְּהִלּוֹ נֵרוֹ עֲלֵי רֹאשִׁי,</p>\n<p>בְּהַהוּא זִמְנָא אִתְּמַר בִּשְׁכִינְתָּא, וְחָלְצָה נַעֲלוֹ (דברים כח ט), נַעֲלוֹ דְקוּדְשָׁא בְּרִיךְ הוּא, לְקַיֵּים בֵּיהּ שַׁל נְעָלֶךָ (שמות ג ה), וְאִתְיַיחֵד בִּשְׁכִינְתֵּיהּ, דְּאִתְקְרִיאַת חֲלִיצָה, וְאִיהוּ חֲלוּץ הַנָּעַל,</p>\n<p>וְלָא צְרִיכִין לְאִתְחַבְּרָא בְאֹרַח יִבּוּם לְעוֹלָם, דְּאִתְּמַר בָּהּ (רות ד ז) וְזֹאת לְפָנִים בְּיִשְׂרָאֵל וְגוֹמֵר, שָׁלַף אִישׁ נַעֲלוֹ וְנָתַן לְרֵעִהוּ, מַאי נַעֲלוֹ דָא כִּנּוּ\"י, הַהוּא דְאִתְּמַר בֵּיהּ (שיר ד יב) גַּן נָעוּל,</p>\n<p>אִתְפַּתַּח הַהוּא נָעוּל מַפְתְּחָא, בְּגִין דְּלַפֶּתַח חַטָּאת רוֹבֵץ (בראשית ד ז), אִתְעַבַּר הַהוּא חַטָּאת וְאִתְפַּתַּח תַּרְעָא, הֲדָא הוּא דִכְתִיב (תהלים קיח כ) זֶה הַשַּׁעַר לַיהו\"ה, וְיֶחזוּן תַּמָּן שְׁכִינְתָּא, דְאִתְּמַר בָּהּ וְזֹאת לְפָנִים בְּיִשְׂרָאֵל.</p>\n<p>דָּבָר אַחֵר וְזֹאת לְפָנִים בְּיִשְׂרָאֵל עַל הַגְּאוּלָה וְעַל הַתְּמוּרָה, עַל הַגְּאוּלָה דָא שְׁכִינְתָּא עִלָּאָה ה' עִלָּאָה, וְעַל הַתְּמוּרָה דָא שְׁכִינְתָּא</p>"],[9500011121,"<p>תַּתָּאָה, דְאִיהִי תְּמוּרָה בְּהַהוּא דְאִתְּמַר בֵּיהּ אַל תְּמִירֵנִי בּוֹ, וְאִינוּן ה\"ה, וְזֹאת דָּא בֵן וּבַת, יִשְׂרָאֵל דָּא אָב,</p>\n<p>וּבְגִין דָּא לְתַתָּא אִיהוּ תְּמוּרוֹת אַתְוָון יהו\"ה בְּאדנ\"י, אֲבָל לְעָלְמָא דְאָתֵי לֵית תְּמוּרָה, כְּמָה דְאוּקְמוּהוּ מָארֵי מַתְנִיתִין לֹא כְּשֶׁאֲנִי נִכְתָּב אֲנִי נִקְרָא,</p>\n<p>בָעוֹלָם הַזֶּה נִכְתָּב בְּיהו\"ה וְנִקְרָא בְּאדנ\"י, וּבָעוֹלָם הַבָּא נִכְתָּב בְּיהו\"ה וְנִקְרָא בְּיהו\"ה.</p>\n<p>וְעוֹד שָׁלַף אִישׁ נַעֲלוֹ, דָּא גוּפָא דְאִיהִי אִתְּתָא כְּלִי דִילֵיהּ, וְדָא מטטרו\"ן, וְנָתַן לְרֵעִהוּ, דִּלְזִמְנִין אִשְׁתַּכַּח בֵּיהּ עַמּוּדָא דְאֶמְצָעִיתָא, וּלְזִמְנִין צַדִּיק, וּלְזִמְנִין שְׁכִינְתָּא עִלָּאָה אִיהִי תְעוּדָה בֵּיהּ, וּלְזִמְנִין שְׁכִינְתָּא תַּתָּאָה הִיא תְּמוּרָה בֵּיהּ,</p>\n<p>וְדָא אִיהוּ גַּן נָעוּל, וּבֵיהּ מַעִִיָן חָתוּם, דְּאִיהִי שְׁכִינְתָּא, י' כְּלִילָא מֵעִִשֶׂר סְפִירָן, י' מִן מיטטרו\"ן.</p>\n<p>כָּל סְפִירָן פּוֹעֲלִים בֵּיהּ בְּהַאי עָלְמָא שְׁפָלָה, וּבֵיהּ יִבּוּם וַחֲלִיצָה וְגֵט פִּטּוּרִין,</p>\n<p>וְכָל אַתְוָון בֵּיהּ אִינוּן תְּמוּרֹת, כְּגוֹן מצפ\"ץ, וְאִיהוּ נְעִילַת חַגִּין וְזִמְנִין וְיוֹמִין טָבִין, נְעִילַת דֶּלֶת בִּפְנֵי לווִֹין,</p>\n<p>בַּיּוֹם הַכִּפּוּרִים דְּאִיהִי עָלְמָא דְאָתֵי, לָא אִתְקְרֵי יהו\"ה בְּאדנ\"י דְּאִיהִי דִין, וְאִיהוּ נַעַל, נְעִילַת דֶּלֶת, וְאֵינוֹ נוֹעִל הַדֶּלֶת, אֶלָּא אִיהִי פְּתִיחָא לְקַבֵּל שָׁבִים,</p>\n<p>וּבְגִין דָּא יוֹם הַכִּפּוּרִים אָסוּר בִּנְעִילַת הַסַּנְדָּל, דְּלֵית יִחוּדָא בֵּיהּ לְקוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתָּא, דִּלְזִמְנִין אִיהִי שְׁכִינְתָּא, וְאִסְתַּלַּק קוּדְשָׁא בְּרִיךְ הוּא, וּלְזִמְנִין קוּדְשָׁא בְּרִיךְ הוּא, וְאִסְתַּלַּק שְׁכִינְתָּא.</p>\n<p>וּבְגִין דָּא עוֹנַת תַּלְמִידֵי חֲכָמִים בְּשַׁבָּת, דִּבְיוֹמִין דְּחוֹל דְּשַׁלִּיט מטטרו\"ן אִתְּמַר (יחזקאל מד ב) יִהְיֶה סָגוּר שֵׁשֶׁת יְמֵי הַמַּעֲשֶׂה, בֵּיהּ אִיהִי סְגִירָא תַרְעָא, וּבְיוֹם הַשַּׁבָּת יִפָּתֵחַ, יִפָּתֵחַ תַּרְעָא, וְתַפִּיק מִינָהּ שְׁכִינְתָּא לְאִתְיַיחֲדָא עִם בַּעִִלָהּ,</p>\n<p>וּבְהַהוּא זִמְנָא אִתְקְרִיאַת כּוֹס מָלֵא, הֲדָא הוּא דִכְתִיב (דברים לג כג) וּמָלֵא בִּרְכַּת יהו\"ה יָם וְדָרוֹם יְרָשָׁה, דִּבְיוֹמִין דְּחוֹל אִתְקְרִיאַת יַבָּשָׁה בְּמטטרו\"ן, הֲדָא הוּא דִכְתִיב (בראשית א ט) וַיֹּאמֶר אלהי\"ם יִקָּווּ הַמַּיִם מִתַּחַת הַשָּׁמַיִם אֶל מָקוֹם אֶחָד וְתֵרָאֶה הַיַּבָּשָׁה.</p>\n<p>וּבְזִמְנָא דְאִתְמְלִיאַת אִתְּמַר עֲלָהּ (תהלים קטז יג) כּוֹס יְשׁוּעוֹת אֶשָּׂא וּבְשֵׁם יהו\"ה אֶקְרָא, כּוֹ\"ס אִיהִי אלהי\"ם בְּחֻשְׁבַּן, דְּסָלִיק לְחֻשְׁבַּן כִּנּוּ\"י, בְּמַאי אִתְמְלִיאַת בְּאָת י', וְאִתְעֲבִידַת כּוֹסִי רְוָיָה, וּבְגִין דָּא כּוֹס צָרִיךְ עֲשָׂרָה דְבָרִים וכו'.</p>\n<p>קָם רַבִּי שִׁמְעוֹן וְאָמַר, אִם תַּחֲנֶה עָלַי מַחֲנֶה לֹא יִירָא לִבִּי, אִם תָּקוּם עָלַי מִלְחָמָה בְּזֹאת אֲנִי בוֹטֵחַ (תהלים כז ג), בְּזֹאת בְּוַדַּאי אֲנָא בָּעִינָא לְאִתְתַּקְּפָא, בְּהַאי קְרָא דְּדָוִד,</p>\n<p>קוּם דָּוִד הָא זֹאת דִּילָךְ לְגַבָּן,</p>\n<p>אַהֲרֹן כַּהֲנָא קוּם מִשִּׁנְּתָךְ הָא זֹאת דִּילָךְ לְגַבָּן, דְּאִתְּמַר בָּהּ (ויקרא טז ג) בְּזֹאת יָבֹא אַהֲרֹן אֶל הַקֹּדֶשׁ,</p>\n<p>קוּם רַעִִיָא מְהֵימְנָא לְאַגָּנָא עַל זֹאת דִּילָךְ, דְּאִתְּמַר בָּהּ (דברים ד מד) וְזֹאת הַתּוֹרָה אֲשֶׁר שָׂם מֹשֶׁה, דְהָא כַּמָּה מָארֵי מַגִּיחֵי קְרָבָא קָא אַתְיָין לְאַגָּחָא עֲלָהּ,</p>\n<p>קוּמוּ נְבִיאֵי קְשׁוֹט דְּהָא זֹאת דִּילְכוֹן לְגַבָּן, דְּקָא הֲוִיתוּן מִתְנַבְּאִין, עֲלָהּ אִתְּמַר (ירמיה ט כב) אַל יִתְהַלֵּל חָכָם בְּחָכְמָתוֹ וְאַל יִתְהַלֵּל הַגִּבּוֹר בִּגְבוּרָתוֹ וְגוֹמֵר כִּי אִם בְּזֹאת, זֹאת אָשִׁיב אֶל לִבִּי עַל כֵּן אוֹחִיל לוֹ (איכה ג כא).</p>\n<p>קוּמוּ אֲבָהָן מָארֵי דִבְרִית, דְּהָא זֹאת הַבְּרִית דִּלְכוֹן בֵּינָנָא, דְאִתְּמַר בָּהּ (ויקרא כו מד) וְאַף גַּם זֹאת בִּהְיוֹתָם בְּאֶרֶץ אוֹיְבֵיהֶם וְגוֹמֵר, וּבְגִינָהּ אָמַר קוּדְשָׁא בְּרִיךְ הוּא (שם יב) וְזָכַרְתִּי אֶת בְּרִיתִי יַעֲקוֹב,</p>\n<p>קוּם שְׁלֹמֹה מַלְכָּא דְאַנְתְּ שְׁלָם דִּילָהּ,</p>\n<p>קוּמוּ לְמֶהֱוִי עִזֶר לְגַבָּהּ בְּהַאי קְרָבָא,</p>\n<p>נַעַר נַעַר דְּאַנְתְּ מָארֵי מַפְתְּחָן דְּאוֹצְרִין דְּמַלְכָּא, דְכָל מָאנֵי קְרָבָא דְמַלְכָּא בְּהוֹן, קוּם אַפְתַּח הֵיכָלָא, אדנ\"י שְׂפָתַי תִּפְתָּח, וּפִי יַגִּיד שְׁבָחוֹי דְּמַלְכָּא עִלָּאָה, דְּהָא הֵיכָלָא (עלאה) דִילֵיהּ אִיהוּ, טוֹל רְשׁוּ וְאַפְתַּח הֵיכָלָא בְּגִין יְקָרָא דִשְׁכִינְתָּא.</p>\n<p>פָּתַח וְאָמַר זַרְקָ\"א מַקַּ\"ף שׁוֹפָ\"ר הוֹלֵ\"ךְ סֶגוֹלְתָּ\"א,</p>\n<p>אַדְהָכִי הָא עוּלֵימָא קָא נָחִית (רעיא מהימנא פתח רבי שמעון) וְאָמַר, רַעִִיָא מְהֵימְנָא אַנְתְּ אִיהוּ מָארֵי דְקִירְטָא, דְּרַעִִיָא דְאָזִיל בְּעָאנָא, בְּגִין דּוּבִּין זְאֵבִין וְחֵיוָון בִּישִׁין דְּקָא אַתְיָין לְמֵיכַל עָאנָא.</p>"],[9500011122,"<p>אָרְחָא דִילֵיהּ לְמֶהֱוִי קִירְטָא בַהֲדֵיהּ לְזַרְקָא אַבְנִין לְגַבַּיְיהוּ, לְמֶהֱוֵי עָאנָא נְטִיר מֵחֵיוָן בִּישָׁן קוּם נָטִיל קִירְטָא בִּידָךְ,</p>\n<p>פָּתַח וְאָמַר זַרְקָ\"א, שְׁכִינְתָּא קַדִּישָׁא, אַנְתְּ הוּא קִירְטָא קַדִּישָׁא דְקוּדְשָׁא בְּרִיךְ הוּא דְבָּךְ, אִזְדַּרִיקוּ תְּלַת אַבְנִין דְּאִינוּן סֶגוֹלְתָּ\"א, תְּלַת אַבְנִין יַקִּירִין דְּאִינוּן תְּלַת אֲבָהָן, וְאַנְתְּ אֶבֶן יְקָרָא עַל כֻּלְּהוּ, תַּגָּא בְרֵישָׁא דְכֻלְּהוּ, עֲלָךְ אִתְּמַר (תהלים קיח כב) אֶבֶן מָאֲסוּ הַבּוֹנִים הָיְתָה לְרֹאשׁ פִּנָּה,</p>\n<p>וְהָאֶבֶן הַזֹּאת אֲשֶׁר שַׂמְתִּי מַצֵּבָה יִהְיֶה בֵּית אלהי\"ם (בראשית כח כב), אַנְתְּ הוּא דְאִתְּמַר עֲלָךְ (דניאל ב לה) אַבְנָא דִי מְחָת לְצַלְמָא וַהֲוַת לְטוּר רַב וּמְלָאת כָּל אַרְעָא. וְאִיהִי תַּגָּא כְּגַוְונָא דָא ם בְּרֵישָׁא דְחוּטָא דְזַרְקָ\"א, אַבְנָא כְּלִילָא וּמִתְעַטְּרָא (נ\"א מוכללת ומעוטרת) כְּאַבְנָא בְרֵישׁ עִזְקָא,</p>\n<p>וְכַד אִית בְּיִשְׂרָאֵל מַשְׂכִּילִים בְּחָכְמָה דְאִיהִי י' מַחֲשָׁבָה עִלָּאָה, יָדְעִין לְזָרְקָא לָהּ לְהַאי אַבְנָא דְאִיהִי בַּת יְחִידָה, לְהַהוּא אֲתַר דְּאִתְגְּזֶרֶת, בְּגִין דִּבְרַתָּא בְּאַבָּא אִתְעֲבִידַת, הֲדָא הוּא דִכְתִיב (משלי ג יט) יהו\"ה בְּחָכְמָה יָסַד אָרֶץ, בְּחָכְמָה דְאִיהוּ אַבָּא יָסַד בְּרַתָּא דְאִיהִי אָרֶץ הֲדוֹם רַגְלָיו.</p>\n<p>וְהַהוּא חוּט דִּילָהּ אִיהוּ ו', דְּאַבְנָא דְאִיהִי תַּגָּא עֲטָרָה עַל רֵישֵׁיהּ, עֲטָרָה דְסֵפֶר תּוֹרָה, וּבְגִינָהּ אִתְּמַר וּדְאִשְׁתַּמֵּשׁ בְּתַגָּא חֲלָף, אִיהוּ כֶּתֶר תּוֹרָה וַדַּאי, דִּתְלַת כִּתְרִין אִינוּן, כֶּתֶר תּוֹרָה וְכֶתֶר כְּהוּנָה וְכֶתֶר מַלְכוּת, וְכֶתֶר תּוֹרָה (נ\"א וכתר שם טוב) עַל גַּבַּיְיהוּ,</p>\n<p>וְהַאי אַבְנָא אִיהִי י' בְּרֵישׁ א, וְאִיהִי י' בְּסוֹפָה, עֲלָהּ אִתְּמַר (ישעיה מו י) מַגִּיד מֵרֵאשִׁית אַחֲרִית, וְאִיהִי (נ\"א ואיהו) יו\"ד ה\"א וא\"ו ה\"א (נ\"א יו\"ד ה\"י וא\"ו ה\"י), כְּלִיל עֲשַׂר סְפִירָן, דְּאִינוּן (ס\"א דאיהו) נָעוּץ סוֹפָן בִּתְחִלָּתָן וּתְחִלָּתָן בְּסוֹפָן.</p>\n<p>קָמוּ כֻּלְּהוּ מָארֵי מְתִיבְתָּא וְאָמְרוּ, רַעִִיָא מְהֵימְנָא כַּמָּה אַנְתְּ תַּקִּיף לְזַרְקָא אַבְנָא, דְּהָא מָטָא לַאֲתַר דְּלֵית מָאן דְּיָדַע אַתְרָהָא, וּמַלְאָכִין קַדִּישִׁין שָׁאֲלִין בְּגִינָהָא אַיֵּה מְקוֹם כְּבוֹדוֹ לְהַעֲרִיצוֹ, דְלֵית מָאן דְּיָדַע מְקוֹמוֹ, כַּד סָלְקָא לְעִילָא בַּאֲתַר דִּזְרִיקַת לָהּ, עַד דְּאָמְרִין כֻּלְּהוּ (יחזקאל ג יב) בָּרוּךְ כְּבוֹד יהו\"ה מִמְּקוֹמוֹ, וְאַף עַל גַּב דְּאִיהִי זְעִירָא לְתַתָּא, לְעִילָא לֵית לָהּ סוֹף.</p>\n<p>מָאן יָכִיל לְאַגָּחָא קְרָבָא בַאֲתַר דְּאַנְתְּ תַּמָּן, בְּאַבְנָא זְעִירָא דִזְרִיקַת אִזְדַּעִִזַעוּ רְקִיעִין עַד אֵין סוֹף, וּמַלְאָכִין עַד אֵין תַּכְלִית,</p>\n<p>וְכָל מָארֵי מְתִיבְתָּא כֻּלְּהוּ אִזְדַּעִִזַעוּ וְנָפְלוּ בִּנְפִילַת אַפַּיִם, מִקִּיּוּמַיְהוּ קֳדָמָהָא, וְאָמְרוּ וְכִי בְאַבְנָא זְעִירָא הַאי, כָּל שֶׁכֵּן מָאן יַגִּיחַ עִמָּךְ בְּסַיְיפָא, דְאִתְּמַר בָּהּ (תהלים קמט ו) רוֹמְמוֹת אֵ\"ל בִּגְרוֹנָם וְחֶרֶב פִּיפִיּוֹת בְּיָדָם, דְּאִיהִי קְרִיאַת שְׁמַע, חַרְבָּא דִילָךְ דְּאַנְתְּ תַּקִּינַת לָךְ (נ\"א לה), דְּבָהּ קְטִילַת לַמִּצְרִי, הֲדָא הוּא דִכְתִיב (שמות ב יב) וַיִּפֶן כֹּה וָכֹה וְגוֹמֵר וַיַּךְ אֶת הַמִּצְרִי, כֹּ\"ה וָכֹ\"ה סָלְקִין לְחַמְשִׁין אַתְוָון, דִּמְיַחֲדִין בְּהוֹן לְקוּדְשָׁא בְּרִיךְ הוּא פַּעֲמַיִם, שְׁמַע יִשְׂרָאֵל יהו\"ה אלהינ\"ו יהו\"ה אֶחָד, דְּאִית בְּהוֹן כ\"ה אַתְוָון תְּרֵין זִמְנִין, וְסָלְקִין לְחַמְשִׁין תַּרְעִין דְּבִינָה, דְּאִיהִי ח' תְּמִינָאָה מֵעֲשַׂר סְפִירָן מִתַּתָּאָה וּלְעִילָא.</p>\n<p>י' רֵישָׁא דְחַרְבָּא, ו' גּוּפָא דְחַרְבָּא, תְּרֵין פִּפִיּוֹת דִּילָהּ ה\"ה, נַרְתְּקָא דְחַרְבָּא אהי\"ה, וְהָכִי לְתַתָּא נַרְתְּקָא דְהַאי חַרְבָּא אדנ\"י, וְאִיהוּ יאהדונה\"י לְתַתָּא, יאההויה\"ה לְעִילָא, (נ\"א יה\"ו הה\"ו יה\"ה),</p>\n<p>וְרָזָא דְמִלָּה (שמות טו א) אָז יָשִׁיר מֹשֶׁה תְּמַנְיָא אַתְוָון בְּחִיבּוּרָא לְעִילָא, (ישעיה נח ט) אָ\"ז תִּקְרָא וַיהו\"ה יַעֲנֶה לְתַתָּא,</p>\n<p>וּמָאן יָכִיל בְּרוּמְחָא דִילָךְ דְּאִיהוּ רְמַ\"ח תֵּיבִין דִּקְרִיאַת שְׁמַע, אַגַּח קְרָבָא לְרַבִּי שִׁמְעוֹן וְחַבְרוֹי, נֶחזֵי מַאי נִיהוּ חֵילָא וּתְקִיפוּ דִילֵיהּ, דְּהָא אִיהוּ אַתְעַר עִלָּאִין וְתַתָּאִין, וְיִזְדַּעִִזַעוּ כָּל עָלְמִין עִלָּאִין וְתַתָּאִין וּבְאוּמָאָה לְכָל חֲיָילִין לְעִילָא וְתַתָּא לְמֶהֱוִי בְּעָזְרֵיהּ, אַגַּח לֵיהּ.</p>\n<p>קוּם רַבִּי שִׁמְעוֹן זָרֵיז גַּרְמָךְ בְּמָאנֵי קְרָבָא דִילָךְ, נֶחזֵי מַאי תַּקִּיפוּ וּגְבוּרָה דִילָךְ.</p>\n<p>קָם רַבִּי שִׁמְעוֹן פָּתַח וְאָמַר, זַרְקָ\"א מַקַּ\"ף שׁוֹפָ\"ר הוֹלֵ\"ךְ סֶגוֹלְתָּ\"א, קָם וְנָטִיל תְּלַת אַבְנִין דְּאִינוּן י י י', וְאַבְנָא עִלָּאָה דְאִיהִי בְּקִירְטָא, תַגָּא בְּחוּטָא הָא אַרְבַּע, דְּאִנּוּן אַרְבְּעִין, וְחוּט דְּסִיהֲרָא (נ\"א דסחרא) עֲלָהּ הַיְינוּ בּ',</p>\n<p>וְרָזָא דְמִלָּה בְּרֵאשִׁית בּ' רֵאשִׁית, הַאי נְקוּדָה</p>"],[9500011123,"<p>עֲלָהּ אִתְּמַר בַּעֲשָׂרָה מַאֲמָרוֹת נִבְרָא הָעוֹלָם</p>\n<p>מַאי בּ' הַהוּא חוּט דְּאַסְחַר עֲלָהּ, וְהַאי נְקוּדָה אִית לָהּ רֵישָׁא וְאֶמְצָעִיתָא וְסוֹפָא, וְאִתְעֲבִידַת תְּלַת יוּדִי\"ן י י י', דְסָלְקִין לִתְלָתִין, וְהַהוּא חוּט ב' תְּלָתִין וּתְרֵין,</p>\n<p>תַּגָּא דְעַל חוּט י', וְהָא אַרְבְּעִין וּתְרֵין, לָקֳבֵל ל\"ב אלהי\"ם, וַעֲשַׂר אֲמִירָן דְּאִתְבְּרִי בְּהוֹן שְׁמַיָּא וְאַרְעָא וְכָל חֵילֵיהוֹן, (וירא אלהי\"ם את כל אשר עשה, דאיהו רזא וירא מלאך יהו\"ה אליו בלבת אש, בלבת דאורייתא ודא איהו כי יום נקם בלב\"י, ובהון פועלים ארבעין ותרין אתוון דיהו\"ה, ורזא דמלה פתחו לי שערי צדק אב\"א ב\"ם אודה י\"ה, וכלהון אתכלילן בבאר שבע, דא אב\"ג ית\"ץ וחברוי).</p>\n<p>אָמְרוּ לֵיהּ מָארֵי מַתְנִיתִין, רַבִּי רַבִּי כַּמָּה תַּקִּיפִין אַבְנִין דִּזְרִיקַת, דְּאִזְדַּעִִזְעוּ בְּהוֹן שְׁמַיָּא וְאַרְעָא, וְחֵיוָון וּבְעִירָן וְעוֹפִין כֻּלְּהוּ בָּרְחוּ, וּמִנְּהוֹן נָפְלוּ לְאַרְעָא, וְכָרְסַיָּיא יַקִּירָא וּמַלְאָכִין וְאוֹפַנִּים כֻּלְּהוּ אִזְדַּעִִזַעוּ מֵאַבְנִין דִּילָךְ, וְאִלֵּין אִינוּן אַרְבָּעָה טוּרֵי אָבֶן, דְּכֻלְּהוּ חָד.</p>\n<p>זַכָּאָה אִיהוּ מָאן דְּאַפִּיק אַבְנִין אִלֵּין שְׁלֵמִין בִּצְלוֹתֵיהּ, בְּאַרְבַּע צְלוֹתִין עִם צְלוֹתָא דְמוּסָף, דַּעֲלַיְיהוּ אִתְּמַר (דברים כו ו) אֲבָנִים שְׁלֵמוֹת תִּבְנֶה,</p>\n<p>וְאִית אֶבֶן דְּאוֹרַיְיתָא, דְאִתְּמַר בָּהּ (בראשית כח כב) וְהָאֶבֶן הַזֹּאת אֲשֶׁר שַׂמְתִּי מַצֵּבָה יִהְיֶה בֵּית אלהי\"ם, דְּאִיהִי מִסִּטְרָא דְעַמּוּדָא דְאֶמְצָעִיתָא, דְאִתְּמַר בֵּיהּ (דברים ד מד) וְזֹאת הַתּוֹרָה אֲשֶׁר שָׂם מֹשֶׁה, דְאִיהוּ דִיּוֹקְנָא דִילֵיהּ.</p>\n<p>וְאִלֵּין אַבְנִין כֻּלְּהוּ חָד, מַלְכוּת קַדִּישָׁא אִיהִי מִסִּטְרָא דִשְׂמָאלָא, אִתְּמַר בָּהּ (שם כה א) אֶבֶן שְׁלֵמָה וָצֶדֶק יִהְיֶה לָּךְ, וְהַאי אִיהִי (דניאל ב לה) אַבְנָא דִי מְחָת לְצַלְמָא דַהֲוַת לְטוּר רַב וּמְלָאת כָּל אַרְעָא, מַאי וּמְלָאת כָּל אַרְעָא, אֶלָּא בְּגִינָהּ אִתְּמַר (ישעיה ו ג) מְלֹא כָל הָאָרֶץ כְּבוֹדוֹ,</p>\n<p>וַעֲלָהּ אִתְּמַר (זכריה ג ט) עַל אֶבֶן אַחַת שִׁבְעָה עִינָיִם, דְּאִינוּן שִׁבְעָה רוֹעִין קַדִּישִׁין, וְאִינוּן שֶׁבַע דְּכוּרִין וְשֶׁבַע נוּקְבִין, כֻּלְּהוּ כְּלִילָן בָּהּ וְרָזָא דְמִלָּה שִׁבְעָה וְשִׁבְעָה מוּצָקוֹת.</p>\n<p>וְהַאי אֶבֶן אִיהִי חֲמִשָּׁה אַבְנִין דְּשַׁוִּי דָוִד בְּקִירְטָא וְאִתְעֲבִידוּ כֻּלְּהוּ חָד, הֲדָא הוּא דִכְתִיב (שמואל א ו יז) וַיִּקַּח דָּוִד חֲמִשָּׁה חֲלוּקֵי אֲבָנִים מִן הַנַּחַל, וְאִינוּן גְּדוּלָה גְבוּרָה תִּפְאֶרֶת נֶצַח הוֹד, דִּבְהוֹן שַׁבַּח דָּוִד לְקוּדְשָׁא בְּרִיךְ הוּא וְאָמַר (דה\"י א כט) לְךָ יהו\"ה הַגְּדוּלָה וְהַגְּבוּרָה וְגוֹמֵר,</p>\n<p>וְאִלֵּין חֲמִשָּׁה חֲלוּקֵי אֲבָנִים נָטִיל לוֹן מִן הַנַּחַל דְּאִיהוּ יְסוֹד חַ\"י עָלְמִין, וְכַד שַׁוִּי לוֹן בְּקִירְטָא דְאִיהִי מַלְכוּת קַדִּישָׁא, אִתְעֲבִידוּ בָּהּ חַד,</p>\n<p>וְטָבַע בְּמִצְחָא דִפְּלִשְׁתָּאָה וְקָטִיל לֵיהּ. וְאִינוּן חָמֵשׁ אַבְנִין דְּאִינוּן שְׁמַע יִשְׂרָאֵל יהו\"ה אלהינ\"ו יהו\"ה, וְכַד שַׁוִּי לוֹן בְּקִירְטָא דְאִיהִי שָׂפָה דְפִימָא צָרִיךְ לְמֶעֱבַד לוֹן בָּהּ כֻּלְּהוּ אֶחָד,</p>\n<p>דִּבְזִמְנָא דְיִנְצַח בָּהּ קוּדְשָׁא בְּרִיךְ הוּא כָּל אוּמִין דְּעָלְמָא יִתְקַיַּים בְּהוֹן כִּי אָז אֶהְפּוֹךְ אֶל עַמִּים שָׂפָה בְרוּרָה לִקְרֹא כֻלָּם בְּשֵׁם יהו\"ה לְעָבְדוֹ שְׁכֶם אֶחָד (צפניה ג ט), וְהָא שָׂפָ\"ה וַדַּאי דָּא שְׁכִינָ\"ה, דְּהָכִי סְלִיקַת בְּחוּשְׁבַּן שָׂפָ\"ה,</p>\n<p>בְּגִין הָכִי כָּל אוּמִין דְּעָלְמָא עֲתִידִין לְאִשְׁתַּעִִבְּדָא תְּחוֹת יְדָהָא, וּלְאַמְלָכָא לָהּ עֲלַיְיהוּ בְּיוֹמִין דְּמַלְכָּא מְשִׁיחָא, לְקַיֵּים מַה דְּאִתְּמַר בָּהּ (תהלים קג יט) וּמַלְכוּתוֹ בַּכֹּל מָשָׁלָה.</p>\n<p>זַכָּאָה אִיהוּ מָאן דְּנָטִיר הַאי אֱמוּנָה בְּלִבֵּיהּ וּבְפוּמֵיהּ דְּוַדַּאי אִיהִי אֱמוּנָה דְיִשְׂרָאֵל, וְאִיהִי יִחוּדָא דְקוּדְשָׁא בְּרִיךְ הוּא, וּבָהּ מְיַחֲדִין יִשְׂרָאֵל לְקוּדְשָׁא בְּרִיךְ הוּא תְּרֵין זִמְנִין בְּכָל יוֹמָא,</p>\n<p>וְזַכָּאָה אִיהוּ מָאן דְּאִיהִי בְּאָמְנָה אִתּוֹ בְגָלוּתָא, דְּלָא דָחִיל מֵעִלָּאִין וְתַתָּאִין, דִּבְגִינָהּ אִתְּמַר לְאָדָם (בראשית ב טו) וַיַּנִּיחֵהוּ בְגַן עִדֶן לְעָבְדָהּ וּלְשָׁמְרָהּ, לְעָבְדָהּ בְּפִקּוּדִין דַּעֲשֵׂה, וּלְשָׁמְרָהּ בְּפִקּוּדִין דְּלֹא תַעֲשֶׂה,</p>\n<p>בְּגִין דְּאִיהִי גַ\"ן סְדָרִים דְּאוֹרַיְיתָא, וְאִיהִי עִדּוּנָא דְאוֹרַיְיתָא, מַאי אוֹרַיְיתָא עַמּוּדָא דְאֶמְצָעִיתָא, אִיהִי גַן דִּילֵיהּ, וְעִדֶן דִּילֵיהּ.</p>\n<p>רַבִּי רַבִּי קוּם אַסְחַר לְהַאי קִירְטָא, וְאַקַּף וְאַסְחַר לָהּ בְּשָׂפָה דִילָךְ, בְּהַאי אַבְנָא דְאִיהִי כְּלִילָא (נ\"א מוכלל ומעוטר) מִכָּל אַבְנִין דְּבִנְיָינָא דְאוֹרַיְיתָא, (וצלותא)</p>\n<p>אִיהִי אֶבֶן יְקָרָה</p>"],[9500011124,"<p>מוּכְלֶלֶת וּמְעוּטֶרֶת בְּאוֹת בְּרִית, וּבְאוֹת דְּשַׁבָּת, וּבְאוֹת דְּיֹמִין טָבִין, וּבְאוֹת תְּפִלִּין, וְחוּט דִּילָהּ כְּרוּכָה בְּאֶצְבְּעָא, וְדָא כְּרִיכוּ דִרְצוּעָה דִתְּפִלָּה דְיָד,</p>\n<p>דְּבָהּ הֲווֹ קַדְמָאִין כּוֹרְכִין אֶת שְׁמַע עִם וְאָהַבְתָּ בִּרְחִימוּ דְאַהֲבָה, דְהַיְינוּ וְאָהַבְתָּ אֵת יהו\"ה אלהי\"ך, בְּגִין דִּתְהֵא רְחִימָא לְגַבֵּי בַּעִִלָהּ, וְלָא מַפְסִיקִין,</p>\n<p>וּלְבָתַר דְּאָתָא יַעֲקֹב דְּאִיהוּ כְּלִיל תְּלַת אֲבָהָן, הִתִּיר הַהוּא כְּרִיכוּ דִילָהּ, וְאָמַר בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעִִד. בְּגִין דְּאִיהִי בָּעִי לְמֶהֱוִי אִיהִי סְגוּלַת מְלָכִים, בְּהַהוּא זִמְנָא אִתְּמַר שׁוֹפָ\"ר הוֹלֵ\"ךְ סֶגוֹלְתָּ\"א,</p>\n<p>וְאַזְלָ\"א לְשַׁרְיָא כִּתְרָא עַל יִשְׂרָאֵל דְּאִיהוּ עַמּוּדָא דְאֶמְצָעִיתָא, דְּאִיהוּ סֵפֶר תּוֹרָה כְּלִיל חֲמִשָּׁה חוּמְשֵׁי תוֹרָה, וְאִתְעֲבִידַת תַּגָּא עַל רֵישֵׁיהּ, בְּכָל אָת וְאָת דִּילֵיהּ, מֵאִלֵּין אַתְוָון יְדִיעָאן דְּסֵפֶר תּוֹרָה, כְּגַוְונָא דָא ש ע ט נ ז ג ץ,</p>\n<p>כֻּלְּהוּ זַיְינִין אִינוּן חַד וְעִִשְׂרִין, לָקֳבֵל חַד וְעִִשְׂרִין אַזְכָּרוֹת דִּתְּפִלִּין דְּרֵישָׁא, וּלְקִבְלַיְיהוּ חַד וְעִִשְׂרִין אַזְכָּרוֹת דִּתְּפִלִּין דְּיָד, דְּסָלְקִין כֻּלְּהוּ אַרְבְּעִין וּתְרֵין, לָקֳבֵל שְׁמָא דְמ\"ב,</p>\n<p>תַּגָּא אִיהִי י' עַל רֵישָׁא דְז', גּוּפָא דִילֵיהּ ו', וְסֵפֶר תּוֹרָה עַמּוּדָא דְאֶמְצָעִיתָא כְּלִיל שִׁית סְפִירָן מֵחֶסֶד עַד יְסוֹד,</p>\n<p>מַלְכוּת י' זְעִירָא, בָּהּ אִתְעֲבִידַת שְׁבִיעִי יוֹם שַׁבָּת, וְאִיהִי אוֹת תְּפִלִּין, אוֹת שַׁבָּת, אוֹת בְּרִית,</p>\n<p>וְאִיהוּ כֶּתֶר כְּהוּנָה וְכֶתֶר מַלְכוּת, מִסִּטְרָא דִימִינָא דְאִתְיְיהִיבַת אוֹרַיְיתָא אִתְקְרִיאַת כֶּתֶר תּוֹרָה</p>\n<p>וִימִינָא אִיהוּ כַּהֲנָא, מִסִּטְרֵיהּ אִיהוּ כֶּתֶר כְּהוּנָה, וְעַמּוּדָא דְאֶמְצָעִיתָא אִיהוּ מֶלֶךְ, וּמִסִּטְרָא דִגְבוּרָה בֵּית דִּין הַגָּדוֹל, נָפִיק מִתַּמָּן אֶשָּׁא וְאוֹקִיד לֵיהּ, וְכַד כַּהֲנָא נָפִיק בִּשְׁלָם מֵהֵיכָלָא, בְּהַהוּא זִמְנָא יִתְעָרוּן לְוִיִּים בְּנִגּוּנָא</p>\n<p>(כאן חסר והוא בתקוני זהר חדש).</p>\n<p>וְעוֹד אִית תִּקּוּנָא חֲמִשָּׁאָה בִּצְלוֹתָא,</p>\n<p>צְלוֹתָא אִיהִי כְּקָרְבָּנָא, כְּמָה דְאוּקְמוּהוּ קַדְמָאִין תְּפִלּוֹת כְּנֶגֶד תְּמִידִין תִּקְנוּם,</p>\n<p>תָּא חֲזִי קָרְבָּנִין אִינוּן מֵאַרְבַּע מִינִין, דְּאִינוּן לָקֳבֵל אַרְיֵה שׁוֹר נֶשֶׁר אָדָם, דְּאִינוּן מְצוּיָירִים בְּכָרְסַיָּיא,</p>\n<p>אִית קָרְבָּנָא דַהֲווֹ מְקָרְבִין יִשְׂרָאֵל, וְכַהֲנָא הֲוָה קָרִיב קָרְבָּנָא דִלְהוֹן.</p>\n<p>קָרְבָּנָא קַדְמָאָה, קָרְבָּנָא דַהֲוָה קָרִיב לִימִינָא, דָּא צְלוֹתָא דְשַׁחֲרִית, וְאִם הֲווֹ זַכְיָין הֲוָה נָחִית דִּיּוֹקְנָא דְאַרְיֵ\"ה וַהֲוָה מְקַבֵּל קָרְבָּנָא, וְדָא מִיכָאֵ\"ל דְּדַרְגֵּיהּ חֶסֶ\"ד, אִיהוּ הֲוָה מְקַבֵּל צְלוֹתָא דְשַׁחֲרִית,</p>\n<p>וְאִם לָא זָכוּ מַה כְּתִיב בְּקָרְבָּנָא (שמות כב ל) לַכֶּלֶב תַּשְׁלִיכוּן אוֹתוֹ, דְחָשִׁיב לֵיהּ כִּטְרֵיפָה, וּבְגִין דָּא הֲוָה נָחִית דִּיּוֹקְנָא דְכֶלֶב לְקַבֵּל הַהוּא דוֹרוֹנָא, וְקָרְבָּנָא, וְדָא אִיהוּ כֶּלֶב דְּאָמַר דָּוִד עָלָיו הַשָּׁלוֹם (תהלים כב כב), הַצִּילָה מֵחֶרֶב נַפְשִׁי מִיַּד כֶּלֶב יְחִידָתִי,</p>\n<p>וְכָל מַלְאֲכֵי חַבָּלָה דְאִינוּן כְּלָבִים צוֹעֲקִים בְּמִשְׁמָרָה תִּנְיָינָא דְלֵילְיָא, אִינוּן צָוְוחִין וְנָבְחִין וְאָמְרִין הַב הַב, בְּגִין דְּאִינוּן מִסִּטְרָא דְגֵיהִנָּם סַם הַמָּוְת, דְּאִתְּמַר בֵּיהּ (משלי ל טו) לַעֲלוּקָה שְׁתֵּי בָנוֹת הַב הַב.</p>\n<p>קָרְבָּנָא תִנְיָינָא לָקֳבֵל שׁוֹ\"ר, דְּאִתְּמַר בֵּיהּ (ויקרא כב כז) שׁוֹר אוֹ כֶשֶׂב אוֹ עִז וְגוֹמֵר, וּלְקִבְלֵיהּ צְלוֹתָא דְמִנְחָה, דְאָמַר דָּוִד עֲלָהּ (תהלים קד יד) מַצְמִיחַ חָצִיר לַבְּהֵמָה וְעִשֶׂב לַעֲבוֹדַת הָאָדָם,</p>\n<p>מַאי עִשֶׂב, ע\"ב ש', וְאִנּוּן ע\"ב שְׁמָהָן, דְּאִינוּן לְבוּשִׁין לְע\"ב שְׁמָהָן עִלָּאִין, כְּגַוְונָא דְעִשֶׂב דְּאִיהוּ לְבוּשָׁא דְחִטָּה, וּבְגִין דָּא לְהוֹצִיא לֶחֶם מִן הָאָרֶץ, וְהַיְינוּ לֶחֶם אַבִּירִים אָכַל אִישׁ (שם עח כ), וְדָא נַהֲמָא דְאוֹרַיְיתָא.</p>\n<p>וּלְעוֹלָם כָּל קָרְבָּנִין שְׁחִיטָתָן בַּצָּפוֹן, בְּגִין דְּמִצָּפוֹן תִּפָּתַח הָרָעָה (ירמיה א יד),</p>\n<p>(ס\"א ודא יצר הרע, ובגין דלא יהא צריך מנשמתא דילך) (ס\"א דלא יסריך נשמתא דילך האכילהו קרבנא, לקיימא ביה (משלי כה כא) אם רעב שונאך האכילהו לחם, ואם צמא השקהו מים, ולבתר דאיהו נטיל דמא דקרבנא, לא יטול מדילך)</p>\n<p>דְמִתַּמָן הַהוּא דְאוֹשִׁיד דָמָא, מְלַחֲךְ הַהוּא דָמָא דְבְעִירָן וּבְגִין דָא לֹא צָרִיךְ לְכַסָאָה לָהּ מִנֵיה, לְקַיְימָא בֵיה אִם רָעִב שׂוֹנַאֲךָ הַאֲכִילֵהוּ לָחֶם וְאִם צָמֵא הַשְׁקֵהוּ מָיִם וּלְבָתָר דְאִיהוּ</p>"],[9500011125,"<p>נָטִיל דָּמָא, קְרֵבִין קָרְבָּנָא לְעִילָא, דְאִתְּמַר בָּהּ (במדבר כח ב) אֶת קָרְבָּנִי לַחְמִי לְאִשַּׁי,</p>\n<p>וּלְקִבְלֵיהּ דְּשׁוֹר אִיהוּ חֲמוֹר נוֹעִר, אִם זָכוּ הָא שׁוֹ\"ר מְקַבֵּל קָרְבָּנָא, וְאִם לַאו הָא חֲמוֹר נוֹעִר, וּבְגִין דָּא אִתְּמַר (דברים כב י) לֹא תַחֲרוֹשׁ בְּשׁוֹר וּבַחֲמוֹר יַחְדָּו, יַחְדָּו כְּלוֹמַר לָא תִגְרוֹם דְּיֹאכָל חֲמוֹר קָרְבָּנָא דְשׁוֹר.</p>\n<p>קָרְבָּנָא תְּלִיתָאָה דְעַרְבִית, קָרְבָּנָא דְעוֹפִין, דְּאִתְּמַר בְּהוֹן (ויקרא ה ז) שְׁתֵּי תוֹרִים אוֹ שְׁנֵי בְנֵי יוֹנָה וְגוֹמֵר, דְּאִי זָכוּ נִשְׁרָ\"א דְיַעֲקֹב נָחִית לְקַבְּלָא לוֹן, וְאִם לַאו נִשְׁרָא דְסִטְרָא דִמְסָאֲבוּ נֵץ לְגַבֵּי יוֹנָה, וּכְפוּם קָרְבָּנָא הָכִי יִתְרַבֵּי אוֹ יִתְזָעִר.</p>\n<p>קָרְבָּנָא רְבִיעָאָה אָדָם, הַאי אִיהוּ דִמְקַבֵּל קָרְבָּנָא דְאָדָ\"ם, דְּאִיהוּ מַחֲשָׁבָה דְקָרִיב וּמְיַחֵד כֹּלָּא, וַעֲלֵיהּ אִתְּמַר (שם א ב) אָדָם כִּי יַקְרִיב מִכֶּם וְגוֹמֵר, הַאי אִיהוּ דִמְקָרֵב קָרְבָּן לַיהו\"ה, וְדָא אוֹרַיְיתָא,</p>\n<p>וּבְגִין דָּא תַּקִּינוּ בִצְלוֹתָא לְמִשְׁמַע בָּהּ סֵפֶר תּוֹרָה, לְמֶהֱוִי בֵּיהּ קָרְבָּנָא שְׁלִים בְּאָדָם, דְּאִתְּמַר בֵּיהּ (שם יט יד) זֹאת הַתּוֹרָה אָדָם, וּבְגִין דָּא מֵסִיר אָזְנוֹ מִשְּׁמוֹעַ תּוֹרָה גַּם תְּפִלָּתוֹ תּוֹעִבָה (משלי כח ט).</p>\n<p>וְכָל קָרְבָּנִין אִלֵּין רְמִיזִין בְּגוּפָא דְבַר נַשׁ, מוֹחָ\"א וְלִיבָּ\"א וְרֵיאָ\"ה, אִינוּן אַרְיֵ\"ה שׁוֹ\"ר נֶשֶׁ\"ר, קִטְרוּגָא דִלְהוֹן כֶּלֶב חֲמוֹר נֵץ, טְחוֹ\"ל מָרָ\"ה וְכָבֵ\"ד, דְּאִינוּן מַשְׁחִי\"ת אַ\"ף וְחֵמָ\"ה,</p>\n<p>מַחֲשָׁבָה דָא אָדָם, אִית מַחֲשָׁבָה טָבָא דְחֵיוָון טָבִין, וְאִית מַחֲשָׁבָה בִּישָׁא דְחֵיוָן בִּישִׁין, וּמַחֲשָׁבָה טָבָא אִיהוּ אָדָם טוֹב, וּמַחֲשָׁבָה בִּישָׁא דָא אָדָם רָע בְּלִיַּעַל, אָדָם לַהֶבֶל דָּמָה.</p>\n<p>לָקֳבֵל מוֹחָ\"א אִיהוּ אַרְיֵ\"ה דְנָחִית לְמֵיכַל קָרְבָּנִין, וַעֲלֵיהּ אִתְּמַר (יחזקאל א י) וּפְנֵי אַרְיֵה אֶל הַיָּמִין לְאַרְבַּעִִתָּם, לִבָּ\"א לִשְׂמָאלָא וַעֲלֵיהּ אִתְּמַר וּפְנֵי שׁוֹ\"ר מֵהַשְּׂמֹאל לְאַרְבַּעִִתָּם, רֵיאָ\"ה דָא נֶשֶׁ\"ר דְּאִית לָהּ גַּדְפִין דְּפָרַח בְּהוֹן, וַעֲלָהּ אִתְּמַר וּפְנֵי נֶשֶׁר לְאַרְבַּעִִתָּם,</p>\n<p>מַחֲשָׁבָה דְאִיהוּ אָדָם רָכִיב עַל כֻּלְּהוֹן, וְאִינוּן מֶרְכָּבָה דִילֵיהּ, כְּסוּסְוָון לִבְנֵי נָשָׁא. -חֲיָילִין דְּמוֹחָא גַרְמִי\"ן בְּקָרְבָּנָא, וַתִּקְרְבוּ עֲצָמוֹת עִִצֶם אֶל עַצְמוֹ (יחזקאל לז ז), חֲיָילִין דְּרֵיאָה וּדְלִבָּא עַרְקִין, קְשִׁירוּ וְחִבּוּרָא, וּתְנוּעָה דִלְהוֹן רוּחָא דְכַנְפֵי רֵיאָה, וְאִיהוּ רוּחַ אלהי\"ם מְרַחֶפֶת עַל פְּנֵי הַמָּיִם (בראשית א ב) (נ\"א דאיהו מוחא), בְּגִין דְּרֵיאָה (נ\"א דרישא) כְּלִילָא מִתַּרְוַיְיהוּ, כְּגַוְונָא דְעוֹפָא מִמַּיָּא וְאַרְעָא, וְאִינוּן כְּלִילָן מִתַּרְוַיְיהוּ.</p>\n<p>עַל מוֹחָא שַׁרְיָא בְּרָכָה, עַל לִבָּא שַׁרְיָא קְדוּשָׁה, עַל רֵיאָה שַׁרְיָא יִחוּד, מַחֲשָׁבָה כְלִילָא מִכֻּלְּהוּ, וְאִינוּן יְבָרֶכְךָ יהו\"ה יָאֵר יהו\"ה יִשָּׂא יהו\"ה (במדבר כד ו), יְבָרֶכְךָ בְּמוֹחָא, יָאֵר בְּלִבָּא דְתַמָּן נְהוֹרָא דְעַיְינִין, כְּמָה דְאוּקְמוּהָ הַלֵּב רוֹאֶה, יִשָּׂא בְּרֵיאָה דְאִיהוּ שָׁלוֹם, הֲדָא הוּא דִכְתִיב וְיָשֵׂם לְךָ שָׁלוֹם.</p>\n<p>וְאִינוּן שְׁמִיעָ\"ה רְאִיָּ\"ה רֵיחָ\"א,</p>\n<p>שְׁמִיעָ\"ה בְּמוֹחַ, וְאִיהוּ בְּהִפּוּכָא חוֹ\"ם, דְּשַׁרְיָא בְלַחוּתָא וּקְרִירוּתָא דְמוֹחָא לְחַמְמָא לֵיהּ, מִסִּטְרָא דִגְבוּרָה, וְאִיהוּ אַרְיֵה מִסִּטְרָא דְגוּפָא, שׁוֹר מִסִּטְרָא דְנַפְשָׁא, דְּאִינוּן אֵשׁ וּמַיִם, אֵשׁ שִׂכְלִית מַיִם יְסוֹדִית,</p>\n<p>רְאִיָּ\"ה בְּלִבָּ\"א, דְאִיהוּ אֵשׁ, רְאִיָּ\"ה אַרְיֵ\"ה, מַיִם שִׂכְלִית לְקַרְרָא אֵשׁ יְסוֹדִי דְּלִבָּא, דְּלָא יוֹקִיד כָּל גּוּפָא.</p>\n<p>רֵיחָא בְרֵיאָה דְנָפִיק לְחוֹטָמָא, עֲלֵיהּ אִתְּמַר (בראשית ב ז) וַיִּפַּח בְּאַפָּיו נִשְׁמַת חַיִּים,</p>\n<p>וְרֵיאָה אִיהִי מִסִּטְרָא דְמוֹחָא קְרִירָא, וּמִסִּטְרָא דְלִבָּא יְבֵישָׁה, וְאִיהוּ חֶצְיוֹ מַיִם יְסוֹדִית, וְחֶצְיוֹ יְבֵשָׁה יְסוֹדִית, בְּגִין דָּא שַׁרְיָא עֲלָהּ רוּחָא שִׂכְלִית, דְּאִיהוּ חַם וְלַח, חַם לְחַמְמָא קְרִירוּתָא, לַח לְרַטְבָא יְבֵשׁוּתָא, דָּא שִׂכְלִי וְדָא יְסוֹדִיִּי.</p>\n<p>דִּבּוּר דָּא אָדָם, דִּכְּלִיל מִכֻּלְּהוּ, וּמָאן אַפִּיק לֵיהּ מַחֲשָׁבָה,</p>\n<p>וּבְגִין אִלֵּין שִׂכְלִיִּים הֲווֹ נָחֲתִין בְּקָרְבָּנָא לְקָרְבָא קָרְבָּנָא וּלְיַחֲדָא כֹלָּא, וְאִלֵּין אִינוּן בִּתְחִיַּית הַמֵּתִים, דִּבְהוֹן יְהֵא קוּדְשָׁא בְּרִיךְ הוּא מְקָרֵב עִִצֶם אֶל עַצְמוֹ, וְגִידִין וְעַרְקִין כֻּלְּהוֹן לְחַבְּרָא דָא בְדָא, וִיקַבְּלוּן אִלֵּין בְּאִלֵּין, וּמְשֻׁלָּבִין אִלֵּין בְּאִלֵּין, הֲדָא הוּא דִכְתִיב (שמות לו ה) מַקְבִּילוֹת הַלּוּלָאוֹת וְגוֹמֵר,</p>\n<p>בְּהַהוּא זִמְנָא יְהֵא חֶדְוָה וְנִגּוּנָא, בִּקְרִיבוּ דִלְהוֹן.</p>"],[9500011126,"<p>בְּרֵאשִׁית בָּרָא אלהי\"ם, בְּרֵאשִׁית חַד אִיהוּ דְלָא אִתְגַּלְיָיא, וּבָרָא תְּרֵין, תְּרֵין אִינוּן, וְאִינוּן בּ', וְאִינוּן תְּרֵין עָלְמִין סְתִימִין, וּבַמֶּה בְרָא לוֹן בִּנְקוּדָא חֲדָא סְתִימָא, רֵאשִׁית אִתְקְרֵי, וַעֲלָהּ אִתְּמַר (תהלים קד כד) כֻּלָּם בְּחָכְמָה עָשִׂיתָ, וּתְרֵין עָלְמִין סְתִימִין לָא הֲווֹ אִתְגַּלְיָין, עַד דְּעָבִיד לוֹן תְּרֵין לְבוּשִׁין, וּמַאי נִינְהוּ אֵת הַשָּׁמַיִם וְאֵת הָאָרֶץ, אֵת הַשָּׁמַיִם לְבוּשָׁא לְעָלְמָא עִלָּאָה דְאִתְבְּרִי בִּנְקוּדָה עִלָּאָה, וְאֵת הָאָרֶץ לְבוּשָׁא לְעָלְמָא תַּתָּאָה דְאִתְבְּרִי בֵּאלֹהִי\"ם דְּאִיהִי אִימָּא עִלָּאָה. י' רֵאשִׁית אִתְקְרִי וְאִיהוּ אַבָּא דְכֹלָּא, ה' אלהי\"ם וְאִיהִי אִמָּא דְכֹלָּא אֵם כָּל חָי, וְחָכְמָה דְאִיהוּ אַבָּא לָא אִשְׁתְּמוֹדָע אֶלָּא בְּבִינָה דְאִיהִי אלהי\"ם, וְתַמָּן י\"ה אַבָּא וְאִימָּא כַּחֲדָא, תְּרֵין עָלְמִין סְתִימִין, ו\"ה אִינוּן תְּרֵין בְּנִין, וְאִינוּן עָלְמָא דֵין וְעָלְמָא דְאָתֵי, ו' עָלְמָא דְאָתֵי דְאִיהוּ עָלְמָא אֲרִיכָא, ה' עָלְמָא דֵין דְּלַאו אִיהוּ אֲרִיךְ.</p>\n<p>בּ' תְּרֵין הֵיכָלִין לִתְרֵין אַתְוָון דְּאִינוּן י\"ה, וַעֲלֵיהּ אִתְּמַר (איוב כח כג) אלהי\"ם הֵבִין דַּרְכָּה וְהוּא יָדַע אֶת מְקוֹמָהּ, וּמַאי נִיהוּ בּ' הֵיכָלִין אִלֵּין, אֶלָּא חַד אִיהוּ אהי\"ה, וְתִנְיָינָא אדנ\"י, וְתַרְוַיְיהוּ אִינוּן כִּנּוּיִין לִתְרֵין אַתְוָון י\"ה אַבָּא וְאִימָּא, וְהָכִי סְלִיק חוּשְׁבַּן אהי\"ה אדנ\"י (ס\"א וחושבן אלהי\"ם) לְחוּשְׁבַּן כִּנּוּ\"י, וּבָהּ גְּנִיזִין אַבָּא וְאִימָּא, וְדָא אִיהוּ הַנִּסְתָּרוֹת לַיהו\"ה אלהינ\"ו (דברים כט כח) י\"ה, וְדָא אִינוּן סְתִירִין וּגְנִיזִין, וְאִינוּן סִתְרֵי דְאוֹרַיְיתָא מַמָּשׁ, וּבְגִין דְּאִינוּן סְתִירִין, צָרִיךְ דְּלָא לְגַלָּאָה לוֹן, וְדָא אִיהוּ רָזָא דְעִִרְיָין, דְּאִתְּמַר בְּהוֹן (ויקרא יח ז) עִִרְוַת אָבִיךָ וְעִִרְוַת אִמְּךָ לֹא תְגַלֵּה, לֹא תְגַלֵּה וַדַּאי מִן כִּסּוּיָא דִלְהוֹן.</p>\n<p>קָם סָבָא פָּתַח וְאָמַר, רַבִּי רַבִּי נְחֵית הָכָא, דְאַתְּ בּוֹצִינָא קַדִּישָׁא, דְּהָא שְׁכִינְתָּא קַדִּישָׁא קָא נְטִירַת לָךְ וּלְחַבְרָךְ, בְּאוֹמָאָה עֲלַיְיכוּ לָא תִּתְעַכְּבוּן הָתָם לְנַחֲתָא הָכָא אַתּוּן, וְהָכִי אוֹמִינָא לְכָל אִינוּן מָארֵי מְתִיבְתָּא עִלָּאָה וְתַתָּאָה, דִיְהוֹן כֻּלְּהוֹן נָחֲתִין עִמְּכוֹן, וְכֵן אֲנָא אוֹמִינָא לְאִינוּן מַלְאָכִין וַחֲיָילִין קַדִּישִׁין דִּי מְמַנָּן לְנַטְרָא לְכוּ, וְלַאו לִיקָרָא דִידִי עֲבִידְנָא וְלַאו לִיקָרָא דְאַבָּא וְאִמָּא, אֶלָּא לִיקָרָא דִשְׁכִינְתָּא.</p>\n<p>מִיָּד קָלָא אִתְעַר בְּעַנְפֵי אִלָּנִין דְּגִנְּתָא דְעִדֶן, עִלָּאִין נָחְתוּ, (מלאכין) (נ\"א תתאין) אִתְכַּנְשׁוּ לְנַחֲתָא, בְּאִלֵּין מָארֵי מְתִיבְתָּא עִלָּאָה וְתַתָּאָה, דְּהָא רְשׁוּתָא אִתְיַיהִיב לְכוּ מִלְּעִילָא, מִיָּד כֻּלְּהוּ אִתְפַּשְׁטוּ מִדִּיּוֹקְנֵיהוֹן, וְאִתְלַבְּשׁוּ בְּאַוִּירִין דְּהַאי עָלְמָא דְּאִיהוּ כִּנּוּי וּסְתִירָה לְאַתְוָון קַדִּישִׁין.</p>\n<p>אַדְהָכִי הָא אֵלִיָּהוּ קָא אַקְדִּים לְתַקְנָא לוֹן מוֹתְבַיְיהוּ, פָּתַח וְאָמַר רַבִּי רַבִּי בּוֹצִינָא קַדִּישָׁא, דְפוּמָא דִילָךְ אִיהוּ מְמַלֵּל רַבְרְבָן בְּאוֹרַיְיתָא, מִנֵּיהּ מִזְדַּעִִזְעִין עִלָּאִין וְתַתָּאִין, וּפוּמָא דִילָךְ אִתְּמַר בָּהּ (שמות יט יח) וְהַר סִינַי עָשַׁן כֻּלּוֹ וכו', בְּגִין דְּאָת י' שַׁרְיָא בְּמוֹחָא דִילָךְ, ה' בְּלִבָּךְ דְּאִיהִי בִּינָה, וּבָהּ לֵב מֵבִין, ו' בְּפוּמָא דִילָךְ, וּמִנֵּיהּ וְכָל הָעָם רוֹאִים אֶת הַקּוֹלוֹת (שם כ יח), דְּאִיהוּ בְּאִינוּן הֲבָלִים דְּנָפְקִין מִפּוּמָךְ, דַּעֲלַיְיהוּ אִתְּמַר (תהלים כט ז) קוֹל יהו\"ה חוֹצֵב לַהֲבוֹת אֵשׁ.</p>\n<p>שִׁית עִזְקָאן אִינוּן בַּקָּנֶה, דִבְהוֹן סָלִיק ו', וְאִינוּן ו' דַּרְגִּין לְכָרְסַיָּיא, ה' בְּלִבָּא אִיהִי הֲבַ\"ל ה' ל\"ב, דְּוַדַּאי אִיהִי ה' בְּלִבָּא, ו' (קול) בְּקוֹל דְּנָפִיק מִנֵּיהּ, וְהַאי אִיהוּ קוֹל דְּנָפַק מֵהֲבַל.</p>\n<p>וּתְרֵין בָּתִּין אִית בְּלִבָּא, חַד אַפִּיק הֲבַל, וְחַד אַפִּיק הֲבַל וְאִינוּן ה' עִלָּאָה ה' תַּתָּאָה, בִּתְרֵי בָּתֵּי לִבָּא, דְאִנּוּן לָקֳבֵל בַּיִת רִאשׁוֹן וְשֵׁנִי, ו' קוֹל דְּנָפִיק מִתַּרְוַיְיהוּ, י' דִּבּוּר דְּשַׁרְיָא בְּפוּמָא, וַעֲלֵיהּ אִתְּמַר (תהלים לג ו) בִּדְבַר יהו\"ה שָׁמַיִם נַעֲשׂוּ, וְאִיהוּ דִבּוּר חַד דִּכְלִיל עֲשַׂר אֲמִירָן, וְרָזָא דְמִלָּה אַחַת דִּבֶּר אלהי\"ם שְׁתַּיִם זוּ שָׁמָעִִתִּי (שם סב יב), לְאַחֲזָאָה בָּהּ דַּעֲשַׂר דִּבְּרָן בְּדִבּוּר חַד אִתְאֲמָרוּ, שְׁתַּיִם זוּ אִלֵּין אָנֹכִי וְלֹא יִהְיֶה לְךָ, וְאִיהוּ אֶחָד חַד בֵּינַיְיהוּ, וְדָא אִיהוּ דְאַמְרָן דִּבְתַרְוַיְיהוּ</p>"],[9500011127,"<p>תַלְיָין פִּקּוּדִין דַּעֲשֵׂה וְלֹא תַעֲשֶׂה, וְקוּדְשָׁא בְּרִיךְ הוּא מִתַּרְוַיְיהוּ מַלִּיל לְמֵיהַב יְקָרָא לְאוֹרַיְיתָא, דְּהָא אִיהוּ בְּדִבּוּרָא חַד אָמַר כֹּלָּא, וְלָמָה אָמַר שְׁתַּיִם זוּ שָׁמָעִִתִּי, ז\"וּ אֶחָ\"ד, הֲוִי בְּחוּשְׁבַּן, דִּתְרֵי תוֹרוֹת הֲווֹ, וְקוּדְשָׁא בְּרִיךְ הוּא חַד בֵּינַיְיהוּ וּשְׁמֵיהּ חָד, וּמִתְּרֵין דִּבּוּרִין נָפַק קָלָא וְאִתְפַּלֵּג לְשַׁבְעִין קָלִין, לָקֳבֵל שַׁבְעִין אַנְפִּין, וְקָטַל בְּהוֹן שַׁבְעִין אוּמִין עַל דְּלָא קַבִּילוּ אוֹרַיְיתָא, וּבִתְרֵין דִּבּוּרִין קָטִיל לִתְרֵין אוּמִין, דְּאִינוּן עִשָׂו וְיִשְׁמָעִאל דְּלָא בָּעוּ לְקַבְּלָא אוֹרַיְיתָא.</p>\n<p>דְּהָא קוּדְשָׁא בְּרִיךְ הוּא חַד אִיהוּ, וְאִיהוּ לָא הֲוָה מְמַלֵּל בְּאִלֵּין קָלִין וְדִבּוּרִין דְּאָנֹכִי, אֶלָּא לְאַחְזָאָה דִשְׁמֵיהּ וִיקָרֵיהּ הֲוָה בְאוֹרַיְיתָא, וּבְגִין דָּא קוּדְשָׁא בְּרִיךְ הוּא מַלִּיל מִינָהּ (נ\"א בדינא), בְּגִין דְּיִתְזַעִִזַעוּן כָּל אוּמִין דְּעָלְמָא מֵאִלֵּין דְּמִשְׁתַּדְלִין בָּהּ, וּבְגִין דָּא אָמַר קוּדְשָׁא בְּרִיךְ הוּא לְמֹשֶׁה (שמות ג טו) זֶה שְּׁמִי לְעֹלָם וְזֶה זִכְרִי לְדוֹר דּוֹר, שְׁמִי עִם י\"ה שְׁסָ\"ה פִּקּוּדִין דְּלֹא תַעֲשֶׂה, זִכְרִי עִם ו\"ה רְמַ\"ח פִּקּוּדִין דַּעֲשֵׂה, לְאַחְזָאָה דְאוֹרַיְיתָא בִשְׁמָא דְקוּדְשָׁא בְּרִיךְ הוּא אִתְבְּרִיאַת, וְעַל שְׁמֵיהּ אִתְקְרִיאַת, הֲדָא הוּא דִכְתִיב (ישעיהו מג ז) כָּל הַנִּקְרָא בִּשְׁמִי וכו', וּבָהּ שַׁרְיָיא קוּדְשָׁא בְּרִיךְ הוּא, וּמִינָהּ מַלִּיל בְּסִינַי.</p>\n<p>וְאִית אוֹרַיְיתָא עִלָּאָה דְלָא אִתְקְרֵי בָּהּ בְּרִיאָה אֶלָּא אֲצִילוּתָא דִילֵיהּ, וְהִיא וְהוּא כֹּלָּא חָד, וְכָל בַּר נַשׁ דְּאִשְׁתַּדַּל בְּאוֹרַיְיתָא שְׁמֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא תַּמָּן, כָּל שֶׁכֵּן וְכָל שֶׁכֵּן בְּבוֹצִינָא קַדִּישָׁא, וּבוֹצִינָא קַדִּישָׁא וַדַּאי פִּימָךְ אִיהִי סִינַי, שֶׁבַע הֲבָלִים דְּנָפְקִין מִפּוּמָךְ שְׁכִינְתָּא שַׁרְיָא עֲלַיְיהוּ, דְאִיהִי בַּת שֶׁבַע, דְּאִינוּן שֶׁבַע שְׁמָהָן דִּשְׁמָא מְפָרַשׁ, דְּאִיהוּ שְׁמָא דְאַרְבְּעִין וּתְרֵין אַתְוָון.</p>\n<p>וּמִנֵּיהּ סָלִיק קוֹל דְּאִיהוּ עַמּוּדָא דְאֶמְצָעִיתָא, וְאִסְתַּלַּק לְשַׁבְעִין קָלִין, דְּאִיהִי וַדַּאי בֵּיהּ סָלְקָא לְשֶׁבַע, דְּאִיהִי ה' עִלָּאָה, אַוִּירָא דַכְיָא, אַוִּירָא דְאֶרֶץ יִשְׂרָאֵל דְּאִיהִי מַחְכִּים, מִסִּטְרָא דְחָכְמָה דְאִיהִי י', וּבָהּ סְלִיק ו' לְעִִשֶׂר ו' זִמְנִין, וּב' הֵהִי\"ן אִינוּן ה' הֲבַל מִלְּגָאו ה' הֲבַל מִלְּבָר, וְתַרְוַיְיהוּ אִינוּן בְּלִבָּא וּבְפוּמָא, אִינוּן עֲשַׂר דִּבְּרָן דְּקוּדְשָׁא בְּרִיךְ הוּא, וּבְהוֹן אִינוּן לִבָּא וּפוּמָא שָׁוִין, וּמָאן דְּאִתְעַסַּק בְּאוֹרַיְיתָא כְּדֵין צָרִיךְ דִּיְהֵא פוּמָא וְלִבָּא שָׁוִין, וְלַאו לְמַגָּנָא אוּקְמוּהוּ מָארֵי מַתְנִיתִין, כָּל מִי שֶׁאֵין תּוֹכוֹ כְּבַרוֹ אַל יִכָּנֵס לְבֵית הַמֶּדְרָשׁ.</p>\n<p>תְּרֵין הֵהִי\"ן וַדַּאי אִינוּן תְּרֵין דִּבּוּרִין, דְּאִתְּמַר בְּהוֹן (תהלים סב יב) שְׁתַּיִם זוּ שָׁמָעִִתִּי, ו' קָלָא דְנָפִיק מִנַּיְיהוּ, וַעֲלֵיהּ אִתְּמַר (דברים ד יב) קוֹל דְּבָרִים אַתֶּם שֹׁמְעִים, וְהַאי קוֹל נָפִיק מִתְּרֵין דִּבּוּרִין דְּאִיהוּ ה\"ה, דִּכְלִילָן עֲשַׂר דִּבְּרָן, ה' בְּלוּחָא חֲדָא, וַהֲווֹ מְסַדְּרִין לְגַבַּיְיהוּ (דברים כט ט) רָאשֵׁיכֶם שִׁבְטֵיכֶם זִקְנֵיכֶם וְשׁוֹטְרֵיכֶם כֹּל אִישׁ יִשְׂרָאֵל, הָא חָמֵשׁ בְּלוּחָא קַדְמָאָה, בְּלוּחָא תִנְיָינָא הֲווֹ מְסַדְּרִין לְגַבַּיְיהוּ חָמֵשׁ תִּקּוּנִין אָחֳרָנִין, דְּאִינוּן טַפְּכֶם נְשֵׁיכֶם וְגֵרְךָ מֵחֹטֵב עִצֶיךָ עַד שֹׁאֵב מֵימֶיךָ, דָּא אִינוּן ה', הָא תְּרֵין דִּבּוּרִין דִּכְלִילָן בְּהוֹן עִִשֶׂר, וְקָלָא דַהֲוָה נָפִיק מִנַּיְיהוּ הֲוָה כְלִיל לוֹן וְדָא ו', כְּלִיל ו' זִמְנִין דִּכְתִיב טוֹב בְּשֵׁשֶׁת יְמֵי בְּרֵאשִׁית, (כאן חסר) וְאִיהִי הֲוָה סָלְקָא מִנַּיְיהוּ בְּאָת י', ו' זִמְנִין י' אִינוּן שִׁתִּין, אִשְׁתַּכַּח דְּאִיהִי י' אֲמִירָן, (דלא הוה סליק לע\"ב שמהן).</p>\n<p>ה' ה' תְּרֵין דִּבּוּרִין וּבְהוֹן עִִשֶׂר הָא תְּרֵיסַר, ו' הוּא סְלִיק בְּאָת י', ו' זִמְנִין י' דְּאִינוּן שִׁתִּין הָא ע\"ב, וְאִי תֵּימָא דִבְאוֹרַיְיתָא מַלִּיל וְלָא יַתִּיר, לָא אִשְׁתַּכַּח אֲתַר לְעִילָא וְתַתָּא דְלָא מַלִּיל מִנֵּיהּ, אֲפִילוּ בְּמַלְאָכִין, דְּלָא אִשְׁתַּכַּח דֶּאלֹ\"ה אָחֳרָא אִית בְּעָלְמָא, וּמַלִּיל בַּכָּרְסַיָּיא, הֲדָא הוּא דִכְתִיב אָנֹכִי, וְהָכִי סְלִיק אָנֹכִ\"י לְחֻשְׁבַּן כִּסֵּ\"א, וּלְבָתַר מַלִּיל בְּמַלְאָכִין, הֲדָא הוּא דִכְתִיב (שמות כ יח) וְכָל הָעָם רֹאִים אֶת הַקּוֹלֹת, דַּעֲלַיְיהוּ אִתְּמַר (קהלת י כ) כִּי עוֹף הַשָּׁמַיִם יוֹלִיךְ אֶת הַקּוֹל כו'.</p>\n<p>בְּגִין דְּכַד קוּדְשָׁא בְּרִיךְ הוּא בָּעָא לְמַלְּלָא בְמַלְאָכַיָּא נָחַת שְׁמֵיהּ עֲלַיְיהוּ, כְּגַוְונָא דָא יהו\"ה, י' בְּחַיָּה חֲדָא דְאִיהִי אַרְיֵ\"ה, וּבֵיהּ אִתְּמַר (עמוס ג ח) אַרְיֵה שָׁאָג מִי לֹא יִירָא, וּבְאָן אֲתַר י' בְּרֵישָׁא ה' עַל גַּדְפוֹי ו' בְּפוּמֵיהּ ה' בִּזְנָבֵיהּ, וּבְגִינָהּ אִתְּמַר הֱוִי זָנָב לַאֲרָיוֹת</p>"],[9500011128,"<p>וכו', וְדָא הוּא וּפְנֵי אַרְיֵה אֶל הַיָּמִין לְאַרְבַּעִִתָּם (יחזקאל א י), וּלְבָתַר הֲוָה נָחִית בְּחַיָּה דִשְׁמָהּ שׁוֹר, כְּגַוְונָא דָא הוה\"י, ה' בְּרֵישֵׁיהּ ו' בְּפוּמוֹי ה' בְּגַדְפוֹי י' בִּזְנָבֵיהּ, וְדָא אִיהוּ וּפְנֵי שׁוֹר מֵהַשְּׂמֹאל, וּלְבָתַר הֲוָה נָחִית עַל חַיָּה שֶׁשְּׁמָהּ נֶשֶׁר, כְּגַוְונָא דָא והי\"ה, ו' בְּרֵישֵׁיהּ ה' בְּפוּמֵיהּ י' בְּגַדְפוֹי ה' עַל זְנָבֵיהּ, וְדָא אִיהוּ וּפְנֵי נֶשֶׁר לְאַרְבַּעִִתָּם, וְאִינוּן תְּרֵי עֲשַׂר אַנְפִּין, לְכָל חַד שִׁית, סָלְקִין לְע\"ב, וְדָא אִיהוּ וְכָל הָעָם רוֹאִים אֶת הַקּוֹלוֹת (שמות כ יח).</p>\n<p>וְאָדָם רָכִיב עַל גַּבַּיְיהוּ דָא מטטרו\"ן, דְּאִיהוּ כְּלִיל שְׁמָא דְאַרְבְּעִין וּתְרֵין אַתְוָון, וְאִינוּן (שית אתוון, ולכל את סלקין שית), ז' תֵּיבִין וּבְכָל תֵּיבָה שִׁית אַתְוָון וְסָלְקִין לְמ\"ב, וְדָא אִיהוּ שְׂרָפִים עוֹמְדִים מִמַּעַל לוֹ, שֵׁשׁ כְּנָפַיִם שֵׁשׁ כְּנָפַיִם לְאֶחָד, בִּשְׁתַּיִם יְכַסֶּה פָנָיו וּבִשְׁתַּיִם יְכַסֶּה רַגְלָיו וּבִשְׁתַּיִם יְעוֹפֵף (ישעיהו ו ב).</p>\n<p>דִּכְמָה דְאִיהוּ שְׁמָא דְקוּדְשָׁא בְּרִיךְ הוּא דְמ\"ב וְע\"ב לְעִילָא, כַּךְ אִיהוּ שְׁמָא דְמ\"ב וְע\"ב לְתַתָּא, הֲדָא הוּא דִכְתִיב (תהלים מח יא) כְּשִׁמְךָ אלהי\"ם כֵּן תְּהִלָּתֶךָ עַל קַצְוִי אֶרֶץ, וְדָא אִיהוּ וְכָל הָעָם רוֹאִים אֶת הַקּוֹלוֹת, וְאִינוּן הֲווֹ מַלְאָכִין, דְּכָל חַד הֲוָה אִתְעֲבִיד קוֹל וּפָרַח בְּאַוִּירָא, וְכָל חַד מִיִּשְׂרָאֵל דַּהֲוָה אָמַר נַעֲשֶׂה וְנִשְׁמָע הֲוָה שַׁרְיָא בְּפוּמֵיהּ, וַהֲוָה אוֹלִיף לֵיהּ אוֹרַיְיתָא כֻּלָּהּ.</p>\n<p>וּלְבָתַר מַלִּיל עִמְּהוֹן מִן שְׁמַיָּא וְאַרְעָא, הֲדָא הוּא דִכְתִיב (דברים ד לו) מִן הַשָּׁמַיִם הִשְׁמִיעֲךָ אֶת קוֹלוֹ לְיַסְּרֶךָּ, וְעַל הָאָרֶץ הֶרְאֲךָ אֶת אִשּׁוֹ הַגְּדוֹלָה וכו', בְּהַהוּא זִמְנָא דְאָמְרוּ יִשְׂרָאֵל נַעֲשֶׂה וְנִשְׁמָע מִיָּד יִ שְׂמְחוּ הַ שָּׁמַיִם וְ תָגֵל הָ אָרֶץ (ד\"ה א טז), לְבָתַר הֲוָה מְמַלֵּל עִמְּהוֹן מֵאַרְבַּע סִטְרִין, וַהֲווֹ מִסְתַּכְּלִין לְגַבֵּי מִזְרָח וַהֲווֹ שָׁמְעִין יָת קָלָא, וּלְגַבֵּי מַעֲרָב וְדָרוֹם וְצָפוֹן הֲווֹ שָׁמְעִין יָת קָלָא, לְאַחְזָאָה דְמִכָּל אֲתַר מַלִּיל עִמְּהוֹן, וְלָא הֲוָה אֲתַר לְעִילָא וְתַתָּא דְלָא מַלִּיל עִמְּהוֹן, לְאַחְזָאָה דִמְלֹא כָל הָאָרֶץ כְּבוֹדוֹ, דְּאִיהוּ סָבִיל עִלָּאִין וְתַתָּאִין, וְאִיהוּ סָמִיךְ עִילָא וְתַתָּא וְכָרְסַיָּא יְקָרָא, וּמַלְאָכִין וְנִשְׁמָתִין, אִיהוּ סָבִיל כֹּלָּא, וְקָשִׁיר כֹּלָּא, וּמְיַחֵד כֹּלָּא, וְלֵית מָאן דְּסָמִיךְ לֵיהּ.</p>\n<p>וְאִיהוּ אִתְקְרֵי בְּכָל שְׁמָהָן, לְאִשְׁתְּמוֹדְעָא תּוּקְפֵיהּ בְּכָל שְׁמָא וּשְׁמָא, מֵהַהוּא דַרְגָּא וּמְמַנָּא דְשַׁרְיָא עֲלֵיהּ, וְלֵיהּ לֵית שְׁמָא יְדִיעָא, וְאִיהוּ אִתְקְרֵי חַד בְּחוּשְׁבָּן כַּד שַׁרְיָא בְדַרְגָּא דְאִינוּן (אחרנין) (נ\"א אחדין) מִשְּׁאָר דַּרְגִּין, וְאִיהוּ לֵית לֵיהּ חוּשְׁבָּן, כַּד שַׁרְיָא עַל כָּל עָלְמִין (ס\"א עלאין) וְעַל כָּל מְמַנָּא דִלְהוֹן, אִתְקְרֵי עַל שְׁמֵיהּ, לְאַחְזָאָה לְכָל חַד מִיִּשְׂרָאֵל מֵאֲתַר דְּקָרָאן לֵיהּ לְפוּם צָרְכַיְיהוּ, כְּמָה דְאוּקְמוּהוּ הָרוֹצֶה לְהַעֲשִׁיר יַצְפִּין לְהַחְכִּים יַדְרִים.</p>\n<p>קָם בּוֹצִינָא קַדִּישָׁא וְכָל מָארֵי מְתִיבְתָּאן, וְאִשְׁתַּטְחוּ קַמֵּי סָבָא, וּבְרִיכוּ לֵיהּ, אָמַר בּוֹצִינָא קַדִּישָׁא וַדַּאי הַאי סָבָא מֵאֲתַר דְּעַתִּיק יוֹמִין קָא אָתֵי, וְתַמָּן אִתְרַבֵּי, זַכָּאָה חוּלְקָנָא דְזָכֵינָא לְמִשְׁמַע מִלִּין עַתִּיקִין, מֵאֲתַר דְּעַתִּיק יוֹמִין, זַכָּאָה חוּלְקָנָא דְזָכֵינָא לְהַאי.</p>\n<p>קָם רַבִּי שִׁמְעוֹן פָּתַח וְאָמַר, בְּרֵאשִׁי\"ת בְּרִי\"ת אֵ\"שׁ, דְּאִיהוּ אוֹת וּרְשִׁימוּ דְּעִלָּאִין וְתַתָּאִין בֵּיהּ קַיְימִין, אִיהוּ אוֹת דְּצָבָא דִלְעִילָא, דִבְהוֹן אִתְקְרִי קוּדְשָׁא בְּרִיךְ הוּא יהו\"ה צבאו\"ת, וְאִיהוּ אוֹת דְּצָבָא דִלְתַתָּא, אִיהוּ אוֹת וּבְרִית דְּבֵיהּ קַיְימִין שְׁמַיָּא וְאַרְעָא, כְּמָה דְאַתְּ אָמַר (ירמיה לג כה) אִם לֹא בְרִיתִי יוֹמָם וָלָיְלָה חוּקוֹת שָׁמַיִם וָאָרֶץ לֹא שָׁמְתִּי, אִיהוּ אוֹת וַדַּאי, דְּאִיהוּ רְשִׁימוּ דְחוֹתָמָא דְמַלְכָּא.</p>\n<p>אַדְהָכִי הָא סָבָא קָא נָחִית לְגַבֵּיהּ כְּמִלְּקַדְמִין פָּתַח וְאָמַר רַבִּי רַבִּי (י') בְּרִית אִיהוּ וַדַּאי צַדִּיק חַ\"י עָלְמִין, דְּאִיהוּ י' זְעִירָא מִסִּטְרָא דְחָכְמָה דִלְעִילָא, דְּכַד נָחֲתָא י' לְגַבֵּיהּ, אַף עַל גַּב דִּבְאַתְרֵיהּ י' עִלָּאָה אִתְקְרֵי, כַּד נָחִית לְגַבֵּי צַדִּיק י' זְעִירָא אִתְקְרֵי, וְאָת ו' אַף עַל גַּב דְּאִיהוּ ו' עִלָּאָה בְּאַתְרֵיהּ בְּעַמּוּדָא דְאֶמְצָעִיתָא, כַּד נָחִית לְגַבֵּי צַדִּיק לְאִתְחַבְּרָא בְּה', ו' זְעִירָא אִתְקְרִי, אַלְפָא בֵּיתָא דְאַתְוָון זְעִירָן</p>"],[9500011129,"<p>בֵּיהּ אִינוּן, וְה' עִלָּאָה כַד נָחֲתָא לְגַבֵּי צַדִּיק, זְעִירָא אִתְקְרִיאַת, וְאַף עַל גַּב דְּאַתְוָון דִּשְׁמָא קַדִּישָׁא בֵיהּ כְּלִילָן, סְתִימִין אִינוּן בֵּיהּ, וּבְגִינֵיהּ אִתְּמַר (תהלים כה יד) סוֹד יהו\"ה לִירֵיאָיו וּבְרִיתוֹ לְהוֹדִיעָם, וְאִי סְתִימִין אִינוּן בֵּיהּ, בְּמַאי אִשְׁתְּמוֹדְעָאן, בִּשְׁכִינְתָּא, דְּאִיהִי אַסְפַּקְלַרְיָאָה דְנַהֲרָא כַּד נָחִית יהו\"ה לְגַבֵּי צַדִּיק לְנַהֲרָא בָּהּ וַדַּאי, וּמִנָּהּ אִשְׁתְּמוֹדְעָן, הֲדָא הוּא דִכְתִיב (ירמיה ט כב) כֹּה אָמַר יהו\"ה אַל יִתְהַלֵּל חָכָם בְּחָכְמָתוֹ, אִי אִיהוּ תַמָּן אִתְקְרִיאַת אַסְפַּקְלַרְיָאָה דְנַהֲרָא, וּבְהַהוּא זִמְנָא כִּי אִם בְּזֹאת יִ תְהַלֵּל הַ מִּתְהַלֵּל הַ שְׂכֵּל וְ יָדוֹעַ (שם כג), וְאִם יִסְתַּלַּק מִצַּדִּיק וְאִשְׁתָּאַר אִיהוּ חָרֵב וְיָבֵשׁ, מִיָּד אִתְקְרִיאַת אַסְפַּקְלַרְיָאָה דְלָא נַהֲרָא, בְּהַהוּא זִמְנָא אַל יִתְהַלֵּל חָכָם בְּחָכְמָתוֹ.</p>\n<p>וּמָאן גְּרִים לְאַנְהָרָא לָהּ, וּלְאִשְׁתְּמוֹדְעָא בָהּ לְקוּדְשָׁא בְּרִיךְ הוּא, מָאן דְּנַטִּיר בְּרִית, וְרָזָא דְמִלָּה זֶה הַשַּׁעַר לַיהו\"ה צַדִּיקִים יָבֹאוּ בוֹ (תהלים קיח כ), דָּא אִיהִי תַרְעָא דְצַדִּיקַיָּיא, וְאִית לוֹן רְשׁוּ לְאַעָלָא תַמָּן, וְדָא אִיהוּ מָאן דְּאִיהוּ צַדִּיק, וּבֵיהּ יהו\"ה, אִיהוּ זָכֵי בִשְׁכִינְתָּא וְיָרִית לָהּ, וְסָלִיק בָּהּ לְמַלְכָּא דְאִיהוּ עַמּוּדָא דְאֶמְצָעִיתָא, דְּאִיהוּ מֶלֶךְ, וְאִיהִי מַלְכוּת דִּילֵיהּ, וְרָזָא דְמִלָּה וְעַמֵּךְ כֻּלָּם צַדִּיקִים לְעוֹלָם יִרְשׁוּ אָרֶץ (ישעיה ס כא), וְדָא אִיהוּ שְׁכִינְתָּא דְאִתְּמַר בָּהּ (שם סו א) וְהָאָרֶץ הֲדוֹם רַגְלָי.</p>\n<p>וּשְׁכִינְתָּא אִיהִי צִיּוּרָא דְעִלָּאִין וְתַתָּאִין, כָּל דִּיּוֹקְנִין דִּסְפִירָן וְכָל שְׁמָהָן דִּלְהוֹן בָּהּ אִינוּן מְצוּיָירִים, וּבָהּ אִינוּן גְּלִיפִין נִשְׁמָתִין וּמַלְאָכִין וְחֵיוָון קַדִּישִׁין, וּבָהּ גְּלִיפִין מַה דְּאִתְּמַר בְּהוֹן (יחזקאל א י) וּדְמוּת פְּנֵיהֶם פְּנֵי אָדָם וכו'.</p>\n<p>קָם רַבִּי שִׁמְעוֹן וְאָמַר, סָבָא סָבָא, וְהָא שְׁכִינְתָּא אִיהִי יִחוּדָא דְקוּדְשָׁא בְּרִיךְ הוּא, אֵיךְ גְּלִיפִין בָּהּ דִּיּוֹקְנִין דִּלְתַתָּא דְלַאו אִינוּן מְצִיאוּתָהּ, אָמַר לֵיהּ רַבִּי, לְמַלְכָּא דְאִיהוּ יָתִיב בְּהֵיכָלֵיהּ, וְכַמָּה בְּנֵי נָשָׁא עָאלִין לְמֶחְזְיֵיהּ, מִנְּהוֹן מִסְתַּכְּלִין בִּלְבוּשׁוֹי, וּמִנְּהוֹן בְּגוּפוֹי, וּמִנְּהוֹן מִסְתַּכְּלִין בְּעוֹבָדוֹי, וּבְוַדַּאי בְּעוֹבָדוֹי אִשְׁתְּמוֹדָע מַאי נִיהוּ מַלְכָּא, דִּלְבוּשִׁין אִיהוּ מִשְׁתַּנֵּי בְּהוֹן לְכַמָּה שִׁנּוּיָין, וּלְבוּשִׁין דְּאִיהוּ לָבוּשׁ בְּצַפְרָא לָא לָבִישׁ בְּרַמְשָׁא, וּלְבוּשִׁין דְּלָבִישׁ יוֹמָא חֲדָא לָא לָבִישׁ יוֹמָא תִנְיָנָא, וְהָכִי בְּכָל יוֹמָא וְיַרְחָא וְשַׁתָּא וְשַׁבַּתָּא וְיֹמִין טָבִין אִשְׁתַּנֵּי בִּלְבוּשִׁין.</p>\n<p>כְּגַוְונָא דָא שְׁכִינְתָּא כַּמָּה לְבוּשִׁין אִית לָהּ, דְּמִנְּהוֹן בָּרָא קוּדְשָׁא בְּרִיךְ הוּא כָּרְסַיָּין (נ\"א כרסיא), וּמַלְאָכִין וְחֵיוָון וּשְׂרָפִים, וּשְׁמַיָּא וְאַרְעָא, וְכָל מַה דְּבָרָא בְהוֹן, וְכָל בִּרְיָין דְּבָרָא מֵאִלֵּין לְבוּשִׁין דִּילָהּ, רָשִׁים לוֹן כֻּלְּהוּ וְגָלִיף לוֹן בִּלְבוּשָׁהָא, בְּגִין לְאִסְתַּכְּלָא מִינָהּ בְּכָל בִּרְיָין לְרַחֲמָא עֲלַיְיהוּ, וְרָזָא דְמִלָּה וּרְאִיתִיהָ לִזְכּוֹר בְּרִית עוֹלָם (בראשית ט טז), וּרְאִיתִיהָ בְּאִלֵּין לְבוּשִׁין דְּאִינוּן נְהִירִין בְּכָל (בריין) זִמְנִין דְּיִשְׂרָאֵל נַהֲרִין לוֹן בְּעוֹבָדִין טָבִין, וּבְגִינַיְיהוּ קוּדְשָׁא בְּרִיךְ הוּא רָחִים עֲלַיְיהוּ.</p>\n<p>וְאִי עָבְדִין עוֹבְדִין בִּישִׁין, אִיהִי אִתְלַבְּשַׁת לְבוּשִׁין אָחֳרָנִין אוּכְמִין, דִּבְהוֹן רְשִׁימִין כָּל אִינוּן מָארֵי דְּדִינִין דְּאִתְקְרִיאוּ לֵילוֹת, לְמֵידָן בְּהוּ לְעָלְמָא, וּבְהַהוּא זִמְנָא אִיהִי אָמְרַת (שיר א ו) אַל תִּרְאוּנִי שֶׁאֲנִי שְׁחַרְחֹרֶת, וּבְגִין דָּא אִלֵּין מִסִּטְרָא דִלְבוּשִׁין אִינוּן גְּלִיפִין בָּהּ, עִלָּאִין דְּאִינוּן מַלְכִין וְשַׁלְטִין עַל תַּתָּאִין, וּמַלְאָכִין (נ\"א ומלכין) אִתְקְרִיאוּ מִסִּטְרָא דְמַלְכוּת, וּמִסִּטְרָא דְגוּפָא אִתְקְרֵי חֶסֶד דְּרוֹעָא יְמִינָא, גְּבוּרָה דְרוֹעָא שְׂמָאלָא, גּוּפָא עַמּוּדָא דְאֶמְצָעִיתָא, נֶצַח וְהוֹד תְּרֵין שׁוֹקִין, צַדִּיק אוֹת בְּרִית, וְהָא אוּקְמוּהָ.</p>\n<p>וְאִיהִי צִיּוּרָא דְכֻלְּהוּ, וּמִלְּגָאו מִינָהּ דְּאִיהוּ תִּקּוּנָא דְגוּפָא נָהִיר קוּדְשָׁא בְּרִיךְ הוּא דְאִיהוּ יהו\"ה, כְּנִשְׁמָתָא בְּגוּפָא, לְגוֹ מִכֹּלָּא הַהוּא דַאֲחִיד כֹּלָּא וְקָשִׁיר כֹּלָּא, דְלָא אִתְרְמִיז בְּשׁוּם רְמִיזוּ, וְכֹלָּא אִתְרְמִיז בִּשְׁכִינְתָּא, דְאִתְלַבִּישַׁת בִּלְבוּשִׁין דִּבְהוֹן מְצוּיָּירִין כָּל בִּרְיָין, אִיהִי אִתְקְרִיאַת בְּכָל שְׁמָהָן, וְאִיהִי דְמוּת אַרְבַּע חֵיוָון בִּלְבוּשָׁהָא, דִּבְכָל חַד וְחַד רָשִׁים אַרְבַּע אַתְוָון, וּדְמוּת אָדָם לָהֵנָה, דָא רְשִׁימוּ</p>"],[9500011130,"<p>דַעֲשַׂר אַתְוָון, דְּאִינוּן יו\"ד ה\"א וא\"ו ה\"א, דְסָלִיק לְחוּשְׁבָּן אָדָם, דְּמוּת אָדָם וַדַּאי דָּא שְׁכִינְתָּא דְאִיהִי דִיּוֹקְנֵיהּ (נ\"א דיוקנא דאדם) וַעֲלָהּ אִתְּמַר (במדבר יב ח) וּתְמוּנַת יהו\"ה יַבִּיט, וְהַאי מִסִּטְרָא דִלְבוּשָׁא, אֲבָל מִסִּטְרָא דְגוּפָא אִיהִי יִחוּדָא דְעַמּוּדָא דְאֶמְצָעִיתָא, אִיהוּ (נ\"א איהי) חוֹתָמָא מִסִּטְרָא דְגוּפָא, וּבְגִין דְּאִיהוּ חוֹתָמָא, אָמְרַת שְׁכִינְתָּא לְגַבֵּי יהו\"ה דְּאִיהוּ מִלְּגָאו, (שיר ח ו) שִׂימֵנִי כַחוֹתָם עַל לִבֶּךָ, דְּאַף עַל גַּב דְּאַנְתְּ תִּסְתַּלֵּק מִנִּי בְּגָלוּתָא, חוֹתָמָא דִילָךְ אִשְׁתָּאַר עִמִּי, וְלָא אִתְעַדֵּי מִנִּי לְעָלַם.</p>\n<p>קָם רַבִּי שִׁמְעוֹן וְאָמַר, סָבָא סָבָא, אֵימָא לָךְ קְרָא דְאוֹלִיפְנָא כְּגַוְונָא דָא שִׂימֵנִי כַחוֹתָם עַל לִבֶּךָ, שִׂימֵנִי חוֹתָם לָא כְּתִיב אֶלָּא כַחוֹתָם, אָמְרַת שְׁכִינְתָּא רִבּוֹן עָלְמִין, שִׂימֵנִי כַחוֹתָם, כְּהַהִיא רְשִׁימוּ דְחוֹתָמָא דִילָךְ, דְּאַף עַל גַּב דְּחוֹתָמָא אִשְׁתָּאַר בִּידָךְ, רְשִׁימוּ דִילֵיהּ בְּפִתְקָא אִיהוּ, וּמֵהַהוּא רְשִׁימוּ מִזְדַעִִזַעִין עִלָּאִין וְתַתָּאִין, כְּגַוְונָא דְמַלְכָּא דְאִיהוּ בִּשְׂרָא וּדְמָא, מַאי דְּרָשִׁים בְּפִתְקָא, רְשִׁימוּ דִילֵיהּ דְּחוֹתָמָא בִּידֵיהּ הוּא, וְאַף עַל גַּב דְּחוֹתָמָא בִּידֵיהּ אִשְׁתָּאַר, הָכִי דְחִילִין מֵרְשִׁימוּ דְחוֹתָמָא, כְּאִלּוּ הֲוָה מַלְכָּא, עַל אַחַת כַּמָּה וְכַמָּה אִי הֲוָה חוֹתָמָא.</p>\n<p>שִׂימֵנִי כַחוֹתָם עַל לִבֶּךָ, וְכִי מָאן חָמָא (נ\"א שוי) חוֹתָמָא עַל לִבָּא, אֶלָּא אִלֵּין תְּפִלִּין, דְּאִינוּן רְצוּעִין דִּלְהוֹן תַּלְיָין עַל לִבָּא, וְאִלֵּין תְּפִלִּין דְּרֵישָׁא, וּתְפִלָּה דְיָד דְּאִיהוּ בִּשְׂמָאלָא לָקֳבֵל לִבָּא, וְדָא אִיהוּ כַחוֹתָם עַל לִבֶּךָ, וְכַּחוֹתָם עַל זְרוֹעִִךָ, תְּפִלָּה דְיָד, דְּאִינוּן רְשִׁימוּ דִשְׁמָא קַדִּישָׁא, דְאִיהוּ י' קַדֶּשׁ לִי כָּל בְּכוֹר, ה' וְהָיָה כִּי יְבִיאֲךָ, ו' שְׁמַע יִשְׂרָאֵל, ה' וְהָיָה אִם שָׁמוֹעַ, וּמֵהַהוּא רְשִׁימוּ מִזְדַעִִזַעִין אוּמִין דְּעָלְמָא, הֲדָא הוּא דִכְתִיב (דברים כח י) וְרָאוּ כָּל עַמֵּי הָאָרֶץ כִּי שֵׁם יהו\"ה נִקְרָא עָלֶיךָ וְיָרְאוּ מִמֶּךָּ, וְהָכִי אוּקְמוּהוּ שֵׁם יהו\"ה אִלֵּין תְּפִלִּין דְּרֵישָׁא.</p>\n<p>שִׂימֵנִי כַחוֹתָם דָּא אוֹת בְּרִית מִילָה, וְאוֹת דְּיֹמִין טָבִין, דְּאִיהוּ רְשִׁימוּ דִשְׁמָא קַדִּישָׁא, כְּגַוְונָא דָא (שם ל יב), מִ י יַ עֲלֶה לָּ נוּ הַ שָּׁמַיְמָה, רֵישֵׁי אַתְוָון (נ\"א תיבין) מִילָה, וְסוֹפִי אַתְוָון יהו\"ה, מָאן דְּנָטִיר הַאי רְשִׁימוּ, כְּאִלּוּ נָטִיר שְׁמָא קַדִּישָׁא, וּמָאן דִּמְשַׁקֵּר בְּהַאי רְשִׁימוּ, כְּאִלּוּ מְשַׁקֵּר בִּשְׁמָא קַדִּישָׁא, דְּהַאי אִתְקְרֵי חוֹתָמָא דְגוּשְׁפַּנְקָא דְמַלְכָּא.</p>\n<p>דְּכָל בַּר נַשׁ דְּנָטִיר הַאי רְשִׁימוּ לְתַתָּא, דְאִיהוּ אוֹת בְּרִית, אוֹת שַׁבָּת, אוֹת תְּפִלִּין, אוֹת דְּיֹמִין טָבִין, אִיהוּ רָשִׁים וְחָקִיק לְעִילָא, וְנָהִיר לְעִילָא, וּמִנֵּיהּ מִזְדַעִִזַעִין עִלָּאִין וְתַתָּאִין, כְּמָה דְאַתְּ אָמַר (שם כח י) וְרָאוּ כָּל עַמֵּי הָאָרֶץ כִּי שֵׁם יהו\"ה נִקְרָא עָלֶיךָ שֵׁם יהו\"ה וַדַּאי, דָּא הַהוּא רְשִׁימוּ דְאוֹת בְּרִית מִילָה, וְאוֹת דִּתְּפִלִּין, וְאוֹת דְּשַׁבָּת וְיֹמִין טָבִין, וּמָאן דִּמְשַׁקֵּר לְתַתָּא בֵּיהּ, אִתְעַבַּר גְּלִיפוּ דִילֵיהּ מִלְּעִילָא, בְּהַהוּא זִמְנָא שָׁלְטִין עֲלֵיהּ כָּל מְקַטְרְגִין עִלָּאִין וְתַתָּאִין.</p>\n<p>שִׂימֵנִי כַחוֹתָם דָּא נִשְׁמָתָא, דְּאִיהוּ רְשִׁימוּ דִילָהּ גְּלִיפָא לְעִילָא, כְּמָה דְאוּקְמוּהוּ בְּיַעֲקֹב, דִּיּוֹקְנוֹ שֶׁל יַעֲקֹב חֲקוּקָה בְּכִסֵּא הַכָּבוֹד, דְּכָל נִשְׁמָתִין דְּאִינוּן גְּזִירִין מִתַּמָּן, גְּלִיפוּ דִּלְהוֹן אִיהוּ חָקוּק לְעִילָא, וּרְשִׁימוּ דִלְהוֹן לְתַתָּא, וְהַהוּא גְלִיפוּ דִלְעִילָא אִיהוּ חוֹתָם, וּרְשִׁימוּ דִלְתַתָּא רְשִׁימוּ דְחוֹתָם, וּמִיָּד דִּרְשִׁימוּ דִגְלִיפוּ דְנִשְׁמָתָא אִיהוּ לְעִילָא, וּרְשִׁימוּ דִילָהּ לְתַתָּא, אִתְּמַר בָּהּ (בראשית כח יב) וְהִנֵּה מַלְאֲכֵי אלהי\"ם עוֹלִים וְיֹרְדִים בּוֹ, סָלְקִין לְעִילָא וּמִסְתַּכְּלִין בְּדִיּוֹקְנָא דְנִשְׁמָתָא דְנַהֲרָא בְּהַהוּא גְלִיפוּ וּמִזְדַעִִזַעִין מִנֵּיהּ, נָחֲתִין לְתַתָּא וּמִסְתַּכְּלִין בִּרְשִׁימוּ דְהַהוּא דִיּוֹקְנָא דִלְתַתָּא, וְחָזָאן דְּלָא אִשְׁתַּנֵּי מִדִּיּוֹקְנָא דִלְעִילָא וְדָחֲלִין מִנֵּיהּ.</p>\n<p>שִׂימֵנִי כַחוֹתָם דָּא צְלוֹתָא, דְבָהּ אִיהוּ חָקִיק וְרָשִׁים חַ\"י עָלְמִין, בְּתַמְנֵי סְרֵי בִּרְכָאָן דִּצְלוֹתָא, וְדָא אִיהוּ רְשִׁימוּ דְחוֹתָמָא בְּפִתְקָא, דְּאִיהִי אוֹרַיְיתָא, גְלִיפוּ דְאַתְוָון דְּחוֹתָמָא דָא צַדִּיק חַ\"י עָלְמִין, חוֹתָמָא דָא עַמּוּדָא דְאֶמְצָעִיתָא, דְאִיהִי קְרִיאַת שְׁמַע, וְהִנֵּה מַלְאֲכֵי אלהי\"ם עוֹלִים, בְּזִמְנָא דְאִיהוּ זוֹקֵף בְּשֵׁם סָלְקִין עִמֵּיהּ.</p>"],[9500011131,"<p>בְּזִמְנָא דְאִיהוּ מָאִיךְ וְכוֹרֵעַ בְּבָרוּךְ נָחֲתִין עִמֵּיהּ, וַדָּאי אִיהוּ וְהִנֵּה מַלְאֲכֵי אלהי\"ם עֹלִים וְיֹרְדִים בּוֹ, מַלְאֲכֵי אלהי\"ם עֹלִים, בְּזִמְנָא דְאִיהוּ קָאִים בְּדִינָא קַיְימִין כֻּלְּהוּ וּמוֹלִיפִין עֲלֵיהּ זְכוּת, וְיוֹרְדִים בְּזִמְנָא דְנָצְחִין לֵיהּ בְּדִינָא וְנָחִית לְתַתָּא, כֻּלְּהוּ נָחֲתִין עִמֵּיהּ, כְּמָה דְאוּקְמוּהוּ בְיַעֲקֹב (בראשית כו ד) אָנֹכִי אֵרֵד עִמְּךָ מִצְרַיְמָה וְאָנֹכִי אַעַלְךָ גַם עָלֹה.</p>\n<p>שִׂימֵנִי כַחוֹתָם דָּא נִשְׁמָתָא דְאִיהִי חֲקוּקָה בְּכוּרְסַיָּיא, בְּזִמְנָא דְאִיהִי אִתְעָרָא לְתַתָּא בִּצְלוֹתָא, כָּרְסַיָּיא אִתְעַר לְעִילָא, כַחוֹתָם דָּא רוּחַ, דְּאִיהוּ צִיּוּרָא (דיש) (נ\"א דש) חֲקִיקָא בְּמַלְאָכַיָּא, בְּזִמְנָא דְאִיהִי אִתְעָרָא לְתַתָּא בִצְלוֹתָא, מַלְאָכַיָּא אִתְעָרוּן עִמֵּיהּ לְעִילָא, עַל זְרוֹעִִךָ דָּא נַפְשָׁא, דְאִיהִי חֲקִיקָא בְּאַרְבַּע סִטְרִין דְּעָלְמָא, בְּזִמְנָא דְאִתְעָרָא אִיהִי בִּצְלוֹתָא לְתַתָּא, אַרְבַּע סִטְרִין דְּעָלְמָא מִתְעָרִין עִמָּהּ.</p>\n<p>נְשָׁמָה אִיהִי חוֹתָמָא, רוּחָא צִיּוּרָא דְאַתְוָון דְּאִנּוּן חֲקוּקִין בְּחוֹתָמָא, נַפְשָׁא רְשִׁימוּ דְאַתְוָון בְּחוֹתָמָא, דְאִינוּן רְשִׁימִין בְּצִיּוּרִין דְּבַר נַשׁ, כִּרְשִׁימוּ דְחוֹתָמָא בְּפִתְקָא, וּבְהַהוּא רִשׁוּמָא דְנַפְשָׁא אִשְׁתְּמוֹדָע פַּרְצוּפָא בְּגוּפָא דְבַר נַשׁ, מֵאָן אֲתַר אִיהוּ, וּבְגִין דָּא אוּקְמוּהוּ, בְּהַאי חוֹתָמָא כַּמָּה רְשִׁימִין אִית בֵּיהּ, אַרְבַּע, רְשִׁימוּ דְאַרְיֵה תַּמָּן, רְשִׁימוּ דְשׁוֹר תַּמָּן, רְשִׁימוּ דְנֶשֶׁר תַּמָּן, רְשִׁימוּ דִדְמוּת אָדָם תַּמָּן, וּמָאן אִיהוּ דְרָשִׁים לוֹן בְּחוֹתָמָא, יהו\"ה אֱמֶת, דִּבְהַאי אַרְבַּע רְשִׁימִין אִינוּן כָּל בִּרְיָין דְּעָלְמָא.</p>\n<p>אֲבָל אוּמִין דְּעָלְמָא דְשַׁקְרוּ בֵיהּ, לַאו אִינוּן רְשִׁימִין בֵּיהּ, אֶלָּא בְחוֹתָמָא דְשִׁקְרָא, וְאִיהוּ נָחָשׁ דְּמַלֵּיל שִׁקְרָא עַל קוּדְשָׁא בְּרִיךְ הוּא, וּבְגִינֵיהּ אִתְּמַר בְּאֹרַח מַתְלָא, שִׁקְרָא לֵית לָהּ רַגְלִין, וְכַךְ חִוְיָא לֵית לֵיהּ רַגְלִין, עַל גְּחֹנְךָ תֵלֵךְ, וְעָתִיד קוּדְשָׁא בְּרִיךְ הוּא לְמַחָאָה שִׁקְרָא מֵעָלְמָא, כְּמָה דְאַתְּ אָמַר (ישעיה כה ח) וּמָחָה יהו\"ה אלהי\"ם דִּמְעָה מֵעַל כָּל פָּנִים וכו', דְּוַדַּאי הַאי חִוְיָא אִיהוּ מַלְאַךְ הַמָּוְת דְּקָטִיל לִבְנֵי נָשָׁא, וְגָרִים דִּמְעָה, דְּאִיהוּ אֵל אַחֵר, וּבְמַאי קָטִיל בְּסַם הַמָּוְת דִּילֵיהּ, דְּאִיהִי גֵיהִנָּם, וְדָא אִיהוּ סמא\"ל.</p>\n<p>וּבְאִלֵּין פַּרְצוּפִין דְּחִוְויָין, אִתְגַּלְיָיא אִיהוּ לִבְנֵי נָשָׁא בְּאֹרַח שִׁקְרָא לְפַתָּאָה לוֹן, וְרָזָא דְמִלָּה (תהלים קכז א) אִם יהו\"ה לֹא יִבְנֶה בַיִת שָׁוְא עָמְלוּ בוֹנָיו בּוֹ, וְלֵית לוֹן קִיּוּמָא, אֲבָל צִיּוּרִין דְּחַיוָן אִינוּן רְשִׁימִין בִּשְׁמָא דְקוּדְשָׁא בְּרִיךְ הוּא, בְּהַאי רְשִׁימוּ דִמְזוּזָה, דְּאִיהוּ שד\"י מִלְּבָר יהו\"ה מִלְּגָאו, וְהַאי אִיהוּ רְשִׁימוּ דִבְרִית מִילָה, שד\"י מִלְּבָר יהו\"ה מִלְּגָאו, שד\"י הָא אוּקְמוּהָא ש תְּלַת אֲבָהָן, דְּאִינוּן תְּרֵין דְּרוֹעִין וְגוּפָא, אִלֵּין אִינוּן תְּלַת עַנְפִין דְּש', ד שְׁכִינְתָּא, י צַדִּיק אוֹת בְּרִית מִילָה, וְעַל הַאי שד\"י אִתְּמַר (שמות ו ג) וָאֵרָא אֶל אַבְרָהָם אֶל יִצְחָק וְאֶל יַעֲקֹב בְּאֵ\"ל שׁד\"י, בְּהַאי שד\"י, דְּאִיהוּ מִלְּבָר בִּמְזוּזָה, אֲבָל וּשְׁמִי יהו\"ה דְּאִיהוּ מִלְּגָאו בַּמְּזוּזָה, דְאִיהִי תַרְעָא דְקוּדְשָׁא בְּרִיךְ הוּא, דְאִתְּמַר בָּהּ (תהלים קיח כ) זֶה הַשַּׁעַר לַיהו\"ה, (שמות ו ג) לֹא נוֹדַעִִתִּי לָהֶם, (דברים ו ח).</p>\n<p>וּכְתַבְתָּם עַל מְזְזוֹת בֵּיתֶךָ וּבִשְׁעָרֶיךָ, אִלֵּין תְּרֵין סַמְכֵי קְשׁוֹט, זָז מָוְת מִן בֵּיתָא דְאִיהִי שְׁכִינְתָּא, וְלָא אִתְקַרִיב לְגַבָּהּ, הֲדָא הוּא דִכְתִיב (במדבר א יח) וְהַזָּר הַקָּרֵב יוּמָת, וְאַתְוָון דִּמְזְזוֹ\"ת אִינוּן מַמָּשׁ זָ\"ז מָוְ\"ת, וּבְגִין דָּא מָאן דְּנָטִיר בְּרִית מִילָה דְאִיהוּ חוֹתָמָא דִילֵיהּ, זָז מָוְת מִנֵּיהּ, דְּאִיהוּ שָׂטָן, יֵצֶר הָרָע, רָע, טָמֵא, צְפוֹנִי, מַלְאַךְ הַמָּוְת, וְלָא יִתְקַרִיב לְגַבֵּיהּ, וְלָא יְמוּת עַל יְדֵיהּ.</p>\n<p>וּמָאן דִּמְשַׁקֵּר בִּבְרִית מִילָה, הוּא מְשַׁקֵּר בְּחוֹתָמָא דְמַלְכָּא, דְּאִיהוּ רָשִׁים בֵּיהּ שד\"י מִלְּבָר יהו\"ה מִלְּגָאו, מְנָא לָן מֵהַאי קְרָא מַשְׁמַע (דברים ל יב) מִ\"י יַעֲלֶ\"ה לָּנ\"וּ הַשָּׁמַיְמָ\"ה, רֵישֵׁי תֵּיבוֹת מִילָ\"ה, סוֹפֵי תֵּיבוֹת יהו\"ה, וּבְוַדַּאי מָאן דִּמְשַׁקֵּר בִּבְרִית מִילָה, אִסְתַּלַּק מִנֵּיהּ יהו\"ה ושד\"י, וְשַׁרְיָא עֲלֵיהּ שָׂטָן דְּאִיהוּ אֵל אַחֵר, חִוְיָא שַׁרְיָא בַּאֲתַר דְּיהו\"ה מִלְּגָאו, וְסַם מָוְת שַׁרְיָא בַּאֲתַר דְּשד\"י מִלְּבָר, וְדָא אִיהוּ דְאָמַר קְרָא (במדבר יט כ) אֶת מִקְדַּשׁ יהו\"ה טִמֵּא וכו', אִם לָא תָב בִּתְיוּבְתָּא, וְסָבִיל כַּמָּה יִסּוּרִין</p>"],[9500011132,"<p>לְאַעֲבָרָא הַהוּא חִוְיָא מִתַּמָּן, וּלְסַם הַמָּוְת דִּילֵיהּ, דְּאִיהִי צָרַעַת מַמְאֶרֶת, בְּכַמָּה מַרְעִין וּמַכְתָּשִׁין, עַד דְּלָא אִשְׁתָּאַר בֵּיהּ בִּשְׂרָא דְאִיהִי עַפְרָא, וְרָזָא דְמִלָּה (ויקרא יד מב) וְעָפָר אַחֵר יִקַּח וְטָח אֶת הַבָּיִת, בְּגִין דְּנָחָשׁ עָפָר לַחְמוֹ, עַד דְּיִתְפַּרְנֵס מֵהַהוּא בִּשְׂרָא לָא יָזוּז מִנֵּיהּ, וְעָנִי חָשׁוּב כַּמֵּת, מַה מִּיתָה אַנְפּוֹי מִשְׁתַּנְּיָין, כְּגַוְונָא דָא עָנִי אַנְפּוֹי מִשְׁתַּנְּיָן, וְהָא אוּקְמוּהוּ (תהלים יב ט) כְּרוּם זְלּוּת לִבְנֵי אָדָם, מַאי כְּרוּם זְלּוּת, אֶלָּא מָאן דְּאִצְטְרִיךְ לְבִרְיָיתָא אַנְפּוֹי מִשְׁתַּנְּיָין כַּכְּרוּם, וְכַמָּה נִשּׁוּכִין דְּיִסּוּרִין נָשִׁיךְ לֵיהּ הַהוּא חִוְיָא.</p>\n<p>וְלָא עוֹד אֶלָּא דְעָנִי חָשִׁיב כַּמְּצוֹרָע, מַה מְּצוֹרָע (ויקרא יג מה) וְרֹאשׁוֹ יִהְיֶה פָרוּעַ וכו', כַּךְ עָנִי, מַה מְּצוֹרָע מִחוּץ לַמַּחֲנֶה מוֹשָׁבוֹ, כַּךְ עָנִי עָרוֹם וְיָחֵף, וַעֲנִיּוּתָא אִיהִי לְיִשְׂרָאֵל בַּאֲתַר דְּצָרַעִִתָּא, וְאַרְבַּע דִּיּוֹקְנִין אִינוּן (ס\"א גונין), כְּאַרְבַּע גַּוָּונִין דְּצָרַעַת, וְאִינוּן נֶגַע לָבָן אֲדַמְדָּם יְרַקְרַק בַּהֶרֶת שְׁחוֹרָה, הָא אַרְבַּע, וְכֻלְּהוּ אִית לוֹן אַתְרִין יְדִיעָאן בְּגוּפָא, וּמִנְּהוֹן אַתְיָין לִבְנֵי נָשָׁא כַּמָּה מַרְעִין, לָבָן וַאֲדַמְדָּם חֵלֶב טָמֵא וְכָבֵד, יְרַקְרַק מָרָה, בַּהֶרֶת שְׁחוֹרָה טְחוֹל, וּמִנְּהוֹן נְבִעִין אַרְבַּע מִינֵי מַרְעִין, וְאִינוּן מָרָה חִוָּורָא, מָרָה סוּמָקָא, מָרָה יְרוֹקָא, מָרָה אוּכָּמָא.</p>\n<p>וְאִם תָּב בִּתְיוּבְתָּא, נָחִית עֲלֵיהּ סַם חַיִּים דְּאִיהִי שְׁכִינְתָּא, וְאִתְּמַר בָּהּ (ישעיה ו י) וָשָׁב וְרָפָא לוֹ מֵאִלֵּין מִינֵי מַרְעִין, וּמְחַיֶּה לֵיהּ מִמִּיתָה דַעֲנִיּוּתָא, כְּמָה דְאַתְּ אָמַר (יחזקאל יא לב) וְהָשִׁיבוּ וִחְיוּ, דְּיִשְׂרָאֵל בְּזִמְנָא דְאִינוּן עֲנִיִּים קְרוּיִים מֵתִים, וּבְגִינַיְיהוּ אִתְּמַר שׁוּבוּ וִחְיוּ, וְלֵית עֲנִיּוּתָא כַּעֲנִיּוּתָא דְאוֹרַיְיתָא, דְּמָאן דְּלָא אִית בֵּיהּ אוֹרַיְיתָא אִתְקְרֵי מֵת, אַסְוָותָא דִילֵיהּ מַאי הוּא לְהַהוּא עָלְמָא, אוֹרַיְיתָא, דְאִתְּמַר בֵּיהּ (משלי ג יח) עִץ חַיִּים הִיא וְגוֹמֵר, וְאִיהִי אַסְוָותָא לְכָל מַרְעִין, כְּמָה דְאַתְּ אָמַר (שם ח) רִפְאוּת תְּהִי לְשָׁרֶךָ וכו'.</p>\n<p>שִׂימֵנִי כַחוֹתָם (שיר ח ו), מַאי חוֹתָם בְּהַאי אֲתַר, דָּא אוֹת שַׁבָּת וְיוֹם טוֹב, דְּאִיהוּ שָׁקִיל לִבְרִית מִילָה, כְּגַוְונָא דָא שַׁבָּ\"ת, ש' לָקֳבֵל שִׁי\"ן דְּשֵׁם שד\"י, כְּלִילָא מִתְּלַת חֵיוָון עִלָּאִין, מִתְּלַת אֲבָהָן, ב' דָּא ד', דְּאִיהִי רְבִיעָאָה לַאֲבָהָן, וּרְבִיעָאָה לִתְלַת חֵיוָון, וְאִיהִי דְמוּת אָדָם, וְלַאו אָדָם, הֲדָא הוּא דִכְתִיב (יחזקאל א י) וּדְמוּת פְּנֵיהֶם פְּנֵי אָדָם, אֶלָּא מַאי אָדָם יו\"ד ה\"א וא\"ו ה\"א, שַׁבָּת בֵּיהּ שד\"י, יהו\"ה הוּא רְשׁוּת הַיָּחִיד רָחְבּוֹ אַרְבָּעָה וְגָבְהוֹ עֲשָׂרָה יו\"ד ה\"א וא\"ו ה\"א, י' דְּשד\"י לָקֳבֵל אוֹת דְּשַׁבָּת וְיוֹמִין טָבִין, י' בֵּיהּ אִתְרְמִיזוּ עֲשַׂר סְפִירָן.</p>\n<p>הַאי רְשִׁימוּ אִיהוּ לִבְרָא דְמַלְכָּא, אֲבָל לְעַבְדָּא דְמַלְכָּא רְשִׁימוּ דִילֵיהּ שד\"י, מִסִּטְרָא דְהַהוּא דְאִתְּמַר בֵּיהּ (ישעיה מג ז) כֹּל הַנִּקְרָא בִשְׁמִי וכו', וּמַאי נִיהוּ מטטרו\"ן, דְּסָלִיק לְחֻשְׁבַּן שד\"י, וְאִיהוּ אָדָם זְעִירָא בְדִיּוֹקְנָא דִלְעִילָא, וְדָא אִיהוּ אִם כַּבָּנִים אִם כַּעֲבָדִים וכו'.</p>\n<p>מָאן דְּאִיהוּ רְשִׁימוּ דְאַרְיֵה בְּחוֹתָמָא דִילֵיהּ אִיהוּ חִוָּור בְּאַנְפּוֹי, מָאן דְּאִיהוּ בְּחוֹתָמָא דְשׁוֹר אִיהוּ סוּמָקָא בְּאַנְפּוֹי, מָאן דְּאִיהוּ בְּחוֹתָמָא דְנֶשֶׁר אִיהוּ יְרוֹקָא בְּאַנְפּוֹי, מָאן דְּאִיהוּ בְּחוֹתָמָא דִדְמוּת אָדָם אִיהוּ אוּכָּם בְּאַנְפּוֹי, כְּגַוְונָא דְאוֹרַיְיתָא דְאִתְּמַר (שיר א ה) שְׁחוֹרָה אֲנִי וְנָאוָה.</p>\n<p>שִׂימֵנִי כַחוֹתָם, דָּא אוֹרַיְיתָא, דְאִתְּמַר בָּהּ (מלאכי ב ו) תּוֹרַת אֱמֶת הָיְתָה בְּפִיהוּ, וְאִיהִי כְלִילָא מֵעֲשַׂר אֲמִירָן דְּאִנּוּן י', וּמֵעֲשַׂר דִּבְּרָן דְּאִינוּן ה\"ה, וּמַאי תּוֹרָה ו' כְּלִיל שִׁית יְמֵי בְרֵאשִׁית, עַל לִבֶּךָ דָּא ל\"ב אלהי\"ם בְּחוּשְׁבַּן ל\"ב, דְּתַלְיָין מִן ו', דְּאִיהוּ ו' זִמְנִין טוֹב, וּבָהּ אִשְׁתַּלִּים (נ\"א ו') שְׁמָא דְאַרְבְּעִין וּתְרֵין אַתְוָון, דִּבְהוֹן אִתְבְּרִיאוּ שְׁמַיָּא וְאַרְעָא וְכָל מַה דְּאִית בְּהוֹן, וְדָא אִיהוּ רָזָא כִּי יוֹם נָקָם בְּלִבִּי (ישעיה סג ד), לִבִּ\"י סְלִיק מ\"ב, וַיְכֻלּ\"וּ ע\"ב שְׁמָהָן דִּשְׁמָא מְפָרַשׁ, וַעֲלֵיהּ אִתְּמַר לְלִבִּי גִלִּיתִי, וּלְאֵבָרַי דְּאִנּוּן רְמַ\"ח פִּקּוּדִין דְּאוֹרַיְיתָא לֹא גִלִּיתִי, וּבְהַאי וַיְכֻלּוּ (ה' בששי דאיהו בו', ודא איהי ויהי</p>"]]});
